INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('c4d22014-ea1c-4f68-b694-490f1a482d3f', '0175a068-7604-4e23-b571-a6d14dd68a47', 'Hingga Mencapai Titik Kritis (～に至って)', 'Kuasai ungkapan titik balik, eskalasi krisis, dan analisis sejarah formal dalam wacana bisnis serta berita tingkat JLPT N1.', 'curriculum', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('59723046-8d1c-4958-8f76-d02c707a13f5', '0175a068-7604-4e23-b571-a6d14dd68a47', 'Terpaksa Oleh Keadaan Luar (～を余儀なくされる)', 'Pahami cara menyampaikan keputusan yang terpaksa diambil akibat bencana, regulasi, atau tekanan ekonomi dalam bahasa formal N1.', 'curriculum', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('3ebb1416-a775-4870-b0e3-6e0c9174816f', '0175a068-7604-4e23-b571-a6d14dd68a47', 'Meskipun Memang Demikian (～とはいえ)', 'Bangun argumen tajuk rencana, evaluasi berimbang, dan kritik bernuansa dengan mengakui fakta terlebih dahulu sebelum menyampaikan catatan penting.', 'curriculum', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('f1cd7b47-f9a0-48f8-91eb-c079a50fb706', '0175a068-7604-4e23-b571-a6d14dd68a47', 'Dengan Sarana Resmi / Batas Waktu (～をもって)', 'Gunakan ungkapan super-formal untuk pengumuman resmi, batas akhir pendaftaran, surat menyurat korporasi, dan prosedur hukum.', 'curriculum', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('9fce8f47-f25f-4a48-9c5e-adca09ca44a1', '0175a068-7604-4e23-b571-a6d14dd68a47', 'Tingkat Ekstrem Tanpa Tandingan (～極まりない)', 'Ekspresikan penilaian tajam, kecaman diplomatis, kritik etika publik, dan apresiasi formal pada tingkat tertinggi.', 'curriculum', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('2ada0069-092d-429a-a798-86fd5318e9c7', '0175a068-7604-4e23-b571-a6d14dd68a47', 'Dengan Caranya Sendiri (～なりに)', 'Sampaikan refleksi diri, empati kepemimpinan, dan penghargaan atas kontribusi sesuai kapasitas serta peran masing-masing.', 'curriculum', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('6433588c-48e2-4808-bb15-7b9199141315', '0175a068-7604-4e23-b571-a6d14dd68a47', 'Pasti Menimbulkan Efek (～ずにはおかない)', 'Analisis dampak karya seni, kebijakan publik, serta reaksi psikologis sosial yang niscaya dan tak terbendung dalam wacana N1.', 'curriculum', 7, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('e327daae-129b-4861-99ce-fedc319f9ff4', '0175a068-7604-4e23-b571-a6d14dd68a47', 'Jika Sudah Sampai Level (～ともなると)', 'Bahas standar eksekutif, proyek berskala besar, serta ekspektasi dan tanggung jawab tinggi yang menyertai posisi prestisius.', 'curriculum', 8, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('292986e7-32af-4d2a-bbed-74dc70d37b87', '0175a068-7604-4e23-b571-a6d14dd68a47', 'Tanpa Memandang Kondisi (～いかんによらず)', 'Kuasai bahasa regulasi, prinsip keadilan hukum, kepatuhan korporasi (compliance), dan klausul resmi tanpa pengecualian.', 'curriculum', 9, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('c1ef7f4c-990c-4d4f-a03f-d3549070bdc3', '0175a068-7604-4e23-b571-a6d14dd68a47', 'Layak Untuk (～に足る)', 'Evaluasi kualitas, kredibilitas, dan kelayakan gagasan secara akademis maupun eksekutif, ditutup dengan sintesis kesiapan JLPT N1.', 'curriculum', 10, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO units ("id", "level_id", "title", "description", "unit_type", "order_index", "created_at") VALUES ('c4278551-4f2e-4692-9da6-e1504b57946f', '0175a068-7604-4e23-b571-a6d14dd68a47', 'Ujian Simulasi Kesiapan JLPT N1', 'Evaluasi komprehensif lintas 4 pilar (Membaca, Mendengar, Menulis, Berbicara) yang menguji seluruh 10 tata bahasa formal tingkat tinggi JLPT N1.', 'diagnostic_exam', 99, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
