INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('67ef1df8-f3dd-45e6-bbd6-f5540a84eef3', '001d5a9e-d56a-45a4-9e99-67ae92fd0cdb', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Pilih pola yang paling tepat untuk teks editorial ini: 多くの反対意見を押し切った結果、住民訴訟に発展する___。', '{"options":["に反した","に準じた","に先立った","に至った"],"translation":"Akibat memaksakan kehendak di tengah banyak penolakan, hal itu akhirnya berkembang hingga menjadi gugatan warga.","sentence_template":"多くの反対意見を押し切った結果、住民訴訟に発展する[blank]。"}'::jsonb, '{"selected":"に至った"}'::jsonb, NULL, NULL, '発展するに至った berarti ''akhirnya berkembang hingga mencapai tahap (gugatan warga)''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f68d4294-3a46-49df-b03e-1655a26556a7', '001d5a9e-d56a-45a4-9e99-67ae92fd0cdb', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Lengkapi kalimat formal berikut: 業績不振が数年続き、主力工場を閉鎖する___、経営陣は責任を取った。', '{"options":["を踏まえて","に至って","に応じて","に照らして"],"translation":"Setelah kinerja buruk berlanjut beberapa tahun hingga menutup pabrik utama, barulah manajemen mengambil tanggung jawab.","sentence_template":"業績不振が数年続き、主力工場を閉鎖する[blank]、経営陣は責任を取った。"}'::jsonb, '{"selected":"に至って"}'::jsonb, NULL, NULL, '～するに至って menunjukkan titik ekstrem (penutupan pabrik utama) yang akhirnya memicu pertanggungjawaban.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bd47b6b1-190d-4051-9acf-7e6dd16454ea', '001d5a9e-d56a-45a4-9e99-67ae92fd0cdb', 'd1000019-0000-0000-0000-000000000028', 'listening', 'listening_choice', 'Dengarkan pernyataan juru bicara berikut. Apa yang sedang diselidiki oleh komite independen?', '{"options":[{"id":"opt_1","text":"Rencana ekspansi perusahaan ke pasar Eropa"},{"id":"opt_2","text":"Penyebab struktural organisasi yang mengarah pada terjadinya skandal tersebut"},{"id":"opt_3","text":"Jumlah bonus tahunan bagi para eksekutif"},{"id":"opt_4","text":"Efektivitas kampanye iklan televisi terbaru"}],"audio_text":"第三者委員会は、今回の不祥事が発生するに至った組織的な原因を徹底的に調査する方針です。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '発生するに至った組織的な原因 berarti ''penyebab organisasional yang berujung pada terjadinya skandal''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7af0e2c1-ea39-410c-aa51-57544903c46d', '001d5a9e-d56a-45a4-9e99-67ae92fd0cdb', 'd1000019-0000-0000-0000-000000000028', 'listening', 'listening_choice', 'Dengarkan komentar analis berikut. Bagaimana sikap pembicara terhadap situasi saat ini?', '{"options":[{"id":"opt_1","text":"Subsidi sementara sudah cukup untuk menyelesaikan masalah"},{"id":"opt_2","text":"Kerusakan yang terjadi masih sangat kecil dan terkendali"},{"id":"opt_3","text":"Reformasi sistem yang mendasar mutlak diperlukan karena kerusakan sudah telanjur meluas"},{"id":"opt_4","text":"Pemerintah sebaiknya menunggu sampai tahun depan sebelum bertindak"}],"audio_text":"ここまでの被害が拡大した今に至っては、一時的な補助金ではなく抜本的な制度改革が不可欠だ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '今に至っては...抜本的な制度改革が不可欠だ menegaskan bahwa reformasi sistem menyeluruh mutlak diperlukan.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3d85536a-279a-4bc9-9792-a0286fe242c6', '001d5a9e-d56a-45a4-9e99-67ae92fd0cdb', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Pada akhirnya, perdebatan itu berujung pada pemungutan suara."', '{"romaji":"Nagai giron no sue saiketsu ni itatta no da.","tokens":["に沿って","末","のだ","採決","に至った","議論の","長い","ながら"],"target_translation":"Pada akhirnya, perdebatan itu berujung pada pemungutan suara."}'::jsonb, '["長い","議論の","末","採決","に至った","のだ"]'::jsonb, NULL, NULL, '長い議論の末 (setelah perdebatan panjang) berujung pada 採決に至った (mencapai tahap pemungutan suara).', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('78f48d77-f437-4f1e-99dd-1a5f4aa97de4', '001d5a9e-d56a-45a4-9e99-67ae92fd0cdb', 'd1000019-0000-0000-0000-000000000028', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan melaporkan secara transparan kronologi hingga tercapainya keputusan ini."', '{"romaji":"Kono ketsuron ni itatta keii wo, toumeisei wo motte go-houkoku itashimasu.","display_text":"この結論に至った経緯を、透明性をもってご報告いたします。","phonetic_breakdown":["ko-no","ke-tsu-ron","ni","i-ta-tta","kei-i","wo","tou-mei-sei","wo","mo-tte","go-hou-ko-ku","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"この結論に至った経緯を、透明性をもってご報告いたします。"}'::jsonb, NULL, NULL, 'Kalimat formal tingkat eksekutif yang memadukan ～に至った経緯 dengan ungkapan sopan ご報告いたします.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c646ae5a-ee4a-47b1-bf2b-2e7c6cee6f75', '001d5a9e-d56a-45a4-9e99-67ae92fd0cdb', 'd1000019-0000-0000-0000-000000000028', 'listening', 'listening_choice', 'Dengarkan berita ekonomi. Mengapa perusahaan teknologi itu menjual anak usahanya?', '{"options":[{"id":"opt_1","text":"Karena anak usaha tersebut mencatat rekor keuntungan tertinggi"},{"id":"opt_2","text":"Karena perusahaan ingin memperluas jaringan ritel"},{"id":"opt_3","text":"Karena kelesuan kinerja berlanjut tiga tahun berturut-turut sehingga terpaksa menjual anak usaha demi restrukturisasi"},{"id":"opt_4","text":"Karena aturan pajak baru melarang kepemilikan anak usaha"}],"audio_text":"業績の低迷が三年連続で続くに至り、経営再建のため子会社の売却に踏み切った。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '三年連続で続くに至り menandai eskalasi kerugian yang memicu keputusan restrukturisasi besar.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('368f6483-cb37-4a1c-8d51-1f7afa943b97', '001d5a9e-d56a-45a4-9e99-67ae92fd0cdb', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Kini setelah mencapai tahap akhir proyek, jangan sampai lengah sedikit pun."', '{"romaji":"Koko ni itatte, sukoshi mo ki o yurumete wa naranai.","tokens":["至って、","気を緩めては","ない。","緩めた","ここに","少しも","なら","をもって、"],"target_translation":"Kini setelah mencapai tahap akhir proyek, jangan sampai lengah sedikit pun."}'::jsonb, '["ここに","至って、","少しも","気を緩めては","なら","ない。"]'::jsonb, NULL, NULL, 'ここに至って menegaskan momen krusial di garis akhir.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1dabdc0f-7549-4e68-b366-f2d7d1853bdf', '024e0e49-f260-44a9-8fc0-dad996942c02', 'd1000019-0000-0000-0000-000000000037', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Rencana bisnis ini memiliki prospek yang layak untuk diinvestasikan."', '{"romaji":"Kono jigyou keikaku wa, choukiteki na toushi ni taru shouraisei wo sonaete iru.","display_text":"この事業計画は、長期的な投資に足る将来性を備えている。","phonetic_breakdown":["ko-no","ji-gyou","kei-ka-ku","wa","chou-ki-te-ki","na","tou-shi","ni","ta-ru","shou-rai-sei","wo","so-na-e-te","i-ru"]}'::jsonb, '{"expected_transcript":"この事業計画は、長期的な投資に足る将来性を備えている。"}'::jsonb, NULL, NULL, '投資に足る将来性 (prospek masa depan yang layak menerima investasi).', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0660a786-19b0-456a-a62a-f636bded87f2', '024e0e49-f260-44a9-8fc0-dad996942c02', 'd1000019-0000-0000-0000-000000000037', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Perbedaan sekecil itu adalah hal remeh yang tidak perlu dikhawatirkan."', '{"romaji":"Sono teido no chigai wa, osoreru ni tarinai sasai na mondai da.","display_text":"その程度の違いは、恐れるに足りない些細な問題だ。","phonetic_breakdown":["so-no","tei-do","no","chi-gai","wa","o-so-re-ru","ni","ta-ri-nai","sa-sai","na","mon-dai","da"]}'::jsonb, '{"expected_transcript":"その程度の違いは、恐れるに足りない些細な問題だ。"}'::jsonb, NULL, NULL, '恐れるに足りない (tidak layak ditakuti) dan 些細な問題 (masalah sepele).', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('12711719-d5a4-43f0-88c4-601c9e55dcae', '024e0e49-f260-44a9-8fc0-dad996942c02', 'd1000019-0000-0000-0000-000000000037', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pengalamannya yang luas membuatnya layak memimpin proyek besar ini."', '{"romaji":"Houfu na jisseki wo motsu kanojo koso, kono juuseki wo makaseru ni taru jinbutsu da.","display_text":"豊富な実績を持つ彼女こそ、この重責を任せるに足る人物だ。","phonetic_breakdown":["hou-fu","na","ji-sse-ki","wo","mo-tsu","ka-no-jo","ko-so","ko-no","juu-se-ki","wo","ma-ka-se-ru","ni","ta-ru","jin-bu-tsu","da"]}'::jsonb, '{"expected_transcript":"豊富な実績を持つ彼女こそ、この重責を任せるに足る人物だ。"}'::jsonb, NULL, NULL, '重責を任せるに足る人物 berarti ''sosok yang layak diserahi tanggung jawab berat''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f50124a6-c9f3-4780-add4-4fbcf6108486', '024e0e49-f260-44a9-8fc0-dad996942c02', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Bukti tersebut masih kurang meyakinkan untuk dijadikan dasar keputusan."', '{"romaji":"Sono shouko wa handan no konkyo to suru ni taranai.","tokens":["足らない","とする","なりに","判断の","に","その証拠は","極まりない","根拠"],"target_translation":"Bukti tersebut masih kurang meyakinkan untuk dijadikan dasar keputusan."}'::jsonb, '["その証拠は","判断の","根拠","とする","に","足らない"]'::jsonb, NULL, NULL, '根拠とするに足らない berarti ''tidak cukup layak untuk dijadikan dasar penilaian''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ac462dd1-cfce-404f-9d9e-ca0a506e0d3f', '024e0e49-f260-44a9-8fc0-dad996942c02', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Karya ini layak disebut sebagai mahakarya sastra modern."', '{"romaji":"Honsaku wa gendai bungaku no kessaku to yobu ni taru sakuhin da.","tokens":["傑作と","に足る","呼ぶ","とはいえ","をもって","本作は","現代文学の","作品だ"],"target_translation":"Karya ini layak disebut sebagai mahakarya sastra modern."}'::jsonb, '["本作は","現代文学の","傑作と","呼ぶ","に足る","作品だ"]'::jsonb, NULL, NULL, '傑作と呼ぶに足る作品 berarti ''karya yang layak disebut mahakarya''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2a43f83d-7658-44ea-a1c9-a4a3ffe28ee3', '024e0e49-f260-44a9-8fc0-dad996942c02', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Informasi yang tidak terverifikasi itu adalah hal remeh."', '{"romaji":"Urazuke no nai jouhou wa toru ni tarinai.","tokens":["ながら","に至って","足りない","に","取る","裏付けの","情報は","ない"],"target_translation":"Informasi yang tidak terverifikasi itu adalah hal remeh."}'::jsonb, '["裏付けの","ない","情報は","取る","に","足りない"]'::jsonb, NULL, NULL, '裏付けのない情報 (informasi tanpa bukti pendukung) dinilai 取るに足りない.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f0e5048e-c4b9-4766-a852-218d59c363a5', '024e0e49-f260-44a9-8fc0-dad996942c02', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Pilih pola yang tepat: 一時的な流行にすぎない現象は、長期戦略の根拠___。', '{"options":["とするに足りない","とするに至った","とせざるを得ない","極まりない"],"translation":"Fenomena yang sekadar tren sesaat tidak layak dijadikan dasar strategi jangka panjang.","sentence_template":"一時的な流行にすぎない現象は、長期戦略の根拠[blank]。"}'::jsonb, '{"selected":"とするに足りない"}'::jsonb, NULL, NULL, '根拠とするに足りない berarti tidak layak dijadikan landasan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('798d7df7-549c-4456-ae3a-7cc1f809e587', '024e0e49-f260-44a9-8fc0-dad996942c02', 'd1000019-0000-0000-0000-000000000037', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Keberhasilan reformasi ini adalah teladan yang patut dipelajari oleh organisasi lain."', '{"romaji":"Kono kaikaku no seikou jirei wa, tadantai ga sankou ni suru ni taru sugureta moderu desu.","display_text":"この改革の成功事例は、他団体が参考にするに足る優れたモデルです。","phonetic_breakdown":["このかいかくの","せいこうじれいは","ただんたいがさんこうにするに","たるすぐれたもでるです"]}'::jsonb, '{"expected_transcript":"この改革の成功事例は、他団体が参考にするに足る優れたモデルです。"}'::jsonb, NULL, NULL, '参考にするに足る (layak dijadikan rujukan/teladan) sering dipakai dalam studi kasus bisnis.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6e3538be-d9b5-4ece-8fd3-da7636029b3a', '030aeeba-6dff-467d-a5c2-93dd77489abc', 'd1000019-0000-0000-0000-000000000029', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena kekurangan tenaga kerja, beberapa layanan terpaksa dikurangi."', '{"romaji":"Hitode busoku ni yori, ichibu saabisu no shukushou wo yoginaku sarete imasu.","display_text":"人手不足により、一部サービスの縮小を余儀なくされています。","phonetic_breakdown":["hi-to-de","bu-so-ku","ni","yo-ri","i-chi-bu","saa-bi-su","no","shu-ku-shou","wo","yo-gi-na-ku","sa-re-te","i-ma-su"]}'::jsonb, '{"expected_transcript":"人手不足により、一部サービスの縮小を余儀なくされています。"}'::jsonb, NULL, NULL, '縮小を余儀なくされています (terpaksa diperkecil/dikurangi) lazim dipakai dalam pengumuman resmi layanan.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e1a9f767-327b-4a0a-9f5d-b84997665441', '030aeeba-6dff-467d-a5c2-93dd77489abc', 'd1000019-0000-0000-0000-000000000029', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Akibat pemadaman listrik mendadak, kereta terpaksa berhenti beroperasi."', '{"romaji":"Totsuzen no teiden de, ressha wa unten miawase wo yoginaku sareta.","display_text":"突然の停電で、列車は運転見合わせを余儀なくされた。","phonetic_breakdown":["to-tsu-zen","no","tei-den","de","re-ssha","wa","un-ten","mi-a-wa-se","wo","yo-gi-na-ku","sa-re-ta"]}'::jsonb, '{"expected_transcript":"突然の停電で、列車は運転見合わせを余儀なくされた。"}'::jsonb, NULL, NULL, '運転見合わせ (unten miawase) adalah istilah perkeretaapian Jepang untuk ''penangguhan sementara operasional kereta''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b519e5cf-4f2e-45bd-a0d0-c384f5227e3d', '030aeeba-6dff-467d-a5c2-93dd77489abc', 'd1000019-0000-0000-0000-000000000029', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Banjir besar memaksa ratusan keluarga mengungsi ke tempat penampungan."', '{"romaji":"Daikibo na kouzui ni yori, suuhyaku setai ga hinanjo e no idou wo yoginaku sareta.","display_text":"大規模な洪水により、数百世帯が避難所への移動を余儀なくされた。","phonetic_breakdown":["dai-ki-bo","na","kou-zui","ni","yo-ri","suu-hya-ku","se-tai","ga","hi-nan-jo","e","no","i-dou","wo","yo-gi-na-ku","sa-re-ta"]}'::jsonb, '{"expected_transcript":"大規模な洪水により、数百世帯が避難所への移動を余儀なくされた。"}'::jsonb, NULL, NULL, '数百世帯 (suuhyaku setai: ratusan rumah tangga) dan 避難所への移動 (perpindahan ke tempat pengungsian).', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5fcf5e8d-8758-4bb9-b80c-b3fa68f143be', '030aeeba-6dff-467d-a5c2-93dd77489abc', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Perusahaan terpaksa memangkas jumlah karyawan akibat krisis."', '{"romaji":"Keiei kiki ni yori tousha wa jin''in sakugen wo yoginaku sareta.","tokens":["当社は","された","により","どころか","を余儀なく","に至って","人員削減","経営危機"],"target_translation":"Perusahaan terpaksa memangkas jumlah karyawan akibat krisis."}'::jsonb, '["経営危機","により","当社は","人員削減","を余儀なく","された"]'::jsonb, NULL, NULL, '人員削減を余儀なくされた berarti ''terpaksa melakukan pengurangan karyawan''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('046a6665-5b82-476d-a597-fa322fb0a989', '030aeeba-6dff-467d-a5c2-93dd77489abc', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Kenaikan biaya logistik memaksa perubahan tarif pengiriman."', '{"romaji":"Butsuryuuhi no koutou ga haisouryou no kaitei wo yoginaku saseta.","tokens":["に先立ち","高騰が","改定","させた","ながら","を余儀なく","物流費の","配送料の"],"target_translation":"Kenaikan biaya logistik memaksa perubahan tarif pengiriman."}'::jsonb, '["物流費の","高騰が","配送料の","改定","を余儀なく","させた"]'::jsonb, NULL, NULL, '物流費の高騰 (lonjakan biaya logistik) sebagai subjek memaksa 配送料の改定 (revisi ongkos kirim).', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('09ef8b54-6d8e-4c3c-af97-93d484e35e93', '030aeeba-6dff-467d-a5c2-93dd77489abc', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Karena gempa susulan, pekerjaan pemulihan terpaksa ditunda."', '{"romaji":"Yoshin no eikyou de fukkyuu sagyou wa chuudan wo yoginaku sarete iru.","tokens":["中断","復旧作業は","をめぐって","余震の","影響で","を余儀なく","されている","ばかりに"],"target_translation":"Karena gempa susulan, pekerjaan pemulihan terpaksa ditunda."}'::jsonb, '["余震の","影響で","復旧作業は","中断","を余儀なく","されている"]'::jsonb, NULL, NULL, '復旧作業 (pekerjaan pemulihan) terpaksa dihentikan sementara (中断を余儀なくされている).', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8bdde171-8d69-4908-9095-3ac5fc13c2a4', '030aeeba-6dff-467d-a5c2-93dd77489abc', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Pilih pola yang tepat: 急激な人口流出により、その村の小学校は統廃合___。', '{"options":["を余儀なくされた","ずにはおかない","に足る","ともなると"],"translation":"Akibat keluarnya penduduk secara drastis, sekolah dasar di desa itu terpaksa digabungkan/ditutup.","sentence_template":"急激な人口流出により、その村の小学校は統廃合[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, NULL, NULL, '統廃合 (penggabungan dan penutupan fasilitas) + を余儀なくされた adalah isu sosial klasik Jepang.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('74044f78-fe62-41e8-a236-2233e19f7a88', '030aeeba-6dff-467d-a5c2-93dd77489abc', 'd1000019-0000-0000-0000-000000000029', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Akibat kelangkaan bahan baku impor, kami terpaksa beralih ke pemasok domestik."', '{"romaji":"Yunyuu shizai no fusoku ni yori, kokunai choutatsu e no kirikae o yoginaku saremashita.","display_text":"輸入資材の不足により、国内調達への切り替えを余儀なくされました。","phonetic_breakdown":["ゆにゅうしざいの","ふそくにより","こくないちょうたつへの","きりかえを","よぎなくされました"]}'::jsonb, '{"expected_transcript":"輸入資材の不足により、国内調達への切り替えを余儀なくされました。"}'::jsonb, NULL, NULL, '切り替えを余儀なくされました berarti terpaksa melakukan peralihan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d2314da6-01de-4a9c-9936-d6185354d5ac', '09fff75c-06e6-419e-91d7-cbe6c7c0b1e4', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼の圧倒的な演奏は、会場にいたすべての聴衆を魅了___。', '{"options":["しずにはおかない","を余儀なくされた","するに足らない","せずにはおかない"],"translation":"Permainan musiknya yang memukau pasti mempesona seluruh hadirin di gedung konser.","sentence_template":"彼の圧倒的な演奏は、会場にいたすべての聴衆を魅了[blank]。"}'::jsonb, '{"selected":"せずにはおかない"}'::jsonb, NULL, NULL, '魅了する -> 魅了せずにはおかない (''pasti memikat hati'').', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5d45ab03-1b8c-4a7b-9b04-27668f572c8e', '09fff75c-06e6-419e-91d7-cbe6c7c0b1e4', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Lengkapi kalimat analisis kebijakan berikut: 事実を隠蔽しようとする動きは、世論のさらなる反発を招か___。', '{"options":["ずにはすまない","ざるを得ない","かねない","ずにはおかない"],"translation":"Upaya menutupi fakta pasti akan mengundang penolakan publik yang lebih keras lagi.","sentence_template":"事実を隠蔽しようとする動きは、世論のさらなる反発を招か[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, NULL, NULL, '反発を招かずにはおかない menegaskan efek sosial yang pasti terjadi.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('489d0927-5c9b-4ecc-b852-1a4b28904a8a', '09fff75c-06e6-419e-91d7-cbe6c7c0b1e4', 'd1000019-0000-0000-0000-000000000034', 'listening', 'listening_choice', 'Dengarkan komentar kritikus film berikut. Apa dampak dari adegan penutup film itu?', '{"options":[{"id":"opt_1","text":"Adegan penutupnya pasti menorehkan kesan kuat di hati penonton"},{"id":"opt_2","text":"Adegan penutupnya sangat bising dan sulit diikuti"},{"id":"opt_3","text":"Penonton langsung melupakan film itu begitu keluar bioskop"},{"id":"opt_4","text":"Adegan penutupnya dipotong dari versi rilis internasional"}],"audio_text":"静寂の中に深い余韻を残すラストシーンは、観る者の心に強い印象を刻まずにはおかない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '強い印象を刻まずにはおかない berarti ''pasti mengukir kesan yang kuat''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3e23ec18-e5d5-40ef-9158-7a45b836bef1', '09fff75c-06e6-419e-91d7-cbe6c7c0b1e4', 'd1000019-0000-0000-0000-000000000034', 'listening', 'listening_choice', 'Dengarkan ulasan ekonomi berikut. Apa prediksi pembicara terhadap keputusan bank sentral?', '{"options":[{"id":"opt_1","text":"Investor tidak akan bereaksi terhadap kenaikan suku bunga"},{"id":"opt_2","text":"Bank sentral memutuskan menurunkan suku bunga menjadi nol"},{"id":"opt_3","text":"Keputusan kenaikan suku bunga pasti berpengaruh besar pada keputusan investor domestik dan asing"},{"id":"opt_4","text":"Pengumuman suku bunga ditunda hingga kuartal berikutnya"}],"audio_text":"中央銀行による今回の利上げ決定は、国内外の投資家の判断に多大な影響を与えずにはおかないだろう。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '多大な影響を与えずにはおかないだろう berarti ''pasti akan membawa dampak sangat besar''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6cf274de-e329-4b53-bd10-7f1f04a331a3', '09fff75c-06e6-419e-91d7-cbe6c7c0b1e4', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Karya lukis yang penuh emosi itu pasti menggetarkan jiwa penikmatnya."', '{"romaji":"Jounetsu ni michita sono kaiga wa miru mono no tamashii wo yusaburazu ni wa okanai.","tokens":["とはいえ","魂を","揺さぶらずにはおかない","情熱に","なりに","満ちた","その絵画は","観る者の"],"target_translation":"Karya lukis yang penuh emosi itu pasti menggetarkan jiwa penikmatnya."}'::jsonb, '["情熱に","満ちた","その絵画は","観る者の","魂を","揺さぶらずにはおかない"]'::jsonb, NULL, NULL, '魂を揺さぶる (mengguncang/menggetarkan jiwa) -> 揺さぶらずにはおかない.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d8bc6e94-20c0-4633-8ebb-92b3ea2eebd3', '09fff75c-06e6-419e-91d7-cbe6c7c0b1e4', 'd1000019-0000-0000-0000-000000000034', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Keputusan bersejarah ini pasti akan mengubah arah masa depan negara."', '{"romaji":"Kono rekishiteki na ketsudan wa, kuni no shourai wo ookiku sayuu sezu ni wa okanai.","display_text":"この歴史的な決断は、国の将来を大きく左右せずにはおかない。","phonetic_breakdown":["ko-no","re-ki-shi-te-ki","na","ke-tsu-dan","wa","ku-ni","no","shou-rai","wo","oo-ki-ku","sa-yuu","se-zu","ni","wa","o-ka-nai"]}'::jsonb, '{"expected_transcript":"この歴史的な決断は、国の将来を大きく左右せずにはおかない。"}'::jsonb, NULL, NULL, '左右する (sayuu suru: menentukan/memengaruhi arah secara besar) -> 左右せずにはおかない.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a5e7a26e-24f7-40ad-ac0c-1ec7b32c8e3e', '09fff75c-06e6-419e-91d7-cbe6c7c0b1e4', 'd1000019-0000-0000-0000-000000000034', 'listening', 'listening_choice', 'Dengarkan komentar kritikus sosial. Apa dampak urbanisasi ekstrem yang disoroti?', '{"options":[{"id":"opt_1","text":"Melemahnya ikatan komunitas memperkuat gotong royong saat bencana"},{"id":"opt_2","text":"Tidak ada hubungan antara komunitas lokal dan kesiapsiagaan bencana"},{"id":"opt_3","text":"Melemahnya komunitas lokal pasti akan memberi dampak negatif serius pada sistem saling tolong saat bencana"},{"id":"opt_4","text":"Semua bencana alam dapat dicegah oleh pemerintah daerah"}],"audio_text":"地域コミュニティの希薄化は、災害時の助け合い体制に深刻な影を落とさずにはおかない。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '影を落とさずにはおかない berarti pasti meninggalkan bayang-bayang/dampak buruk serius.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bdff9c68-92fe-4b3f-81c4-5d2482c47f31', '09fff75c-06e6-419e-91d7-cbe6c7c0b1e4', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Kegigihan atlet difabel itu pasti akan menginspirasi generasi muda."', '{"romaji":"Kare no fukutsu no seishin wa wakai sedai o furuitatasezu ni wa okanai.","tokens":["若い世代を","ずには","ない。","ともなると、","彼の不屈の精神は、","奮い立たせ","おか","奮い立たせた"],"target_translation":"Kegigihan atlet difabel itu pasti akan menginspirasi generasi muda."}'::jsonb, '["彼の不屈の精神は、","若い世代を","奮い立たせ","ずには","おか","ない。"]'::jsonb, NULL, NULL, '奮い立たせる (membangkitkan semangat) -> 奮い立たせずにはおかない.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fc948c40-c950-405f-ae2b-4282777add47', '0db7ce8d-d908-4752-ada3-98be543827ad', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 企業の社長___、一言の発言が株価に大きな影響を与えかねない。', '{"options":["なりに","をもって","ともなると","とはいえ"],"translation":"Jika sudah sampai level direktur utama perusahaan, sepatah kata saja bisa berdampak besar pada harga saham.","sentence_template":"企業の社長[blank]、一言の発言が株価に大きな影響を与えかねない。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, NULL, NULL, 'Kata benda + ともなると menyatakan bahwa jika sudah mencapai status/skala/tahap tinggi tersebut, wajar muncul konsekuensi atau standar tinggi.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cf84a85f-591e-4dc5-972b-4a120a81ebb5', '0db7ce8d-d908-4752-ada3-98be543827ad', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Pilih pola yang tepat untuk konteks skala proyek: 総工費が数百億円規模のプロジェクト___、関係省庁との調整だけで数年を要する。', '{"options":["ともなれば","に至っては","をよそに","に足らず"],"translation":"Kalau sudah proyek berskala puluhan miliar yen, koordinasi dengan kementerian terkait saja membutuhkan beberapa tahun.","sentence_template":"総工費が数百億円規模のプロジェクト[blank]、関係省庁との調整だけで数年を要する。"}'::jsonb, '{"selected":"ともなれば"}'::jsonb, NULL, NULL, '～ともなれば memiliki makna setara dengan ～ともなると, menyoroti skala besar proyek.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('393b8345-26e5-40bc-92e1-55b34ee1b7a0', '0db7ce8d-d908-4752-ada3-98be543827ad', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Lengkapi kalimat mengenai tahapan ujian berikut: JLPTのN1レベル___、新聞の社説や専門的な論説文を読み解く力が求められる。', '{"options":["極まりなく","ずにはおかない","を余儀なく","ともなると"],"translation":"Jika sudah sampai level JLPT N1, dituntut kemampuan memahami tajuk rencana koran dan esai ilmiah.","sentence_template":"JLPTのN1レベル[blank]、新聞の社説や専門的な論説文を読み解く力が求められる。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, NULL, NULL, 'N1レベルともなると menekankan tingginya ekspektasi kemampuan pada level tertinggi.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('295a75e8-f6ba-4a62-8bcb-549dca824829', '0db7ce8d-d908-4752-ada3-98be543827ad', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah memasuki bulan Desember, kota menjadi sangat sibuk."', '{"romaji":"Juunigatsu to mo naru to machi wa ikki ni awatadashiku naru.","tokens":["なりに","をもって","ともなると","街は","慌ただしく","十二月","なる","一気に"],"target_translation":"Jika sudah memasuki bulan Desember, kota menjadi sangat sibuk."}'::jsonb, '["十二月","ともなると","街は","一気に","慌ただしく","なる"]'::jsonb, NULL, NULL, '～ともなると juga dapat dipakai untuk musim/waktu tertentu yang menandai perubahan suasana khas.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('67716d72-8c05-43f8-a4ed-bc6bc5d20b64', '0db7ce8d-d908-4752-ada3-98be543827ad', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau sudah sekelas pakar internasional, jadwalnya penuh sepanjang tahun."', '{"romaji":"Sekaiteki na senmonka to mo nareba yotei ga ichinen saki made umatte iru.","tokens":["埋まっている","とはいえ","に至って","一年先まで","世界的な","予定が","ともなれば","専門家"],"target_translation":"Kalau sudah sekelas pakar internasional, jadwalnya penuh sepanjang tahun."}'::jsonb, '["世界的な","専門家","ともなれば","予定が","一年先まで","埋まっている"]'::jsonb, NULL, NULL, '世界的な専門家ともなれば menekankan status prestisius yang membawa kesibukan luar biasa.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0aff2e5a-3d71-4577-a062-3a31ae10b70b', '0db7ce8d-d908-4752-ada3-98be543827ad', 'd1000019-0000-0000-0000-000000000035', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjadi cabang utama, jumlah pengunjung harian mencapai puluhan ribu."', '{"romaji":"Toshin no kikanten to mo naru to, ichinichi no raiten kyakusuu wa suumannin ni oyobu.","display_text":"都心の旗艦店ともなると、一日の来店客数は数万人に及ぶ。","phonetic_breakdown":["to-shin","no","ki-kan-ten","to","mo","na-ru","to","i-chi-ni-chi","no","rai-ten","kya-ku-suu","wa","suu-man-nin","ni","o-yo-bu"]}'::jsonb, '{"expected_transcript":"都心の旗艦店ともなると、一日の来店客数は数万人に及ぶ。"}'::jsonb, NULL, NULL, '旗艦店 (kikanten: toko flagship) dan 数万人に及ぶ (mencapai puluhan ribu orang).', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8fedd952-7bd4-4144-ab83-b9c99508f495', '0db7ce8d-d908-4752-ada3-98be543827ad', 'd1000019-0000-0000-0000-000000000035', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa poin yang ditekankan dengan ～ともなると?', '{"options":[{"id":"opt_1","text":"Pemain inti bisbol profesional bahkan di luar musim tetap berlatih tanpa henti sesuai standar levelnya"},{"id":"opt_2","text":"Pemain bisbol profesional tidak pernah berlatih di luar musim"},{"id":"opt_3","text":"Hanya pemain amatir yang perlu berlatih keras"},{"id":"opt_4","text":"Musim bisbol berlangsung hanya satu minggu"}],"audio_text":"プロ野球の主力選手ともなると、オフシーズンでも休む間もなくトレーニングを続ける。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '主力選手ともなると menyoroti dedikasi luar biasa yang menyertai status pemain inti.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0a66d279-0b24-4bbc-9871-36a845994155', '0db7ce8d-d908-4752-ada3-98be543827ad', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 子どもが三人___、毎月の食費や教育費の負担もかなりの額になる。', '{"options":["ともなると","なりに","をもって","いかんによらず"],"translation":"Jika sudah memiliki tiga orang anak, beban biaya makan dan pendidikan tiap bulan pun mencapai jumlah yang cukup besar.","sentence_template":"子どもが三人[blank]、毎月の食費や教育費の負担もかなりの額になる。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, NULL, NULL, 'Jumlah/skala (三人) + ともなると menyatakan konsekuensi yang tak terhindarkan saat mencapai skala itu.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b1d69a3e-0948-4666-aeaa-4de7eac75648', '10839be7-cc1b-4cf5-9de3-1a6a61896149', 'd1000019-0000-0000-0000-000000000036', 'listening', 'listening_choice', 'Dengarkan kutipan pedoman medis. Prinsip apa yang dipegang rumah sakit darurat tersebut?', '{"options":[{"id":"opt_1","text":"Di unit gawat darurat, penanganan dilakukan sesuai tingkat kegawatan nyawa tanpa memandang status sosial atau kondisi ekonomi pasien"},{"id":"opt_2","text":"Pasien kaya selalu dilayani lebih dahulu meski tidak gawat"},{"id":"opt_3","text":"Rumah sakit hanya menerima pasien dengan asuransi swasta"},{"id":"opt_4","text":"Unit gawat darurat tutup pada akhir pekan"}],"audio_text":"救急医療の現場では、患者の社会的地位や経済状況のいかんによらず、命の緊急度に応じて処置を行う。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '社会的地位や経済状況のいかんによらず menyatakan prinsip etika medis universal.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d0c3c907-3e1a-4cd2-900a-e0f39127c9ad', '10839be7-cc1b-4cf5-9de3-1a6a61896149', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang pengalaman kerja sebelumnya, semua staf baru wajib mengikuti pelatihan kepatuhan."', '{"romaji":"Keiken no ikan ni yorazu, shain wa konpuraiansu kenshuu no jukou ga hissu da.","tokens":["いかん","全社員は","受講が必須だ。","受講した。","経験の","によらず、","コンプライアンス研修の","なりに、"],"target_translation":"Tanpa memandang pengalaman kerja sebelumnya, semua staf baru wajib mengikuti pelatihan kepatuhan."}'::jsonb, '["経験の","いかん","によらず、","全社員は","コンプライアンス研修の","受講が必須だ。"]'::jsonb, NULL, NULL, '経験のいかんによらず (tanpa memandang ada tidaknya pengalaman) umum di aturan SDM.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f2ce0165-22b8-4f00-ab00-ee9f6360eed8', '10839be7-cc1b-4cf5-9de3-1a6a61896149', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 金額の___、取引先からの不適切な金品の受領は就業規則で禁じられている。', '{"options":["いかんによらず","極まりなく","ともなると","に足らず"],"translation":"Tanpa memandang besar kecilnya nominal, penerimaan uang atau barang tak pantas dari mitra bisnis dilarang oleh peraturan kerja.","sentence_template":"金額の[blank]、取引先からの不適切な金品の受領は就業規則で禁じられている。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, NULL, NULL, '金額のいかんによらず menegaskan kebijakan nol toleransi terhadap gratifikasi.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ef940878-1a64-4502-87bd-3734ac61afb6', '10839be7-cc1b-4cf5-9de3-1a6a61896149', 'd1000019-0000-0000-0000-000000000036', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang skala perusahaan, kepatuhan terhadap hukum lingkungan adalah kewajiban mutlak."', '{"romaji":"Kigyou kibo no ikan ni yorazu, kankyou hourei no junshu wa zettaiteki na gimu desu.","display_text":"企業規模のいかんによらず、環境法令の遵守は絶対的な義務です。","phonetic_breakdown":["きぎょうきぼの","いかんによらず","かんきょうほうれいの","じゅんしゅは","ぜったいてきなぎむです"]}'::jsonb, '{"expected_transcript":"企業規模のいかんによらず、環境法令の遵守は絶対的な義務です。"}'::jsonb, NULL, NULL, '法令の遵守 (kepatuhan terhadap peraturan perundang-undangan) adalah istilah kunci compliance N1.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('11caae06-e52f-4586-a02f-f61b770dd07c', '10839be7-cc1b-4cf5-9de3-1a6a61896149', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 勝敗の___、最後まで全力を出し切った選手たちに拍手を送りたい。', '{"options":["いかんによらず","とはいえ","をもって","に至って"],"translation":"Tanpa memandang menang atau kalah, saya ingin memberikan tepuk tangan kepada para atlet yang mengerahkan segenap tenaga hingga akhir.","sentence_template":"勝敗の[blank]、最後まで全力を出し切った選手たちに拍手を送りたい。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, NULL, NULL, '勝敗のいかんによらず (menang ataupun kalah) memuji sportivitas atlet.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ff9d76b5-bc85-4bde-acf4-b4a80236513b', '10839be7-cc1b-4cf5-9de3-1a6a61896149', 'd1000019-0000-0000-0000-000000000036', 'listening', 'listening_choice', 'Dengarkan pengumuman kebijakan pengembalian barang. Dalam kondisi apa barang rusak dapat ditukar?', '{"options":[{"id":"opt_1","text":"Barang hanya bisa ditukar jika dibeli di kantor pusat"},{"id":"opt_2","text":"Produk cacat produksi tidak dapat ditukar"},{"id":"opt_3","text":"Pelanggan harus membayar biaya tambahan untuk penukaran"},{"id":"opt_4","text":"Tanpa memandang di cabang mana produk dibeli, produk yang terbukti cacat produksi akan diganti secara gratis"}],"audio_text":"購入店舗のいかんによらず、製造上の欠陥が確認された製品は無償で交換いたします。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '購入店舗のいかんによらず memberikan jaminan layanan konsumen menyeluruh.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9faf8797-ebb4-400b-a1c6-9e792c5bd829', '10839be7-cc1b-4cf5-9de3-1a6a61896149', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang latar belakang budaya, setiap pendapat dihargai dalam forum ini."', '{"romaji":"Bunka-teki haikei no ikan ni yorazu, subete no iken ga sonchou sareru.","tokens":["いかん","すべての意見が","される。","を余儀なくされ、","文化的背景の","によらず、","尊重","尊重した"],"target_translation":"Tanpa memandang latar belakang budaya, setiap pendapat dihargai dalam forum ini."}'::jsonb, '["文化的背景の","いかん","によらず、","すべての意見が","尊重","される。"]'::jsonb, NULL, NULL, '文化的背景のいかんによらず menegaskan inklusivitas forum internasional.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('409a79c6-e83f-42aa-99cf-8ec4644d3dfe', '10839be7-cc1b-4cf5-9de3-1a6a61896149', 'd1000019-0000-0000-0000-000000000036', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang alasan apa pun, pelanggaran kerahasiaan data akan dikenai sanksi berat."', '{"romaji":"Riyuu no ikan ni yorazu, kimitsu jouhou no fusei mochidashi wa genbatsu no taishou to narimasu.","display_text":"理由のいかんによらず、機密情報の不正持ち出しは厳罰の対象となります。","phonetic_breakdown":["りゆうの","いかんによらず","きみつじょうほうの","ふせいもちだしは","げんばつのたいしょうとなります"]}'::jsonb, '{"expected_transcript":"理由のいかんによらず、機密情報の不正持ち出しは厳罰の対象となります。"}'::jsonb, NULL, NULL, '厳罰の対象となる (menjadi sasaran sanksi berat) adalah gaya bahasa aturan keamanan informasi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ba3d9195-26dd-4e48-8a32-238583945e1c', '13a95fdc-e295-4731-b9d4-eae2b3c8f330', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan berikut. Apa yang berubah mulai tanggal 31 Maret?', '{"options":[{"id":"opt_1","text":"Jam layanan telepon diperpanjang menjadi 24 jam"},{"id":"opt_2","text":"Layanan pertanyaan via telepon ditiadakan per 31 Maret"},{"id":"opt_3","text":"Nomor telepon kantor pusat diganti dengan nomor bebas pulsa"},{"id":"opt_4","text":"Seluruh layanan daring ditutup sementara hingga akhir Maret"}],"audio_text":"誠に勝手ながら、三月三十一日をもちまして、電話によるお問い合わせ窓口を廃止させていただきます。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '電話によるお問い合わせ窓口を廃止させていただきます berarti ''menghapus/menutup loket pertanyaan melalui telepon''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b776eae3-c2f5-4652-bd53-9fd6568385cf', '13a95fdc-e295-4731-b9d4-eae2b3c8f330', NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan pejabat berikut. Bagaimana keputusan pengadilan tersebut diterima?', '{"options":[{"id":"opt_1","text":"Menolak putusan pengadilan dan mengabaikan instruksinya"},{"id":"opt_2","text":"Meminta penundaan sidang hingga tahun depan"},{"id":"opt_3","text":"Menerima putusan dengan sungguh-sungguh dan menangani tindak lanjutnya dengan iktikad baik"},{"id":"opt_4","text":"Mengajukan tuntutan balik terhadap panitera pengadilan"}],"audio_text":"裁判所の判決を厳粛に受け止め、誠意をもって今後の対応に当たる所存です。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '厳粛に受け止め (menerima dengan khidmat/sungguh-sungguh) dan 誠意をもって...に当たる (menangani dengan ketulusan).', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7dac60be-0f57-4d9c-848c-592dfaf1b595', '13a95fdc-e295-4731-b9d4-eae2b3c8f330', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman universitas berikut. Bagaimana cara pendaftaran mata kuliah yang sah?', '{"options":[{"id":"opt_1","text":"Dianggap selesai hanya dengan menghadiri kuliah pertama"},{"id":"opt_2","text":"Harus menyerahkan formulir kertas secara langsung ke dekan"},{"id":"opt_3","text":"Dilakukan secara otomatis tanpa perlu tindakan mahasiswa"},{"id":"opt_4","text":"Dianggap selesai setelah mengirimkan formulir daring yang ditentukan"}],"audio_text":"履修登録は、所定のオンラインフォームの送信をもって完了とみなされます。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '送信をもって完了とみなされます berarti ''dianggap selesai dengan terkirimnya formulir tersebut''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('90243e17-bd0e-48ed-8806-dce6964a5968', '13a95fdc-e295-4731-b9d4-eae2b3c8f330', NULL, 'reading', 'fill_blank', 'Lengkapi ketentuan kontrak berikut: 本契約は、双方の署名および捺印___発効するものとする。', '{"options":["なりに","とはいえ","をもって","を余儀なく"],"translation":"Kontrak ini mulai berlaku secara resmi dengan adanya tanda tangan dan cap dari kedua belah pihak.","sentence_template":"本契約は、双方の署名および捺印[blank]発効するものとする。"}'::jsonb, '{"selected":"をもって"}'::jsonb, NULL, NULL, '署名および捺印をもって発効する adalah frasa legal standar untuk syarat mulai berlakunya perjanjian.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d9dee9de-2e90-4f05-9842-6de639f621f0', '13a95fdc-e295-4731-b9d4-eae2b3c8f330', NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat untuk pernyataan pembukaan: ただいまの開会宣言___、国際シンポジウムを開始いたします。', '{"options":["に反しまして","をめぐりまして","をもちまして","に至りまして"],"translation":"Dengan deklarasi pembukaan barusan, simposium internasional resmi dimulai.","sentence_template":"ただいまの開会宣言[blank]、国際シンポジウムを開始いたします。"}'::jsonb, '{"selected":"をもちまして"}'::jsonb, NULL, NULL, '～をもちまして menandai titik dimulainya suatu acara resmi secara khidmat.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('214aefca-c4a8-4b1d-b206-cd0440b6d3b2', '13a95fdc-e295-4731-b9d4-eae2b3c8f330', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat formal berikut: 当社は、公正な取引と法令遵守___社会の信頼に応えてまいります。', '{"options":["をもって","に足らず","をよそに","ともなると"],"translation":"Perusahaan kami akan menjawab kepercayaan masyarakat melalui transaksi yang adil dan kepatuhan hukum.","sentence_template":"当社は、公正な取引と法令遵守[blank]社会の信頼に応えてまいります。"}'::jsonb, '{"selected":"をもって"}'::jsonb, NULL, NULL, '～をもって di sini bermakna ''dengan/melalui sarana (transaksi adil dan kepatuhan hukum)''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('01f60dc2-82d5-4de3-ad85-93c326b52a50', '13a95fdc-e295-4731-b9d4-eae2b3c8f330', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Kami berupaya memecahkan masalah melalui dialog yang sabar dan terbuka."', '{"romaji":"Taiwa o motte, mondai no heiwa-teki na kaiketsu o hakaru.","tokens":["対話","問題の平和的な","図る。","とはいえ、","粘り強い","をもって、","解決を","図った"],"target_translation":"Kami berupaya memecahkan masalah melalui dialog yang sabar dan terbuka."}'::jsonb, '["粘り強い","対話","をもって、","問題の平和的な","解決を","図る。"]'::jsonb, NULL, NULL, '対話をもって (dengan sarana dialog) lazim dalam pernyataan diplomatik dan korporasi.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('608fa6ff-4632-4141-8ab3-1f49ec59f0a7', '13a95fdc-e295-4731-b9d4-eae2b3c8f330', 'd1000019-0000-0000-0000-000000000031', 'listening', 'listening_choice', 'Dengarkan pengumuman universitas. Bagaimana hasil kelulusan diumumkan?', '{"options":[{"id":"opt_1","text":"Hasil kelulusan dikirim melalui telepon satu per satu"},{"id":"opt_2","text":"Pengumuman kelulusan dilakukan melalui penayangan nomor ujian di situs resmi universitas"},{"id":"opt_3","text":"Peserta harus datang ke kantor pos pusat"},{"id":"opt_4","text":"Hasil kelulusan tidak akan diumumkan kepada publik"}],"audio_text":"合格発表は、大学公式サイトへの受験番号の掲載をもって行います。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '掲載をもって行います menyatakan mekanisme resmi pengumuman.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fd92afaf-6677-448c-b78b-12da53a95afe', '1a057cd2-bf97-4c9d-8039-e839d22e9689', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼は口数こそ少ないが、彼___周囲の仲間を気遣っている。', '{"options":["極まりなく","をもって","に至って","なりに"],"translation":"Dia memang sedikit bicara, tetapi dengan caranya sendiri ia memperhatikan rekan-rekan di sekitarnya.","sentence_template":"彼は口数こそ少ないが、彼[blank]周囲の仲間を気遣っている。"}'::jsonb, '{"selected":"なりに"}'::jsonb, NULL, NULL, '彼なりに menunjukkan bahwa meskipun tidak tampak menonjol, ia peduli dengan caranya sendiri.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4b0c7a83-2f4f-47d9-80a6-c938513b8e33', '1a057cd2-bf97-4c9d-8039-e839d22e9689', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 失敗に終わったとはいえ、その経験から得た自分___教訓は大きい。', '{"options":["ともなると","なりの","ならではの","なりに"],"translation":"Meskipun berakhir gagal, pelajaran tersendiri yang saya petik dari pengalaman itu sangat besar.","sentence_template":"失敗に終わったとはいえ、その経験から得た自分[blank]教訓は大きい。"}'::jsonb, '{"selected":"なりの"}'::jsonb, NULL, NULL, '自分なりの教訓 (pelajaran tersendiri bagi diri saya) memakai ～なりの karena diikuti kata benda 教訓.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8f1a5ced-6984-4556-8a2b-aa6402b75217', '1a057cd2-bf97-4c9d-8039-e839d22e9689', 'd1000019-0000-0000-0000-000000000033', 'listening', 'listening_choice', 'Dengarkan nasihat mentor berikut. Apa inti pesan yang ingin disampaikan?', '{"options":[{"id":"opt_1","text":"Kita harus selalu membandingkan diri dengan orang yang paling sukses"},{"id":"opt_2","text":"Terus maju selangkah demi selangkah sesuai kondisi diri sendiri membawa pertumbuhan"},{"id":"opt_3","text":"Jika kondisi belum ideal, sebaiknya berhenti berusaha sementara"},{"id":"opt_4","text":"Pertumbuhan hanya ditentukan oleh bakat bawaan sejak lahir"}],"audio_text":"他人と比べるのではなく、今の自分の状況なりに一歩ずつ前進し続けることが成長につながる。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '今の自分の状況なりに一歩ずつ前進し続ける berarti ''terus melangkah maju sesuai situasi diri saat ini''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4bb7dad6-1c37-414d-90aa-cb6d4cbfd421', '1a057cd2-bf97-4c9d-8039-e839d22e9689', 'd1000019-0000-0000-0000-000000000033', 'listening', 'listening_choice', 'Dengarkan komentar mengenai proyek desa berikut. Apa yang dicapai oleh warga setempat?', '{"options":[{"id":"opt_1","text":"Proyek dibatalkan karena tidak ada dana sama sekali"},{"id":"opt_2","text":"Pemerintah pusat mengirimkan ratusan tenaga ahli ke desa"},{"id":"opt_3","text":"Warga menyerahkan seluruh produksi kepada perusahaan asing"},{"id":"opt_4","text":"Di tengah keterbatasan dana dan tenaga, warga urun gagasan melahirkan produk khas menarik"}],"audio_text":"資金や人手が乏しいなら乏しいなりに、住民たちが知恵を出し合って魅力的な特産品を生み出した。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '乏しいなら乏しいなりに (sesuai kondisi serba terbatas) warga tetap melahirkan produk unggulan.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e1e62fa3-0df0-41ce-9e1f-572aa9ec0d78', '1a057cd2-bf97-4c9d-8039-e839d22e9689', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Setiap departemen telah menyiapkan rencana perbaikan dengan caranya sendiri."', '{"romaji":"Kaku busho ga sorezore nari ni kaizensaku wo matomete kita.","tokens":["きた","とはいえ","に足る","それぞれ","なりに","各部署が","まとめて","改善策を"],"target_translation":"Setiap departemen telah menyiapkan rencana perbaikan dengan caranya sendiri."}'::jsonb, '["各部署が","それぞれ","なりに","改善策を","まとめて","きた"]'::jsonb, NULL, NULL, 'それぞれなりに berarti ''masing-masing dengan caranya sendiri''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cbea38e4-db93-4170-b893-af1e551138f7', '1a057cd2-bf97-4c9d-8039-e839d22e9689', 'd1000019-0000-0000-0000-000000000033', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Beban kerja yang tinggi memang berat, tetapi ada kepuasan tersendiri di dalamnya."', '{"romaji":"Sekinin ga omoi bun, soko ni wa soko nari no yarigai ga aru.","display_text":"責任が重い分、そこにはそこなりのやりがいがある。","phonetic_breakdown":["se-ki-nin","ga","o-moi","bun","so-ko","ni","wa","so-ko","na-ri","no","ya-ri-gai","ga","a-ru"]}'::jsonb, '{"expected_transcript":"責任が重い分、そこにはそこなりのやりがいがある。"}'::jsonb, NULL, NULL, 'そこにはそこなりのやりがいがある menunjukkan bahwa setiap tanggung jawab membawa rasa bermakna tersendiri.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('89f8363c-d227-4425-b605-5b5817f1c612', '1a057cd2-bf97-4c9d-8039-e839d22e9689', 'd1000019-0000-0000-0000-000000000033', 'listening', 'listening_choice', 'Dengarkan wawancara direktur seni. Apa filosofi beliau dalam membimbing desainer muda?', '{"options":[{"id":"opt_1","text":"Semua desainer muda harus meniru satu gaya yang sama"},{"id":"opt_2","text":"Desainer muda tidak boleh menyampaikan ide sendiri"},{"id":"opt_3","text":"Beliau berharap tiap desainer memperluas daya ekspresi sesuai kepekaan masing-masing tanpa dikekang cetakan kaku"},{"id":"opt_4","text":"Beliau hanya menerima desainer yang sudah berpengalaman dua puluh tahun"}],"audio_text":"型にはめるのではなく、それぞれの感性なりに表現の幅を広げてほしいと願っています。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'それぞれの感性なりに berarti sesuai sensitivitas estetika masing-masing.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('433fb4cc-0c32-4343-b909-f07da12c12c2', '1a057cd2-bf97-4c9d-8039-e839d22e9689', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun hasilnya belum maksimal, saya sudah berupaya sebaik mungkin dengan cara saya."', '{"romaji":"Kekka wa manzoku dewa nai ga, watashi nari ni zenryoku o tsukushita.","tokens":["不十分だが、","なりに","尽くした。","を余儀なくされた。","結果は","私","全力を","なりの"],"target_translation":"Meskipun hasilnya belum maksimal, saya sudah berupaya sebaik mungkin dengan cara saya."}'::jsonb, '["結果は","不十分だが、","私","なりに","全力を","尽くした。"]'::jsonb, NULL, NULL, '私なりに全力を尽くした (saya sudah mengerahkan segenap tenaga sesuai kapasitas saya).', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f4dfe08-25f6-464c-b69b-5d708debf2d8', '1c7c53cc-ce76-40d4-8fe3-522cec985e5b', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Lengkapi kalimat refleksi berikut: 経験が浅い新入社員でも、彼___工夫を重ねて業務に取り組んでいる。', '{"options":["なりに","をもって","に至って","極まりなく"],"translation":"Meskipun masih karyawan baru yang minim pengalaman, ia berusaha dengan caranya sendiri yang penuh kreativitas.","sentence_template":"経験が浅い新入社員でも、彼[blank]工夫を重ねて業務に取り組んでいる。"}'::jsonb, '{"selected":"なりに"}'::jsonb, NULL, NULL, '～なりに berarti ''dengan cara/kapasitas yang sesuai dengan subjeknya sendiri''.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('90da6b54-7efb-421d-93fd-4a22a282ae78', '1c7c53cc-ce76-40d4-8fe3-522cec985e5b', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Pilih bentuk penyambung kata benda yang tepat: 完璧ではなくても、私___答えを論文にまとめて提出した。', '{"options":["なりの","なりに","なる","なれば"],"translation":"Meskipun tidak sempurna, saya merangkum jawaban versi saya sendiri ke dalam makalah dan menyerahkannya.","sentence_template":"完璧ではなくても、私[blank]答えを論文にまとめて提出した。"}'::jsonb, '{"selected":"なりの"}'::jsonb, NULL, NULL, 'Sebelum kata benda (答え), digunakan bentuk ～なりの.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('907452ec-6280-4627-b582-d1b814fdc48f', '1c7c53cc-ce76-40d4-8fe3-522cec985e5b', 'd1000019-0000-0000-0000-000000000033', 'listening', 'listening_choice', 'Dengarkan komentar kepala departemen tentang anggota baru. Apa sikap beliau?', '{"options":[{"id":"opt_1","text":"Ia ingin menegur anggota baru karena tidak berusaha"},{"id":"opt_2","text":"Ia ingin mengapresiasi usaha gigih anggota baru tersebut sesuai kapasitasnya meski hasilnya masih kecil"},{"id":"opt_3","text":"Ia berencana memindahkan anggota baru ke divisi lain"},{"id":"opt_4","text":"Ia menilai anggota baru sudah melampaui semua senior"}],"audio_text":"まだ成果は小さいかもしれないが、彼女は彼女なりに毎日必死に努力しているのを評価したい。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '彼女は彼女なりに menunjukkan empati pemimpin yang menghargai usaha sesuai tahap kemampuan individu.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b76986c4-ece8-4439-b4bc-e4a4431fc177', '1c7c53cc-ce76-40d4-8fe3-522cec985e5b', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Setiap generasi memiliki cara pandang dan kesulitannya masing-masing."', '{"romaji":"Dono sedai ni mo, sono sedai nari no nayami ga aru.","tokens":["その世代","悩みが","ものだ。","とはいえ、","どの世代にも、","なりの","ある","なりに"],"target_translation":"Setiap generasi memiliki cara pandang dan kesulitannya masing-masing."}'::jsonb, '["どの世代にも、","その世代","なりの","悩みが","ある","ものだ。"]'::jsonb, NULL, NULL, 'その世代なりの悩み (kesulitan khas generasi tersebut) menggunakan ～なりの + kata benda.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dff24a79-a9e5-4e3c-9b9e-c01c9ea13a2a', '1c7c53cc-ce76-40d4-8fe3-522cec985e5b', 'd1000019-0000-0000-0000-000000000033', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun kemampuan saya terbatas, saya ingin berkontribusi dengan cara saya sendiri."', '{"romaji":"Biryoku dewa arimasu ga, watashi nari ni seiippai kouken shitai to kangaete orimasu.","display_text":"微力ではありますが、私なりに精一杯貢献したいと考えております。","phonetic_breakdown":["びりょくではありますが","わたしなりに","せいいっぱい","こうけんしたいと","かんがえております"]}'::jsonb, '{"expected_transcript":"微力ではありますが、私なりに精一杯貢献したいと考えております。"}'::jsonb, NULL, NULL, '私なりに精一杯 (sekuat tenaga dengan cara saya sendiri) adalah ungkapan rendah hati profesional.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9d9203d3-22e1-4c4f-be89-cf6e405e48ef', '1c7c53cc-ce76-40d4-8fe3-522cec985e5b', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予算が少ないプロジェクトには、少ない___進め方や面白さがある。', '{"options":["なりの","をもって","いかんによらず","ずにはおかない"],"translation":"Pada proyek beranggaran kecil, ada cara menjalankan dan daya tarik tersendiri sesuai keterbatasannya.","sentence_template":"予算が少ないプロジェクトには、少ない[blank]進め方や面白さがある。"}'::jsonb, '{"selected":"なりの"}'::jsonb, NULL, NULL, 'Kata sifat-i (少ない) + なりの menyatakan kesesuaian dengan kondisi tersebut.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f99fa73f-39df-4995-ab76-41527ff239ed', '1c7c53cc-ce76-40d4-8fe3-522cec985e5b', 'd1000019-0000-0000-0000-000000000033', 'listening', 'listening_choice', 'Dengarkan wawancara penulis novel. Bagaimana ia memandang kritik pembaca?', '{"options":[{"id":"opt_1","text":"Ia mengabaikan semua masukan dari pembaca"},{"id":"opt_2","text":"Ia berhenti menulis novel karena kritik"},{"id":"opt_3","text":"Ia memaknai kritik tajam sebagai wujud harapan dan keterikatan pembaca dengan caranya sendiri"},{"id":"opt_4","text":"Ia hanya membaca ulasan yang memuji karyanya"}],"audio_text":"厳しい意見であっても、読者なりの期待や作品への愛着があるからこそだと受け止めている。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '読者なりの期待 berarti harapan khas dari sudut pandang pembaca.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('94ebc242-7283-41b9-8085-70d0cfe8c9f9', '1c7c53cc-ce76-40d4-8fe3-522cec985e5b', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Meski tidak mahir berbicara di depan umum, ia menyampaikan pesan dengan caranya sendiri."', '{"romaji":"Hanashi ga jouzu dewa nakutemo, kare nari ni omoi o tsutaeta.","tokens":["彼","思いを","のだ。","ともなると、","話が上手ではなくても、","なりに","伝えた","なりの"],"target_translation":"Meski tidak mahir berbicara di depan umum, ia menyampaikan pesan dengan caranya sendiri."}'::jsonb, '["話が上手ではなくても、","彼","なりに","思いを","伝えた","のだ。"]'::jsonb, NULL, NULL, '彼なりに (dengan caranya sendiri) menekankan ketulusan penyampaian.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('edbe97f8-03c6-42c4-b360-efa4d9944f5c', '23f48a6f-781e-4588-afb8-4ed81fb4cf2f', NULL, 'listening', 'listening_choice', 'Dengarkan ketentuan tiket acara berikut. Bagaimana kebijakan pengembalian dana?', '{"options":[{"id":"opt_1","text":"Tiket dapat dikembalikan penuh kapan saja tanpa syarat"},{"id":"opt_2","text":"Pengembalian dana tidak dapat dilayani apa pun alasan dari pihak pembeli"},{"id":"opt_3","text":"Pembeli mendapat potongan lima puluh persen untuk acara berikutnya"},{"id":"opt_4","text":"Tiket hanya dapat ditukar di loket stasiun"}],"audio_text":"ご購入後のチケットは、お客様のご都合のいかんによらず、払い戻しには応じかねます。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'ご都合のいかんによらず、払い戻しには応じかねます berarti ''apa pun alasan pelanggan, pengembalian uang tidak dapat dilayani''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5331b1d-50e0-4c2d-a5c2-e0e704138fc9', '23f48a6f-781e-4588-afb8-4ed81fb4cf2f', NULL, 'listening', 'listening_choice', 'Dengarkan aturan keselamatan kerja berikut. Apa yang diwajibkan di area pabrik?', '{"options":[{"id":"opt_1","text":"Helm pengaman hanya wajib jika berada di pabrik lebih dari satu jam"},{"id":"opt_2","text":"Tamu kunjungan singkat dibebaskan dari kewajiban memakai helm"},{"id":"opt_3","text":"Helm pengaman wajib dipakai di dalam pabrik tanpa memandang lama atau singkatnya kunjungan"},{"id":"opt_4","text":"Helm pengaman hanya disediakan untuk operator mesin berat"}],"audio_text":"滞在時間の長短のいかんにかかわらず、工場内では必ず保護帽を着用してください。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '滞在時間の長短のいかんにかかわらず berarti ''tidak peduli sebentar atau lama berada di lokasi''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ac262593-90e9-42d4-a82a-f7f09486a0bd', '23f48a6f-781e-4588-afb8-4ed81fb4cf2f', NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan dewan etik berikut. Bagaimana sikap mereka terhadap pelanggaran aturan?', '{"options":[{"id":"opt_1","text":"Pelanggaran berat tetap ditindak tegas baik dilakukan sengaja maupun karena kelalaian"},{"id":"opt_2","text":"Pelanggaran karena kelalaian tidak akan dikenai sanksi apa pun"},{"id":"opt_3","text":"Hanya pelanggaran yang merugikan finansial yang diperiksa"},{"id":"opt_4","text":"Dewan etik menyerahkan sanksi sepenuhnya kepada masing-masing divisi"}],"audio_text":"故意か過失かのいかんを問わず、重大な情報管理義務違反には厳正に対処する方針である。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '故意か過失かのいかんを問わず berarti ''tanpa memandang apakah disengaja (故意) atau lalai (過失)''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a26c4f39-9ae1-4186-a9c7-83cd1cd97be5', '23f48a6f-781e-4588-afb8-4ed81fb4cf2f', NULL, 'reading', 'fill_blank', 'Lengkapi ketentuan layanan berikut: 被害額の大小の___、不正アクセスが確認された場合は速やかに警察へ通報する。', '{"options":["いかんによらず","いかんによっては","いかんで","に至っては"],"translation":"Tanpa memandang besar kecilnya nilai kerugian, apabila akses ilegal terkonfirmasi, segera laporkan ke polisi.","sentence_template":"被害額の大小の[blank]、不正アクセスが確認された場合は速やかに警察へ通報する。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, NULL, NULL, '大小のいかんによらず menegaskan tidak ada ambang batas pengecualian dalam pelaporan insiden keamanan.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3fa0e53f-3faf-4478-8da2-c1b33d9ddd6d', '23f48a6f-781e-4588-afb8-4ed81fb4cf2f', NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat: 今回の交渉の成否___、当社の来期の方針が大きく左右される。', '{"options":["いかんによらず","いかんで","いかんにかかわらず","いかんを問わず"],"translation":"Bergantung pada berhasil tidaknya negosiasi kali ini, arah kebijakan perusahaan periode depan akan sangat terpengaruh.","sentence_template":"今回の交渉の成否[blank]、当社の来期の方針が大きく左右される。"}'::jsonb, '{"selected":"いかんで"}'::jsonb, NULL, NULL, '成否いかんで (bergantung pada berhasil atau gagalnya) karena kalimat menyatakan pengaruh langsung.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('66e6faaf-4e9a-45c0-be68-caed89758a79', '23f48a6f-781e-4588-afb8-4ed81fb4cf2f', NULL, 'reading', 'fill_blank', 'Lengkapi klausul berikut: 天候の___、本大会は屋内会場にて予定通り開催いたします。', '{"options":["を余儀なく","なりに","いかんによらず","とはいえ"],"translation":"Tanpa memandang kondisi cuaca, turnamen ini akan diselenggarakan sesuai jadwal di gedung tertutup.","sentence_template":"天候の[blank]、本大会は屋内会場にて予定通り開催いたします。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, NULL, NULL, '天候のいかんによらず (bagaimanapun kondisi cuacanya) karena acara berlangsung di dalam ruangan.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2a677611-5c1e-476c-bcf8-b32464516f3f', '23f48a6f-781e-4588-afb8-4ed81fb4cf2f', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang untung atau rugi, keselamatan konsumen harus selalu dinomorsatukan."', '{"romaji":"Soneki no ikan ni yorazu, shouhisha no anzen ga saiyuu-sen sareru beki da.","tokens":["いかん","消費者の安全が","べきだ。","とはいえ、","損益の","によらず、","最優先される","最優先した"],"target_translation":"Tanpa memandang untung atau rugi, keselamatan konsumen harus selalu dinomorsatukan."}'::jsonb, '["損益の","いかん","によらず、","消費者の安全が","最優先される","べきだ。"]'::jsonb, NULL, NULL, '損益のいかんによらず (tanpa memandang untung-rugi) adalah prinsip etika bisnis.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e8eb0f0f-c7bf-40ff-843c-73372826fe2c', '23f48a6f-781e-4588-afb8-4ed81fb4cf2f', 'd1000019-0000-0000-0000-000000000036', 'listening', 'listening_choice', 'Dengarkan peraturan perpustakaan nasional. Siapa yang dapat mengakses arsip digital?', '{"options":[{"id":"opt_1","text":"Hanya penduduk ibu kota yang boleh mengakses arsip"},{"id":"opt_2","text":"Siapa saja dapat mengakses arsip digital setelah melakukan registrasi resmi tanpa memandang wilayah tempat tinggal"},{"id":"opt_3","text":"Arsip digital hanya dibuka satu jam dalam setahun"},{"id":"opt_4","text":"Pengguna harus membeli buku cetak terlebih dahulu"}],"audio_text":"居住地域のいかんによらず、所定の利用登録を行えば誰でもデジタルアーカイブを閲覧できる。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '居住地域のいかんによらず berarti tanpa memandang daerah domisili.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f0580aff-9411-484a-b721-e6e70be08a25', '2721f9f7-666f-4b68-8aca-fe7f65c0afd8', NULL, 'listening', 'listening_choice', 'Dengarkan tanggapan direktur berikut. Bagaimana ia menilai rumor di media sosial?', '{"options":[{"id":"opt_1","text":"Ia menilai kritik berdasar spekulasi tak jelas itu tidak layak dibantah satu per satu"},{"id":"opt_2","text":"Ia akan segera menggelar konferensi pers untuk membahas setiap komentar"},{"id":"opt_3","text":"Ia membenarkan seluruh isi rumor yang beredar"},{"id":"opt_4","text":"Ia meminta semua karyawan berhenti menggunakan internet"}],"audio_text":"出所不明の憶測に基づく批判など、いちいち反論するに足りないものだ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '反論するに足りない berarti ''tidak layak untuk dibantah''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b72e867b-f2b6-4cee-9032-d7cae9cd70cf', '2721f9f7-666f-4b68-8aca-fe7f65c0afd8', NULL, 'listening', 'listening_choice', 'Dengarkan penilaian dosen pembimbing berikut. Apa kualitas makalah mahasiswa tersebut?', '{"options":[{"id":"opt_1","text":"Makalah itu belum layak dipresentasikan karena kurang referensi"},{"id":"opt_2","text":"Makalah itu memiliki tingkat kematangan tinggi yang layak dipresentasikan di konferensi ilmiah"},{"id":"opt_3","text":"Makalah itu harus ditulis ulang dari awal bulan depan"},{"id":"opt_4","text":"Makalah itu terlalu singkat untuk dinilai"}],"audio_text":"先行研究を丹念に検証したこの論文は、学会での発表に足る高い完成度を誇っている。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '発表に足る高い完成度 berarti ''tingkat kesempurnaan tinggi yang layak dipresentasikan''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eae11fa8-716b-4af0-98aa-7f42c2c99707', '2721f9f7-666f-4b68-8aca-fe7f65c0afd8', NULL, 'listening', 'listening_choice', 'Dengarkan ulasan komite seleksi mitra bisnis. Apa syarat utama kandidat perusahaan?', '{"options":[{"id":"opt_1","text":"Memilih perusahaan dengan biaya termurah tanpa melihat stabilitas keuangan"},{"id":"opt_2","text":"Hanya memilih perusahaan baru yang belum memiliki laporan keuangan"},{"id":"opt_3","text":"Memilih perusahaan yang layak dipercaya baik dari segi teknologi maupun fondasi keuangan"},{"id":"opt_4","text":"Menunda pemilihan mitra selama lima tahun"}],"audio_text":"長期的な共同開発を任せる以上、技術力と財務基盤の双方で信頼に足る企業を選定したい。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '技術力と財務基盤の双方で信頼に足る企業 berarti ''perusahaan yang layak dipercaya di kedua aspek teknologi dan keuangan''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f1f65a32-68eb-4fe5-a816-4eac8f8f7ca0', '2721f9f7-666f-4b68-8aca-fe7f65c0afd8', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: わずかな誤差は統計上、取る___小さなものに過ぎない。', '{"options":["に足りない","に足る","に至った","を余儀なくされた"],"translation":"Selisih kecil tersebut secara statistik hanyalah hal remeh yang tidak berarti.","sentence_template":"わずかな誤差は統計上、取る[blank]小さなものに過ぎない。"}'::jsonb, '{"selected":"に足りない"}'::jsonb, NULL, NULL, '取るに足りない (toru ni tarinai) adalah ungkapan baku N1 untuk ''sangat remeh / tidak berarti''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6d4866d5-b2b2-4fd1-ab78-073b27fb93cf', '2721f9f7-666f-4b68-8aca-fe7f65c0afd8', NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼の提案は斬新であり、経営会議で真剣に検討する___。', '{"options":["なりに","に足る","とはいえ","いかんによらず"],"translation":"Usulannya segar dan layak dikaji secara serius dalam rapat manajemen.","sentence_template":"彼の提案は斬新であり、経営会議で真剣に検討する[blank]。"}'::jsonb, '{"selected":"に足る"}'::jsonb, NULL, NULL, '検討するに足る berarti ''layak untuk dipertimbangkan/dikaji''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c3a09811-4ff4-48b9-9e71-44cf07f6c6ed', '2721f9f7-666f-4b68-8aca-fe7f65c0afd8', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi sejarah berikut: この出来事は、現代社会の転換点として特筆する___重要な意義を持つ。', '{"options":["ともなると","に足りない","極まりない","に足る"],"translation":"Peristiwa ini memiliki makna penting yang layak dicatat secara khusus sebagai titik balik masyarakat modern.","sentence_template":"この出来事は、現代社会の転換点として特筆する[blank]重要な意義を持つ。"}'::jsonb, '{"selected":"に足る"}'::jsonb, NULL, NULL, '特筆するに足る berarti ''layak dicatat secara istimewa (noteworthy)''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a64c5509-b23f-4930-a9d3-28da93bc870c', '2721f9f7-666f-4b68-8aca-fe7f65c0afd8', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Kualitas layanan mereka tidak layak dijadikan alasan untuk mengeluh."', '{"romaji":"Karera no saabisu wa fuman o iu ni taranai hodo yoi.","tokens":["サービスは、","に","ほど立派だ。","とはいえ、","彼らの","非難する","足らない","足る"],"target_translation":"Kualitas layanan mereka tidak layak dijadikan alasan untuk mengeluh."}'::jsonb, '["彼らの","サービスは、","非難する","に","足らない","ほど立派だ。"]'::jsonb, NULL, NULL, '非難するに足らない (tidak pantas dikritik/dicela) memakai bentuk negatif に足らない.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('03ee682c-734c-4edf-b85f-55626add914b', '2721f9f7-666f-4b68-8aca-fe7f65c0afd8', 'd1000019-0000-0000-0000-000000000037', 'listening', 'listening_choice', 'Dengarkan komentar editor jurnal. Mengapa artikel tersebut terpilih sebagai artikel utama?', '{"options":[{"id":"opt_1","text":"Artikel itu dipilih karena halamannya paling sedikit"},{"id":"opt_2","text":"Karena sudut pandang multidimensional dan verifikasi ketat, makalah ini bernilai akademis tinggi dan layak menjadi titik tolak diskusi ke depan"},{"id":"opt_3","text":"Artikel itu tidak memiliki referensi ilmiah"},{"id":"opt_4","text":"Artikel itu ditolak oleh seluruh tim penelaah"}],"audio_text":"多角的な視点と厳密な検証により、本論文は今後の議論の出発点とするに足る高い学術的価値を持つ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '出発点とするに足る berarti layak dijadikan titik awal pembahasan ilmiah.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1a8d8e2d-966b-46c3-bc92-ebb5b3584866', '29d99f19-26c8-4160-9876-decb41598f73', NULL, 'listening', 'listening_choice', 'Dengarkan pendapat seorang direktur berikut. Apa pandangannya tentang gaya kepemimpinan?', '{"options":[{"id":"opt_1","text":"Bawahan wajib meniru persis cara kerja atasan tanpa modifikasi"},{"id":"opt_2","text":"Penting untuk terlebih dahulu menghargai inisiatif bawahan sesuai pemikirannya"},{"id":"opt_3","text":"Atasan sebaiknya mengerjakan semua tugas sendiri"},{"id":"opt_4","text":"Perbedaan cara kerja harus langsung diberi sanksi"}],"audio_text":"部下のやり方が自分の理想と違っても、相手なりに考えた工夫をまず認めることが大切だ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '相手なりに考えた工夫をまず認める berarti ''menghargai dulu siasat/upaya yang dipikirkan lawan bicara sesuai kapasitasnya''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1bb79223-ee4c-4c5f-874a-f3aa8134ebbe', '29d99f19-26c8-4160-9876-decb41598f73', NULL, 'listening', 'listening_choice', 'Dengarkan wawancara penulis berikut. Bagaimana ia menilai karya debutnya?', '{"options":[{"id":"opt_1","text":"Ia ingin menghapus karya debutnya karena tidak ada nilai sama sekali"},{"id":"opt_2","text":"Ia merasa gaya bahasanya dulu jauh lebih sempurna daripada sekarang"},{"id":"opt_3","text":"Meski banyak ungkapan belum matang, karya itu memuat semangat maksimalnya saat itu"},{"id":"opt_4","text":"Karya debutnya ditulis sepenuhnya oleh editornya"}],"audio_text":"今読み返すと未熟な表現も多いが、当時の私なりの精一杯の情熱が込められている。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '当時の私なりの精一杯の情熱 berarti ''semangat sepenuh hati sesuai kapasitas saya pada masa itu''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('048f1af7-0ff8-41df-90de-d3f595410e4f', '29d99f19-26c8-4160-9876-decb41598f73', NULL, 'listening', 'listening_choice', 'Dengarkan percakapan tentang kehidupan daerah. Apa keunggulan kota kecil menurut pembicara?', '{"options":[{"id":"opt_1","text":"Kota daerah memiliki cara hidup yang kaya tersendiri meski tidak semegah kota besar"},{"id":"opt_2","text":"Kota daerah jauh lebih ramai dan bising daripada ibu kota"},{"id":"opt_3","text":"Tidak ada keuntungan apa pun tinggal di kota daerah"},{"id":"opt_4","text":"Biaya hidup di kota daerah jauh lebih mahal daripada di Tokyo"}],"audio_text":"大都市のような派手さはないが、地方都市には地方都市なりの豊かな暮らし方がある。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '地方都市には地方都市なりの豊かな暮らし方がある menunjukkan apresiasi yang proporsional.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9bace282-dbba-4fdb-a570-f3fec0c7a005', '29d99f19-26c8-4160-9876-decb41598f73', NULL, 'reading', 'fill_blank', 'Lengkapi refleksi karier berikut: 若手には若手___役割があり、ベテランとは違う視点で組織を活性化できる。', '{"options":["極まりの","に至っての","をもっての","なりの"],"translation":"Karyawan muda memiliki perannya sendiri yang sesuai, dan dapat menghidupkan organisasi dari sudut pandang berbeda dari senior.","sentence_template":"若手には若手[blank]役割があり、ベテランとは違う視点で組織を活性化できる。"}'::jsonb, '{"selected":"なりの"}'::jsonb, NULL, NULL, '若手なりの役割 berarti ''peran tersendiri yang sesuai dengan posisi karyawan muda''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e189bba6-ee16-482c-b1ea-1cac5c3b2ff9', '29d99f19-26c8-4160-9876-decb41598f73', NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat: 完璧な語学力ではなくても、相手と分かり合おうと自分___努力する姿勢が伝わる。', '{"options":["を余儀なく","なりに","に足る","とはいえ"],"translation":"Meskipun kemampuan bahasanya belum sempurna, sikap berusaha dengan cara sendiri untuk saling memahami akan tersampaikan.","sentence_template":"完璧な語学力ではなくても、相手と分かり合おうと自分[blank]努力する姿勢が伝わる。"}'::jsonb, '{"selected":"なりに"}'::jsonb, NULL, NULL, '自分なりに努力する姿勢 (sikap berusaha sesuai kemampuan diri sendiri).', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c088d35d-0568-4cf7-89c3-5db922cd4d99', '29d99f19-26c8-4160-9876-decb41598f73', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予算が少ないなら少ない___、最大限の効果を出せる企画を練ろう。', '{"options":["に至って","いかんによらず","をもって","なりに"],"translation":"Jika anggarannya memang sedikit, mari susun rencana yang bisa menghasilkan dampak maksimal sesuai keterbatasan itu.","sentence_template":"予算が少ないなら少ない[blank]、最大限の効果を出せる企画を練ろう。"}'::jsonb, '{"selected":"なりに"}'::jsonb, NULL, NULL, 'Pola AならAなりに (kalau memang A, ya sesuai kondisi A itu) sangat sering diujikan di JLPT N1.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4cb90d4c-c228-43ac-8c28-03a0d1ff785d', '29d99f19-26c8-4160-9876-decb41598f73', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Setiap daerah memiliki kebijaksanaan tradisionalnya sendiri dalam menghadapi bencana."', '{"romaji":"Sono tochi ni wa sono tochi nari no bousai no chie ga aru.","tokens":["その土地","防災の知恵が","いる。","受け継いだ。","その土地には","なりの","受け継がれて","なりに"],"target_translation":"Setiap daerah memiliki kebijaksanaan tradisionalnya sendiri dalam menghadapi bencana."}'::jsonb, '["その土地には","その土地","なりの","防災の知恵が","受け継がれて","いる。"]'::jsonb, NULL, NULL, 'その土地なりの知恵 (kearifan lokal khas daerah tersebut) adalah konteks budaya yang tepat.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0bdf22fd-489d-4a2b-ae15-9d74e743448f', '29d99f19-26c8-4160-9876-decb41598f73', 'd1000019-0000-0000-0000-000000000033', 'listening', 'listening_choice', 'Dengarkan komentar pelatih. Mengapa ia memuji pemain cadangan itu?', '{"options":[{"id":"opt_1","text":"Karena pemain itu mencetak sepuluh gol di final"},{"id":"opt_2","text":"Karena meski tidak turun bermain, ia tidak patah semangat dan menjalankan peran mendukung tim dengan caranya sendiri"},{"id":"opt_3","text":"Karena pemain itu pindah ke klub lain"},{"id":"opt_4","text":"Karena pemain itu menolak berlatih bersama tim"}],"audio_text":"試合に出られない時期も腐らず、彼なりにチームを支える役割を果たしてくれた。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '彼なりにチームを支える役割を果たす berarti berkontribusi sesuai posisinya.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b962e2eb-4b8f-45e4-abb5-fad1321f325c', '2b2f07d5-7293-459c-8f86-0c944262696c', 'd1000019-0000-0000-0000-000000000035', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjadi proyek nasional, pengawasan publik sangat ketat."', '{"romaji":"Kokkateki na jigyou to mo naru to, kokumin no kanshi no me mo kiwamete kibishii.","display_text":"国家的な事業ともなると、国民の監視の目も極めて厳しい。","phonetic_breakdown":["ko-kka-te-ki","na","ji-gyou","to","mo","na-ru","to","ko-ku-min","no","kan-shi","no","me","mo","ki-wa-me-te","ki-bi-shii"]}'::jsonb, '{"expected_transcript":"国家的な事業ともなると、国民の監視の目も極めて厳しい。"}'::jsonb, NULL, NULL, '監視の目 (sorotan pengawasan) sangat ketat pada 国家的な事業 (proyek nasional).', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2b9a1cab-029c-4839-99ce-3b7c7b35479b', '2b2f07d5-7293-459c-8f86-0c944262696c', 'd1000019-0000-0000-0000-000000000035', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kalau sudah sekelas orkestra ternama, tiketnya langsung terjual habis."', '{"romaji":"Sekai ichiryuu no ookesutora to mo nareba, chiketto wa hatsubai to douji ni kanbai suru.","display_text":"世界一流のオーケストラともなれば、チケットは発売と同時に完売する。","phonetic_breakdown":["se-kai","i-chi-ryuu","no","oo-ke-su-to-ra","to","mo","na-re-ba","chi-ke-tto","wa","ha-tsu-bai","to","dou-ji","ni","kan-bai","su-ru"]}'::jsonb, '{"expected_transcript":"世界一流のオーケストラともなれば、チケットは発売と同時に完売する。"}'::jsonb, NULL, NULL, '発売と同時に完売する berarti ''langsung habis terjual begitu mulai dipasarkan''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('df25fcf1-af8b-4db8-9ea2-4c54b4f2413a', '2b2f07d5-7293-459c-8f86-0c944262696c', 'd1000019-0000-0000-0000-000000000035', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah mencapai jabatan direktur, keputusan harus diambil dengan cepat."', '{"romaji":"Yakuin kurasu to mo naru to, fukakujitsu na joukyou demo jinsoku na ketsudan ga motomerareru.","display_text":"役員クラスともなると、不確実な状況でも迅速な決断が求められる。","phonetic_breakdown":["ya-ku-in","ku-ra-su","to","mo","na-ru","to","fu-ka-ku-ji-tsu","na","jou-kyou","de-mo","jin-so-ku","na","ke-tsu-dan","ga","mo-to-me-ra-re-ru"]}'::jsonb, '{"expected_transcript":"役員クラスともなると、不確実な状況でも迅速な決断が求められる。"}'::jsonb, NULL, NULL, '役員クラス (kalangan eksekutif/direksi) dituntut 迅速な決断 (keputusan cepat).', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7bdefed4-218f-4d47-a122-ef28223717ab', '2b2f07d5-7293-459c-8f86-0c944262696c', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah memimpin tim multinasional, pemahaman lintas budaya sangat penting."', '{"romaji":"Takokuseki chiimu no riidaa to mo naru to ibunka rikai ga kakasenai.","tokens":["ともなると","チームの","多国籍","極まりない","異文化理解が","をもって","リーダー","欠かせない"],"target_translation":"Jika sudah memimpin tim multinasional, pemahaman lintas budaya sangat penting."}'::jsonb, '["多国籍","チームの","リーダー","ともなると","異文化理解が","欠かせない"]'::jsonb, NULL, NULL, '異文化理解が欠かせない berarti ''pemahaman lintas budaya mutlak tak tergantikan''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1fc318aa-dbe7-4112-9660-9c7692264a38', '2b2f07d5-7293-459c-8f86-0c944262696c', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Kalau sudah selevel profesor terkemuka, karyanya dikutip di seluruh dunia."', '{"romaji":"Chomei na kyouju to mo nareba ronbun ga sekaijuu de in''you sareru.","tokens":["著名な","引用される","教授","なりに","論文が","とはいえ","世界中で","ともなれば"],"target_translation":"Kalau sudah selevel profesor terkemuka, karyanya dikutip di seluruh dunia."}'::jsonb, '["著名な","教授","ともなれば","論文が","世界中で","引用される"]'::jsonb, NULL, NULL, '引用される berarti ''dikutip/disitasi'' dalam dunia akademik.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('38ac1ffc-d29f-4b2f-adc5-d0bdc98dc632', '2b2f07d5-7293-459c-8f86-0c944262696c', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah akhir musim dingin, salju mulai mencair perlahan."', '{"romaji":"Sangatsu no gejun to mo naru to sankanbu no yuki mo tokehajimeru.","tokens":["雪も","三月の","ともなると","山間部の","に至って","下旬","溶け始める","ながら"],"target_translation":"Jika sudah akhir musim dingin, salju mulai mencair perlahan."}'::jsonb, '["三月の","下旬","ともなると","山間部の","雪も","溶け始める"]'::jsonb, NULL, NULL, '三月の下旬ともなると (jika sudah memasuki akhir Maret) menandai pergantian musim.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3f2fd3e1-cdbd-4e24-8931-6891bc479cc1', '2b2f07d5-7293-459c-8f86-0c944262696c', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Pilih pola yang tepat: 国の政策を左右する審議会___、各分野の第一人者が委員に選ばれる。', '{"options":["ともなると","極まりなく","ずにはおかず","を余儀なくされ"],"translation":"Jika sudah dewan pertimbangan yang menentukan kebijakan negara, tokoh terkemuka dari tiap bidang yang dipilih menjadi anggotanya.","sentence_template":"国の政策を左右する審議会[blank]、各分野の第一人者が委員に選ばれる。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, NULL, NULL, '第一人者 (pakar terkemuka) berpasangan alami dengan standar tinggi ～ともなると.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5153db19-be62-4210-8663-ff46c0db9a6a', '2b2f07d5-7293-459c-8f86-0c944262696c', 'd1000019-0000-0000-0000-000000000035', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjadi duta besar, setiap tindak tanduk membawa kehormatan negara."', '{"romaji":"Ikkoku no taishi to mo nareba, hibi no furumai hitotsu ni mo kuni no ishin ga kakatte imasu.","display_text":"一国の大使ともなれば、日々の振る舞い一つにも国の威信がかかっています。","phonetic_breakdown":["いっこくのたいし","ともなれば","ひびのふるまいひとつにも","くにのいしんが","かかっています"]}'::jsonb, '{"expected_transcript":"一国の大使ともなれば、日々の振る舞い一つにも国の威信がかかっています。"}'::jsonb, NULL, NULL, '国の威信がかかる (mempertaruhkan wibawa negara) cocok dengan peran tinggi 大使ともなれば.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('228f6ee6-7ef6-43b7-8e44-98228e8a8a4a', '352f58c1-2360-414e-864e-6f6c115b2f16', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan pola tata bahasa N1 yang tepat: 事態がここまで悪化する___、ようやく経営陣は重い腰を上げた。', '{"options":["に先立って","に至って","に沿って","をめぐって"],"translation":"Setelah situasi memburuk sampai sejauh ini, barulah jajaran direksi akhirnya bergerak.","sentence_template":"事態がここまで悪化する[blank]、ようやく経営陣は重い腰を上げた。"}'::jsonb, '{"selected":"に至って"}'::jsonb, NULL, NULL, '～に至って menyatakan bahwa setelah mencapai titik ekstrem/kritis tertentu, barulah suatu reaksi atau kenyataan muncul.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e6c3a992-6dfc-49c9-b66f-99f83c5d493f', '352f58c1-2360-414e-864e-6f6c115b2f16', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk menyatakan kondisi yang sudah terlambat: 今___、後悔しても手遅れだ。', '{"options":["に応じて","に際して","に至るまで","に至っては"],"translation":"Kalau sudah sampai saat sekarang ini, menyesal pun sudah terlambat.","sentence_template":"今[blank]、後悔しても手遅れだ。"}'::jsonb, '{"selected":"に至っては"}'::jsonb, NULL, NULL, '今に至っては (sudah sampai titik sekarang ini) sering diikuti ungkapan bahwa situasinya tidak dapat diubah lagi.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7064889d-88de-4358-9306-dbbd2e014817', '352f58c1-2360-414e-864e-6f6c115b2f16', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Lengkapi kalimat berikut untuk menunjukkan cakupan menyeluruh: 社長から新入社員___、全員が研修に参加した。', '{"options":["に至るまで","を契機に","を踏まえて","に至っては"],"translation":"Mulai dari direktur utama hingga karyawan baru, semuanya mengikuti pelatihan.","sentence_template":"社長から新入社員[blank]、全員が研修に参加した。"}'::jsonb, '{"selected":"に至るまで"}'::jsonb, NULL, NULL, 'AからBに至るまで menunjukkan rentang ekstrem dari A sampai ke detail atau tingkat B.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fb025314-25e7-490b-aee2-e1025e0a6c52', '352f58c1-2360-414e-864e-6f6c115b2f16', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Setelah mencapai tahap ini, tidak ada jalan lain selain mundur."', '{"romaji":"Kono dankai ni itatte wa tettai suru hoka nai.","tokens":["に応じて","この","撤退","する","ながら","に至っては","段階","ほかない"],"target_translation":"Setelah mencapai tahap ini, tidak ada jalan lain selain mundur."}'::jsonb, '["この","段階","に至っては","撤退","する","ほかない"]'::jsonb, NULL, NULL, 'この段階に至っては (kalau sudah sampai tahap ini) berpasangan alami dengan ～するほかない (tidak ada pilihan lain selain...).', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d9a7bab0-973e-403f-a005-2798b7362dd1', '352f58c1-2360-414e-864e-6f6c115b2f16', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Dia menjelaskan kronologi hingga tercapainya keputusan itu."', '{"romaji":"Kettei ni itatta keii wo teinei ni setsumei shita.","tokens":["をめぐった","を","丁寧に","ばかりに","説明した","に至った","決定","経緯"],"target_translation":"Dia menjelaskan kronologi hingga tercapainya keputusan itu."}'::jsonb, '["決定","に至った","経緯","を","丁寧に","説明した"]'::jsonb, NULL, NULL, '決定に至った経緯 berarti ''latar belakang/kronologi yang mengarah pada keputusan tersebut''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5512db3a-490f-4132-adb5-e3a278c42b66', '352f58c1-2360-414e-864e-6f6c115b2f16', 'd1000019-0000-0000-0000-000000000028', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Baru setelah jatuh sakit parah, saya menyadari pentingnya kesehatan."', '{"romaji":"Taibyou wo wazurau ni itatte, hajimete kenkou no arigatami wo shitta.","display_text":"大病を患うに至って、初めて健康のありがたみを知った。","phonetic_breakdown":["tai-byou","wo","wa-zu-rau","ni","i-ta-tte","ha-ji-me-te","ken-kou","no","a-ri-ga-ta-mi","wo","shi-tta"]}'::jsonb, '{"expected_transcript":"大病を患うに至って、初めて健康のありがたみを知った。"}'::jsonb, NULL, NULL, 'Pola ～に至って、初めて～ menegaskan kesadaran yang baru muncul setelah mencapai titik ekstrem.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('18844f9e-02e4-4c2e-a68c-0594265c9da4', '352f58c1-2360-414e-864e-6f6c115b2f16', 'd1000019-0000-0000-0000-000000000028', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa makna ～に至って dalam konteks ini?', '{"options":[{"id":"opt_1","text":"Pemerintah daerah mengakui kelemahan rencana evakuasi sebelum ada korban"},{"id":"opt_2","text":"Baru setelah korban benar-benar jatuh, pemerintah daerah akhirnya mengakui kekurangan rencana evakuasi"},{"id":"opt_3","text":"Rencana evakuasi pemerintah daerah sudah sempurna sejak awal"},{"id":"opt_4","text":"Warga menolak mengikuti rencana evakuasi"}],"audio_text":"実際に被害が出てからに至って、ようやく自治体も避難計画の不備を認めた。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '～に至って sering membawa nuansa kritik bahwa tindakan baru diambil setelah terlambat/mencapai titik kritis.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b2ad990a-99c8-4fc2-bc38-9d21e5fb6ed2', '352f58c1-2360-414e-864e-6f6c115b2f16', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Lengkapi kalimat dengan bentuk yang tepat: 調査の結果、複数の部署で規則違反が常態化していた事実が明らかになる___。', '{"options":["に至った","を余儀なくされた","とはいえ","極まりない"],"translation":"Hasil investigasi sampai mengungkap fakta bahwa pelanggaran aturan sudah menjadi kebiasaan di beberapa divisi.","sentence_template":"調査の結果、複数の部署で規則違反が常態化していた事実が明らかになる[blank]。"}'::jsonb, '{"selected":"に至った"}'::jsonb, NULL, NULL, '明らかになるに至った menyatakan hasil akhir investigasi yang serius.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e7bcd72a-196d-43af-aa6e-93a5e7c9ca94', '415b9b29-9061-4c37-a209-d3835caeb91f', 'd1000019-0000-0000-0000-000000000031', 'listening', 'listening_choice', 'Dengarkan pengumuman direksi. Kapan perubahan struktur organisasi resmi berlaku?', '{"options":[{"id":"opt_1","text":"Mulai 1 April mendatang, divisi penjualan dan bisnis luar negeri resmi digabung menuju struktur baru"},{"id":"opt_2","text":"Perusahaan menutup seluruh divisi penjualan mulai 1 April"},{"id":"opt_3","text":"Penggabungan divisi dibatalkan hingga tahun depan"},{"id":"opt_4","text":"Divisi luar negeri dipisahkan menjadi perusahaan mandiri"}],"audio_text":"来る四月一日をもって、営業本部と海外事業部を統合し、新体制へ移行いたします。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '来る四月一日をもって (terhitung 1 April mendatang) menyatakan tanggal efektif keputusan organisasi.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('621c5eff-8a61-4fe6-bd0e-187eb540a157', '415b9b29-9061-4c37-a209-d3835caeb91f', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Dengan upacara ini, seluruh rangkaian acara peringatan resmi berakhir."', '{"romaji":"Kore o motte, kinen gyoushi no zen nittei o shuuryou itashimasu.","tokens":["をもって、","全日程を","いたします。","終了した","これ","記念行事の","終了","とはいえ、"],"target_translation":"Dengan upacara ini, seluruh rangkaian acara peringatan resmi berakhir."}'::jsonb, '["これ","をもって、","記念行事の","全日程を","終了","いたします。"]'::jsonb, NULL, NULL, 'これをもって (dengan ini) adalah penutup resmi upacara dan rapat formal.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bdda3d23-747c-45d7-9646-e2d96711cc2f', '415b9b29-9061-4c37-a209-d3835caeb91f', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 弊社は品質の安定と迅速な対応___、顧客満足の向上に努めている。', '{"options":["をもって","に至って","を余儀なくされ","極まりなく"],"translation":"Perusahaan kami berupaya meningkatkan kepuasan pelanggan melalui stabilitas kualitas dan respons cepat.","sentence_template":"弊社は品質の安定と迅速な対応[blank]、顧客満足の向上に努めている。"}'::jsonb, '{"selected":"をもって"}'::jsonb, NULL, NULL, '～をもって menyatakan sarana/prinsip utama yang dijadikan landasan upaya perusahaan.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8d5cf8aa-0141-4f61-90aa-677ef4c59a7d', '415b9b29-9061-4c37-a209-d3835caeb91f', 'd1000019-0000-0000-0000-000000000031', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terhitung akhir bulan ini, saya resmi mengundurkan diri dari jabatan ini."', '{"romaji":"Kongetsumatsu o mochimashite, taishoku suru koto to narimashita.","display_text":"今月末をもちまして、退職することとなりました。","phonetic_breakdown":["こんげつまつを","もちまして","たいしょくすることと","なりました"]}'::jsonb, '{"expected_transcript":"今月末をもちまして、退職することとなりました。"}'::jsonb, NULL, NULL, '～をもちまして adalah versi lebih sopan (teineigo) dari ～をもって dalam surat atau pidato perpisahan.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b39450c4-5d37-40ed-a298-8ec3e2546786', '415b9b29-9061-4c37-a209-d3835caeb91f', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 規則に反する行為に対しては、厳正な態度___臨む方針だ。', '{"options":["をもって","なりに","に足る","ともなると"],"translation":"Terhadap tindakan yang melanggar aturan, kebijakan kami adalah menghadapinya dengan sikap tegas dan adil.","sentence_template":"規則に反する行為に対しては、厳正な態度[blank]臨む方針だ。"}'::jsonb, '{"selected":"をもって"}'::jsonb, NULL, NULL, '厳正な態度をもって臨む (menghadapi dengan sikap tegas dan objektif) adalah kolokasi N1.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f7aa854f-9b21-4dc3-8408-40f169e08c3d', '415b9b29-9061-4c37-a209-d3835caeb91f', 'd1000019-0000-0000-0000-000000000031', 'listening', 'listening_choice', 'Dengarkan pengumuman di gedung pertemuan. Apa yang baru saja diumumkan?', '{"options":[{"id":"opt_1","text":"Simposium baru saja dimulai"},{"id":"opt_2","text":"Akan ada sesi tambahan selama dua jam"},{"id":"opt_3","text":"Peserta diminta pindah ke gedung sebelah"},{"id":"opt_4","text":"Dengan berakhirnya presentasi barusan, seluruh rangkaian program simposium hari ini resmi ditutup"}],"audio_text":"ただいまの発表をもちまして、本日のシンポジウムの全プログラムを終了させていただきます。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '～をもちまして…終了させていただきます adalah frasa penutup acara resmi tingkat N1.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('07fc4cf3-9b56-4382-a5f4-60762c72ed23', '415b9b29-9061-4c37-a209-d3835caeb91f', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Kami akan menjawab harapan masyarakat melalui hasil penelitian yang nyata."', '{"romaji":"Kenkyuu no seika o motte, shakai no kitai ni kotaetai.","tokens":["成果","社会の期待に","たい。","いかんによらず、","研究の","をもって、","応え","に応えた"],"target_translation":"Kami akan menjawab harapan masyarakat melalui hasil penelitian yang nyata."}'::jsonb, '["研究の","成果","をもって、","社会の期待に","応え","たい。"]'::jsonb, NULL, NULL, '成果をもって (dengan hasil nyata sebagai sarana/bukti) berpasangan alami dengan 期待に応える.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4220f2c4-2ecf-47dc-a911-7ddd0dd68836', '415b9b29-9061-4c37-a209-d3835caeb91f', 'd1000019-0000-0000-0000-000000000031', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Terhitung hari ini, layanan konsultasi daring kami resmi dibuka untuk umum."', '{"romaji":"Honjitsu o motte, onrain soudan madoguchi no unyou o kaishi itashimasu.","display_text":"本日をもって、オンライン相談窓口の運用を開始いたします。","phonetic_breakdown":["ほんじつをもって","おんらいんそうだんまどぐちの","うんようを","かいしいたします"]}'::jsonb, '{"expected_transcript":"本日をもって、オンライン相談窓口の運用を開始いたします。"}'::jsonb, NULL, NULL, '本日をもって (terhitung hari ini) menegaskan titik awal resmi beroperasinya layanan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5b45aacc-a0e6-4240-bc0e-9e2fd1cc5be2', '4313f9af-ba3b-434d-a89a-66ade38113bf', 'd1000019-0000-0000-0000-000000000030', 'listening', 'listening_choice', 'Dengarkan tanggapan manajer risiko. Apa peringatan beliau meski penjualan naik?', '{"options":[{"id":"opt_1","text":"Meskipun penjualan periode ini memecahkan rekor tertinggi, kita tidak boleh menutup mata dari penurunan margin laba"},{"id":"opt_2","text":"Margin laba perusahaan juga mencapai rekor tertinggi"},{"id":"opt_3","text":"Penjualan periode ini turun drastis dibanding tahun lalu"},{"id":"opt_4","text":"Perusahaan tidak perlu memantau laporan keuangan lagi"}],"audio_text":"今期の売上が過去最高を更新したとはいえ、利益率の低下から目を背けるわけにはいかない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '更新したとはいえ mengakui rekor penjualan sambil mengingatkan risiko penurunan 利益率.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1ca15f10-e044-44bb-b5ce-2ce6cedb6321', '4313f9af-ba3b-434d-a89a-66ade38113bf', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun sudah pensiun dari jabatan resmi, beliau masih aktif memberi nasihat."', '{"romaji":"Geneki o shirizoita to wa ie, sensei wa ima mo jogen o tsuzukete iru.","tokens":["退いた","先生は今も","続けている。","を余儀なくされ、","現役を","とはいえ、","助言を","退く"],"target_translation":"Meskipun sudah pensiun dari jabatan resmi, beliau masih aktif memberi nasihat."}'::jsonb, '["現役を","退いた","とはいえ、","先生は今も","助言を","続けている。"]'::jsonb, NULL, NULL, '現役を退いたとはいえ mengakui status pensiun sebelum kontras aktivitas sekarang.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c5d287d1-425b-41e3-947d-fa21bc2a0511', '4313f9af-ba3b-434d-a89a-66ade38113bf', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 都市部に比べて物価が安い___、車がないと生活しにくい地域もある。', '{"options":["とはいえ","極まりない","ずにはおかない","ともなると"],"translation":"Meskipun biaya hidup lebih murah dibanding perkotaan, ada juga daerah yang sulit ditinggali tanpa mobil.","sentence_template":"都市部に比べて物価が安い[blank]、車がないと生活しにくい地域もある。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, 'Kata sifat-i (安い) langsung tersambung ke とはいえ.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7efc1046-b45e-4dd5-a856-3bacb2777de4', '4313f9af-ba3b-434d-a89a-66ade38113bf', 'd1000019-0000-0000-0000-000000000030', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun telah meminta maaf secara resmi, memulihkan kepercayaan pelanggan butuh waktu lama."', '{"romaji":"Koushiki ni shazai shita to wa ie, ushinatta shinrai o torimodosu ni wa nagai jikan ga kakarimasu.","display_text":"公式に謝罪したとはいえ、失った信頼を取り戻すには長い時間がかかります。","phonetic_breakdown":["こうしきに","しゃざいしたとはいえ","うしなったしんらいを","とりもどすには","ながいじかんがかかります"]}'::jsonb, '{"expected_transcript":"公式に謝罪したとはいえ、失った信頼を取り戻すには長い時間がかかります。"}'::jsonb, NULL, NULL, '公式に謝罪したとはいえ menyajikan realitas manajemen krisis secara objektif.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ee1dc040-5562-4fd5-bbeb-d82b9263069d', '4313f9af-ba3b-434d-a89a-66ade38113bf', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 自由な校風___、最低限の規律やマナーは厳しく指導される。', '{"options":["とはいえ","をもって","に至って","に足る"],"translation":"Meskipun memiliki budaya sekolah yang bebas, disiplin dan tata krama dasar tetap dibimbing dengan tegas.","sentence_template":"自由な校風[blank]、最低限の規律やマナーは厳しく指導される。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '自由な校風とはいえ mengontraskan kebebasan budaya sekolah dengan ketegasan disiplin dasar.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('025bf1aa-7f5d-41ae-9b21-3ba54197c555', '4313f9af-ba3b-434d-a89a-66ade38113bf', 'd1000019-0000-0000-0000-000000000030', 'listening', 'listening_choice', 'Dengarkan kritik pengamat lingkungan. Apa masalah yang masih tersisa?', '{"options":[{"id":"opt_1","text":"Jaringan transmisi listrik sudah jauh melampaui kebutuhan"},{"id":"opt_2","text":"Energi terbarukan belum pernah digunakan di negara ini"},{"id":"opt_3","text":"Biaya listrik turun menjadi gratis di seluruh kota"},{"id":"opt_4","text":"Meskipun rasio energi terbarukan meningkat, kenyataannya pembangunan jaringan transmisi belum mampu mengejar"}],"audio_text":"再生可能エネルギーの比率が高まったとはいえ、送電網の整備が追いついていないのが実情だ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '高まったとはいえ dikontraskan dengan 送電網の整備が追いついていないのが実情だ.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('90a7c0bb-1957-4c4f-b45c-a55f44240c8b', '4313f9af-ba3b-434d-a89a-66ade38113bf', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun disebut bahasa yang sulit, jika belajar rutin pasti akan ada kemajuan."', '{"romaji":"Muzukashii gengo to wa ie, mainichi tsuzukereba kanarazu joutatsu suru.","tokens":["とはいえ、","必ず","する。","極まりなく、","難しい言語","毎日続ければ","上達","上達した"],"target_translation":"Meskipun disebut bahasa yang sulit, jika belajar rutin pasti akan ada kemajuan."}'::jsonb, '["難しい言語","とはいえ、","毎日続ければ","必ず","上達","する。"]'::jsonb, NULL, NULL, '難しい言語とはいえ mengakui kesulitan sambil memberi dorongan realistis.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8a0f5c23-1d05-4ed4-b710-3acf42b8f9f5', '4313f9af-ba3b-434d-a89a-66ade38113bf', 'd1000019-0000-0000-0000-000000000030', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun hanya untuk sementara waktu, perubahan prosedur ini sangat membantu tim lapangan."', '{"romaji":"Ichijiteki na sochi to wa ie, kono tetsuzuki henkou wa genba no futan o ookiku herashimashita.","display_text":"一時的な措置とはいえ、この手続き変更は現場の負担を大きく減らしました。","phonetic_breakdown":["いちじてきな","そちとはいえ","このてつづきへんこうは","げんばのふたんを","おおきくへらしました"]}'::jsonb, '{"expected_transcript":"一時的な措置とはいえ、この手続き変更は現場の負担を大きく減らしました。"}'::jsonb, NULL, NULL, '一時的な措置とはいえ (meskipun langkah sementara) lazim dalam evaluasi operasional.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cce02a4b-58cd-4b07-8cef-e4091e3248ae', '469fe96f-b404-4f61-b03f-ba3c45835ae1', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Lengkapi kalimat kritik berikut: 十分な安全確認を怠ったまま運行を続けるのは、危険___。', '{"options":["とはいえ","に足りない","余儀ない","極まりない"],"translation":"Melanjutkan operasional tanpa pemeriksaan keselamatan yang memadai adalah hal yang luar biasa berbahaya.","sentence_template":"十分な安全確認を怠ったまま運行を続けるのは、危険[blank]。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, NULL, NULL, 'Kata sifat-na (akar) + 極まりない menyatakan tingkat ekstrem ''tiada tara / luar biasa''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8794f55f-4b21-4f7e-8037-8d7a056a6d39', '469fe96f-b404-4f61-b03f-ba3c45835ae1', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk memodifikasi kata benda: 事実確認をせずに報道するとは、無責任___行為である。', '{"options":["に至る","に足る","極まる","をめぐる"],"translation":"Memberitakan tanpa verifikasi fakta adalah tindakan yang luar biasa tidak bertanggung jawab.","sentence_template":"事実確認をせずに報道するとは、無責任[blank]行為である。"}'::jsonb, '{"selected":"極まる"}'::jsonb, NULL, NULL, '～極まる (atau ～極まりない) dapat diletakkan sebelum kata benda untuk menekankan derajat ekstrem.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bf590f6f-9469-4250-a505-e2445212ae61', '469fe96f-b404-4f61-b03f-ba3c45835ae1', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Lengkapi pernyataan resmi berikut: このような不祥事が再び起きたことは、遺憾___。', '{"options":["の限りである","の極みである","の余地がある","の至りである"],"translation":"Terulangnya skandal semacam ini sungguh sangat disayangkan hingga tiada tara.","sentence_template":"このような不祥事が再び起きたことは、遺憾[blank]。"}'::jsonb, '{"selected":"の極みである"}'::jsonb, NULL, NULL, '遺憾の極みである (puncak penyesalan) adalah varian nomina dari 遺憾極まりない yang sangat formal.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b6771ea7-f39b-4c94-879f-dc8f65f1db94', '469fe96f-b404-4f61-b03f-ba3c45835ae1', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Sikapnya terhadap para pelanggan sungguh luar biasa tidak sopan."', '{"romaji":"Kare no kokyaku ni taisuru taido wa shitsurei kiwamarinai.","tokens":["失礼","彼の","なりに","態度は","極まりない","顧客に","に足る","対する"],"target_translation":"Sikapnya terhadap para pelanggan sungguh luar biasa tidak sopan."}'::jsonb, '["彼の","顧客に","対する","態度は","失礼","極まりない"]'::jsonb, NULL, NULL, '失礼極まりない berarti ''luar biasa tidak sopan / sangat kurang ajar''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2a51bdc4-7c9f-4529-8568-8a38a04810dc', '469fe96f-b404-4f61-b03f-ba3c45835ae1', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Keputusan yang mengabaikan pendapat lapangan itu sangat tidak menyenangkan."', '{"romaji":"Genba wo mushi shita kettei ni wa fuyukai kiwamarinai omoi da.","tokens":["極まりない","無視した","決定には","現場を","思いだ","不愉快","をもって","ながら"],"target_translation":"Keputusan yang mengabaikan pendapat lapangan itu sangat tidak menyenangkan."}'::jsonb, '["現場を","無視した","決定には","不愉快","極まりない","思いだ"]'::jsonb, NULL, NULL, '不愉快極まりない思い berarti ''perasaan yang luar biasa tidak menyenangkan''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('93ecf982-fedf-4b30-b263-30f8a803b034', '469fe96f-b404-4f61-b03f-ba3c45835ae1', 'd1000019-0000-0000-0000-000000000032', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tindakan yang merugikan banyak pihak itu sungguh sangat tidak tahu aturan."', '{"romaji":"Shuui ni tadai na meiwaku wo kakeru koui wa, hijoushiki kiwamarinai.","display_text":"周囲に多大な迷惑をかける行為は、非常識極まりない。","phonetic_breakdown":["shuu-i","ni","ta-dai","na","mei-wa-ku","wo","ka-ke-ru","kou-i","wa","hi-jou-shi-ki","ki-wa-ma-ri-nai"]}'::jsonb, '{"expected_transcript":"周囲に多大な迷惑をかける行為は、非常識極まりない。"}'::jsonb, NULL, NULL, '多大な迷惑 (gangguan yang sangat besar) dikritik keras dengan 非常識極まりない.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('889a1e3e-7e7b-4d07-80f3-7506274fedf2', '469fe96f-b404-4f61-b03f-ba3c45835ae1', 'd1000019-0000-0000-0000-000000000032', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Bagaimana nuansa penilaian pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara melontarkan kritik tajam bahwa sistem komunikasi darurat yang tak berfungsi itu amat sangat buruk/ceroboh"},{"id":"opt_2","text":"Pembicara memuji kecepatan sistem komunikasi darurat"},{"id":"opt_3","text":"Pembicara menyatakan belum ada situasi darurat yang terjadi"},{"id":"opt_4","text":"Pembicara mengusulkan agar sistem komunikasi dihapus saja"}],"audio_text":"緊急時の連絡体制が全く機能していなかったとは、お粗末極まりない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, 'お粗末極まりない berarti amat sangat buruk/tidak memadai.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('606d130d-0353-4231-a4d7-01f085f0cad7', '469fe96f-b404-4f61-b03f-ba3c45835ae1', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Lengkapi kalimat dengan kata sifat-na yang tepat: 深夜に大音量で音楽を流すのは、近所にとって___極まりない。', '{"options":["迷惑","親切","丁寧","清潔"],"translation":"Memutar musik dengan volume keras di tengah malam sungguh amat mengganggu bagi tetangga.","sentence_template":"深夜に大音量で音楽を流すのは、近所にとって[blank]極まりない。"}'::jsonb, '{"selected":"迷惑"}'::jsonb, NULL, NULL, '迷惑 (kata sifat-na) + 極まりない menyatakan gangguan pada tingkat ekstrem.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1f79313b-f485-4df1-9145-c679f5e85994', '474823bb-06c9-4329-837d-d6491f36ff2f', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Simulasi N1 (1/10): Lengkapi kalimat formal berikut: 顧客データの流出が発覚する___、経営陣はようやく抜本的な安全対策に着手した。', '{"options":["に至って","とはいえ","なりに","に足る"],"translation":"Baru setelah kebocoran data pelanggan terungkap, manajemen akhirnya mulai menerapkan langkah keamanan mendasar.","sentence_template":"顧客データの流出が発覚する[blank]、経営陣はようやく抜本的な安全対策に着手した。"}'::jsonb, '{"selected":"に至って"}'::jsonb, NULL, NULL, '～に至って menandai titik kritis ekstrem yang baru memicu kesadaran atau tindakan.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9e59215e-3cf2-46f7-9e7a-cfd531be35eb', '474823bb-06c9-4329-837d-d6491f36ff2f', 'd1000019-0000-0000-0000-000000000029', 'listening', 'listening_choice', 'Simulasi N1 (2/10): Dengarkan berita internasional berikut. Apa konsekuensi yang dialami industri manufaktur?', '{"options":[{"id":"opt_1","text":"Banyak produsen utama terpaksa menghentikan produksi sementara akibat terputusnya rantai pasok internasional"},{"id":"opt_2","text":"Rantai pasok internasional berjalan lebih lancar dari sebelumnya"},{"id":"opt_3","text":"Semua produsen melipatgandakan kapasitas pabriknya"},{"id":"opt_4","text":"Industri manufaktur tidak bergantung pada pasokan luar negeri"}],"audio_text":"国際的な供給網の寸断により、主要メーカーの多くが一時的な生産停止を余儀なくされている。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '生産停止を余儀なくされている berarti terpaksa menghentikan produksi akibat faktor eksternal.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('74624a9c-e7ca-4004-8b63-82f0e1874588', '474823bb-06c9-4329-837d-d6491f36ff2f', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Simulasi N1 (3/10): Pilih pola argumen berimbang yang tepat: 自動化技術が大きく進展した___、危機発生時の最終判断は人間に委ねられる。', '{"options":["とはいえ","をもって","極まりなく","いかんによらず"],"translation":"Meskipun teknologi otomatisasi telah berkembang pesat, keputusan akhir saat krisis tetap diserahkan kepada manusia.","sentence_template":"自動化技術が大きく進展した[blank]、危機発生時の最終判断は人間に委ねられる。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '～とはいえ mengakui fakta kemajuan otomatisasi sambil menegaskan catatan kritisnya.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d53def38-7013-4f59-bfd9-bdb4592e7fb3', '474823bb-06c9-4329-837d-d6491f36ff2f', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Terhitung pukul 17.00 hari ini, penerimaan pendaftaran peserta resmi ditutup."', '{"romaji":"Honjitsu gogo goji o motte, sanka moushikomi no uketsuke o shuuryou itashimasu.","tokens":["をもって、","受付を","いたします。","終了した","本日午後五時","参加申込の","終了","に至って、"],"target_translation":"Terhitung pukul 17.00 hari ini, penerimaan pendaftaran peserta resmi ditutup."}'::jsonb, '["本日午後五時","をもって、","参加申込の","受付を","終了","いたします。"]'::jsonb, NULL, NULL, 'Waktu + をもって menandai batas akhir resmi dalam pengumuman korporasi.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('11f969f4-7c69-4cb3-9634-df16b86a1552', '474823bb-06c9-4329-837d-d6491f36ff2f', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Simulasi N1 (5/10): Lengkapi kritik editorial berikut: 住民の安全を軽視した計画強行は、無責任___と言わざるを得ない。', '{"options":["極まりない","に足る","ともなると","なりに"],"translation":"Memaksakan rencana sambil meremehkan keselamatan warga mau tidak mau harus disebut amat sangat tidak bertanggung jawab.","sentence_template":"住民の安全を軽視した計画強行は、無責任[blank]と言わざるを得ない。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, NULL, NULL, '無責任極まりない menyatakan kritik tajam pada tingkat ekstrem.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('97ff2a4a-f55c-44c9-9a06-a7296d48a335', '474823bb-06c9-4329-837d-d6491f36ff2f', 'd1000019-0000-0000-0000-000000000033', 'listening', 'listening_choice', 'Simulasi N1 (6/10): Dengarkan komentar mentor berikut. Bagaimana beliau menilai usaha staf baru?', '{"options":[{"id":"opt_1","text":"Staf baru itu dianggap tidak memahami masalah lapangan sama sekali"},{"id":"opt_2","text":"Meski masih ada kekurangan, staf baru itu telah menganalisis masalah lapangan dan menyusun usulan orisinal dengan caranya sendiri"},{"id":"opt_3","text":"Staf baru itu menyalin laporan orang lain tanpa izin"},{"id":"opt_4","text":"Mentor meminta staf baru membatalkan usulannya"}],"audio_text":"まだ荒削りな点はあるが、彼は彼なりに現場の課題を分析して独自の提案をまとめてくれた。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '彼は彼なりに mengapresiasi kontribusi sesuai tahap kemampuan dan perannya.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2e99eda0-91c3-4902-adfa-b8f6f2a5fa24', '474823bb-06c9-4329-837d-d6491f36ff2f', 'd1000019-0000-0000-0000-000000000034', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karya dokumenter yang jujur itu pasti menggugah kesadaran setiap penontonnya."', '{"romaji":"Genjitsu o chokushi shita sono kiroku eiga wa, miru mono no ryoushin o yusaburazu ni wa okimasen.","display_text":"現実を直視したその記録映画は、見る者の良心を揺さぶらずにはおきません。","phonetic_breakdown":["げんじつをちょくしした","そのきろくえいがは","みるもののりょうしんを","ゆさぶらずには","おきません"]}'::jsonb, '{"expected_transcript":"現実を直視したその記録映画は、見る者の良心を揺さぶらずにはおきません。"}'::jsonb, NULL, NULL, '揺さぶらずにはおきません menyatakan dampak emosional dan moral yang niscaya terjadi.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2ed7db7d-7385-43c6-9e9a-7f736a862fbc', '474823bb-06c9-4329-837d-d6491f36ff2f', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah menjadi proyek berskala internasional, standar keamanannya pun sangat ketat."', '{"romaji":"Kokusai purojekuto to mo naru to, anzen kijun mo kiwamete kibishii.","tokens":["とも","安全基準も","厳しい。","厳しかった。","国際プロジェクト","なると、","極めて","とはいえ、"],"target_translation":"Jika sudah menjadi proyek berskala internasional, standar keamanannya pun sangat ketat."}'::jsonb, '["国際プロジェクト","とも","なると、","安全基準も","極めて","厳しい。"]'::jsonb, NULL, NULL, '～ともなると menyoroti ekspektasi dan standar ketat pada level prestisius.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2cb36ddd-8f85-4094-b555-4067bd429b0b', '474823bb-06c9-4329-837d-d6491f36ff2f', 'd1000019-0000-0000-0000-000000000036', 'listening', 'listening_choice', 'Simulasi N1 (9/10): Dengarkan pasal kepatuhan hukum berikut. Bagaimana prinsip penegakan aturan di organisasi ini?', '{"options":[{"id":"opt_1","text":"Pejabat tinggi dibebaskan dari sanksi jika kontribusinya besar"},{"id":"opt_2","text":"Sanksi hanya berlaku bagi karyawan baru"},{"id":"opt_3","text":"Tanpa memandang jabatan maupun tingkat kontribusi, pelanggaran hukum yang terbukti akan dikenai sanksi tegas"},{"id":"opt_4","text":"Organisasi tidak memiliki aturan kepatuhan hukum"}],"audio_text":"役職や貢献度のいかんによらず、法令違反が確認された場合には厳正な処分を科すものとする。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '役職や貢献度のいかんによらず menegaskan keadilan hukum tanpa pengecualian.', 9, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('408db6fd-9958-4c2a-ab94-7ca2701e3434', '474823bb-06c9-4329-837d-d6491f36ff2f', 'd1000019-0000-0000-0000-000000000037', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Analisis mendalam yang didukung bukti objektif ini sungguh layak untuk dipercaya."', '{"romaji":"Kyakkanteki na shouko ni urauchi sareta kono bunseki wa, juubun ni shinrai suru ni taru mono desu.","display_text":"客観的な証拠に裏打ちされたこの分析は、十分に信頼するに足るものです。","phonetic_breakdown":["きゃっかんてきな","しょうこにうらうちされた","このぶんせきは","じゅうぶんに","しんらいするにたるものです"]}'::jsonb, '{"expected_transcript":"客観的な証拠に裏打ちされたこの分析は、十分に信頼するに足るものです。"}'::jsonb, NULL, NULL, '信頼するに足る (layak dipercaya) menutup simulasi kesiapan JLPT N1.', 10, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cc9fadea-c120-4b81-9ee2-0e868133aeba', '488f5061-8241-4269-b37d-897b0e2137c2', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Lengkapi kalimat berita berikut: 悪天候のため、国際会議の日程変更___。', '{"options":["を皮切りにした","を契機にした","をよそにした","を余儀なくされた"],"translation":"Akibat cuaca buruk, konferensi internasional terpaksa mengubah jadwalnya.","sentence_template":"悪天候のため、国際会議の日程変更[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, NULL, NULL, 'Kata benda + を余儀なくされる menyatakan terpaksa melakukan sesuatu karena keadaan eksternal yang tidak terelakkan.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9cb9a015-0cc5-4591-b0fa-f9beb988b90a', '488f5061-8241-4269-b37d-897b0e2137c2', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Pilih bentuk kausatif yang tepat untuk kalimat berikut: 原材料費の高騰が、メーカー各社に値上げ___。', '{"options":["を余儀なくさせている","に至っている","を禁じ得ない","を余儀なくされている"],"translation":"Lonjakan harga bahan baku memaksa berbagai perusahaan manufaktur untuk menaikkan harga.","sentence_template":"原材料費の高騰が、メーカー各社に値上げ[blank]。"}'::jsonb, '{"selected":"を余儀なくさせている"}'::jsonb, NULL, NULL, 'Jika subjeknya adalah penyebab eksternal (原材料費の高騰), gunakan bentuk kausatif ～に...を余儀なくさせる.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6b6e0743-fd0e-4f6e-87fb-42b9c0ebfae8', '488f5061-8241-4269-b37d-897b0e2137c2', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan pola yang benar: 震災により、多くの被災者が長期の避難生活___。', '{"options":["を前提としている","を対象としている","を余儀なくされている","を軸としている"],"translation":"Akibat gempa besar, banyak korban bencana terpaksa menjalani kehidupan pengungsian jangka panjang.","sentence_template":"震災により、多くの被災者が長期の避難生活[blank]。"}'::jsonb, '{"selected":"を余儀なくされている"}'::jsonb, NULL, NULL, '～を余儀なくされている menggambarkan kondisi keterpaksaan yang masih berlangsung hingga kini.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('82669568-ec1c-4e73-8b5f-f9b4cb9b012f', '488f5061-8241-4269-b37d-897b0e2137c2', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Akibat kekurangan dana, proyek itu terpaksa dihentikan."', '{"romaji":"Shikin busoku ni yori keikaku wa chuushi wo yoginaku sareta no da.","tokens":["により","のだ","中止","計画は","ながら","資金不足","を余儀なくされた","に至った"],"target_translation":"Akibat kekurangan dana, proyek itu terpaksa dihentikan."}'::jsonb, '["資金不足","により","計画は","中止","を余儀なくされた","のだ"]'::jsonb, NULL, NULL, '中止を余儀なくされた berarti ''terpaksa dibatalkan/dihentikan''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('08715d39-474f-4f00-bda4-cc74e888b77b', '488f5061-8241-4269-b37d-897b0e2137c2', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Perubahan regulasi memaksa kami meninjau ulang strategi."', '{"romaji":"Kisei no kyouka de senryaku no minaoshi wo yoginaku sareta.","tokens":["見直し","規制の","を余儀なく","された","戦略の","強化で","をめぐって","ばかりに"],"target_translation":"Perubahan regulasi memaksa kami meninjau ulang strategi."}'::jsonb, '["規制の","強化で","戦略の","見直し","を余儀なく","された"]'::jsonb, NULL, NULL, '戦略の見直しを余儀なくされた berarti ''terpaksa meninjau ulang strategi''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('08a6a386-2771-4af3-bc56-bb5fe863045c', '488f5061-8241-4269-b37d-897b0e2137c2', 'd1000019-0000-0000-0000-000000000029', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena cedera, atlet tersebut terpaksa mengundurkan diri dari turnamen."', '{"romaji":"Fushou no tame, sono senshu wa taikai kara no kiken wo yoginaku sareta.","display_text":"負傷のため、その選手は大会からの棄権を余儀なくされた。","phonetic_breakdown":["fu-shou","no","ta-me","so-no","sen-shu","wa","tai-kai","ka-ra","no","ki-ken","wo","yo-gi-na-ku","sa-re-ta"]}'::jsonb, '{"expected_transcript":"負傷のため、その選手は大会からの棄権を余儀なくされた。"}'::jsonb, NULL, NULL, '棄権を余儀なくされた adalah kolokasi berita olahraga yang sangat umum untuk ''terpaksa mundur/walkover''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c939f812-4730-4e05-ac79-e10d45708a3f', '488f5061-8241-4269-b37d-897b0e2137c2', 'd1000019-0000-0000-0000-000000000029', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Siapa yang mengalami keterpaksaan dan apa penyebabnya?', '{"options":[{"id":"opt_1","text":"Tim peneliti terpaksa mengecilkan skala eksperimen akibat pemangkasan anggaran besar-besaran"},{"id":"opt_2","text":"Tim peneliti meminta tambahan anggaran untuk memperbesar eksperimen"},{"id":"opt_3","text":"Pemangkasan anggaran membuat eksperimen selesai lebih cepat"},{"id":"opt_4","text":"Tim peneliti membubarkan diri sebelum anggaran dipotong"}],"audio_text":"予算の大幅削減により、研究チームは実験規模の縮小を余儀なくされた。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '実験規模の縮小を余儀なくされた menunjukkan keterpaksaan akibat pemangkasan anggaran.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f731512f-213f-4b36-bf3b-bfec0afc588f', '488f5061-8241-4269-b37d-897b0e2137c2', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Lengkapi kalimat dengan kata benda yang tepat: 道路の陥没事故により、周辺は全面通行止め___。', '{"options":["を余儀なくされた","を余儀なくさせた","に至った","極まりない"],"translation":"Akibat insiden jalan amblas, area sekitar terpaksa ditutup total bagi lalu lintas.","sentence_template":"道路の陥没事故により、周辺は全面通行止め[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, NULL, NULL, '全面通行止めを余儀なくされた berarti terpaksa mengalami penutupan jalan total.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('383b61e4-aac3-4b69-91ce-33db070cb50e', '4fcb77ae-4a49-4b45-91a4-2eafce253180', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk melengkapi kalimat berita berikut: 経済状況の___により、政府は緊急対策を講じた。', '{"options":["自動化","簡略化","活性化","深刻化"],"translation":"Akibat memburuknya kondisi ekonomi secara serius, pemerintah mengambil langkah darurat.","sentence_template":"経済状況の[blank]により、政府は緊急対策を講じた。"}'::jsonb, '{"selected":"深刻化"}'::jsonb, NULL, NULL, '深刻化 (shinkokuka) berarti ''menjadi semakin serius/kritis'', sangat lazim dalam konteks krisis ekonomi atau sosial di level N1.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('168be49d-d64a-4252-8277-595b1062b543', '4fcb77ae-4a49-4b45-91a4-2eafce253180', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan istilah manajemen krisis yang tepat: 不正会計が___し、経営陣の責任が厳しく問われている。', '{"options":["出発","発揮","発行","発覚"],"translation":"Kecurangan akuntansi terbongkar, dan tanggung jawab jajaran direksi dipertanyakan secara keras.","sentence_template":"不正会計が[blank]し、経営陣の責任が厳しく問われている。"}'::jsonb, '{"selected":"発覚"}'::jsonb, NULL, NULL, '発覚 (hakkaku) berarti terbongkarnya suatu skandal, pelanggaran, atau fakta tersembunyi.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('090c3988-0a54-45e3-a744-1a85d0f349ee', '4fcb77ae-4a49-4b45-91a4-2eafce253180', NULL, 'reading', 'fill_blank', 'Pilih kosakata formal yang tepat: 表面的な修正ではなく、___な改革が求められている。', '{"options":["一時的","抜本的","偶発的","消極的"],"translation":"Bukan perbaikan di permukaan saja, melainkan reformasi yang mendasar yang dibutuhkan.","sentence_template":"表面的な修正ではなく、[blank]な改革が求められている。"}'::jsonb, '{"selected":"抜本的"}'::jsonb, NULL, NULL, '抜本的 (bapponteki) berarti ''mendasar/radikal hingga ke akar masalah'', kontras dengan 表面的な (di permukaan).', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8e52ed2f-fa57-42ea-b57e-f7fe709d312a', '4fcb77ae-4a49-4b45-91a4-2eafce253180', NULL, 'listening', 'listening_choice', 'Dengarkan laporan singkat berikut. Langkah apa yang diambil perusahaan setelah insiden terjadi?', '{"options":[{"id":"opt_1","text":"Membentuk markas besar penanggulangan darurat di kantor pusat"},{"id":"opt_2","text":"Memindahkan kantor pusat ke gedung baru"},{"id":"opt_3","text":"Menunda peluncuran produk selama satu tahun"},{"id":"opt_4","text":"Menghapus seluruh data pelanggan lama"}],"audio_text":"大規模な情報漏洩が発生したことを受け、本社に緊急対策本部が設置されました。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '緊急対策本部が設置されました berarti ''markas besar penanggulangan darurat telah dibentuk'' akibat kebocoran informasi (情報漏洩).', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('368eea51-7e89-4893-9e71-c702eca52c6b', '4fcb77ae-4a49-4b45-91a4-2eafce253180', NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan berikut. Apa yang sedang dihadapi oleh proyek tersebut?', '{"options":[{"id":"opt_1","text":"Berhasil memperoleh pendanaan tambahan dari investor"},{"id":"opt_2","text":"Secara de facto jatuh dalam kondisi gagal total akibat kekurangan dana berkepanjangan"},{"id":"opt_3","text":"Sedang memasuki tahap uji coba akhir dengan hasil memuaskan"},{"id":"opt_4","text":"Dialihkan pengelolaannya ke anak perusahaan di luar negeri"}],"audio_text":"長引く資金不足により、開発計画は事実上の破綻状態に陥っている。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '事実上の破綻状態に陥っている berarti ''secara de facto terperosok ke dalam kondisi bangkrut/gagal total''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f160c43-d81e-479f-8206-a6812d936bbf', '4fcb77ae-4a49-4b45-91a4-2eafce253180', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kita harus segera menyusun langkah pencegahan terulangnya kejadian."', '{"romaji":"Soukyuu ni saihatsu boushisaku wo sakutei shinakereba naranai.","display_text":"早急に再発防止策を策定しなければならない。","phonetic_breakdown":["sou-kyuu","ni","sai-ha-tsu","bou-shi-sa-ku","wo","sa-ku-tei","shi-na-ke-re-ba","na-ra-nai"]}'::jsonb, '{"expected_transcript":"早急に再発防止策を策定しなければならない。"}'::jsonb, NULL, NULL, '再発防止策 (saihatsu boushisaku) adalah istilah standar bisnis/pemerintahan untuk ''langkah pencegahan terulangnya insiden''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8283aa16-4f22-4ca4-9e8b-45a0e1bdbc93', '4fcb77ae-4a49-4b45-91a4-2eafce253180', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: 長年の交渉の末、ようやく平和条約の___に至った。', '{"options":["締結","撤回","破棄","決裂"],"translation":"Setelah negosiasi bertahun-tahun, akhirnya tercapai penandatanganan perjanjian damai.","sentence_template":"長年の交渉の末、ようやく平和条約の[blank]に至った。"}'::jsonb, '{"selected":"締結"}'::jsonb, NULL, NULL, '締結に至る (mencapai tahap pengesahan/penandatanganan) adalah kolokasi resmi diplomasi dan hukum.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2b98fd0d-aa86-43d9-a77f-b00475bcfd8c', '4fcb77ae-4a49-4b45-91a4-2eafce253180', 'd1000019-0000-0000-0000-000000000028', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah melalui diskusi panjang, dewan akhirnya mencapai kesimpulan bersama."', '{"romaji":"Tabikasanaru giron no sue, iinkai wa youyaku goui keisei ni itarimashita.","display_text":"度重なる議論の末、委員会はようやく合意形成に至りました。","phonetic_breakdown":["たびかさなる","ぎろんのすえ","いいんかいはようやく","ごういけいせいに","いたりました"]}'::jsonb, '{"expected_transcript":"度重なる議論の末、委員会はようやく合意形成に至りました。"}'::jsonb, NULL, NULL, '合意形成に至る berarti berhasil mencapai konsensus.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4a220901-634d-4a43-9c03-8b43c6536117', '538428ec-44ed-4292-ac00-1269d9b6292f', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Lengkapi tajuk rencana berikut: 景気回復の兆しが見え始めた___、中小企業の経営環境は依然として厳しい。', '{"options":["とはいえ","をもって","を余儀なくされ","極まりない"],"translation":"Meskipun memang tanda-tanda pemulihan ekonomi mulai terlihat, iklim usaha UKM tetap saja masih berat.","sentence_template":"景気回復の兆しが見え始めた[blank]、中小企業の経営環境は依然として厳しい。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '～とはいえ mengakui kebenaran klausa pertama terlebih dahulu, lalu menyampaikan realitas atau catatan kontras.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d1a1a6fa-744a-4322-be47-bf7412fa17f2', '538428ec-44ed-4292-ac00-1269d9b6292f', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Pilih bentuk yang tepat setelah kata benda: 経験豊富なベテラン___、初めての市場では慎重な調査が欠かせない。', '{"options":["とはいえ","に至って","ともなると","ずにはおかず"],"translation":"Meskipun ia seorang veteran berpengalaman, riset yang cermat tetap mutlak diperlukan di pasar yang baru pertama kali dimasuki.","sentence_template":"経験豊富なベテラン[blank]、初めての市場では慎重な調査が欠かせない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, 'Kata benda (ベテラン) dapat langsung diikuti とはいえ (atau であるとはいえ).', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5c6d2781-4681-4092-8c8d-1df2cb5927d1', '538428ec-44ed-4292-ac00-1269d9b6292f', 'd1000019-0000-0000-0000-000000000030', 'listening', 'listening_choice', 'Dengarkan komentar editor surat kabar. Apa penilaian berimbang beliau terhadap AI generatif?', '{"options":[{"id":"opt_1","text":"AI generatif sama sekali tidak meningkatkan efisiensi kerja"},{"id":"opt_2","text":"Meskipun AI generatif meningkatkan efisiensi kerja secara drastis, proses verifikasi akurasi oleh manusia tetap tidak boleh dihilangkan"},{"id":"opt_3","text":"Manusia tidak perlu lagi memeriksa data yang dihasilkan AI"},{"id":"opt_4","text":"Perusahaan harus melarang penggunaan semua perangkat lunak komputer"}],"audio_text":"生成AIが業務効率を飛躍的に高めたとはいえ、情報の正確性を人間が検証する工程は省けない。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '高めたとはいえ mengakui manfaat AI, lalu menegaskan syarat penting 検証する工程は省けない.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('419bd25b-b4bf-42f6-9391-cad2d797ac77', '538428ec-44ed-4292-ac00-1269d9b6292f', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun sudah memasuki bulan April, udara pagi masih terasa cukup dingin."', '{"romaji":"Shigatsu ni haitta to wa ie, asa no kuuki wa mada hadazamui.","tokens":["入った","朝の空気は","肌寒い。","肌寒かった。","四月に","とはいえ、","まだ","をもって、"],"target_translation":"Meskipun sudah memasuki bulan April, udara pagi masih terasa cukup dingin."}'::jsonb, '["四月に","入った","とはいえ、","朝の空気は","まだ","肌寒い。"]'::jsonb, NULL, NULL, '四月に入ったとはいえ mengakui fakta kalender sebelum kontras cuaca まだ肌寒い.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('02627139-6c15-49cb-a598-816e88773900', '538428ec-44ed-4292-ac00-1269d9b6292f', 'd1000019-0000-0000-0000-000000000030', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun dikatakan bebas biaya, tetap ada syarat dan ketentuan yang harus diperhatikan."', '{"romaji":"Muryou to wa ie, riyou ni atatte wa ikutsuka no chuuiten ga arimasu.","display_text":"無料とはいえ、利用にあたってはいくつかの注意点があります。","phonetic_breakdown":["むりょう","とはいえ","りようにあたっては","いくつかの","ちゅういてんがあります"]}'::jsonb, '{"expected_transcript":"無料とはいえ、利用にあたってはいくつかの注意点があります。"}'::jsonb, NULL, NULL, '無料とはいえ (meskipun gratis) sangat lazim dalam penjelasan layanan dan perjanjian.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6b3d9912-48fb-499c-bcd7-844e36c7c706', '538428ec-44ed-4292-ac00-1269d9b6292f', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: オンライン会議が定着した___、重要な信頼構築には対面での対話が有効だ。', '{"options":["とはいえ","なりに","に足らず","いかんによらず"],"translation":"Meskipun rapat daring sudah mengakar, dialog tatap muka tetap efektif untuk membangun kepercayaan penting.","sentence_template":"オンライン会議が定着した[blank]、重要な信頼構築には対面での対話が有効だ。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '定着したとはいえ mengakui tren kerja digital sambil mempertahankan nilai pertemuan langsung.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('42f84fb2-4d5a-4018-9f3c-63bf04958981', '538428ec-44ed-4292-ac00-1269d9b6292f', 'd1000019-0000-0000-0000-000000000030', 'listening', 'listening_choice', 'Dengarkan ulasan pakar pendidikan. Apa catatannya terhadap pembelajaran digital?', '{"options":[{"id":"opt_1","text":"Semua buku tulis kertas harus dibuang dari sekolah"},{"id":"opt_2","text":"Tablet sama sekali tidak berguna untuk belajar"},{"id":"opt_3","text":"Meskipun materi tablet praktis, pengembangan kemampuan menata pikiran dengan menulis di kertas tidak boleh diremehkan"},{"id":"opt_4","text":"Siswa tidak boleh menggunakan komputer sebelum lulus kuliah"}],"audio_text":"タブレット教材は便利だとはいえ、紙に書いて思考を整理する力の育成も軽視すべきではない。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '便利だとはいえ (bentuk biasa kata sifat-na + とはいえ) menyajikan argumen seimbang.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2dafe4f9-996a-4422-8315-ef086237f8dc', '538428ec-44ed-4292-ac00-1269d9b6292f', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun hanya proyek kecil, kita harus mengerjakannya dengan penuh tanggung jawab."', '{"romaji":"Chiisana anken to wa ie, sekinin o motte torikumu beki da.","tokens":["とはいえ、","持って","べきだ。","取り組んだ","小さな案件","責任を","取り組む","に至って、"],"target_translation":"Meskipun hanya proyek kecil, kita harus mengerjakannya dengan penuh tanggung jawab."}'::jsonb, '["小さな案件","とはいえ、","責任を","持って","取り組む","べきだ。"]'::jsonb, NULL, NULL, '小さな案件とはいえ menegaskan profesionalisme meski skala proyek kecil.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f57c02fb-b177-41d1-bc2f-c8a6b8e1a6c8', '5f66ce48-d83a-4c1c-a56d-95f9e939bb87', NULL, 'reading', 'fill_blank', 'Pilih istilah diplomatis yang tepat: 合意に反する一方的な行動は、誠に___である。', '{"options":["満足","愉快","歓迎","遺憾"],"translation":"Tindakan sepihak yang melanggar kesepakatan sungguh sangat disayangkan.","sentence_template":"合意に反する一方的な行動は、誠に[blank]である。"}'::jsonb, '{"selected":"遺憾"}'::jsonb, NULL, NULL, '遺憾 (ikan) adalah istilah diplomatis dan resmi untuk menyatakan penyesalan keras atau ketidaksetujuan.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9a98a3fd-d6c6-4afd-84ab-65f6dc0e4aa1', '5f66ce48-d83a-4c1c-a56d-95f9e939bb87', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kritik sosial berikut: 公共の場でのマナーを無視した行為は___だと言わざるを得ない。', '{"options":["合理的","模範的","非常識","建設的"],"translation":"Perilaku yang mengabaikan tata krama di tempat umum mau tidak mau harus disebut tidak tahu adat.","sentence_template":"公共の場でのマナーを無視した行為は[blank]だと言わざるを得ない。"}'::jsonb, '{"selected":"非常識"}'::jsonb, NULL, NULL, '非常識 (hijoushiki) berarti ''melampaui akal sehat / tidak beradab / tidak tahu aturan umum''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6fb89c2b-8acd-4a46-8b9a-e889adbf6f59', '5f66ce48-d83a-4c1c-a56d-95f9e939bb87', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk penilaian pernyataan resmi: 責任の所在を曖昧にしたままの説明は、___な印象を与える。', '{"options":["誠実","明快","無責任","丁寧"],"translation":"Penjelasan yang membiarkan letak tanggung jawab tetap kabur memberikan kesan sangat tidak bertanggung jawab.","sentence_template":"責任の所在を曖昧にしたままの説明は、[blank]な印象を与える。"}'::jsonb, '{"selected":"無責任"}'::jsonb, NULL, NULL, '無責任 (musekinin) berarti ''tidak bertanggung jawab'', sering muncul dalam kritik politik dan bisnis.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('35fe28dc-a6a2-4047-926e-8a71981331a5', '5f66ce48-d83a-4c1c-a56d-95f9e939bb87', NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan juru bicara kementerian berikut. Bagaimana sikap pemerintah terhadap tindakan tersebut?', '{"options":[{"id":"opt_1","text":"Mendukung penuh keputusan negara mitra"},{"id":"opt_2","text":"Menilai tindakan tersebut sangat tidak pantas dan melayangkan protes keras"},{"id":"opt_3","text":"Meminta waktu satu bulan untuk mempelajari isi aturan"},{"id":"opt_4","text":"Mengucapkan terima kasih atas konsultasi sebelumnya"}],"audio_text":"事前の協議もなく規制を強化した相手国の対応は、極めて不適切であり、強く抗議する。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '極めて不適切であり、強く抗議する berarti ''sangat tidak patut dan memprotes keras''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3586c7da-218d-42c1-aee0-2f6517245ac0', '5f66ce48-d83a-4c1c-a56d-95f9e939bb87', NULL, 'listening', 'listening_choice', 'Dengarkan komentar editor berikut. Apa pujian yang diberikan kepada laporan tersebut?', '{"options":[{"id":"opt_1","text":"Laporannya terlalu panjang dan bertele-tele"},{"id":"opt_2","text":"Datanya tidak lengkap sehingga sulit dipahami"},{"id":"opt_3","text":"Laporannya sangat jelas, ringkas, dan berhasil merangkum data besar"},{"id":"opt_4","text":"Laporannya harus ditulis ulang oleh tim lain"}],"audio_text":"膨大なデータを整理し、要点を簡潔にまとめた彼の報告書は実に明快だ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '要点を簡潔にまとめた...実に明快だ berarti ''merangkum poin inti secara ringkas dan sungguh sangat jelas''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4fd4c932-2a4b-458c-9810-82d487a20840', '5f66ce48-d83a-4c1c-a56d-95f9e939bb87', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pernyataan seperti itu sungguh tidak sopan terhadap para hadirin."', '{"romaji":"Sono you na hatsugen wa, shussekisha ni taishite taihen shitsurei ni ataru.","display_text":"そのような発言は、出席者に対して大変失礼にあたる。","phonetic_breakdown":["so-no","you","na","ha-tsu-gen","wa","shu-sse-ki-sha","ni","tai-shi-te","tai-hen","shi-tsu-rei","ni","a-ta-ru"]}'::jsonb, '{"expected_transcript":"そのような発言は、出席者に対して大変失礼にあたる。"}'::jsonb, NULL, NULL, '失礼にあたる berarti ''termasuk tindakan yang tidak sopan'' dalam konteks formal.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('85b17cb3-9a45-41d8-8519-3679a3b38190', '5f66ce48-d83a-4c1c-a56d-95f9e939bb87', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: 根拠のない誹謗中傷は、極めて___極まりない行為だ。', '{"options":["悪質","円満","誠実","謙虚"],"translation":"Fitnah dan pencemaran nama baik tanpa dasar adalah tindakan yang amat sangat tercela/jahat.","sentence_template":"根拠のない誹謗中傷は、[blank]極まりない行為だ。"}'::jsonb, '{"selected":"悪質"}'::jsonb, NULL, NULL, '悪質極まりない (sangat jahat/berniat buruk) berpasangan erat dengan 誹謗中傷 (fitnah/pencemaran nama baik).', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a1523187-20e4-41dc-8e64-be01fca8bb69', '5f66ce48-d83a-4c1c-a56d-95f9e939bb87', 'd1000019-0000-0000-0000-000000000032', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sungguh merupakan kehormatan tak terhingga dapat diundang sebagai pembicara utama."', '{"romaji":"Kichou kouen ni omaneki itadaki, mi ni amaru kouei, kangeki kiwamari gozaimasen.","display_text":"基調講演にお招きいただき、身に余る光栄、感激極まりございません。","phonetic_breakdown":["きちょうこうえんに","おまねきいただき","みにあまるこうえい","かんげききわまりございません"]}'::jsonb, '{"expected_transcript":"基調講演にお招きいただき、身に余る光栄、感激極まりございません。"}'::jsonb, NULL, NULL, '感激極まりございません adalah bentuk super-sopan untuk mengekspresikan rasa haru dan terima kasih.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9f6919c3-d63c-41f0-890c-5e0c57bb9ce1', '600d9ae4-a799-4d44-aad2-d0aca219d2b1', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Uji kesiapan N1 — pilih pola yang tepat: 多角的な検証を経たこの報告書は、国際会議での議論___高い信頼性を備えている。', '{"options":["に足りない","を余儀なくされた","に足る","極まりない"],"translation":"Laporan yang telah melalui verifikasi multidimensi ini memiliki kredibilitas tinggi yang layak untuk dibahas di konferensi internasional.","sentence_template":"多角的な検証を経たこの報告書は、国際会議での議論[blank]高い信頼性を備えている。"}'::jsonb, '{"selected":"に足る"}'::jsonb, NULL, NULL, '議論に足る高い信頼性 menegaskan kelayakan laporan untuk forum internasional.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('345f2b43-77d2-46fe-a1e6-aa1a0e0f0488', '600d9ae4-a799-4d44-aad2-d0aca219d2b1', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Sintesis N1 — lengkapi kalimat berita berikut: 度重なる遅延が続き、ついに契約解除___、同社は抜本的な体制刷新を余儀なくされた。', '{"options":["いかんによらず","なりに","に至るに及んで","に至って"],"translation":"Setelah keterlambatan berulang hingga akhirnya berujung pada pembatalan kontrak, perusahaan itu terpaksa merombak sistemnya secara mendasar.","sentence_template":"度重なる遅延が続き、ついに契約解除[blank]、同社は抜本的な体制刷新を余儀なくされた。"}'::jsonb, '{"selected":"に至って"}'::jsonb, NULL, NULL, 'Menggabungkan pola Unit 1 (～に至って) dan Unit 2 (～を余儀なくされた) dalam satu kalimat berita N1 yang utuh.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('24cb8087-1a19-41fd-b627-90ae9d73ce83', '600d9ae4-a799-4d44-aad2-d0aca219d2b1', 'd1000019-0000-0000-0000-000000000037', 'listening', 'listening_choice', 'Dengarkan pernyataan penutup konferensi berikut. Apa yang ditegaskan oleh ketua panitia?', '{"options":[{"id":"opt_1","text":"Diskusi hari ini tidak menghasilkan rekomendasi apa pun"},{"id":"opt_2","text":"Hanya peserta dari satu bidang ilmu yang diperbolehkan berbicara"},{"id":"opt_3","text":"Konferensi dibatalkan sebelum sesi penutupan dimulai"},{"id":"opt_4","text":"Tanpa memandang jabatan atau bidang, diskusi melahirkan rekomendasi berharga yang layak menggerakkan masyarakat"}],"audio_text":"立場や専門分野のいかんによらず、本日の議論は今後の社会を動かすに足る貴重な提言を生み出した。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, 'Sintesis pola Unit 9 (～いかんによらず) dan Unit 10 (～に足る) dalam pidato penutupan formal.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('67d51240-9b30-4c12-8f57-46bd8037736a', '600d9ae4-a799-4d44-aad2-d0aca219d2b1', 'd1000019-0000-0000-0000-000000000037', 'listening', 'listening_choice', 'Dengarkan komentar editorial berikut. Apa kesimpulan penulis tentang proyek pembaruan kota?', '{"options":[{"id":"opt_1","text":"Warga menolak seluruh rencana penataan kota karena terlalu mahal"},{"id":"opt_2","text":"Meski terkendala anggaran, upaya membangun kota yang membanggakan generasi mendatang pasti mengundang empati warga"},{"id":"opt_3","text":"Anggaran pemerintah daerah berlebih sehingga proyek bisa dipercepat"},{"id":"opt_4","text":"Proyek tersebut hanya berfokus pada pembangunan gedung perkantoran"}],"audio_text":"財政的な制約があるとはいえ、次世代に誇れる街づくりを目指す姿勢は市民の共感を呼ばずにはおかない。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'Sintesis pola Unit 3 (～とはいえ) dan Unit 7 (～ずにはおかない) dalam wacana tajuk rencana N1.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ce4ee329-cce5-41d5-8f6e-d1a89ec2a9c6', '600d9ae4-a799-4d44-aad2-d0aca219d2b1', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Dengan dedikasi tinggi, mereka telah membangun reputasi yang layak dipercaya."', '{"romaji":"Naganen no seijitsu na taiou ni yori shinrai ni taru jisseki wo kizuita.","tokens":["に足る","対応により","実績を築いた","とはいえ","長年の","信頼","誠実な","極まりない"],"target_translation":"Dengan dedikasi tinggi, mereka telah membangun reputasi yang layak dipercaya."}'::jsonb, '["長年の","誠実な","対応により","信頼","に足る","実績を築いた"]'::jsonb, NULL, NULL, '信頼に足る実績を築いた berarti ''telah membangun rekam jejak yang layak dipercaya''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('47e25c8f-9c10-4852-a965-9cfa74cdd019', '600d9ae4-a799-4d44-aad2-d0aca219d2b1', 'd1000019-0000-0000-0000-000000000037', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dengan selesainya tahap ini, Anda telah mencapai tingkat penguasaan yang layak dibanggakan."', '{"romaji":"Kore made no manabi wo motte, hokori ni taru koudo na nihongoryoku wo mi ni tsuketa to ieyou.","display_text":"これまでの学びをもって、誇りに足る高度な日本語力を身につけたと言えよう。","phonetic_breakdown":["ko-re","ma-de","no","ma-na-bi","wo","mo-tte","ho-ko-ri","ni","ta-ru","kou-do","na","ni-hon-go-ryo-ku","wo","mi","ni","tsu-ke-ta","to","i-e-you"]}'::jsonb, '{"expected_transcript":"これまでの学びをもって、誇りに足る高度な日本語力を身につけたと言えよう。"}'::jsonb, NULL, NULL, 'Sintesis elegan ～をもって (Unit 4) dan 誇りに足る (Unit 10: layak dibanggakan) sebagai penutup kurikulum JLPT N1.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('57900ddc-2044-4df6-bba2-dd860ccee5dd', '600d9ae4-a799-4d44-aad2-d0aca219d2b1', 'd1000019-0000-0000-0000-000000000037', 'listening', 'listening_choice', 'Dengarkan sambutan penutup seminar N1. Apa pesan pembicara kepada para peserta?', '{"options":[{"id":"opt_1","text":"Peserta diminta mengulang seluruh pelajaran dari tingkat dasar"},{"id":"opt_2","text":"Peserta belum siap menggunakan bahasa Jepang di kantor"},{"id":"opt_3","text":"Kemampuan analisis logis dan ekspresi para peserta telah mencapai standar yang layak berkiprah di dunia bisnis internasional"},{"id":"opt_4","text":"Seminar N1 dibatalkan untuk tahun depan"}],"audio_text":"皆さんの論理的な分析力と表現力は、国際的なビジネス現場で活躍するに足る水準に達しています。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '活躍するに足る水準 (standar yang layak untuk berkiprah) merangkum kesiapan praktis JLPT N1.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5b6d0b75-66ab-4650-888e-b7675049adba', '600d9ae4-a799-4d44-aad2-d0aca219d2b1', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Hasil riset jangka panjang itu benar-benar patut mendapat perhatian dunia internasional."', '{"romaji":"Chouki kenkyuu no seika wa chuumoku ni taru kachi ga aru.","tokens":["成果は、","に","価値がある。","極まりない。","長期研究の","注目","足る","に足りない"],"target_translation":"Hasil riset jangka panjang itu benar-benar patut mendapat perhatian dunia internasional."}'::jsonb, '["長期研究の","成果は、","注目","に","足る","価値がある。"]'::jsonb, NULL, NULL, '注目に足る (layak mendapat perhatian) menutup rangkaian sintesis N1 Unit 10.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f93ac12e-24c4-41ae-ab19-13e42b0f62b1', '64c592c5-f646-4295-9823-ffa120bc8bfc', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Pilih pola yang tepat: 顧客の個人情報を杜撰に管理していたとは、言語道断であり遺憾___。', '{"options":["に足らない","を余儀なくされた","極まりない","とはいえ"],"translation":"Mengelola data pribadi pelanggan secara sembrono sungguh keterlaluan dan amat sangat disayangkan.","sentence_template":"顧客の個人情報を杜撰に管理していたとは、言語道断であり遺憾[blank]。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, NULL, NULL, '遺憾極まりない menutup kecaman formal dengan penekanan tingkat tertinggi.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('37abf4e3-fd4d-4412-838c-c02c6aa7d6e8', '64c592c5-f646-4295-9823-ffa120bc8bfc', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 根拠のない誹謗中傷を繰り返す行為は、悪質___ものである。', '{"options":["に至る","に足る","極まる","をもって"],"translation":"Tindakan mengulang fitnah tanpa dasar adalah perbuatan yang luar biasa jahat.","sentence_template":"根拠のない誹謗中傷を繰り返す行為は、悪質[blank]ものである。"}'::jsonb, '{"selected":"極まる"}'::jsonb, NULL, NULL, '悪質極まるもの berarti ''sesuatu yang tingkat kejahatan/keburukannya ekstrem''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bfa84e6f-549c-4b9e-9e57-aeb0d6a6d9bf', '64c592c5-f646-4295-9823-ffa120bc8bfc', 'd1000019-0000-0000-0000-000000000032', 'listening', 'listening_choice', 'Dengarkan kutipan komentar berikut. Mengapa pembicara mengecam usulan tersebut?', '{"options":[{"id":"opt_1","text":"Karena pertemuan warga diadakan terlalu sering setiap minggu"},{"id":"opt_2","text":"Karena memaksakan proyek tanpa sekali pun mengadakan sosialisasi dinilai sangat egois dan sepihak"},{"id":"opt_3","text":"Karena anggaran proyek tersebut terlalu kecil"},{"id":"opt_4","text":"Karena rencana tersebut dibatalkan secara mendadak"}],"audio_text":"住民への説明会を一度も開かずに計画を強行するとは、独善的極まりないやり方だ。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '独善的極まりない berarti ''luar biasa merasa benar sendiri / sepihak''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1cf966b3-09be-4c84-a3fb-cdc258d1c847', '64c592c5-f646-4295-9823-ffa120bc8bfc', 'd1000019-0000-0000-0000-000000000032', 'listening', 'listening_choice', 'Dengarkan ulasan perjalanan berikut. Bagaimana kesan pembicara terhadap layanan penginapan itu?', '{"options":[{"id":"opt_1","text":"Sangat kecewa dengan kebersihan kamar"},{"id":"opt_2","text":"Harganya terlalu mahal dibandingkan fasilitasnya"},{"id":"opt_3","text":"Keramahtamahan yang teliti hingga detail membuat masa inap sangat nyaman dan tak terlupakan"},{"id":"opt_4","text":"Lokasinya terlalu jauh dari stasiun kereta"}],"audio_text":"細部まで行き届いたおもてなしは実に快適極まりなく、忘れられない滞在となった。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '快適極まりなく berarti ''luar biasa nyaman''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fb97c398-72bc-4f9a-8018-3466095f27cf', '64c592c5-f646-4295-9823-ffa120bc8bfc', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Membiarkan kerusakan jembatan tanpa perbaikan adalah tindakan yang amat berbahaya."', '{"romaji":"Hashi no sonshou wo houchi suru no wa kiken kiwamarinai.","tokens":["放置する","をもって","危険","極まりない","なりに","損傷を","橋の","のは"],"target_translation":"Membiarkan kerusakan jembatan tanpa perbaikan adalah tindakan yang amat berbahaya."}'::jsonb, '["橋の","損傷を","放置する","のは","危険","極まりない"]'::jsonb, NULL, NULL, '損傷を放置する (membiarkan kerusakan terbengkalai) dinilai 危険極まりない.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a14f3df7-4eb7-4b56-97ef-889ae09b7dfd', '64c592c5-f646-4295-9823-ffa120bc8bfc', 'd1000019-0000-0000-0000-000000000032', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sungguh luar biasa tidak adil jika hanya satu pihak yang menanggung semua kerugian."', '{"romaji":"Ippou dake ni subete no sonshitsu wo oshitsukeru no wa, fukouhei kiwamarinai.","display_text":"一方だけに全ての損失を押し付けるのは、不公平極まりない。","phonetic_breakdown":["i-ppou","da-ke","ni","su-be-te","no","son-shi-tsu","wo","o-shi-tsu-ke-ru","no","wa","fu-kou-hei","ki-wa-ma-ri-nai"]}'::jsonb, '{"expected_transcript":"一方だけに全ての損失を押し付けるのは、不公平極まりない。"}'::jsonb, NULL, NULL, '不公平極まりない berarti ''luar biasa tidak adil''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('81db33a8-e9dd-42de-8869-299de3e94fcd', '64c592c5-f646-4295-9823-ffa120bc8bfc', 'd1000019-0000-0000-0000-000000000032', 'listening', 'listening_choice', 'Dengarkan ulasan pengamat keamanan siber. Mengapa ia mengkritik perusahaan tersebut?', '{"options":[{"id":"opt_1","text":"Perusahaan telah menerapkan enkripsi tercanggih di dunia"},{"id":"opt_2","text":"Pelanggan tidak perlu menggunakan kata sandi"},{"id":"opt_3","text":"Menyimpan kata sandi pelanggan tanpa enkripsi menunjukkan sistem manajemen yang amat sangat ceroboh"},{"id":"opt_4","text":"Sistem keamanan perusahaan tidak pernah mengalami celah"}],"audio_text":"顧客のパスワードを暗号化せず平文で保存していたとは、杜撰極まりない管理体制だ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '杜撰極まりない (zusan kiwamarinai) berarti luar biasa ceroboh/asal-asalan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('043f6e6a-3298-4c89-bb55-84ead4980562', '64c592c5-f646-4295-9823-ffa120bc8bfc', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Membuat keputusan besar tanpa data pendukung adalah tindakan yang sangat gegabah."', '{"romaji":"Konkyo no nai handan wa keisotsu kiwamarinai.","tokens":["重大な判断は、","極まり","行為だ。","をもって、","根拠のない","軽率","ない","軽率に"],"target_translation":"Membuat keputusan besar tanpa data pendukung adalah tindakan yang sangat gegabah."}'::jsonb, '["根拠のない","重大な判断は、","軽率","極まり","ない","行為だ。"]'::jsonb, NULL, NULL, '軽率極まりない行為 berarti tindakan yang luar biasa gegabah.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3f8e828a-e880-4acf-91dc-3340bed17ed0', '67e2f856-1589-44aa-bc3f-658f80017a53', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi berikut: 彼は長年の誠実な仕事ぶりから、十分に信頼___人物である。', '{"options":["を余儀なく","極まりない","に至る","に足る"],"translation":"Dari rekam kerja tulusnya selama bertahun-tahun, ia adalah sosok yang sangat layak dipercaya.","sentence_template":"彼は長年の誠実な仕事ぶりから、十分に信頼[blank]人物である。"}'::jsonb, '{"selected":"に足る"}'::jsonb, NULL, NULL, 'Kata benda / kata kerja bentuk kamus + に足る berarti ''layak/cukup bernilai untuk...''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f79f0327-0919-4fb3-a120-6cad423abfc6', '67e2f856-1589-44aa-bc3f-658f80017a53', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Pilih bentuk negatif yang tepat untuk menyatakan sesuatu yang sepele: それは些細なミスであり、わざわざ問題視する___。', '{"options":["に足る","に足りない","ずにはおかない","に至らない"],"translation":"Itu hanyalah kesalahan sepele dan tidak layak untuk dipermasalahkan.","sentence_template":"それは些細なミスであり、わざわざ問題視する[blank]。"}'::jsonb, '{"selected":"に足りない"}'::jsonb, NULL, NULL, '～に足りない (atau ～に足らない) berarti ''tidak layak / tidak sepadan untuk (dikhawatirkan/dipermasalahkan)''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('719b1189-d37e-485a-8163-3a25c0cdbc1f', '67e2f856-1589-44aa-bc3f-658f80017a53', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Lengkapi kalimat ilmiah berikut: 今回得られたデータは、学術的な議論___高い精度を備えている。', '{"options":["に足る","なりに","をもって","とはいえ"],"translation":"Data yang diperoleh kali ini memiliki presisi tinggi yang layak untuk diperdebatkan secara akademis.","sentence_template":"今回得られたデータは、学術的な議論[blank]高い精度を備えている。"}'::jsonb, '{"selected":"に足る"}'::jsonb, NULL, NULL, '議論に足る berarti ''layak dijadikan bahan diskusi/kajian''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('382408e0-f35b-46ed-aa90-ac19483a1579', '67e2f856-1589-44aa-bc3f-658f80017a53', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Itu adalah kekhawatiran kecil yang tidak layak dirisaukan."', '{"romaji":"Sonna chiisana uwasa wa ki ni suru ni tarinai.","tokens":["噂は","気にする","足りない","極まりない","をもって","そんな","に","小さな"],"target_translation":"Itu adalah kekhawatiran kecil yang tidak layak dirisaukan."}'::jsonb, '["そんな","小さな","噂は","気にする","に","足りない"]'::jsonb, NULL, NULL, '気にするに足りない (atau 気にするに足らない) berarti ''tidak pantas untuk dipusingkan''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('174df52b-413b-4806-bda6-5a51165717c4', '67e2f856-1589-44aa-bc3f-658f80017a53', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Pencapaiannya layak menerima penghormatan tertinggi."', '{"romaji":"Kare no kouseki wa fukai keii ni taru mono da.","tokens":["に足る","深い","なりに","ものだ","彼の","とはいえ","敬意","功績は"],"target_translation":"Pencapaiannya layak menerima penghormatan tertinggi."}'::jsonb, '["彼の","功績は","深い","敬意","に足る","ものだ"]'::jsonb, NULL, NULL, '敬意に足る berarti ''layak mendapatkan rasa hormat''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('380b70dc-62b6-4659-83fb-3ea76a7ed079', '67e2f856-1589-44aa-bc3f-658f80017a53', 'd1000019-0000-0000-0000-000000000037', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Ini adalah temuan luar biasa yang layak mendapat perhatian dunia."', '{"romaji":"Kore wa sekai no chuumoku ni taru kakkiteki na seika de aru.","display_text":"これは世界の注目に足る画期的な成果である。","phonetic_breakdown":["ko-re","wa","se-kai","no","chuu-mo-ku","ni","ta-ru","ka-kki-te-ki","na","sei-ka","de","a-ru"]}'::jsonb, '{"expected_transcript":"これは世界の注目に足る画期的な成果である。"}'::jsonb, NULL, NULL, '注目に足る (layak diperhatikan) dan 画期的な成果 (pencapaian terobosan).', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a0cd993c-cbe6-49f7-ba40-421dc9114f4f', '67e2f856-1589-44aa-bc3f-658f80017a53', 'd1000019-0000-0000-0000-000000000037', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa arti ～に足らない di sini?', '{"options":[{"id":"opt_1","text":"Perbedaan pendapat kecil itu masalah sepele yang tidak berarti dibanding kuatnya aliansi kedua perusahaan"},{"id":"opt_2","text":"Perbedaan pendapat kecil itu langsung membatalkan aliansi"},{"id":"opt_3","text":"Kedua perusahaan tidak pernah bekerja sama"},{"id":"opt_4","text":"Perbedaan pendapat itu memerlukan sidang pengadilan"}],"audio_text":"些細な意見の相違など、両社の強固な提携関係から見れば取るに足らない問題だ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '取るに足らない adalah idiom baku N1 yang berarti ''sepele / tidak layak diperhitungkan''.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b2aa6a40-9640-43b7-805f-957043c82926', '67e2f856-1589-44aa-bc3f-658f80017a53', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Lengkapi kalimat dengan kata kerja yang tepat: 彼の証言は客観的な証拠と一致しており、___に足る。', '{"options":["信じる","信じた","信じて","信じない"],"translation":"Kesaksiannya konsisten dengan bukti objektif sehingga layak untuk dipercaya.","sentence_template":"彼の証言は客観的な証拠と一致しており、[blank]に足る。"}'::jsonb, '{"selected":"信じる"}'::jsonb, NULL, NULL, 'Di depan に足る, kata kerja selalu menggunakan bentuk kamus (信じるに足る).', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('46c04d9d-1059-4ee4-9745-ca9baaf900c5', '6eda4d41-dc1d-498c-af4f-cc44d5467057', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Pilih pola yang tepat untuk klausul resmi: 今回の改定案は、理事会の承認___正式に決定される。', '{"options":["とはいえ","なりに","に至って","をもって"],"translation":"Rancangan revisi kali ini akan diputuskan secara resmi dengan persetujuan dewan pengurus.","sentence_template":"今回の改定案は、理事会の承認[blank]正式に決定される。"}'::jsonb, '{"selected":"をもって"}'::jsonb, NULL, NULL, '理事会の承認をもって menandai sarana/syarat resmi penetapan keputusan.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e8cc58de-7425-48c4-b8d0-731be95cefcf', '6eda4d41-dc1d-498c-af4f-cc44d5467057', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Lengkapi pengumuman berikut: 誠に残念ですが、本日午後八時___、当館は閉館いたします。', '{"options":["に反しまして","をめぐりまして","をもちまして","を余儀なくして"],"translation":"Sungguh sangat disayangkan, terhitung hari ini pukul delapan malam, gedung ini akan ditutup secara permanen.","sentence_template":"誠に残念ですが、本日午後八時[blank]、当館は閉館いたします。"}'::jsonb, '{"selected":"をもちまして"}'::jsonb, NULL, NULL, '本日午後八時をもちまして adalah ungkapan penutupan resmi yang sangat santun.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c4fa8429-17c3-45b0-9a5f-323f19a8d5f9', '6eda4d41-dc1d-498c-af4f-cc44d5467057', 'd1000019-0000-0000-0000-000000000031', 'listening', 'listening_choice', 'Dengarkan pemberitahuan resmi berikut. Kapan peraturan baru tersebut mulai berlaku?', '{"options":[{"id":"opt_1","text":"Mulai tanggal 1 bulan depan"},{"id":"opt_2","text":"Mulai hari ini juga tanpa pemberitahuan sebelumnya"},{"id":"opt_3","text":"Mulai akhir tahun depan"},{"id":"opt_4","text":"Hanya berlaku bagi karyawan baru yang bergabung bulan lalu"}],"audio_text":"新たな就業規則は、来月一日をもって施行されますので、全社員は事前に内容を確認してください。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '来月一日をもって施行されます berarti ''diberlakukan mulai tanggal 1 bulan depan''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('61494abb-d620-4a3f-ac65-99e933655541', '6eda4d41-dc1d-498c-af4f-cc44d5467057', 'd1000019-0000-0000-0000-000000000031', 'listening', 'listening_choice', 'Dengarkan kutipan pidato berikut. Apa sikap yang dijanjikan oleh pembicara?', '{"options":[{"id":"opt_1","text":"Mengurangi jumlah staf layanan pelanggan"},{"id":"opt_2","text":"Berupaya meningkatkan mutu layanan dengan sistem kesiapan yang paripurna"},{"id":"opt_3","text":"Menyerahkan seluruh operasional kepada pihak ketiga"},{"id":"opt_4","text":"Menghentikan pengembangan produk baru sementara waktu"}],"audio_text":"今後も社員一丸となり、万全の体制をもってサービスの品質向上に努めてまいります。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '万全の体制をもって (dengan sistem kesiapan penuh) meningkatkan kualitas layanan.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('24295bde-51ac-4718-a56a-710ec287ea9d', '6eda4d41-dc1d-498c-af4f-cc44d5467057', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Pemberitahuan tertulis ini berlaku sebagai undangan resmi."', '{"romaji":"Honsho no soufu wo motte seishiki na go-annai to itashimasu.","tokens":["正式な","に至って","とはいえ","ご案内","をもって","といたします","本書の","送付"],"target_translation":"Pemberitahuan tertulis ini berlaku sebagai undangan resmi."}'::jsonb, '["本書の","送付","をもって","正式な","ご案内","といたします"]'::jsonb, NULL, NULL, '本書の送付をもってご案内といたします adalah kalimat penutup surat resmi korporasi.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bbe534bd-45c2-4ae2-994b-20f7c1df40d1', '6eda4d41-dc1d-498c-af4f-cc44d5467057', 'd1000019-0000-0000-0000-000000000031', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami menyambut para tamu undangan dengan penuh rasa hormat."', '{"romaji":"Fukai keii wo motte, go-raihin no minasama wo omukae itashimasu.","display_text":"深い敬意をもって、ご来賓の皆様をお迎えいたします。","phonetic_breakdown":["fu-kai","kei-i","wo","mo-tte","go-rai-hin","no","mi-na-sa-ma","wo","o-mu-ka-e","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"深い敬意をもって、ご来賓の皆様をお迎えいたします。"}'::jsonb, NULL, NULL, '深い敬意をもって (dengan rasa hormat yang mendalam) adalah ungkapan seremonial tingkat N1.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('277042bb-12de-42b5-a54e-e5facbcd9073', '6eda4d41-dc1d-498c-af4f-cc44d5467057', 'd1000019-0000-0000-0000-000000000031', 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan. Apa isi pemberitahuan tersebut?', '{"options":[{"id":"opt_1","text":"Perubahan anggaran dasar dapat dilakukan tanpa rapat"},{"id":"opt_2","text":"Anggaran dasar perusahaan tidak boleh diubah selamanya"},{"id":"opt_3","text":"Perubahan anggaran dasar resmi berlaku melalui resolusi khusus dalam rapat umum pemegang saham"},{"id":"opt_4","text":"Pemegang saham dilarang menghadiri rapat umum"}],"audio_text":"定款の変更は、株主総会における特別決議をもって効力を生じるものとする。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '特別決議をもって効力を生じる adalah bahasa hukum korporasi (会社法) tingkat N1.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d1ffac8d-c33f-4894-a45d-d045c002a4e1', '6eda4d41-dc1d-498c-af4f-cc44d5467057', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Dengan berlakunya peraturan baru ini, aturan lama resmi dicabut."', '{"romaji":"Shinkisoku no shikou o motte, kyuukisoku wa haishi sareru.","tokens":["施行","旧規則は","される。","を余儀なくされ、","新規則の","をもって、","廃止","廃止した"],"target_translation":"Dengan berlakunya peraturan baru ini, aturan lama resmi dicabut."}'::jsonb, '["新規則の","施行","をもって、","旧規則は","廃止","される。"]'::jsonb, NULL, NULL, '施行をもって (terhitung berlakunya peraturan) lazim dalam dokumen legislasi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('10da9d92-1919-40de-a6df-7b569c0c6063', '728654d7-41ce-4380-9af0-e4c83bfe5e62', NULL, 'reading', 'fill_blank', 'Pilih istilah bisnis yang tepat: 採算が取れないため、海外市場からの___を決定した。', '{"options":["提携","進出","撤退","拡大"],"translation":"Karena tidak menguntungkan, perusahaan memutuskan penarikan diri dari pasar luar negeri.","sentence_template":"採算が取れないため、海外市場からの[blank]を決定した。"}'::jsonb, '{"selected":"撤退"}'::jsonb, NULL, NULL, '撤退 (tettai) berarti ''penarikan diri/mundur'' dari pasar atau bisnis tertentu.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b41f4f8a-6e5d-440c-a4f2-548e916b35de', '728654d7-41ce-4380-9af0-e4c83bfe5e62', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berita industri berikut: 部品の供給が途絶え、工場の___が続いている。', '{"options":["設備投資","大量生産","新規採用","操業停止"],"translation":"Pasokan suku cadang terputus, dan penghentian operasi pabrik terus berlanjut.","sentence_template":"部品の供給が途絶え、工場の[blank]が続いている。"}'::jsonb, '{"selected":"操業停止"}'::jsonb, NULL, NULL, '操業停止 (sougyou teishi) berarti ''penghentian operasional pabrik/produksi''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6479f73c-107a-4a0f-8d54-17bb7afcd894', '728654d7-41ce-4380-9af0-e4c83bfe5e62', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat untuk konteks pemerintahan daerah: 深刻な___により、公共施設の新設が見送られた。', '{"options":["増収","好景気","財政難","黒字化"],"translation":"Akibat kesulitan keuangan yang serius, pembangunan fasilitas publik baru ditunda.","sentence_template":"深刻な[blank]により、公共施設の新設が見送られた。"}'::jsonb, '{"selected":"財政難"}'::jsonb, NULL, NULL, '財政難 (zaiseinan) berarti ''kesulitan fiskal/keuangan'' pada pemerintah atau lembaga.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('20fbff10-cffa-445e-8466-6d35487f0d6c', '728654d7-41ce-4380-9af0-e4c83bfe5e62', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan berikut. Langkah apa yang diambil manajemen untuk memulihkan kondisi?', '{"options":[{"id":"opt_1","text":"Memulai restrukturisasi manajemen skala besar termasuk penataan divisi yang merugi"},{"id":"opt_2","text":"Membagikan dividen khusus kepada seluruh pemegang saham"},{"id":"opt_3","text":"Membuka sepuluh cabang baru di seluruh Jepang"},{"id":"opt_4","text":"Menaikkan harga semua produk sebesar lima puluh persen"}],"audio_text":"業績悪化を受け、当社は不採算部門の整理を含む大規模な経営再建に着手いたします。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '不採算部門の整理 (penataan divisi tidak menguntungkan) dan 経営再建 (restrukturisasi manajemen).', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f3d0fed-846c-4fb2-8c29-28aad9dedce6', '728654d7-41ce-4380-9af0-e4c83bfe5e62', NULL, 'listening', 'listening_choice', 'Dengarkan laporan cuaca berikut. Apa dampak langsung dari angin topan tersebut?', '{"options":[{"id":"opt_1","text":"Seluruh pelabuhan dibuka untuk wisata akhir pekan"},{"id":"opt_2","text":"Warga di wilayah pesisir diimbau segera melakukan evakuasi"},{"id":"opt_3","text":"Curah hujan diperkirakan jauh lebih rendah dari rata-rata"},{"id":"opt_4","text":"Transportasi kereta cepat beroperasi lebih cepat dari jadwal"}],"audio_text":"大型台風の接近に伴い、沿岸部の住民には早急な避難が呼びかけられています。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '沿岸部の住民には早急な避難が呼びかけられています berarti ''warga pesisir diimbau segera mengungsi/evakuasi''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3306d696-23db-45ba-8e7b-7ea048b4a361', '728654d7-41ce-4380-9af0-e4c83bfe5e62', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami sedang meninjau ulang perubahan arah kebijakan secara menyeluruh."', '{"romaji":"Bapponteki na houshin tenkan wo kentou shite iru tokoro desu.","display_text":"抜本的な方針転換を検討しているところです。","phonetic_breakdown":["ba-ppon-te-ki","na","hou-shin","ten-kan","wo","ken-tou","shi-te","i-ru","to-ko-ro","de-su"]}'::jsonb, '{"expected_transcript":"抜本的な方針転換を検討しているところです。"}'::jsonb, NULL, NULL, '方針転換 (houshin tenkan) berarti ''perubahan haluan/arah kebijakan''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4397d9af-2233-4e64-b0ca-234918720879', '728654d7-41ce-4380-9af0-e4c83bfe5e62', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Pilih kosakata formal N1 yang tepat: 業績悪化のため、同社は人員の___を余儀なくされた。', '{"options":["削減","増強","表彰","歓迎"],"translation":"Akibat memburuknya kinerja, perusahaan tersebut terpaksa melakukan pengurangan pegawai.","sentence_template":"業績悪化のため、同社は人員の[blank]を余儀なくされた。"}'::jsonb, '{"selected":"削減"}'::jsonb, NULL, NULL, '人員削減 (pengurangan tenaga kerja) adalah kolokasi ekonomi/berita yang lazim dengan を余儀なくされる.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('57fc465e-439e-4471-add1-df219ca3a236', '728654d7-41ce-4380-9af0-e4c83bfe5e62', 'd1000019-0000-0000-0000-000000000029', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Akibat kebangkrutan mitra utama, perusahaan terpaksa meninjau ulang arus kasnya."', '{"romaji":"Shuyou torihikisaki no tousan ni yori, shikin keikaku no minaoshi o yoginaku saremashita.","display_text":"主要取引先の倒産により、資金計画の見直しを余儀なくされました。","phonetic_breakdown":["しゅようとりひきさきの","とうさんにより","しきんけいかくの","みなおしを","よぎなくされました"]}'::jsonb, '{"expected_transcript":"主要取引先の倒産により、資金計画の見直しを余儀なくされました。"}'::jsonb, NULL, NULL, '倒産 (kebangkrutan) dan 資金計画の見直し (peninjauan ulang rencana keuangan) adalah kosakata inti N1.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e6150c0a-171f-4128-9f1f-f169d2f495a3', '737ca019-ca2b-498b-a5fb-ae40a2311ba6', NULL, 'listening', 'listening_choice', 'Dengarkan komentar kritikus berikut. Apa penilaiannya terhadap rencana pembangunan tersebut?', '{"options":[{"id":"opt_1","text":"Keputusan yang sangat gegabah karena memulai konstruksi tanpa kajian lingkungan memadai"},{"id":"opt_2","text":"Keputusan yang sangat bijaksana dan ramah lingkungan"},{"id":"opt_3","text":"Proyek tersebut sudah selesai dikerjakan lebih cepat dari jadwal"},{"id":"opt_4","text":"Kajian lingkungan telah disetujui oleh seluruh warga setempat"}],"audio_text":"環境への影響を十分に調査せず着工に踏み切るのは、あまりにも無謀極まりない判断だ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '無謀極まりない判断 berarti ''keputusan yang luar biasa nekat/gegabah''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('91dd1cb5-800f-492b-bd4a-a1f2aa44e995', '737ca019-ca2b-498b-a5fb-ae40a2311ba6', NULL, 'listening', 'listening_choice', 'Dengarkan kutipan pidato penerimaan penghargaan berikut. Bagaimana perasaan pembicara?', '{"options":[{"id":"opt_1","text":"Merasa kecewa karena hadiahnya tidak sesuai harapan"},{"id":"opt_2","text":"Merasa ragu apakah penghargaan tersebut sah"},{"id":"opt_3","text":"Merasa sangat terhormat dan luar biasa terharu"},{"id":"opt_4","text":"Menolak menerima penghargaan karena alasan pribadi"}],"audio_text":"このような栄誉ある賞をいただき、身に余る光栄であり、感激極まりない思いでございます。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '感激極まりない思い menunjukkan rasa haru yang mendalam (penggunaan positif dari ～極まりない).', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('454ea7bf-e40a-4186-b7e9-4b240e44ae1b', '737ca019-ca2b-498b-a5fb-ae40a2311ba6', NULL, 'listening', 'listening_choice', 'Dengarkan tanggapan warga terhadap gangguan di fasilitas umum. Apa yang dikeluhkan?', '{"options":[{"id":"opt_1","text":"Lampu jalan di lingkungan tersebut padam setiap malam"},{"id":"opt_2","text":"Taman kota ditutup terlalu awal pada hari Minggu"},{"id":"opt_3","text":"Pengumpulan sampah terlambat satu hari"},{"id":"opt_4","text":"Memutar musik keras tengah malam sangat mengganggu warga sekitar"}],"audio_text":"深夜に大音量で音楽を流し続けるとは、近隣住民にとって迷惑極まりない行為だ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '迷惑極まりない行為 berarti ''tindakan yang luar biasa mengganggu''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b81b4604-98ff-4254-b4ec-4106ff0b9be6', '737ca019-ca2b-498b-a5fb-ae40a2311ba6', NULL, 'reading', 'fill_blank', 'Lengkapi teks editorial berikut: 説明責任を果たさず批判を避け続ける姿勢は、不誠実___。', '{"options":["極まりない","とはいえ","を余儀なくされる","に至らない"],"translation":"Sikap terus menghindari kritik tanpa memenuhi kewajiban penjelasan sungguh luar biasa tidak tulus.","sentence_template":"説明責任を果たさず批判を避け続ける姿勢は、不誠実[blank]。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, NULL, NULL, '不誠実極まりない adalah kritik tajam dalam tajuk rencana surat kabar Jepang.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9f94ad48-bce3-4f2b-83d7-de70c2348d0d', '737ca019-ca2b-498b-a5fb-ae40a2311ba6', NULL, 'reading', 'fill_blank', 'Pilih kata yang paling tepat sebelum 極まりない: 書類手続きが___極まりなく、利用者の負担が大きい。', '{"options":["円滑","快適","迅速","煩雑"],"translation":"Prosedur dokumennya luar biasa berbelit-belit, sehingga beban pengguna sangat besar.","sentence_template":"書類手続きが[blank]極まりなく、利用者の負担が大きい。"}'::jsonb, '{"selected":"煩雑"}'::jsonb, NULL, NULL, '煩雑 (hanzatsu: rumit/berbelit-belit) + 極まりなく sangat alami untuk mengkritik birokrasi.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d7183a3f-bb38-49ce-8e0f-35178aecebf7', '737ca019-ca2b-498b-a5fb-ae40a2311ba6', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat pujian formal berikut: 彼の論文は論理構成が___極まりなく、専門家の間でも高く評価された。', '{"options":["精緻","曖昧","冗長","粗雑"],"translation":"Struktur logika makalahnya luar biasa tajam dan terperinci, sehingga dinilai tinggi di kalangan pakar.","sentence_template":"彼の論文は論理構成が[blank]極まりなく、専門家の間でも高く評価された。"}'::jsonb, '{"selected":"精緻"}'::jsonb, NULL, NULL, '精緻 (seichi: sangat teliti/halus/presisi) berpasangan positif dengan 極まりなく.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1e932dfb-6b34-46e3-800f-4bb35ee7d807', '737ca019-ca2b-498b-a5fb-ae40a2311ba6', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Pernyataan yang mengabaikan fakta sejarah tersebut amat sangat tidak bertanggung jawab."', '{"romaji":"Rekishi no jijitsu o mushi shita hatsugen wa musekinin kiwamarinai.","tokens":["無視した発言は、","極まり","ものだ。","とはいえ、","歴史の事実を","無責任","ない","無責任に"],"target_translation":"Pernyataan yang mengabaikan fakta sejarah tersebut amat sangat tidak bertanggung jawab."}'::jsonb, '["歴史の事実を","無視した発言は、","無責任","極まり","ない","ものだ。"]'::jsonb, NULL, NULL, '無責任極まりないものだ adalah ungkapan kritik tajam khas kolom opini.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('955d4af7-0d79-4296-b963-fd4c44c2a122', '737ca019-ca2b-498b-a5fb-ae40a2311ba6', 'd1000019-0000-0000-0000-000000000032', 'listening', 'listening_choice', 'Dengarkan komentar warga kota. Apa yang mereka keluhkan tentang proyek renovasi?', '{"options":[{"id":"opt_1","text":"Warga senang karena renovasi berlangsung cepat"},{"id":"opt_2","text":"Keluhan membanjir karena menimbulkan kebisingan semalaman tanpa pemberitahuan dianggap amat tidak masuk akal/tidak beradab"},{"id":"opt_3","text":"Warga meminta konstruksi dilakukan pada tengah malam saja"},{"id":"opt_4","text":"Tidak ada satu pun warga yang mengeluh"}],"audio_text":"事前通知もなしに夜通し騒音を出し続けるとは、非常識極まりないと苦情が殺到した。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '非常識極まりない berarti luar biasa tidak tahu aturan/tidak masuk akal.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('622f5076-fe7f-48b0-a642-2e3369be3d26', '7df615b1-5205-44c6-823e-92faac4e7c86', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Lengkapi pengumuman resmi penutupan pendaftaran berikut: 本日の午後五時___、今年度の応募受付を終了いたします。', '{"options":["をもって","とはいえ","なりに","ともなると"],"translation":"Terhitung pukul 17.00 hari ini, penerimaan pendaftaran tahun fiskal ini resmi ditutup.","sentence_template":"本日の午後五時[blank]、今年度の応募受付を終了いたします。"}'::jsonb, '{"selected":"をもって"}'::jsonb, NULL, NULL, 'Waktu/tanggal + をもって menandai batas akhir atau titik pemberlakuan secara sangat resmi.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a6c6f558-4011-425e-bfc7-c78ffb4cb988', '7df615b1-5205-44c6-823e-92faac4e7c86', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk sarana resmi dalam surat bisnis: 選考結果につきましては、書面___ご通知申し上げます。', '{"options":["をもって","に至って","を余儀なくされ","極まりなく"],"translation":"Mengenai hasil seleksi, kami akan memberitahukannya secara resmi melalui surat tertulis.","sentence_template":"選考結果につきましては、書面[blank]ご通知申し上げます。"}'::jsonb, '{"selected":"をもって"}'::jsonb, NULL, NULL, '書面をもって (dengan/melalui dokumen tertulis) menyatakan sarana resmi formal.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5303bb67-df72-404e-8fc3-ec6c132b1d7e', '7df615b1-5205-44c6-823e-92faac4e7c86', 'd1000019-0000-0000-0000-000000000031', 'listening', 'listening_choice', 'Dengarkan pengumuman penutupan pameran. Kapan pameran tersebut berakhir?', '{"options":[{"id":"opt_1","text":"Pameran diperpanjang tanpa batas waktu"},{"id":"opt_2","text":"Pameran khusus tersebut resmi berakhir pada hari terakhir bulan ini"},{"id":"opt_3","text":"Pameran baru akan dibuka awal bulan depan"},{"id":"opt_4","text":"Pameran ditutup mendadak hari ini karena hujan"}],"audio_text":"皆様にご愛顧いただきました特別展は、今月末日をもって閉幕いたします。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '今月末日をもって閉幕いたします berarti resmi berakhir terhitung hari terakhir bulan ini.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('55a6d9f5-9bc2-48dd-ab63-2fcafe180083', '7df615b1-5205-44c6-823e-92faac4e7c86', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Dengan ini, saya akhiri sambutan pembukaan saya."', '{"romaji":"Ijou o motte, kaikai no aisatsu to sasete itadakimasu.","tokens":["をもって、","挨拶","いただきます。","挨拶した","以上","開会の","とさせて","とはいえ、"],"target_translation":"Dengan ini, saya akhiri sambutan pembukaan saya."}'::jsonb, '["以上","をもって、","開会の","挨拶","とさせて","いただきます。"]'::jsonb, NULL, NULL, '以上をもって adalah penutup pidato resmi paling klasik dalam bahasa Jepang formal.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5bb083cd-9f6c-4db3-b693-bc03d6c7156a', '7df615b1-5205-44c6-823e-92faac4e7c86', 'd1000019-0000-0000-0000-000000000031', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan menangani setiap masukan pelanggan dengan ketulusan penuh."', '{"romaji":"Okyakusama no goiken ni wa, seii o motte taiou sasete itadakimasu.","display_text":"お客様のご意見には、誠意をもって対応させていただきます。","phonetic_breakdown":["おきゃくさまの","ごいけんには","せいいをもって","たいおうさせて","いただきます"]}'::jsonb, '{"expected_transcript":"お客様のご意見には、誠意をもって対応させていただきます。"}'::jsonb, NULL, NULL, '誠意をもって (dengan ketulusan penuh) adalah kolokasi korporasi yang wajib dikuasai di N1.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b3b283bf-1425-419d-8289-9cabde784316', '7df615b1-5205-44c6-823e-92faac4e7c86', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Lengkapi kalimat resmi berikut: 三月三十一日___、現行の旧システムは完全に運用を終了する。', '{"options":["をもって","ずにはおかず","に足らず","いかんによらず"],"translation":"Terhitung tanggal 31 Maret, sistem lama yang berlaku saat ini akan sepenuhnya mengakhiri operasionalnya.","sentence_template":"三月三十一日[blank]、現行の旧システムは完全に運用を終了する。"}'::jsonb, '{"selected":"をもって"}'::jsonb, NULL, NULL, 'Tanggal + をもって menyatakan tenggat resmi berakhirnya suatu layanan atau sistem.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('06550800-5532-44f6-b7ef-d059e3eb4318', '7df615b1-5205-44c6-823e-92faac4e7c86', 'd1000019-0000-0000-0000-000000000031', 'listening', 'listening_choice', 'Dengarkan pengumuman perusahaan. Bagaimana cara pemberitahuan pengumuman pemenang?', '{"options":[{"id":"opt_1","text":"Daftar pemenang akan diumumkan di televisi nasional"},{"id":"opt_2","text":"Pemenang harus datang sendiri mengambil sertifikat"},{"id":"opt_3","text":"Pengumuman pemenang digantikan langsung oleh pengiriman hadiahnya"},{"id":"opt_4","text":"Undian dibatalkan karena peserta kurang"}],"audio_text":"当選者の発表は、賞品の発送をもって代えさせていただきます。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '発送をもって代えさせていただきます adalah kalimat baku kampanye/undian resmi di Jepang.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('42308c03-cf43-42a1-a9dd-11673201910a', '7df615b1-5205-44c6-823e-92faac4e7c86', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Kami menyampaikan ucapan selamat secara resmi melalui surat ini."', '{"romaji":"Shochuu o motte kokoro yori oiwai moushiagemasu.","tokens":["をもって、","お祝い","ます。","申し上げた","書中","心より","申し上げ","なりに、"],"target_translation":"Kami menyampaikan ucapan selamat secara resmi melalui surat ini."}'::jsonb, '["書中","をもって、","心より","お祝い","申し上げ","ます。"]'::jsonb, NULL, NULL, '書中をもって (melalui surat ini) adalah ungkapan super-formal dalam korespondensi korporasi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a17aa963-a6ca-40f2-810d-7797f07f378d', '83690cd2-583b-46be-b4b2-d39e09879a7c', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Lengkapi pengumuman resmi berikut: 本日___、旧バージョンのサポートを終了させていただきます。', '{"options":["にわたって","に沿って","をもって","をめぐって"],"translation":"Terhitung hari ini, kami mengakhiri dukungan untuk versi lama.","sentence_template":"本日[blank]、旧バージョンのサポートを終了させていただきます。"}'::jsonb, '{"selected":"をもって"}'::jsonb, NULL, NULL, 'Waktu + をもって menandai batas akhir atau titik waktu resmi suatu tindakan/pengumuman.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ddcc86ab-583c-46db-89da-4e8b1c9de8b0', '83690cd2-583b-46be-b4b2-d39e09879a7c', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Pilih pola yang tepat untuk menyatakan sarana/media resmi: 当選者の発表は、賞品の発送___代えさせていただきます。', '{"options":["をよそに","に際して","に至って","をもって"],"translation":"Pengumuman pemenang akan kami gantikan dengan pengiriman hadiah secara langsung.","sentence_template":"当選者の発表は、賞品の発送[blank]代えさせていただきます。"}'::jsonb, '{"selected":"をもって"}'::jsonb, NULL, NULL, '発送をもって代えさせていただきます adalah formula resmi yang sangat sering dipakai dalam pengumuman hasil undian/seleksi.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4cc78ea2-96bc-481f-a1ba-8d267f991d5c', '83690cd2-583b-46be-b4b2-d39e09879a7c', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Lengkapi kalimat sopan berikut: 以上___、私からの最終報告といたします。', '{"options":["を皮切りにして","を前提として","をもちまして","を余儀なくして"],"translation":"Dengan demikian, saya akhiri laporan akhir dari saya.","sentence_template":"以上[blank]、私からの最終報告といたします。"}'::jsonb, '{"selected":"をもちまして"}'::jsonb, NULL, NULL, 'をもちまして adalah bentuk super-sopan (teineigo) dari をもって untuk presentasi atau upacara resmi.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e0534845-e6c5-4838-8d5b-45754b6d58f3', '83690cd2-583b-46be-b4b2-d39e09879a7c', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Hasil ujian akan diberitahukan melalui dokumen tertulis."', '{"romaji":"Shiken no kekka wa shomen wo motte tsuuchi itashimasu.","tokens":["結果は","通知","書面","試験の","ながら","いたします","をもって","に至って"],"target_translation":"Hasil ujian akan diberitahukan melalui dokumen tertulis."}'::jsonb, '["試験の","結果は","書面","をもって","通知","いたします"]'::jsonb, NULL, NULL, '書面をもって通知いたします berarti ''kami beritahukan melalui surat/dokumen tertulis''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('49fdd465-f636-45e4-a923-d9a08f2f6c2f', '83690cd2-583b-46be-b4b2-d39e09879a7c', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Dengan akhir bulan ini, toko tersebut akan menutup operasinya."', '{"romaji":"Kongetsumatsu wo motte touten wa eigyou wo shuuryou itashimasu.","tokens":["当店は","いたします","なりに","をめぐって","をもって","営業を","今月末","終了"],"target_translation":"Dengan akhir bulan ini, toko tersebut akan menutup operasinya."}'::jsonb, '["今月末","をもって","当店は","営業を","終了","いたします"]'::jsonb, NULL, NULL, '今月末をもって menandai akhir bulan ini sebagai batas resmi penutupan toko.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5acbddf2-9687-4292-ad8f-f5bb949efef9', '83690cd2-583b-46be-b4b2-d39e09879a7c', 'd1000019-0000-0000-0000-000000000031', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan melaksanakan tugas ini dengan penuh tanggung jawab."', '{"romaji":"Tsuyoi sekininkan wo motte, kono ninmu wo suikou itashimasu.","display_text":"強い責任感をもって、この任務を遂行いたします。","phonetic_breakdown":["tsu-yo-i","se-ki-nin-kan","wo","mo-tte","ko-no","nin-mu","wo","sui-kou","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"強い責任感をもって、この任務を遂行いたします。"}'::jsonb, NULL, NULL, '強い責任感をもって menyatakan sikap/semangat yang menyertai pelaksanaan tugas (遂行).', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('47d775a1-e029-47ff-9246-b53076d46afc', '83690cd2-583b-46be-b4b2-d39e09879a7c', 'd1000019-0000-0000-0000-000000000031', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Fungsi apakah yang dimiliki ～をもって di sini?', '{"options":[{"id":"opt_1","text":"Menyatakan batas akhir resmi pendaftaran, yaitu besok pukul 12 siang"},{"id":"opt_2","text":"Menyatakan alasan pembatalan acara"},{"id":"opt_3","text":"Menyatakan perbandingan antara dua produk"},{"id":"opt_4","text":"Menyatakan keterpaksaan karena bencana"}],"audio_text":"本件に関するお申し込みは、明日正午をもって締め切らせていただきます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '明日正午をもって締め切る menggunakan をもって untuk menandai tenggat akhir resmi.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a2f5dd9e-30ca-4afc-86ac-4c6fc67df187', '83690cd2-583b-46be-b4b2-d39e09879a7c', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Lengkapi kalimat dengan bentuk sopan: 本年十二月末日___、当該店舗は営業を終了いたします。', '{"options":["をもちまして","に至りまして","とはいえまして","なりまして"],"translation":"Terhitung hari terakhir Desember tahun ini, gerai tersebut resmi mengakhiri operasionalnya.","sentence_template":"本年十二月末日[blank]、当該店舗は営業を終了いたします。"}'::jsonb, '{"selected":"をもちまして"}'::jsonb, NULL, NULL, '～をもちまして adalah padanan sopan resmi dari ～をもって untuk pengumuman publik.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('89edde98-526f-498d-90c4-3d41e7753421', '86a83d4a-f58b-4ac4-8a81-01183176edfe', NULL, 'listening', 'listening_choice', 'Dengarkan resensi buku berikut. Bagaimana efek novel tersebut terhadap pembacanya?', '{"options":[{"id":"opt_1","text":"Novel itu membuat pembaca mengantuk karena alurnya datar"},{"id":"opt_2","text":"Novel itu hanya cocok dibaca sebagai hiburan ringan di kereta"},{"id":"opt_3","text":"Novel itu pasti mendorong pembaca merenung secara mendalam"},{"id":"opt_4","text":"Novel itu mendapat kritik keras karena temanya dangkal"}],"audio_text":"人間の孤独を鋭く描いたこの小説は、読者に深い思索を促さずにはおかない傑作だ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '深い思索を促さずにはおかない berarti ''pasti mendorong perenungan mendalam''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4d5346ca-e79d-4253-a1ca-7aa127257c1d', '86a83d4a-f58b-4ac4-8a81-01183176edfe', NULL, 'listening', 'listening_choice', 'Dengarkan analisis pasar berikut. Apa dampak merger dua perusahaan besar tersebut?', '{"options":[{"id":"opt_1","text":"Tidak akan membawa perubahan berarti bagi struktur pasar"},{"id":"opt_2","text":"Pasti akan merombak besar-besaran struktur pasar di masa mendatang"},{"id":"opt_3","text":"Dibatalkan oleh otoritas pengawas persaingan usaha"},{"id":"opt_4","text":"Hanya memengaruhi satu cabang kecil di luar negeri"}],"audio_text":"業界大手二社の経営統合は、今後の市場構造を大きく変革せずにはおかない。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '市場構造を大きく変革せずにはおかない berarti ''pasti akan mentransformasi struktur pasar secara besar-besaran''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c3a87f15-0a99-440a-a5b6-e624009e237f', '86a83d4a-f58b-4ac4-8a81-01183176edfe', NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan pengacara berikut. Apa tekad yang disampaikannya?', '{"options":[{"id":"opt_1","text":"Akan menghentikan gugatan jika prosesnya terlalu lama"},{"id":"opt_2","text":"Menyerahkan seluruh penyelesaian kepada pihak lawan"},{"id":"opt_3","text":"Tidak akan mengajukan tuntutan apa pun di pengadilan"},{"id":"opt_4","text":"Bertekad pasti menuntut pertanggungjawaban demi memulihkan nama baik korban meski penuh kesulitan"}],"audio_text":"被害者の名誉を回復するため、どのような困難があろうとも責任を追及せずにはおかない。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '責任を追及せずにはおかない mengekspresikan tekad tak tergoyahkan untuk menuntut pertanggungjawaban.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f2f8f06-f6d1-4a01-9c9e-af48bab8b714', '86a83d4a-f58b-4ac4-8a81-01183176edfe', NULL, 'reading', 'fill_blank', 'Lengkapi komentar budaya berikut: 職人の妥協なき技は、見る者に深い感銘を与え___。', '{"options":["わけにはいかない","ずにはおかない","ざるを得ない","に過ぎない"],"translation":"Keahlian tanpa kompromi sang perajin pasti meninggalkan kesan mendalam bagi siapa pun yang menyaksikannya.","sentence_template":"職人の妥協なき技は、見る者に深い感銘を与え[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, NULL, NULL, '深い感銘を与えずにはおかない berarti ''pasti memberikan kesan mendalam''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('af79cb5f-50d0-4da6-84af-6b2bfdbcc32a', '86a83d4a-f58b-4ac4-8a81-01183176edfe', NULL, 'reading', 'fill_blank', 'Pilih bentuk konjugasi yang benar untuk する: 彼の率直な問題提起は、会議の雰囲気を一変___。', '{"options":["しずにはおかない","すずにはおかない","さずにはおかない","せずにはおかない"],"translation":"Pengajuan masalah yang lugas darinya pasti akan mengubah suasana rapat secara drastis.","sentence_template":"彼の率直な問題提起は、会議の雰囲気を一変[blank]。"}'::jsonb, '{"selected":"せずにはおかない"}'::jsonb, NULL, NULL, 'Bentuk ず dari kata kerja する selalu せず (bukan しず), sehingga menjadi 一変せずにはおかない.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7e17e33a-4063-4a50-9771-3075ae0b3662', '86a83d4a-f58b-4ac4-8a81-01183176edfe', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kritik sosial berikut: 格差の固定化は、将来的に社会の分断を深刻化させ___。', '{"options":["なりに","とはいえ","をもって","ずにはおかない"],"translation":"Mengakarnya kesenjangan pasti akan memperparah perpecahan sosial di masa depan.","sentence_template":"格差の固定化は、将来的に社会の分断を深刻化させ[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, NULL, NULL, '深刻化させずにはおかない menegaskan konsekuensi sosial yang tak terhindarkan.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d6a32b5-3c7a-4fd7-a99e-7dab4d530fcb', '86a83d4a-f58b-4ac4-8a81-01183176edfe', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Keputusan mendadak itu pasti akan menimbulkan kebingungan di pasar keuangan."', '{"romaji":"Totsuzen no kettei wa kinyuu shijou ni konran o motarasazu ni wa okanai.","tokens":["金融市場に","もたらさ","おかない。","とはいえ、","突然の決定は、","混乱を","ずには","もたらす"],"target_translation":"Keputusan mendadak itu pasti akan menimbulkan kebingungan di pasar keuangan."}'::jsonb, '["突然の決定は、","金融市場に","混乱を","もたらさ","ずには","おかない。"]'::jsonb, NULL, NULL, '混乱をもたらさずにはおかない adalah gaya bahasa laporan ekonomi N1.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f3635fc1-17cf-48b3-aa0d-c213cabfdb01', '86a83d4a-f58b-4ac4-8a81-01183176edfe', 'd1000019-0000-0000-0000-000000000034', 'listening', 'listening_choice', 'Dengarkan ulasan buku ilmiah. Apa keunggulan buku tersebut?', '{"options":[{"id":"opt_1","text":"Buku itu terlalu sulit dipahami oleh pembaca umum"},{"id":"opt_2","text":"Buku yang menjelaskan asal-usul alam semesta dengan bahasa sederhana ini pasti merangsang rasa ingin tahu intelektual terhadap sains"},{"id":"opt_3","text":"Buku itu tidak membahas topik astronomi sama sekali"},{"id":"opt_4","text":"Buku itu sudah ditarik dari peredaran"}],"audio_text":"宇宙の起源を平易な言葉で解き明かした本書は、科学への知的好奇心を刺激せずにはおかない。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '知的好奇心を刺激せずにはおかない berarti pasti memacu rasa ingin tahu intelektual.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c8877314-2905-48f4-a399-bf702c1f2cb2', '87edca88-a15a-4eaa-bec1-a64a45f50e5c', 'd1000019-0000-0000-0000-000000000028', 'listening', 'listening_choice', 'Dengarkan laporan investigasi berikut. Bagaimana respons masyarakat terhadap skandal tersebut?', '{"options":[{"id":"opt_1","text":"Masyarakat memuji sikap pihak yang terlibat"},{"id":"opt_2","text":"Kritik publik mereda dengan sendirinya"},{"id":"opt_3","text":"Media massa berhenti memberitakan kasus tersebut"},{"id":"opt_4","text":"Karena pihak terkait sampai bersikeras tidak mengakui kesalahan, kritik publik tidak mungkin mereda"}],"audio_text":"当事者が責任を認めない姿勢を貫くに至っては、世論の批判が収まるはずもない。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '貫くに至っては menyoroti sikap ekstrem yang membuat kritik publik kian tak terbendung.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d61ae33-96fe-4ead-9cb5-038daf0fe10c', '87edca88-a15a-4eaa-bec1-a64a45f50e5c', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Baru pada abad ke-21 teknologi ini mulai diterapkan dalam kehidupan sehari-hari."', '{"romaji":"Nijuu-isseiki ni itatte, kono gijutsu wa youyaku jitsuyouka sareta.","tokens":["に至って、","ようやく","された。","実用化する","二十一世紀","この技術は","実用化","をもって、"],"target_translation":"Baru pada abad ke-21 teknologi ini mulai diterapkan dalam kehidupan sehari-hari."}'::jsonb, '["二十一世紀","に至って、","この技術は","ようやく","実用化","された。"]'::jsonb, NULL, NULL, '二十一世紀に至って menandai era ketika teknologi akhirnya masuk tahap penerapan praktis.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4c3540c3-cedd-4b80-b51c-dbab6a310e94', '87edca88-a15a-4eaa-bec1-a64a45f50e5c', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 交渉が完全に決裂する___、両社は法廷で争うこととなった。', '{"options":["に至り","なりに","とはいえ","に足らず"],"translation":"Hingga negosiasi benar-benar buntu/putus, kedua perusahaan akhirnya bersengketa di pengadilan.","sentence_template":"交渉が完全に決裂する[blank]、両社は法廷で争うこととなった。"}'::jsonb, '{"selected":"に至り"}'::jsonb, NULL, NULL, '決裂するに至り adalah bentuk tertulis formal N1 untuk hasil eskalasi negosiasi.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2bb55b45-63c2-44d5-aac1-cb0fdb13264c', '87edca88-a15a-4eaa-bec1-a64a45f50e5c', 'd1000019-0000-0000-0000-000000000028', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bahkan sampai hari ini, penyebab utama kecelakaan tersebut masih belum terungkap sepenuhnya."', '{"romaji":"Genzai ni itaru made, sono jiko no konpon genin wa kanzen ni wa kaimei sarete imasen.","display_text":"現在に至るまで、その事故の根本原因は完全には解明されていません。","phonetic_breakdown":["げんざいに","いたるまで","そのじこの","こんぽんげんいんは","かんぜんには","かいめいされていません"]}'::jsonb, '{"expected_transcript":"現在に至るまで、その事故の根本原因は完全には解明されていません。"}'::jsonb, NULL, NULL, '現在に至るまで (hingga sampai saat ini) adalah kolokasi berita dan laporan investigasi N1.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('817176e8-7cea-4357-b5fa-0a2bd4f5835c', '87edca88-a15a-4eaa-bec1-a64a45f50e5c', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 主力商品の販売が急落する___、同社は事業転換を迫られた。', '{"options":["に至って","極まりない","ともなると","いかんによらず"],"translation":"Ketika penjualan produk andalan sampai anjlok drastis, perusahaan tersebut didesak melakukan transformasi bisnis.","sentence_template":"主力商品の販売が急落する[blank]、同社は事業転換を迫られた。"}'::jsonb, '{"selected":"に至って"}'::jsonb, NULL, NULL, '急落するに至って menandai titik kritis finansial yang memaksa perubahan model bisnis.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a4aa7351-fb69-4c4e-8749-ae5d26a1b6c1', '87edca88-a15a-4eaa-bec1-a64a45f50e5c', 'd1000019-0000-0000-0000-000000000028', 'listening', 'listening_choice', 'Dengarkan kutipan kuliah sosiologi. Apa yang dijelaskan dosen tentang proses urbanisasi?', '{"options":[{"id":"opt_1","text":"Pada masa pertumbuhan ekonomi tinggi, migrasi penduduk besar-besaran dari desa ke kota besar melaju pesat"},{"id":"opt_2","text":"Penduduk kota besar berbondong-bondong kembali ke desa pada masa itu"},{"id":"opt_3","text":"Pertumbuhan ekonomi Jepang terhenti selama era tersebut"},{"id":"opt_4","text":"Tidak ada perubahan demografi selama era pertumbuhan tinggi"}],"audio_text":"高度経済成長期に至って、農村から大都市への大規模な人口移動が加速した。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '高度経済成長期に至って menandai periode sejarah tertentu ketika fenomena mulai berakselerasi.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d580e492-0dcc-40b6-9c07-59a6c16cb9f8', '87edca88-a15a-4eaa-bec1-a64a45f50e5c', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Masalah kecil yang dibiarkan akhirnya berkembang hingga memicu krisis kepercayaan."', '{"romaji":"Chiisana mondai ga houchi sare, shinrai kiki o maneku ni itatta.","tokens":["放置され、","招く","至った。","を余儀なくされた。","小さな問題が","信頼危機を","に","招いた"],"target_translation":"Masalah kecil yang dibiarkan akhirnya berkembang hingga memicu krisis kepercayaan."}'::jsonb, '["小さな問題が","放置され、","信頼危機を","招く","に","至った。"]'::jsonb, NULL, NULL, 'V-dict + に至った menyatakan hasil akhir ekstrem dari rangkaian proses sebelumnya.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d474d1f5-189b-45c5-ae6d-8892d4f8381a', '87edca88-a15a-4eaa-bec1-a64a45f50e5c', 'd1000019-0000-0000-0000-000000000028', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah keadaan berkembang sampai sejauh ini, penjelasan terbuka kepada publik mutlak diperlukan."', '{"romaji":"Koko ni itatte wa, shakai ni taisuru seijitsu na setsumei sekinin o hatasu hoka arimasen.","display_text":"ここに至っては、社会に対する誠実な説明責任を果たすほかありません。","phonetic_breakdown":["ここに","いたっては","しゃかいにたいする","せいじつなせつめいせきにんを","はたすほかありません"]}'::jsonb, '{"expected_transcript":"ここに至っては、社会に対する誠実な説明責任を果たすほかありません。"}'::jsonb, NULL, NULL, 'ここに至っては (setelah sampai pada titik ini) adalah frasa idiomatik N1 tingkat tinggi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5642149c-6bc6-40fb-9c27-a1076f5581ce', '8b8c4b24-cd41-4abc-b9c9-36a4757df84b', 'd1000019-0000-0000-0000-000000000032', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Menyebarkan informasi yang belum terverifikasi adalah hal yang sangat berbahaya."', '{"romaji":"Mikakunin no jouhou wo kakusan suru no wa, kiken kiwamarinai koui da.","display_text":"未確認の情報を拡散するのは、危険極まりない行為だ。","phonetic_breakdown":["mi-ka-ku-nin","no","jou-hou","wo","ka-ku-san","su-ru","no","wa","ki-ken","ki-wa-ma-ri-nai","kou-i","da"]}'::jsonb, '{"expected_transcript":"未確認の情報を拡散するのは、危険極まりない行為だ。"}'::jsonb, NULL, NULL, '未確認の情報 (informasi belum terkonfirmasi) dan 危険極まりない行為 (tindakan amat berbahaya).', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4b546ba2-c98a-4b4d-833c-1c3f048526c3', '8b8c4b24-cd41-4abc-b9c9-36a4757df84b', 'd1000019-0000-0000-0000-000000000032', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Batal mendadak tanpa pemberitahuan sungguh luar biasa tidak sopan."', '{"romaji":"Renraku mo naku chokuzen ni kyanseru suru to wa, shitsurei kiwamarinai.","display_text":"連絡もなく直前にキャンセルするとは、失礼極まりない。","phonetic_breakdown":["ren-ra-ku","mo","na-ku","cho-ku-zen","ni","kyan-se-ru","su-ru","to","wa","shi-tsu-rei","ki-wa-ma-ri-nai"]}'::jsonb, '{"expected_transcript":"連絡もなく直前にキャンセルするとは、失礼極まりない。"}'::jsonb, NULL, NULL, 'Pola ～とは、...極まりない sering digunakan untuk mengekspresikan keterkejutan sekaligus kecaman.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a1f7ce4c-2398-4552-b35b-4e12ccae9df8', '8b8c4b24-cd41-4abc-b9c9-36a4757df84b', 'd1000019-0000-0000-0000-000000000032', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kemenangan dramatis itu sungguh luar biasa memuaskan."', '{"romaji":"Ano gekiteki na gyakuten shouri wa, tsuukai kiwamarinai shunkan datta.","display_text":"あの劇的な逆転勝利は、痛快極まりない瞬間だった。","phonetic_breakdown":["a-no","ge-ki-te-ki","na","gya-ku-ten","shou-ri","wa","tsuu-kai","ki-wa-ma-ri-nai","shun-kan","da-tta"]}'::jsonb, '{"expected_transcript":"あの劇的な逆転勝利は、痛快極まりない瞬間だった。"}'::jsonb, NULL, NULL, '痛快極まりない (luar biasa seru/memuaskan) adalah contoh penggunaan positif yang kuat.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('be0639b3-4798-4502-9ff9-e16383da59a6', '8b8c4b24-cd41-4abc-b9c9-36a4757df84b', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Memalsukan data penelitian adalah pelanggaran etika yang luar biasa tidak bertanggung jawab."', '{"romaji":"Kenkyuu deeta no kaizan wa musekinin kiwamarinai fusei koui de aru.","tokens":["をもって","無責任","なりに","不正行為","極まりない","改ざんは","である","研究データの"],"target_translation":"Memalsukan data penelitian adalah pelanggaran etika yang luar biasa tidak bertanggung jawab."}'::jsonb, '["研究データの","改ざんは","無責任","極まりない","不正行為","である"]'::jsonb, NULL, NULL, '改ざん (pemalsuan) dan 不正行為 (tindakan curang/pelanggaran).', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('405c468e-3136-46e9-a7dd-540e2780caee', '8b8c4b24-cd41-4abc-b9c9-36a4757df84b', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Penjelasan yang tidak konsisten itu sungguh sangat membingungkan."', '{"romaji":"Ikkansei no nai setsumei wa fukakai kiwamarinai mono da.","tokens":["ない","説明は","極まりない","とはいえ","ものだ","不可解","一貫性の","に至って"],"target_translation":"Penjelasan yang tidak konsisten itu sungguh sangat membingungkan."}'::jsonb, '["一貫性の","ない","説明は","不可解","極まりない","ものだ"]'::jsonb, NULL, NULL, '不可解極まりない berarti ''luar biasa sulit dimengerti / sangat janggal''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5dc0a1e6-cac8-41c3-9539-6752f5343f16', '8b8c4b24-cd41-4abc-b9c9-36a4757df84b', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Meremehkan standar keselamatan adalah kelalaian yang amat berbahaya."', '{"romaji":"Anzen kijun wo keishi suru taido wa kiken kiwamaru mono da.","tokens":["安全基準を","に足る","軽視する","ながら","態度は","極まる","危険","ものだ"],"target_translation":"Meremehkan standar keselamatan adalah kelalaian yang amat berbahaya."}'::jsonb, '["安全基準を","軽視する","態度は","危険","極まる","ものだ"]'::jsonb, NULL, NULL, '危険極まるものだ menekankan tingkat bahaya yang sudah melampaui batas.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('612e0187-cbcb-4497-8b75-1cfa74891ca5', '8b8c4b24-cd41-4abc-b9c9-36a4757df84b', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 貴重な文化財が管理不足で破損したとは、残念___。', '{"options":["極まりない","を余儀なくされる","をもって","なりに"],"translation":"Sungguh amat disayangkan bahwa cagar budaya berharga rusak akibat kurangnya pemeliharaan.","sentence_template":"貴重な文化財が管理不足で破損したとは、残念[blank]。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, NULL, NULL, '残念極まりない menyatakan penyesalan yang sangat mendalam.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e9de6430-e689-460f-8ec8-6d230825852e', '8b8c4b24-cd41-4abc-b9c9-36a4757df84b', 'd1000019-0000-0000-0000-000000000032', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Aturan yang melarang diskusi terbuka di rapat inovasi sungguh amat tidak masuk akal."', '{"romaji":"Kakushin o mezasu kaigi de jiyuu na hatsugen o kinjiru nado, fugouri kiwamari arimasen.","display_text":"革新を目指す会議で自由な発言を禁じるなど、不合理極まりありません。","phonetic_breakdown":["かくしんをめざす","かいぎでじゆうなはつげんを","きんじるなど","ふごうりきわまりありません"]}'::jsonb, '{"expected_transcript":"革新を目指す会議で自由な発言を禁じるなど、不合理極まりありません。"}'::jsonb, NULL, NULL, '不合理極まりありません berarti amat sangat tidak rasional.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('696a3959-8c41-4c7e-bede-d01aeb45c8fd', '8c713fb9-b38a-4169-aa63-0ddc550daba4', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Lengkapi berita berikut: 大規模な土砂崩れにより、周辺地域の住民は長期の避難生活___。', '{"options":["を余儀なくされた","に至った","とはいえ","に足る"],"translation":"Akibat tanah longsor berskala besar, warga di wilayah sekitar terpaksa menjalani kehidupan pengungsian jangka panjang.","sentence_template":"大規模な土砂崩れにより、周辺地域の住民は長期の避難生活[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, NULL, NULL, 'Kata benda + を余儀なくされる menyatakan keterpaksaan akibat faktor eksternal di luar kendali.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('29a15ea3-384b-4ce3-9c94-97f1233ee522', '8c713fb9-b38a-4169-aa63-0ddc550daba4', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Pilih bentuk kausatif yang tepat (memaksa pihak lain): 突然の輸入規制は、現地の輸出業者に事業計画の全面見直し___。', '{"options":["を余儀なくさせた","を余儀なくされた","に至らせた","をもってした"],"translation":"Regulasi impor yang mendadak memaksa para eksportir lokal meninjau ulang rencana bisnis secara menyeluruh.","sentence_template":"突然の輸入規制は、現地の輸出業者に事業計画の全面見直し[blank]。"}'::jsonb, '{"selected":"を余儀なくさせた"}'::jsonb, NULL, NULL, '～を余儀なくさせる adalah bentuk kausatif (aktor/faktor X memaksa pihak Y melakukan sesuatu).', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('73bd0413-e4fd-4f87-a7d1-e8b050e6203b', '8c713fb9-b38a-4169-aa63-0ddc550daba4', 'd1000019-0000-0000-0000-000000000029', 'listening', 'listening_choice', 'Dengarkan laporan ekonomi berikut. Dampak apa yang dialami maskapai penerbangan?', '{"options":[{"id":"opt_1","text":"Beberapa maskapai terpaksa menyusutkan rute penerbangan akibat lonjakan biaya bahan bakar dan memburuknya situasi internasional"},{"id":"opt_2","text":"Semua maskapai membuka puluhan rute baru bulan ini"},{"id":"opt_3","text":"Harga tiket pesawat internasional turun separuh"},{"id":"opt_4","text":"Biaya bahan bakar pesawat disubsidi penuh oleh bandara"}],"audio_text":"燃料費の急激な高騰と国際情勢の悪化を受け、複数の航空会社が路線縮小を余儀なくされている。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '路線縮小を余儀なくされている berarti terpaksa memangkas rute penerbangan.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b16f1813-560c-4899-a8cb-3656a364e37f', '8c713fb9-b38a-4169-aa63-0ddc550daba4', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Akibat pandemi global, banyak acara internasional terpaksa ditunda."', '{"romaji":"Sekai-teki na ryuukou ni yori, ooku no kokusai gyouji ga enki o yoginaku sareta.","tokens":["流行により、","延期","された。","とはいえ、","世界的な","多くの国際行事が","を余儀なく","を余儀なくさせた。"],"target_translation":"Akibat pandemi global, banyak acara internasional terpaksa ditunda."}'::jsonb, '["世界的な","流行により、","多くの国際行事が","延期","を余儀なく","された。"]'::jsonb, NULL, NULL, '延期を余儀なくされた adalah kolokasi berita N1 yang sangat sering muncul.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a4b4abe4-4e59-4988-86f2-19c02012fa47', '8c713fb9-b38a-4169-aa63-0ddc550daba4', 'd1000019-0000-0000-0000-000000000029', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Akibat perubahan regulasi lingkungan, pabrik kami terpaksa mengganti seluruh peralatan produksi."', '{"romaji":"Kankyou kisei no kyouka ni tomonai, koujou setsubi no zenmen sasshin o yoginaku saremashita.","display_text":"環境規制の強化に伴い、工場設備の全面刷新を余儀なくされました。","phonetic_breakdown":["かんきょうきせいの","きょうかにともない","こうじょうせつびの","ぜんめんさっしんを","よぎなくされました"]}'::jsonb, '{"expected_transcript":"環境規制の強化に伴い、工場設備の全面刷新を余儀なくされました。"}'::jsonb, NULL, NULL, '全面刷新 (pembaruan menyeluruh) + を余儀なくされました sangat khas laporan korporasi N1.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2c7e1474-f282-4a6f-a79c-d932903b46e5', '8c713fb9-b38a-4169-aa63-0ddc550daba4', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予期せぬ為替変動により、同社は業績予想の下方修正___状況にある。', '{"options":["を余儀なくされる","極まりない","なりに","ずにはおかない"],"translation":"Akibat fluktuasi nilai tukar yang tak terduga, perusahaan tersebut berada dalam situasi terpaksa merevisi turun proyeksi kinerjanya.","sentence_template":"予期せぬ為替変動により、同社は業績予想の下方修正[blank]状況にある。"}'::jsonb, '{"selected":"を余儀なくされる"}'::jsonb, NULL, NULL, '下方修正を余儀なくされる状況 menyatakan posisi terpaksa menurunkan target keuangan.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c076d9ff-c8b5-4a4f-875d-f2a496f7acf1', '8c713fb9-b38a-4169-aa63-0ddc550daba4', 'd1000019-0000-0000-0000-000000000029', 'listening', 'listening_choice', 'Dengarkan berita olahraga. Mengapa atlet unggulan itu batal tampil di final?', '{"options":[{"id":"opt_1","text":"Ia memilih beristirahat untuk persiapan tahun depan"},{"id":"opt_2","text":"Ia terkena sanksi karena terlambat hadir"},{"id":"opt_3","text":"Cedera lutut kanan di semifinal lebih parah dari dugaan sehingga ia terpaksa mundur dari final"},{"id":"opt_4","text":"Pertandingan final dibatalkan karena hujan salju"}],"audio_text":"準決勝で負った右膝の負傷が想定以上に重く、決勝戦の棄権を余儀なくされたとのことだ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '棄権を余儀なくされた berarti terpaksa mengundurkan diri (walkover/withdraw).', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4ddea6a7-8537-4f56-b35d-db37c88fe6be', '8c713fb9-b38a-4169-aa63-0ddc550daba4', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Kekurangan semikonduktor memaksa produsen mobil mengurangi volume produksi."', '{"romaji":"Handoutai busoku wa jidousha meekaa ni gensan o yoginaku saseta.","tokens":["自動車メーカーに","を","させた。","をもって、","半導体不足は","減産","余儀なく","された。"],"target_translation":"Kekurangan semikonduktor memaksa produsen mobil mengurangi volume produksi."}'::jsonb, '["半導体不足は","自動車メーカーに","減産","を","余儀なく","させた。"]'::jsonb, NULL, NULL, '減産を余儀なくさせた memakai bentuk kausatif karena subjeknya adalah faktor penyebab (半導体不足).', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2ea9ddd9-e84a-4a6d-9b6e-f25882fa6e93', '938d5524-8db2-4450-8fae-9bf7e7cf1e6b', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Lengkapi laporan krisis berikut: 深刻なシステム障害が発生する___、ようやく抜本的な改修予算が承認された。', '{"options":["に至って","をもって","なりに","ともなると"],"translation":"Baru setelah terjadi gangguan sistem yang parah, anggaran perombakan mendasar akhirnya disetujui.","sentence_template":"深刻なシステム障害が発生する[blank]、ようやく抜本的な改修予算が承認された。"}'::jsonb, '{"selected":"に至って"}'::jsonb, NULL, NULL, '～に至って menandai titik kritis ekstrem yang baru memicu kesadaran atau tindakan.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d0426f4-3a16-4240-b14b-7484b4d4343b', '938d5524-8db2-4450-8fae-9bf7e7cf1e6b', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk eskalasi puncak: 事態がここまで悪化する___、もはや従来の対策では不十分だ。', '{"options":["に至っては","を余儀なくされ","とはいえ","に足る"],"translation":"Setelah situasi memburuk sampai sejauh ini, langkah penanggulangan konvensional tidak lagi memadai.","sentence_template":"事態がここまで悪化する[blank]、もはや従来の対策では不十分だ。"}'::jsonb, '{"selected":"に至っては"}'::jsonb, NULL, NULL, '～に至っては memberi penekanan kuat pada situasi yang sudah mencapai tahap ekstrem.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b00f1f28-a342-4844-9930-5c12951f18e7', '938d5524-8db2-4450-8fae-9bf7e7cf1e6b', 'd1000019-0000-0000-0000-000000000028', 'listening', 'listening_choice', 'Dengarkan ulasan berita politik berikut. Kapan pemerintah akhirnya mengambil tindakan tegas?', '{"options":[{"id":"opt_1","text":"Sebelum pabrik mulai beroperasi sama sekali"},{"id":"opt_2","text":"Baru setelah laporan gangguan kesehatan warga datang dari berbagai pemda, pemerintah memerintahkan penghentian operasi pabrik"},{"id":"opt_3","text":"Pemerintah tidak pernah mengeluarkan perintah apa pun"},{"id":"opt_4","text":"Pabrik memutuskan berhenti sendiri tanpa laporan warga"}],"audio_text":"複数の自治体から住民の健康被害が報告されるに至って、国はようやく工場の操業停止を命じた。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '報告されるに至って menegaskan keterlambatan respons hingga situasi mencapai titik kritis.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6f091c42-ab75-4abd-8da6-db930bd1f648', '938d5524-8db2-4450-8fae-9bf7e7cf1e6b', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Baru setelah kehilangan kesehatannya, ia menyadari betapa berharganya istirahat."', '{"romaji":"Kenkou o ushinau ni itatte, kare wa kyuusoku no toutosa ni kizuita.","tokens":["失う","彼は休息の","気づいた。","とはいえ、","健康を","に至って、","尊さに","失った"],"target_translation":"Baru setelah kehilangan kesehatannya, ia menyadari betapa berharganya istirahat."}'::jsonb, '["健康を","失う","に至って、","彼は休息の","尊さに","気づいた。"]'::jsonb, NULL, NULL, '失うに至って (baru ketika sampai kehilangan) memakai verba bentuk kamus.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('183b504b-8533-41ae-bc12-f8e6025b3ef2', '938d5524-8db2-4450-8fae-9bf7e7cf1e6b', 'd1000019-0000-0000-0000-000000000028', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setelah mencapai tahap ini, kita harus meninjau ulang seluruh strategi dari awal."', '{"romaji":"Kono dankai ni itatte wa, senryaku zentai o konpon kara minaosu hoka arimasen.","display_text":"この段階に至っては、戦略全体を根本から見直すほかありません。","phonetic_breakdown":["このだんかいに","いたっては","せんりゃくぜんたいを","こんぽんから","みなおすほかありません"]}'::jsonb, '{"expected_transcript":"この段階に至っては、戦略全体を根本から見直すほかありません。"}'::jsonb, NULL, NULL, 'この段階に至っては adalah ungkapan rapat eksekutif tingkat N1 saat menghadapi titik balik.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('da742bab-c630-44bf-9bdb-3f9ca09ef8bc', '938d5524-8db2-4450-8fae-9bf7e7cf1e6b', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Lengkapi kalimat sejarah bisnis: 明治時代___、日本の産業構造は急速な近代化を遂げた。', '{"options":["に至って","極まりなく","ずにはおかず","いかんによらず"],"translation":"Memasuki era Meiji, struktur industri Jepang mencapai modernisasi yang pesat.","sentence_template":"明治時代[blank]、日本の産業構造は急速な近代化を遂げた。"}'::jsonb, '{"selected":"に至って"}'::jsonb, NULL, NULL, 'Kata benda waktu/era (明治時代) + に至って menandai titik sejarah baru.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3f8c53de-53c5-44b2-aa9d-2e75df4bde2d', '938d5524-8db2-4450-8fae-9bf7e7cf1e6b', 'd1000019-0000-0000-0000-000000000028', 'listening', 'listening_choice', 'Dengarkan komentar analis keuangan. Apa pemicu mundurnya dewan direksi?', '{"options":[{"id":"opt_1","text":"Kenaikan laba perusahaan yang melampaui target"},{"id":"opt_2","text":"Keinginan direksi untuk membuka cabang di Eropa"},{"id":"opt_3","text":"Terungkapnya fakta manipulasi akuntansi oleh komite independen hingga direksi memutuskan mundur massal"},{"id":"opt_4","text":"Berakhirnya masa jabatan rutin lima tahunan"}],"audio_text":"不正会計の事実が第三者委員会によって公表されるに至り、経営陣は総辞職を決断した。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '公表されるに至り (bentuk formal tertulis dari に至って) menandai titik balik yang memicu pengunduran diri.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ef505b8b-abfb-42e0-b67a-9e06ab86a552', '938d5524-8db2-4450-8fae-9bf7e7cf1e6b', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Hingga saat terakhir pun, ia tetap mempertahankan pendiriannya."', '{"romaji":"Saigo no shunkan ni itaru made, kare wa jibun no shinnen o tsuranuita.","tokens":["瞬間に","彼は自分の","貫いた。","貫く","最後の","至るまで、","信念を","至って、"],"target_translation":"Hingga saat terakhir pun, ia tetap mempertahankan pendiriannya."}'::jsonb, '["最後の","瞬間に","至るまで、","彼は自分の","信念を","貫いた。"]'::jsonb, NULL, NULL, '～に至るまで berarti ''hingga mencapai titik (paling akhir)''.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fed4c51e-a34b-4345-bb44-b8d294d3d2e3', '93ade43c-6382-468e-a452-00dbe512103c', 'd1000019-0000-0000-0000-000000000033', 'listening', 'listening_choice', 'Dengarkan percakapan dua orang tua. Apa yang mereka bicarakan tentang anak mereka?', '{"options":[{"id":"opt_1","text":"Anak-anak pun dengan caranya sendiri memperhatikan ekspresi orang tua dan berusaha menjaga perasaan mereka"},{"id":"opt_2","text":"Anak-anak sama sekali tidak peduli pada orang tuanya"},{"id":"opt_3","text":"Orang tua tidak perlu berbicara dengan anak-anak"},{"id":"opt_4","text":"Anak-anak selalu menuntut mainan mahal setiap hari"}],"audio_text":"子どもは子どもなりに親の顔色をよく見ていて、気を遣っていることがあるんだよ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '子どもは子どもなりに adalah pola repetisi XはXなりに yang sangat alami di N1.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('621996d8-7dd3-4a4f-886c-0fbd575442fc', '93ade43c-6382-468e-a452-00dbe512103c', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Perusahaan kecil memiliki keunggulan kecepatan keputusan sesuai skalanya sendiri."', '{"romaji":"Chuushou kigyou ni wa chuushou kigyou nari no tsuyomi ga aru.","tokens":["中小企業","強みが","はずだ。","を余儀なくされ、","中小企業には","なりの","ある","なりに"],"target_translation":"Perusahaan kecil memiliki keunggulan kecepatan keputusan sesuai skalanya sendiri."}'::jsonb, '["中小企業には","中小企業","なりの","強みが","ある","はずだ。"]'::jsonb, NULL, NULL, '中小企業なりの強み (keunggulan khas skala UKM) memakai kata benda + なりの.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('351eebe8-951f-4f1b-848d-de3288304f29', '93ade43c-6382-468e-a452-00dbe512103c', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 都会の便利さはないが、田舎には田舎___豊かな暮らしがある。', '{"options":["なりの","なりに","をもって","に足る"],"translation":"Memang tidak ada kepraktisan kota besar, tetapi di desa ada kehidupan yang kaya sesuai karakteristik desanya sendiri.","sentence_template":"都会の便利さはないが、田舎には田舎[blank]豊かな暮らしがある。"}'::jsonb, '{"selected":"なりの"}'::jsonb, NULL, NULL, '田舎なりの豊かな暮らし memodifikasi frasa nominal 豊かな暮らし.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('00d30afa-8202-4576-a740-fb8acf44aca6', '93ade43c-6382-468e-a452-00dbe512103c', 'd1000019-0000-0000-0000-000000000033', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya telah memikirkan solusi terbaik menurut pemahaman saya sendiri."', '{"romaji":"Jibun nari ni kangaenuita ue de, kono kaizenan o sakusei shimashita.","display_text":"自分なりに考え抜いた上で、この改善案を作成しました。","phonetic_breakdown":["じぶんなりに","かんがえぬいたうえで","このかいぜんあんを","さくせいしました"]}'::jsonb, '{"expected_transcript":"自分なりに考え抜いた上で、この改善案を作成しました。"}'::jsonb, NULL, NULL, '自分なりに考え抜く (memikirkan matang-matang dengan cara sendiri) menunjukkan inisiatif mandiri.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('516876aa-a258-420d-8047-af461a9a4f4e', '93ade43c-6382-468e-a452-00dbe512103c', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 歳を取れば、若い頃とは違う老後___楽しみ方が見つかるものだ。', '{"options":["なりの","に至って","極まりない","ずにはおかない"],"translation":"Jika bertambah usia, akan ditemukan cara menikmati masa tua tersendiri yang berbeda dari masa muda.","sentence_template":"歳を取れば、若い頃とは違う老後[blank]楽しみ方が見つかるものだ。"}'::jsonb, '{"selected":"なりの"}'::jsonb, NULL, NULL, '老後なりの楽しみ方 menyatakan cara menikmati hidup yang sesuai dengan fase usia lanjut.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('08906055-aff2-4de8-a28f-11d0529bfd54', '93ade43c-6382-468e-a452-00dbe512103c', 'd1000019-0000-0000-0000-000000000033', 'listening', 'listening_choice', 'Dengarkan tanggapan manajer proyek. Bagaimana ia mengevaluasi presentasi staf junior?', '{"options":[{"id":"opt_1","text":"Presentasi staf junior dinilai gagal total"},{"id":"opt_2","text":"Data analisisnya tidak relevan dengan proyek"},{"id":"opt_3","text":"Staf junior diminta meniru presentasi orang lain persis sama"},{"id":"opt_4","text":"Meski masih ada bagian yang mentah, sudut pandang analisis datanya memancarkan orisinalitas khas dirinya sendiri"}],"audio_text":"まだ荒削りな部分はあるものの、データ分析の切り口には君なりの独自性が光っていたよ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '君なりの独自性 berarti keunikan/orisinalitas yang lahir dari pemikiran staf itu sendiri.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c8c597dd-9a00-4c1f-b045-30b34524c548', '93ade43c-6382-468e-a452-00dbe512103c', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Walaupun sibuk, saya meluangkan waktu belajar bahasa Jepang sesuai ritme saya sendiri."', '{"romaji":"Isogashii naka demo, jibun nari no peesu de Nihongo o benkyou shite iru.","tokens":["自分","ペースで","勉強している。","勉強した。","忙しい中でも、","なりの","日本語を","なりに"],"target_translation":"Walaupun sibuk, saya meluangkan waktu belajar bahasa Jepang sesuai ritme saya sendiri."}'::jsonb, '["忙しい中でも、","自分","なりの","ペースで","日本語を","勉強している。"]'::jsonb, NULL, NULL, '自分なりのペースで (dengan ritme sendiri) sangat alami untuk menggambarkan kebiasaan belajar.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8771ffd4-bc41-42c1-8873-d1ebe36f63b0', '93ade43c-6382-468e-a452-00dbe512103c', 'd1000019-0000-0000-0000-000000000033', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setiap anggota tim berkontribusi sesuai peran dan keahliannya masing-masing."', '{"romaji":"Menbaa sorezore ga, jibun no tachiba nari ni saizen o tsukushite kuremashita.","display_text":"メンバーそれぞれが、自分の立場なりに最善を尽くしてくれました。","phonetic_breakdown":["めんばーそれぞれが","じぶんのたちばなりに","さいぜんを","つくしてくれました"]}'::jsonb, '{"expected_transcript":"メンバーそれぞれが、自分の立場なりに最善を尽くしてくれました。"}'::jsonb, NULL, NULL, '立場なりに最善を尽くす berarti melakukan yang terbaik sesuai posisi masing-masing.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5abccc13-bc51-430b-ad07-3d4ff3ad64b4', '980fbc33-f591-47b9-8520-765f0431b84a', 'd1000019-0000-0000-0000-000000000029', 'listening', 'listening_choice', 'Dengarkan wawancara pemilik penginapan tradisional. Mengapa mereka merenovasi bangunan secara besar-besaran?', '{"options":[{"id":"opt_1","text":"Untuk menarik wisatawan dengan desain futuristik"},{"id":"opt_2","text":"Karena mereka terpaksa melakukan renovasi besar demi memenuhi standar tahan gempa yang baru"},{"id":"opt_3","text":"Karena bangunan lama terbakar habis tahun lalu"},{"id":"opt_4","text":"Karena pemerintah kota membeli bangunan tersebut"}],"audio_text":"新たな耐震基準を満たすため、歴史ある木造建築であっても大規模な改修を余儀なくされたのです。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '大規模な改修を余儀なくされた menjelaskan keterpaksaan mematuhi standar tahan gempa baru.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3a388665-dd4a-4ac1-ba30-cb245d91871d', '980fbc33-f591-47b9-8520-765f0431b84a', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Akibat pemadaman listrik luas, rumah sakit terpaksa menggunakan generator darurat."', '{"romaji":"Kouiki teiden ni yori, byouin wa hijouyou hatsudenki no kadou o yoginaku sareta.","tokens":["病院は","稼働","された。","ともなると、","広域停電により、","非常用発電機の","を余儀なく","稼働する"],"target_translation":"Akibat pemadaman listrik luas, rumah sakit terpaksa menggunakan generator darurat."}'::jsonb, '["広域停電により、","病院は","非常用発電機の","稼働","を余儀なく","された。"]'::jsonb, NULL, NULL, '稼働を余儀なくされた menggunakan kata benda 稼働 langsung sebelum を余儀なくされた.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fa1bbd56-73d3-470a-8456-99fff9d6970b', '980fbc33-f591-47b9-8520-765f0431b84a', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 深刻な干ばつが続き、農家は作付け品目の変更___。', '{"options":["を余儀なくされている","に至っている","に足る","いかんによらず"],"translation":"Kekeringan parah terus berlanjut sehingga para petani terpaksa mengubah jenis tanaman yang ditanam.","sentence_template":"深刻な干ばつが続き、農家は作付け品目の変更[blank]。"}'::jsonb, '{"selected":"を余儀なくされている"}'::jsonb, NULL, NULL, '変更を余儀なくされている menyatakan kondisi keterpaksaan yang sedang berlangsung.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f73d19e7-84ee-454a-8e97-975c3c88d17d', '980fbc33-f591-47b9-8520-765f0431b84a', 'd1000019-0000-0000-0000-000000000029', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Akibat penghentian pasokan bahan baku, kami terpaksa menangguhkan penerimaan pesanan baru."', '{"romaji":"Genzairyou no kyoukyuu teishi o uke, shinki juchuu no ichiji teishi o yoginaku sarete orimasu.","display_text":"原材料の供給停止を受け、新規受注の一時停止を余儀なくされております。","phonetic_breakdown":["げんざいりょうの","きょうきゅうていしをうけ","しんきじゅちゅうの","いちじていしを","よぎなくされております"]}'::jsonb, '{"expected_transcript":"原材料の供給停止を受け、新規受注の一時停止を余儀なくされております。"}'::jsonb, NULL, NULL, '一時停止を余儀なくされております adalah ungkapan surat pemberitahuan resmi bisnis N1.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('baebf50a-47ed-40f5-9e51-44d96a03a5e5', '980fbc33-f591-47b9-8520-765f0431b84a', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 競合他社の急速な台頭が、老舗企業にビジネスモデルの再構築___。', '{"options":["を余儀なくさせた","を余儀なくされた","とはいえ","極まりない"],"translation":"Kebangkitan pesat perusahaan pesaing memaksa perusahaan mapan membangun ulang model bisnisnya.","sentence_template":"競合他社の急速な台頭が、老舗企業にビジネスモデルの再構築[blank]。"}'::jsonb, '{"selected":"を余儀なくさせた"}'::jsonb, NULL, NULL, 'Subjek penyebab (台頭が) + pihak terdampak (老舗企業に) + 再構築を余儀なくさせた.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('76afd1d9-def4-4d22-816f-5e3d6c9ecd18', '980fbc33-f591-47b9-8520-765f0431b84a', 'd1000019-0000-0000-0000-000000000029', 'listening', 'listening_choice', 'Dengarkan laporan bencana laut. Apa dampak tumpahan minyak bagi nelayan setempat?', '{"options":[{"id":"opt_1","text":"Hasil tangkapan ikan meningkat dua kali lipat"},{"id":"opt_2","text":"Nelayan menerima kapal baru dari pemerintah"},{"id":"opt_3","text":"Harga ikan di pasar lokal turun drastis"},{"id":"opt_4","text":"Koperasi nelayan setempat terpaksa menghentikan penangkapan ikan selama beberapa bulan"}],"audio_text":"沿岸部の油流出事故により、地元の漁業協同組合は数ヶ月間にわたる禁漁を余儀なくされた。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '禁漁を余儀なくされた berarti terpaksa menjalani larangan melaut/menangkap ikan.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('22359660-3661-465e-b083-0fde95b58bfe', '980fbc33-f591-47b9-8520-765f0431b84a', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Akibat konflik berkepanjangan, ribuan penduduk terpaksa meninggalkan kampung halaman mereka."', '{"romaji":"Choukika suru funsou ni yori, ooku no juumin ga kokyou kara no dasshutsu o yoginaku sareta.","tokens":["紛争により、","故郷からの脱出","された。","なりに、","長期化する","多くの住民が","を余儀なく","を余儀なくさせた。"],"target_translation":"Akibat konflik berkepanjangan, ribuan penduduk terpaksa meninggalkan kampung halaman mereka."}'::jsonb, '["長期化する","紛争により、","多くの住民が","故郷からの脱出","を余儀なく","された。"]'::jsonb, NULL, NULL, '脱出を余儀なくされた menyoroti penderitaan akibat faktor luar yang tak terelakkan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('50e50846-61b5-481e-bff8-4c3d48f2e6e9', '980fbc33-f591-47b9-8520-765f0431b84a', 'd1000019-0000-0000-0000-000000000029', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karena cuaca ekstrem yang belum pernah terjadi, jadwal konstruksi terpaksa diperpanjang."', '{"romaji":"Kirokuteki na akutenkou no tame, kouki no oohaba na enchou o yoginaku saremashita.","display_text":"記録的な悪天候のため、工期の大幅な延長を余儀なくされました。","phonetic_breakdown":["きろくてきな","あくてんこうのため","こうきのおおはばな","えんちょうを","よぎなくされました"]}'::jsonb, '{"expected_transcript":"記録的な悪天候のため、工期の大幅な延長を余儀なくされました。"}'::jsonb, NULL, NULL, '工期の延長 (perpanjangan jadwal proyek konstruksi) + を余儀なくされました.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9130185e-e433-4ce6-a379-6d04c1445ce0', '9a6234b2-b488-47e9-a0ab-05ba548779f4', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Pilih pola yang tepat untuk klausul resmi: 事由の___、許可なく館内で撮影を行うことは固く禁じられている。', '{"options":["とはいえ","ともなると","いかんによらず","いかんで"],"translation":"Tanpa memandang apa pun alasannya, mengambil gambar di dalam gedung tanpa izin dilarang keras.","sentence_template":"事由の[blank]、許可なく館内で撮影を行うことは固く禁じられている。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, NULL, NULL, '事由のいかんによらず adalah formulasi hukum yang sangat tepat untuk larangan tanpa pengecualian.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3ebebc58-78a2-4359-97e8-dff5fb96d38b', '9a6234b2-b488-47e9-a0ab-05ba548779f4', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 採択の可否の___、提出された応募書類は返却いたしません。', '{"options":["に足らず","いかんによっては","をもって","いかんにかかわらず"],"translation":"Tanpa memandang diterima atau ditolaknya lamaran, berkas yang telah diserahkan tidak akan dikembalikan.","sentence_template":"採択の可否の[blank]、提出された応募書類は返却いたしません。"}'::jsonb, '{"selected":"いかんにかかわらず"}'::jsonb, NULL, NULL, '採択の可否のいかんにかかわらず lazim tercantum pada panduan pendaftaran hibah atau rekrutmen.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e79a7f8b-de4f-4e9b-855b-8dd6a40d2575', '9a6234b2-b488-47e9-a0ab-05ba548779f4', 'd1000019-0000-0000-0000-000000000036', 'listening', 'listening_choice', 'Dengarkan pernyataan kepala rumah sakit berikut. Apa prinsip pelayanan medis yang dipegang?', '{"options":[{"id":"opt_1","text":"Memberikan layanan medis terbaik kepada semua orang tanpa memandang status sosial atau ekonomi"},{"id":"opt_2","text":"Hanya menerima pasien dengan asuransi swasta khusus"},{"id":"opt_3","text":"Memprioritaskan pasien berdasarkan jabatan publik mereka"},{"id":"opt_4","text":"Menutup layanan gawat darurat pada akhir pekan"}],"audio_text":"患者の社会的地位や経済状況のいかんによらず、当院はすべての人に最善の医療を提供する。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '社会的地位や経済状況のいかんによらず menegaskan prinsip kesetaraan layanan medis.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('403f305d-b3cf-45c2-92ca-b812cbbb8769', '9a6234b2-b488-47e9-a0ab-05ba548779f4', 'd1000019-0000-0000-0000-000000000036', 'listening', 'listening_choice', 'Dengarkan komentar panitia lelang berikut. Apa syarat mutlak pengajuan penawaran?', '{"options":[{"id":"opt_1","text":"Hanya perusahaan berusia di atas lima puluh tahun yang boleh ikut"},{"id":"opt_2","text":"Proposal terbaik akan dipilih secara transparan tanpa memandang skala atau rekam jejak perusahaan"},{"id":"opt_3","text":"Pemenang lelang sudah ditentukan sebelum proposal dibuka"},{"id":"opt_4","text":"Perusahaan kecil dilarang mengajukan penawaran"}],"audio_text":"企業の規模や実績のいかんを問わず、透明な手続きのもとで最も優れた提案を採用いたします。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '企業の規模や実績のいかんを問わず berarti ''tanpa memandang besar kecilnya perusahaan atau rekam jejaknya''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d348d8a3-7c19-4f95-8b9d-1fae754023d9', '9a6234b2-b488-47e9-a0ab-05ba548779f4', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang status keanggotaan, biaya masuk dibebaskan hari ini."', '{"romaji":"Kaiin shikaku no umu no ikan ni yorazu honjitsu wa nyuujou muryou da.","tokens":["いかんに","よらず","本日は","入場無料だ","会員資格の","なりに","有無の","極まりない"],"target_translation":"Tanpa memandang status keanggotaan, biaya masuk dibebaskan hari ini."}'::jsonb, '["会員資格の","有無の","いかんに","よらず","本日は","入場無料だ"]'::jsonb, NULL, NULL, '有無のいかんによらず berarti ''tanpa memandang ada atau tidak adanya''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('248277c7-7463-46e6-9474-6a3262b9bf0d', '9a6234b2-b488-47e9-a0ab-05ba548779f4', 'd1000019-0000-0000-0000-000000000036', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang perbedaan pendapat, kita harus menghormati aturan rapat."', '{"romaji":"Kenkai no soui no ikan ni yorazu, kaigi no ruuru wa junshu subeki de aru.","display_text":"見解の相違のいかんによらず、会議のルールは遵守すべきである。","phonetic_breakdown":["ken-kai","no","sou-i","no","i-kan","ni","yo-ra-zu","kai-gi","no","ruu-ru","wa","jun-shu","su-be-ki","de","a-ru"]}'::jsonb, '{"expected_transcript":"見解の相違のいかんによらず、会議のルールは遵守すべきである。"}'::jsonb, NULL, NULL, '見解の相違 (perbedaan pandangan) dan 遵守すべき (wajib dipatuhi).', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bc549a26-8b4c-451d-a409-f7b077a4fe1c', '9a6234b2-b488-47e9-a0ab-05ba548779f4', 'd1000019-0000-0000-0000-000000000036', 'listening', 'listening_choice', 'Dengarkan kutipan aturan ketenagakerjaan. Apa isi ketentuan tersebut?', '{"options":[{"id":"opt_1","text":"Pekerja kontrak selalu dibayar setengah dari pekerja tetap untuk pekerjaan sama"},{"id":"opt_2","text":"Upah tidak berkaitan dengan jenis pekerjaan"},{"id":"opt_3","text":"Tanpa memandang status kepegawaian, pekerjaan yang sama harus menerima upah yang sama"},{"id":"opt_4","text":"Perusahaan dilarang mempekerjakan staf paruh waktu"}],"audio_text":"雇用形態のいかんによらず、同一の労働に対しては同一の賃金が支払われるべきである。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '雇用形態のいかんによらず (tanpa memandang status kerja tetap/kontrak) adalah prinsip 同一労働同一賃金.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a0558f6e-b4c1-4522-b82a-84b71c73542a', '9a6234b2-b488-47e9-a0ab-05ba548779f4', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang hasilnya nanti, pengalaman ini pasti menjadi bekal berharga."', '{"romaji":"Gouhi no ikan ni yorazu, kono keiken wa kichou na kate ni naru.","tokens":["いかん","この経験は","なるはずだ。","をもって、","合否の","によらず、","貴重な糧に","なった。"],"target_translation":"Tanpa memandang hasilnya nanti, pengalaman ini pasti menjadi bekal berharga."}'::jsonb, '["合否の","いかん","によらず、","この経験は","貴重な糧に","なるはずだ。"]'::jsonb, NULL, NULL, '合否のいかんによらず (tanpa memandang lulus atau tidaknya) lazim dalam refleksi ujian.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('de27263a-1784-45bb-8356-49ea6d905f68', '9bbd793f-b110-4a0e-a45f-b5374efd30f7', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan tajuk rencana berikut. Apa kekhawatiran penulis terhadap penggunaan AI?', '{"options":[{"id":"opt_1","text":"Akurasi AI generatif justru semakin menurun"},{"id":"opt_2","text":"Manusia tetap harus menjadi penentu akhir kebenaran informasi"},{"id":"opt_3","text":"AI generatif sebaiknya dilarang sepenuhnya di sektor pendidikan"},{"id":"opt_4","text":"Biaya pengembangan AI terlalu rendah untuk diawasi"}],"audio_text":"生成AIの精度が飛躍的に高まったとはいえ、情報の真偽を最終的に判断するのは人間でなければならない。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '情報の真偽を最終的に判断するのは人間でなければならない berarti ''yang memutuskan benar-salahnya informasi pada akhirnya haruslah manusia''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d5427c4-9807-4707-aab5-5cc64170bd3d', '9bbd793f-b110-4a0e-a45f-b5374efd30f7', NULL, 'listening', 'listening_choice', 'Dengarkan ulasan ekonomi berikut. Bagaimana penilaian pembicara terhadap kenaikan gaji tahun ini?', '{"options":[{"id":"opt_1","text":"Kenaikan gaji belum mampu mengejar laju kenaikan harga barang"},{"id":"opt_2","text":"Harga barang menurun drastis berkat kenaikan gaji"},{"id":"opt_3","text":"Perusahaan besar menolak menaikkan gaji karyawan"},{"id":"opt_4","text":"Daya beli masyarakat meningkat dua kali lipat"}],"audio_text":"大手企業を中心に賃上げが進んだとはいえ、物価上昇のペースには依然として追いついていない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '物価上昇のペースには依然として追いついていない berarti ''tetap belum mengejar laju inflasi/kenaikan harga''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d553f228-0da8-4f47-95f6-ec99baf7db05', '9bbd793f-b110-4a0e-a45f-b5374efd30f7', NULL, 'listening', 'listening_choice', 'Dengarkan pendapat pakar pendidikan berikut. Apa pesan utamanya?', '{"options":[{"id":"opt_1","text":"Materi daring masih sangat kurang dan sulit diakses"},{"id":"opt_2","text":"Sekolah tatap muka akan segera dihapuskan"},{"id":"opt_3","text":"Dialog langsung antara guru dan siswa tidak tergantikan meski materi daring lengkap"},{"id":"opt_4","text":"Siswa belajar lebih cepat tanpa bantuan guru sama sekali"}],"audio_text":"オンライン教材が充実してきたとはいえ、教師と生徒の直接的な対話に代わるものはない。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '直接的な対話に代わるものはない berarti ''tidak ada yang dapat menggantikan dialog langsung''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7a43ef19-2149-450c-862a-8edaa0b0d372', '9bbd793f-b110-4a0e-a45f-b5374efd30f7', NULL, 'reading', 'fill_blank', 'Lengkapi paragraf analisis berikut: 人口減少への対策が急務である___、即効性のある解決策は容易に見つからない。', '{"options":["とばかりに","とあって","とはいえ","ともなると"],"translation":"Meskipun penanggulangan penurunan populasi memang mendesak, solusi yang berdampak instan tidak mudah ditemukan.","sentence_template":"人口減少への対策が急務である[blank]、即効性のある解決策は容易に見つからない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '急務であるとはいえ mengakui urgensi masalah, lalu menyoroti kesulitan menemukan solusi instan.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8ed59fda-4f70-4ed8-ac15-7419afae8390', '9bbd793f-b110-4a0e-a45f-b5374efd30f7', NULL, 'reading', 'fill_blank', 'Pilih ungkapan yang tepat: 個人的な見解___、影響力のある立場の発言には慎重さが求められる。', '{"options":["とはいえ","をもって","に足る","なりに"],"translation":"Meskipun itu memang pendapat pribadi, pernyataan dari posisi yang berpengaruh menuntut kehati-hatian.","sentence_template":"個人的な見解[blank]、影響力のある立場の発言には慎重さが求められる。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '個人的な見解とはいえ (''meski itu pendapat pribadi'') sering muncul dalam diskusi etika publik.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('328f7871-9d97-4995-a2db-d6ae41fb3c56', '9bbd793f-b110-4a0e-a45f-b5374efd30f7', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 試験の合格率が上昇した___、問題の難易度自体が下がったわけではない。', '{"options":["に沿って","に至って","をよそに","とはいえ"],"translation":"Walaupun tingkat kelulusan ujian meningkat, bukan berarti tingkat kesulitan soalnya sendiri menurun.","sentence_template":"試験の合格率が上昇した[blank]、問題の難易度自体が下がったわけではない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '～とはいえ...わけではない adalah kombinasi klasik N1 untuk meluruskan kesalahpahaman umum.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7495ed66-87db-43c0-b19d-87978e2d3836', '9bbd793f-b110-4a0e-a45f-b5374efd30f7', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun mendapat dukungan mayoritas, kita tetap perlu mendengarkan suara minoritas."', '{"romaji":"Tasuu no shiji o eta to wa ie, shousuu iken ni mo mimi o katamukeru beki da.","tokens":["得た","少数意見にも","べきだ。","に至って、","多数の支持を","とはいえ、","耳を傾ける","得る"],"target_translation":"Meskipun mendapat dukungan mayoritas, kita tetap perlu mendengarkan suara minoritas."}'::jsonb, '["多数の支持を","得た","とはいえ、","少数意見にも","耳を傾ける","べきだ。"]'::jsonb, NULL, NULL, '耳を傾ける (mendengarkan dengan saksama) + とはいえ menonjolkan prinsip demokrasi berimbang.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('92a1e9ee-aabb-4cb1-b7d7-92564b8423f1', '9bbd793f-b110-4a0e-a45f-b5374efd30f7', 'd1000019-0000-0000-0000-000000000030', 'listening', 'listening_choice', 'Dengarkan ulasan arsitektur. Apa penilaian pengamat tentang gedung bersejarah itu?', '{"options":[{"id":"opt_1","text":"Gedung itu sudah runtuh karena terlalu tua"},{"id":"opt_2","text":"Meskipun bangunan tua berusia lebih dari seratus tahun, kondisi pemeliharaannya amat baik dan memenuhi standar tahan gempa modern"},{"id":"opt_3","text":"Gedung itu tidak boleh dikunjungi oleh siapa pun"},{"id":"opt_4","text":"Gedung itu baru selesai dibangun tahun lalu"}],"audio_text":"築百年を超える古い建物とはいえ、保存状態が極めて良好で現代の耐震基準も満たしている。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '古い建物とはいえ mengakui usianya sambil memuji kondisi pemeliharaan dan keamanannya.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('987b813d-efda-4153-a1ed-0b648173f574', '9eb0cd9a-4661-46ef-bf04-1c7166b2962c', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Pilih pola yang tepat untuk melengkapi opini berikut: 制度の理念には賛同する___、導入時期については再考の余地がある。', '{"options":["ともなると","とあって","とばかりに","とはいえ"],"translation":"Meskipun saya setuju dengan prinsip sistemnya, soal waktu penerapannya masih ada ruang untuk dipertimbangkan ulang.","sentence_template":"制度の理念には賛同する[blank]、導入時期については再考の余地がある。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '賛同するとはいえ mengakui persetujuan secara prinsip sebelum mengajukan catatan soal jadwal implementasi.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('14084814-dce4-44b9-8f0f-4a88c27f6865', '9eb0cd9a-4661-46ef-bf04-1c7166b2962c', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 自由競争が原則である___、消費者保護のための一定の規制は必要だ。', '{"options":["に足る","をもって","に至っては","とはいえ"],"translation":"Meskipun persaingan bebas adalah prinsipnya, regulasi tertentu untuk perlindungan konsumen tetap diperlukan.","sentence_template":"自由競争が原則である[blank]、消費者保護のための一定の規制は必要だ。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '自由競争が原則であるとはいえ menyusun argumen berimbang yang sangat khas dalam bacaan N1.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('86df7575-0de5-4480-bdf2-68717560c8eb', '9eb0cd9a-4661-46ef-bf04-1c7166b2962c', 'd1000019-0000-0000-0000-000000000030', 'listening', 'listening_choice', 'Dengarkan komentar rapat berikut. Apa catatan kritis yang disampaikan pembicara?', '{"options":[{"id":"opt_1","text":"Penjualan produk baru sangat buruk sejak hari pertama"},{"id":"opt_2","text":"Perusahaan tidak memiliki pesaing di pasar saat ini"},{"id":"opt_3","text":"Pangsa pasar dapat hilang jika tidak terus memantau gerak-gerik kompetitor"},{"id":"opt_4","text":"Harga produk baru harus segera dinaikkan"}],"audio_text":"新製品の売れ行きが好調とはいえ、競合他社の動向を注視し続けなければ市場シェアを失いかねない。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '競合他社の動向を注視し続けなければ市場シェアを失いかねない mengingatkan agar tetap waspada terhadap pesaing.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('da1e2e43-fc9f-4515-9728-297cf1f96f2c', '9eb0cd9a-4661-46ef-bf04-1c7166b2962c', 'd1000019-0000-0000-0000-000000000030', 'listening', 'listening_choice', 'Dengarkan ulasan kebijakan energi berikut. Apa poin utama yang ditekankan pembicara?', '{"options":[{"id":"opt_1","text":"Energi terbarukan belum mulai diterapkan sama sekali"},{"id":"opt_2","text":"Pasokan energi terbarukan sudah sepenuhnya stabil tanpa kendala"},{"id":"opt_3","text":"Biaya listrik turun drastis di seluruh wilayah"},{"id":"opt_4","text":"Masih banyak tantangan teknis untuk menjamin pasokan yang stabil"}],"audio_text":"再生可能エネルギーの導入が進んだとはいえ、安定供給の確保にはまだ多くの技術的課題が残っている。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '安定供給の確保にはまだ多くの技術的課題が残っている menyoroti tantangan teknis stabilitas pasokan.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('070d368c-cdc7-41f7-a633-c008599d1a6f', '9eb0cd9a-4661-46ef-bf04-1c7166b2962c', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Walaupun hanya perbedaan kecil, dalam jangka panjang pengaruhnya besar."', '{"romaji":"Wazuka na sa da to wa ie, choukiteki ni wa ookina eikyou ga deru.","tokens":["大きな","に至って","差だ","なりに","長期的には","影響が出る","とはいえ","わずかな"],"target_translation":"Walaupun hanya perbedaan kecil, dalam jangka panjang pengaruhnya besar."}'::jsonb, '["わずかな","差だ","とはいえ","長期的には","大きな","影響が出る"]'::jsonb, NULL, NULL, 'わずかな差だとはいえ mengakui perbedaannya kecil, lalu menekankan dampak jangka panjangnya.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b23a7d3-fb39-44c8-bed2-d6b6b753039f', '9eb0cd9a-4661-46ef-bf04-1c7166b2962c', 'd1000019-0000-0000-0000-000000000030', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun ini baru tahap awal, hasil yang menjanjikan sudah mulai terlihat."', '{"romaji":"Mada shoki dankai to wa ie, tashika na tegotae ga kanjirareru.","display_text":"まだ初期段階とはいえ、確かな手応えが感じられる。","phonetic_breakdown":["ma-da","sho-ki","dan-kai","to","wa","i-e","ta-shi-ka","na","te-go-ta-e","ga","kan-ji-ra-re-ru"]}'::jsonb, '{"expected_transcript":"まだ初期段階とはいえ、確かな手応えが感じられる。"}'::jsonb, NULL, NULL, '確かな手応え (tashika na tegotae) berarti ''respons/hasil nyata yang menjanjikan''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('14035d7b-def8-4dcd-8802-989161c90b84', '9eb0cd9a-4661-46ef-bf04-1c7166b2962c', 'd1000019-0000-0000-0000-000000000030', 'listening', 'listening_choice', 'Dengarkan analisis berita teknologi. Apa kesimpulan narasumber?', '{"options":[{"id":"opt_1","text":"Baterai kendaraan listrik sudah tidak punya kelemahan sama sekali"},{"id":"opt_2","text":"Kendaraan listrik tidak bisa berjalan di musim panas"},{"id":"opt_3","text":"Meskipun performa baterai meningkat pesat, jarak tempuh di daerah beriklim dingin masih menyisakan tantangan"},{"id":"opt_4","text":"Teknologi baterai tidak mengalami perkembangan selama dua puluh tahun"}],"audio_text":"電池の性能が飛躍的に向上したとはいえ、寒冷地での航続距離にはまだ課題が残る。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '向上したとはいえ diikuti catatan teknis objektif 課題が残る.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e5931d1f-0717-4162-890e-455a032ce893', '9eb0cd9a-4661-46ef-bf04-1c7166b2962c', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun dikatakan sebagai rekan dekat, ada batas privasi yang harus dijaga."', '{"romaji":"Shitashii nakama to wa ie, puraibashii ni wa hairyo subeki da.","tokens":["とはいえ、","配慮","だ。","極まりない。","親しい仲間","プライバシーには","すべき","配慮した"],"target_translation":"Meskipun dikatakan sebagai rekan dekat, ada batas privasi yang harus dijaga."}'::jsonb, '["親しい仲間","とはいえ、","プライバシーには","配慮","すべき","だ。"]'::jsonb, NULL, NULL, '親しい仲間とはいえ menegaskan etika menjaga batas privasi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('15155c2e-72c3-4e6c-9e23-30273cb1a10d', '9f948ada-3dcb-4c3c-b9eb-537bb74267e4', NULL, 'listening', 'listening_choice', 'Dengarkan ulasan karier berikut. Apa yang dituntut pada posisi kepala divisi?', '{"options":[{"id":"opt_1","text":"Hanya fokus pada laporan penjualan harian saja"},{"id":"opt_2","text":"Tidak perlu terlibat dalam penyusunan strategi jangka panjang"},{"id":"opt_3","text":"Dituntut menyusun strategi lima tahun ke depan, bukan sekadar kinerja sesaat"},{"id":"opt_4","text":"Menyerahkan seluruh target kinerja kepada tim pemasaran"}],"audio_text":"事業部長ともなると、目先の業績だけでなく五年先を見据えた戦略立案が求められる。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '五年先を見据えた戦略立案 (penyusunan strategi dengan memandang lima tahun ke depan).', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a0017eea-49d6-4540-a91c-dfc89c806044', '9f948ada-3dcb-4c3c-b9eb-537bb74267e4', NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan acara olahraga berikut. Mengapa persiapan dilakukan bertahun-tahun sebelumnya?', '{"options":[{"id":"opt_1","text":"Karena persiapan besar mulai dari infrastruktur transportasi hingga akomodasi sangat dibutuhkan"},{"id":"opt_2","text":"Karena panitia baru dibentuk dua minggu sebelum pembukaan"},{"id":"opt_3","text":"Karena jumlah penonton dibatasi hanya seratus orang"},{"id":"opt_4","text":"Karena seluruh pertandingan diadakan secara daring"}],"audio_text":"国際的な大規模スポーツ大会の開催ともなれば、交通インフラの整備から宿泊施設の確保まで膨大な準備が必要になる。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '交通インフラの整備から宿泊施設の確保まで menunjukkan cakupan persiapan berskala raksasa.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('abf47020-0869-455e-a087-5c54ef28fdb7', '9f948ada-3dcb-4c3c-b9eb-537bb74267e4', NULL, 'listening', 'listening_choice', 'Dengarkan komentar akademisi berikut. Apa yang berubah ketika masuk program doktoral?', '{"options":[{"id":"opt_1","text":"Mahasiswa cukup menghafal buku teks dasar"},{"id":"opt_2","text":"Tidak ada kewajiban menulis karya ilmiah"},{"id":"opt_3","text":"Seluruh penelitian dilakukan sepenuhnya oleh dosen pembimbing"},{"id":"opt_4","text":"Diuji kemampuan menghasilkan temuan baru sendiri, bukan sekadar mempelajari ilmu yang ada"}],"audio_text":"大学院の博士課程ともなると、既存の知識を学ぶのではなく自ら新たな知見を生み出す力が試される。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '自ら新たな知見を生み出す力が試される berarti ''kemampuan melahirkan pengetahuan baru sendiri yang diuji''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('55cec215-5be2-4637-906c-daee432fe790', '9f948ada-3dcb-4c3c-b9eb-537bb74267e4', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 社員数が一万人を超える大企業___、社内コミュニケーションの仕組みづくりが不可欠だ。', '{"options":["ともなると","とはいえ","極まりなく","を余儀なく"],"translation":"Jika sudah perusahaan besar dengan lebih dari sepuluh ribu karyawan, pembangunan sistem komunikasi internal mutlak diperlukan.","sentence_template":"社員数が一万人を超える大企業[blank]、社内コミュニケーションの仕組みづくりが不可欠だ。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, NULL, NULL, '大企業ともなると menyoroti kebutuhan sistemik yang muncul pada skala organisasi besar.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cbf4455a-0546-4f95-9e8e-f6c77beb4105', '9f948ada-3dcb-4c3c-b9eb-537bb74267e4', NULL, 'reading', 'fill_blank', 'Pilih pola yang tepat: 国を代表する外交官___、高い語学力のみならず深い歴史的教養も不可欠である。', '{"options":["ともなれば","に至っては","をもって","なりに"],"translation":"Jika sudah menjadi diplomat yang mewakili negara, bukan hanya kemahiran bahasa tinggi melainkan wawasan sejarah mendalam pun mutlak diperlukan.","sentence_template":"国を代表する外交官[blank]、高い語学力のみならず深い歴史的教養も不可欠である。"}'::jsonb, '{"selected":"ともなれば"}'::jsonb, NULL, NULL, '国を代表する外交官ともなれば menekankan standar tinggi yang menyertai jabatan diplomat.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('55c2ce76-7545-4aef-bf97-a51562fe6682', '9f948ada-3dcb-4c3c-b9eb-537bb74267e4', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 創業百年の老舗___、伝統を守りつつ時代に合わせた革新も続けている。', '{"options":["いかんによらず","に足らず","ともなると","をよそに"],"translation":"Jika sudah toko legendaris berusia seratus tahun, mereka menjaga tradisi sekaligus terus berinovasi mengikuti zaman.","sentence_template":"創業百年の老舗[blank]、伝統を守りつつ時代に合わせた革新も続けている。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, NULL, NULL, '老舗 (shinise: usaha/toko mapan turun-temurun) + ともなると.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3c72e342-97ab-48a8-88ff-7b8b9cfec28b', '9f948ada-3dcb-4c3c-b9eb-537bb74267e4', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah memasuki musim panas yang terik, risiko sengatan panas meningkat drastis."', '{"romaji":"Manatsu to mo naru to, netchuushou no risuku ga kyuugeki ni takamaru.","tokens":["とも","熱中症の","急激に高まる。","高まった。","真夏","なると、","リスクが","とはいえ、"],"target_translation":"Jika sudah memasuki musim panas yang terik, risiko sengatan panas meningkat drastis."}'::jsonb, '["真夏","とも","なると、","熱中症の","リスクが","急激に高まる。"]'::jsonb, NULL, NULL, '真夏ともなると (jika sudah puncak musim panas) sangat alami untuk peringatan kesehatan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('df3622ff-8c0e-46ce-8c03-e7ee7eb770d6', '9f948ada-3dcb-4c3c-b9eb-537bb74267e4', 'd1000019-0000-0000-0000-000000000035', 'listening', 'listening_choice', 'Dengarkan komentar kurator museum. Apa keistimewaan pameran berskala internasional?', '{"options":[{"id":"opt_1","text":"Museum membuka jendela lebar-lebar tanpa pengaturan suhu"},{"id":"opt_2","text":"Untuk pameran yang menampilkan karya seni kelas warisan dunia, pengaturan suhu dan kelembapan dilakukan dengan ketelitian maksimal"},{"id":"opt_3","text":"Karya seni boleh disentuh langsung oleh pengunjung"},{"id":"opt_4","text":"Pameran berlangsung di lapangan terbuka"}],"audio_text":"世界遺産級の美術品を展示する展覧会ともなれば、温度や湿度の管理には細心の注意が払われる。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '細心の注意が払われる berarti perhatian paling cermat diberikan sesuai kelas pamerannya.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ff098c3f-d4e0-4fc2-a2a3-be360c0270f5', 'a30cebbf-ff7a-4e49-bbd2-f4176aabcb08', 'd1000019-0000-0000-0000-000000000031', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dengan demikian, saya menutup presentasi hari ini."', '{"romaji":"Ijou wo mochimashite, honjitsu no happyou wo shuuryou sasete itadakimasu.","display_text":"以上をもちまして、本日の発表を終了させていただきます。","phonetic_breakdown":["i-jou","wo","mo-chi-ma-shi-te","hon-ji-tsu","no","ha-ppyou","wo","shuu-ryou","sa-se-te","i-ta-da-ki-ma-su"]}'::jsonb, '{"expected_transcript":"以上をもちまして、本日の発表を終了させていただきます。"}'::jsonb, NULL, NULL, 'Formula penutup presentasi paling formal dan berwibawa dalam bahasa Jepang bisnis.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('14944c01-fd40-433a-9de4-c1afa317955a', 'a30cebbf-ff7a-4e49-bbd2-f4176aabcb08', 'd1000019-0000-0000-0000-000000000031', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pendaftaran ditutup pada pukul lima sore hari Jumat ini."', '{"romaji":"Konshuu kin''youbi no gogo goji wo motte, oubo wo shimekirimasu.","display_text":"今週金曜日の午後五時をもって、応募を締め切ります。","phonetic_breakdown":["kon-shuu","kin-you-bi","no","go-go","go-ji","wo","mo-tte","ou-bo","wo","shi-me-ki-ri-ma-su"]}'::jsonb, '{"expected_transcript":"今週金曜日の午後五時をもって、応募を締め切ります。"}'::jsonb, NULL, NULL, '締め切ります (menutup pendaftaran) sangat serasi dipasangkan dengan ～をもって.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b2c276b5-6e54-4eb0-8474-c05197eb13b8', 'a30cebbf-ff7a-4e49-bbd2-f4176aabcb08', 'd1000019-0000-0000-0000-000000000031', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan menyampaikan pemberitahuan resmi melalui situs web."', '{"romaji":"Koushiki webusaito de no keisai wo motte, tsuuchi to sasete itadakimasu.","display_text":"公式ウェブサイトでの掲載をもって、通知とさせていただきます。","phonetic_breakdown":["kou-shi-ki","we-bu-sai-to","de","no","kei-sai","wo","mo-tte","tsuu-chi","to","sa-se-te","i-ta-da-ki-ma-su"]}'::jsonb, '{"expected_transcript":"公式ウェブサイトでの掲載をもって、通知とさせていただきます。"}'::jsonb, NULL, NULL, '掲載をもって通知とする berarti ''pemuatan di situs resmi berlaku sebagai pemberitahuan sah''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('abc0f978-6aea-4447-aea7-876c4fed33e7', 'a30cebbf-ff7a-4e49-bbd2-f4176aabcb08', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Terhitung akhir tahun ini, beliau pensiun dari jabatannya."', '{"romaji":"Honnenmatsu wo motte shi wa yakushoku wo tainin sareru.","tokens":["される","とはいえ","をもって","退任","役職を","氏は","本年末","なりに"],"target_translation":"Terhitung akhir tahun ini, beliau pensiun dari jabatannya."}'::jsonb, '["本年末","をもって","氏は","役職を","退任","される"]'::jsonb, NULL, NULL, '本年末をもって (terhitung akhir tahun ini) diikuti bentuk hormat 退任される.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7b567336-0aef-40a8-947b-0ee0c86c74e9', 'a30cebbf-ff7a-4e49-bbd2-f4176aabcb08', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Dengan pembayaran biaya, pendaftaran dianggap sah."', '{"romaji":"Sankahi no nyuukin wo motte touroku kanryou to minasu mono to suru.","tokens":["ばかりに","に至って","参加費の","登録完了","とみなす","ものとする","入金を","もって"],"target_translation":"Dengan pembayaran biaya, pendaftaran dianggap sah."}'::jsonb, '["参加費の","入金を","もって","登録完了","とみなす","ものとする"]'::jsonb, NULL, NULL, 'Kalimat klausul regulasi yang menggabungkan ～をもって dan ～ものとする.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('74ff7c9d-80d0-4c9f-9741-d6e7a516ba05', 'a30cebbf-ff7a-4e49-bbd2-f4176aabcb08', 'd1000019-0000-0000-0000-000000000031', 'writing', 'sentence_builder', 'Susun kalimat: "Kami akan menjawab harapan Anda dengan hasil nyata."', '{"romaji":"Tashika na jisseki wo motte minasama no go-kitai ni okotae shimasu.","tokens":["ながら","確かな","実績","皆様の","を余儀なく","ご期待に","をもって","お応えします"],"target_translation":"Kami akan menjawab harapan Anda dengan hasil nyata."}'::jsonb, '["確かな","実績","をもって","皆様の","ご期待に","お応えします"]'::jsonb, NULL, NULL, '確かな実績をもって berarti ''dengan rekam jejak/hasil yang nyata''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d9577afb-edcb-40ca-8bf9-38d45935ecf4', 'a30cebbf-ff7a-4e49-bbd2-f4176aabcb08', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼の実績___すれば、次期部長に推されるのも当然だ。', '{"options":["をもって","なりに","極まりなく","ずにはおかず"],"translation":"Jika dilihat dari rekam jejak prestasinya, wajar saja bila ia dicalonkan sebagai kepala divisi berikutnya.","sentence_template":"彼の実績[blank]すれば、次期部長に推されるのも当然だ。"}'::jsonb, '{"selected":"をもって"}'::jsonb, NULL, NULL, '～をもってすれば berarti ''jika berdasarkan kemampuan/prestasi tersebut''.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9715c38f-7613-46ed-8e9d-d5a7fc20ffb3', 'a30cebbf-ff7a-4e49-bbd2-f4176aabcb08', 'd1000019-0000-0000-0000-000000000031', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dengan penuh rasa hormat, saya menyampaikan apresiasi atas kerja keras seluruh tim."', '{"romaji":"Keii o motte, chiimu zenin no jinryoku ni kansha no i o hyoushimasu.","display_text":"敬意をもって、チーム全員の尽力に感謝の意を表します。","phonetic_breakdown":["けいいをもって","ちーむぜんいんの","じんりょくに","かんしゃのいを","ひょうします"]}'::jsonb, '{"expected_transcript":"敬意をもって、チーム全員の尽力に感謝の意を表します。"}'::jsonb, NULL, NULL, '敬意をもって (dengan penuh rasa hormat) cocok untuk pidato penghargaan formal.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0ec7728c-7999-423c-a699-daa1f77b0616', 'a3bb02f7-32e6-459d-b134-83c514d9af5d', NULL, 'listening', 'listening_choice', 'Dengarkan kutipan editorial berikut. Mengapa publik baru bereaksi keras sekarang?', '{"options":[{"id":"opt_1","text":"Karena standar keamanan sebelumnya sudah terlalu ketat"},{"id":"opt_2","text":"Karena peringatan berkali-kali sudah langsung ditindaklanjuti sejak awal"},{"id":"opt_3","text":"Karena peninjauan standar baru dimulai setelah kecelakaan besar benar-benar terjadi"},{"id":"opt_4","text":"Karena biaya pemeliharaan fasilitas meningkat drastis"}],"audio_text":"度重なる警告が無視され続け、大規模な事故が発生するに至って、ようやく安全基準の見直しが始まった。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '大規模な事故が発生するに至って、ようやく... menunjukkan kritik bahwa tindakan baru diambil setelah insiden besar terjadi.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e91092ba-4b98-4439-9833-865554c4e0ac', 'a3bb02f7-32e6-459d-b134-83c514d9af5d', NULL, 'listening', 'listening_choice', 'Dengarkan laporan rapat direksi berikut. Apa kesimpulan mengenai proses negosiasi?', '{"options":[{"id":"opt_1","text":"Kedua perusahaan sepakat menandatangani kontrak jangka panjang"},{"id":"opt_2","text":"Negosiasi diperpanjang selama enam bulan lagi"},{"id":"opt_3","text":"Salah satu perusahaan mengakuisisi seluruh saham mitra"},{"id":"opt_4","text":"Tidak tercapai kesepakatan sehingga perundingan kembali ke titik nol"}],"audio_text":"半年以上にわたる協議の末、両社は合意に至らず、提携交渉は白紙に戻された。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '合意に至らず (tidak mencapai kesepakatan) dan 白紙に戻された (dikembalikan ke kertas kosong/titik nol).', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dd8ed004-6b8d-4303-b7b1-b08fb339295c', 'a3bb02f7-32e6-459d-b134-83c514d9af5d', NULL, 'listening', 'listening_choice', 'Dengarkan penjelasan sejarah perusahaan berikut. Apa yang dicakup dalam reformasi tersebut?', '{"options":[{"id":"opt_1","text":"Pembaruan menyeluruh dari alur kerja hingga sistem evaluasi SDM"},{"id":"opt_2","text":"Hanya perubahan nama merek dan logo perusahaan"},{"id":"opt_3","text":"Penutupan seluruh cabang di luar negeri saja"},{"id":"opt_4","text":"Pengurangan jam kerja karyawan tanpa mengubah sistem evaluasi"}],"audio_text":"創業以来の危機に直面し、業務フローから人事評価制度に至るまで全面的な刷新が行われた。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '業務フローから人事評価制度に至るまで berarti ''mulai dari alur kerja hingga sistem penilaian SDM''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4a416cfa-b371-4912-8fb4-3734b3055ca7', 'a3bb02f7-32e6-459d-b134-83c514d9af5d', NULL, 'reading', 'fill_blank', 'Lengkapi teks berita berikut: 交渉が決裂___、労使双方は法的措置を検討し始めた。', '{"options":["するに先立ち","するに至り","するに際し","するに連れ"],"translation":"Setelah perundingan mencapai kebuntuan total, pihak serikat pekerja dan manajemen mulai mempertimbangkan jalur hukum.","sentence_template":"交渉が決裂[blank]、労使双方は法的措置を検討し始めた。"}'::jsonb, '{"selected":"するに至り"}'::jsonb, NULL, NULL, 'するに至り adalah bentuk bahasa tulis (ren''youkei) dari するに至って yang sangat sering muncul dalam berita formal.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a71d658b-6889-4bff-99f3-5d873be83aaa', 'a3bb02f7-32e6-459d-b134-83c514d9af5d', NULL, 'reading', 'fill_blank', 'Pilih ungkapan yang tepat: 細かい配線の配置___、設計図には一切の妥協が見られない。', '{"options":["をよそに","に至っては","に至るまで","を皮切りに"],"translation":"Hingga detail penempatan kabel yang sangat halus sekalipun, tidak tampak sedikit pun kompromi pada cetak birunya.","sentence_template":"細かい配線の配置[blank]、設計図には一切の妥協が見られない。"}'::jsonb, '{"selected":"に至るまで"}'::jsonb, NULL, NULL, '～に至るまで menekankan ketelitian sampai ke bagian paling kecil sekalipun.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('aec380a5-dc41-4ebd-b806-407a92307df9', 'a3bb02f7-32e6-459d-b134-83c514d9af5d', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluatif berikut: 信頼関係が完全に失われた___、共同研究の継続は困難である。', '{"options":["今に先立って","今をめぐって","今に至っては","今に沿って"],"translation":"Kini setelah hubungan saling percaya hilang sepenuhnya, kelanjutan riset bersama menjadi sulit.","sentence_template":"信頼関係が完全に失われた[blank]、共同研究の継続は困難である。"}'::jsonb, '{"selected":"今に至っては"}'::jsonb, NULL, NULL, '～た今に至っては menegaskan bahwa kondisi saat ini sudah mencapai titik yang menyulitkan kelanjutan.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('417977ed-94dc-43a8-a98a-792c3aa18d7a', 'a3bb02f7-32e6-459d-b134-83c514d9af5d', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Dari persiapan hingga pelaksanaan acara, semua proses berjalan tanpa hambatan."', '{"romaji":"Junbi kara jisshi ni itaru made, subete no koutei ga juncho ni susunda.","tokens":["実施","すべての工程が","進んだ。","進む","準備から","に至るまで、","順調に","に至って、"],"target_translation":"Dari persiapan hingga pelaksanaan acara, semua proses berjalan tanpa hambatan."}'::jsonb, '["準備から","実施","に至るまで、","すべての工程が","順調に","進んだ。"]'::jsonb, NULL, NULL, 'AからBに至るまで mencakup seluruh rentang proses dari awal hingga akhir.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('88a04111-1f0c-4f21-88fd-e29a398e6dec', 'a3bb02f7-32e6-459d-b134-83c514d9af5d', 'd1000019-0000-0000-0000-000000000028', 'listening', 'listening_choice', 'Dengarkan wawancara penulis buku. Kapan beliau memutuskan menulis memoar tersebut?', '{"options":[{"id":"opt_1","text":"Saat baru mulai bekerja di usia dua puluh tahun"},{"id":"opt_2","text":"Saat masih duduk di bangku kuliah"},{"id":"opt_3","text":"Saat memasuki masa pensiun dan menengok kembali perjalanan hidupnya"},{"id":"opt_4","text":"Setelah buku tersebut diterjemahkan ke bahasa asing"}],"audio_text":"定年退職を迎えて自身の歩みを振り返るに至り、次世代に伝えたい経験を一冊にまとめることにした。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '振り返るに至り menandai titik balik refleksi kehidupan saat pensiun.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4ea8a9d9-8323-4501-a001-0d054fce5776', 'a72239bc-39d2-4fb9-bb1d-5b8039641e93', 'd1000019-0000-0000-0000-000000000035', 'listening', 'listening_choice', 'Dengarkan komentar direktur keamanan. Apa standar untuk konferensi tingkat tinggi internasional?', '{"options":[{"id":"opt_1","text":"Persiapan pengamanan untuk KTT internasional yang dihadiri para kepala negara sudah disiapkan matang sejak beberapa bulan sebelumnya"},{"id":"opt_2","text":"KTT internasional hanya dijaga oleh dua petugas keamanan"},{"id":"opt_3","text":"Persiapan pengamanan baru dimulai satu jam sebelum acara"},{"id":"opt_4","text":"KTT internasional selalu diadakan secara daring tanpa pengamanan"}],"audio_text":"各国首脳が一堂に会する国際サミットともなると、警備体制は数ヶ月前から万全を期して準備されます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '国際サミットともなると menjelaskan standar pengamanan luar biasa sesuai skalanya.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7d52bfb2-e721-46c0-94ea-eb1c074c3495', 'a72239bc-39d2-4fb9-bb1d-5b8039641e93', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah menjadi atlet nasional, menjaga pola makan sehari-hari pun bagian dari pekerjaan."', '{"romaji":"Daihyou senshu to mo nareba, shokuji kanri mo juuyou na shigoto da.","tokens":["とも","日々の食事管理も","仕事だ。","仕事だった。","代表選手","なれば、","重要な","なりに、"],"target_translation":"Jika sudah menjadi atlet nasional, menjaga pola makan sehari-hari pun bagian dari pekerjaan."}'::jsonb, '["代表選手","とも","なれば、","日々の食事管理も","重要な","仕事だ。"]'::jsonb, NULL, NULL, '代表選手ともなれば menyoroti kedisiplinan profesional seorang atlet timnas.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('32cef526-dc2f-4f26-8fb2-d33bc1fce15f', 'a72239bc-39d2-4fb9-bb1d-5b8039641e93', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 創業百年の老舗___、伝統を守りつつ革新を続ける重圧も大きい。', '{"options":["ともなると","をもって","を余儀なくされ","極まりない"],"translation":"Jika sudah menjadi perusahaan mapan berusia seratus tahun, tekanan untuk menjaga tradisi sambil terus berinovasi pun besar.","sentence_template":"創業百年の老舗[blank]、伝統を守りつつ革新を続ける重圧も大きい。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, NULL, NULL, '老舗ともなると menunjukkan beban sekaligus kehormatan status perusahaan berusia seabad.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f835679e-4a3d-4066-a494-f2fb881164a5', 'a72239bc-39d2-4fb9-bb1d-5b8039641e93', 'd1000019-0000-0000-0000-000000000035', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah mengelola tim beranggotakan lima puluh orang, pendelegasian tugas menjadi kunci."', '{"romaji":"Gojuunin kibo no chiimu o hikiiru tachiba to mo naru to, kengen ijou ga kagi ni narimasu.","display_text":"五十人規模のチームを率いる立場ともなると、権限委譲が鍵になります。","phonetic_breakdown":["ごじゅうにんきぼの","ちーむをひきいる","たちばともなると","けんげんいじょうが","かぎになります"]}'::jsonb, '{"expected_transcript":"五十人規模のチームを率いる立場ともなると、権限委譲が鍵になります。"}'::jsonb, NULL, NULL, '権限委譲 (pendelegasian wewenang) adalah kosakata manajemen tingkat N1.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bbfb81b1-5e59-462c-a715-9b13664c5ca4', 'a72239bc-39d2-4fb9-bb1d-5b8039641e93', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 標高三千メートル級の登山___、夏場でも防寒具の携行が欠かせない。', '{"options":["ともなると","に至って","に足る","ずにはおかない"],"translation":"Jika sudah pendakian gunung kelas ketinggian 3.000 meter, membawa pakaian hangat mutlak diperlukan meski di musim panas.","sentence_template":"標高三千メートル級の登山[blank]、夏場でも防寒具の携行が欠かせない。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, NULL, NULL, '標高三千メートル級の登山ともなると menekankan syarat keselamatan khusus level ekstrem.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('30ed3d9f-993c-4844-bb0e-e62b56e79271', 'a72239bc-39d2-4fb9-bb1d-5b8039641e93', 'd1000019-0000-0000-0000-000000000035', 'listening', 'listening_choice', 'Dengarkan ulasan pengamat properti. Apa ciri gedung pencakar langit di pusat Tokyo?', '{"options":[{"id":"opt_1","text":"Gedung pencakar langit di pusat kota dibangun tanpa standar tahan gempa"},{"id":"opt_2","text":"Semua gedung di pusat kota hanya setinggi dua lantai"},{"id":"opt_3","text":"Gedung pencakar langit tidak memperhatikan efisiensi energi"},{"id":"opt_4","text":"Jika sudah gedung pencakar langit di lokasi premium pusat kota, struktur peredam gempa mutakhir dan performa ramah lingkungan menjadi standar baku"}],"audio_text":"都心の一等地に建つ超高層ビルともなれば、最先端の免震構造と環境性能が標準仕様となっている。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '超高層ビルともなれば menunjukkan ekspektasi spesifikasi kelas atas.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f3d36121-f12e-4f78-acd6-afcdf99cb844', 'a72239bc-39d2-4fb9-bb1d-5b8039641e93', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah menjadi pemimpin proyek global, kemampuan negosiasi lintas budaya sangat dibutuhkan."', '{"romaji":"Guroobaru anken no riidaa to mo nareba, ibunka koushouryoku ga fukaketsu da.","tokens":["リーダー","異文化交渉力が","だ。","不可欠だった。","グローバル案件の","ともなれば、","不可欠","とはいえ、"],"target_translation":"Jika sudah menjadi pemimpin proyek global, kemampuan negosiasi lintas budaya sangat dibutuhkan."}'::jsonb, '["グローバル案件の","リーダー","ともなれば、","異文化交渉力が","不可欠","だ。"]'::jsonb, NULL, NULL, 'リーダーともなれば menegaskan kompetensi kunci bagi posisi pimpinan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2f661c00-4446-4c1e-bbff-030c2e98d839', 'a72239bc-39d2-4fb9-bb1d-5b8039641e93', 'd1000019-0000-0000-0000-000000000035', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjadi perusahaan terbuka, tanggung jawab keterbukaan informasi kepada investor jauh lebih ketat."', '{"romaji":"Joujou kigyou to mo naru to, toushika e no jouhou kaiji sekinin ga issou kibishiku narimasu.","display_text":"上場企業ともなると、投資家への情報開示責任が一層厳しくなります。","phonetic_breakdown":["じょうじょうきぎょう","ともなると","とうしかへの","じょうほうかいじせきにんが","いっそうきびしくなります"]}'::jsonb, '{"expected_transcript":"上場企業ともなると、投資家への情報開示責任が一層厳しくなります。"}'::jsonb, NULL, NULL, '上場企業ともなると (jika sudah menjadi emiten/perusahaan terbuka) sangat lazim di wacana bisnis N1.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ce260340-1451-429c-be7c-838aa361bab9', 'aaabcc4d-c6be-423c-9d71-53aeda903e81', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Lengkapi kalimat refleksi berikut: 新人として未熟な点も多いが、今は私___最善を尽くしている。', '{"options":["なりに","をもって","に至って","極まりなく"],"translation":"Sebagai pendatang baru masih banyak kekurangan, tetapi sekarang saya berusaha semaksimal mungkin dengan cara saya sendiri.","sentence_template":"新人として未熟な点も多いが、今は私[blank]最善を尽くしている。"}'::jsonb, '{"selected":"なりに"}'::jsonb, NULL, NULL, 'Kata benda + なりに menyatakan ''sesuai dengan kapasitas/posisi/caranya sendiri''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('917bc60b-3252-4a4d-a9af-d6c84b2111d6', 'aaabcc4d-c6be-423c-9d71-53aeda903e81', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Pilih bentuk yang tepat sebelum kata benda: 子どもたちにも、子ども___悩みや葛藤があるものだ。', '{"options":["なりの","なりに","ながらの","ならではの"],"translation":"Anak-anak pun memiliki kekhawatiran dan pergulatan batin tersendiri sesuai dunia anak-anak.","sentence_template":"子どもたちにも、子ども[blank]悩みや葛藤があるものだ。"}'::jsonb, '{"selected":"なりの"}'::jsonb, NULL, NULL, 'Ketika memodifikasi kata benda (悩みや葛藤), gunakan bentuk ～なりの.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f2a97028-c1a6-457c-87eb-a157aa50c1b8', 'aaabcc4d-c6be-423c-9d71-53aeda903e81', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan pola yang benar: 収入が限られているのだから、今の生活水準___やりくりするしかない。', '{"options":["なりに","をよそに","に足らず","とはいえ"],"translation":"Karena penghasilan terbatas, tidak ada pilihan selain mengatur keuangan sesuai standar hidup sekarang.","sentence_template":"収入が限られているのだから、今の生活水準[blank]やりくりするしかない。"}'::jsonb, '{"selected":"なりに"}'::jsonb, NULL, NULL, '生活水準なりに berarti ''sesuai dengan tingkat/standar kehidupan saat ini''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0a56ad2d-535d-4e24-a8a0-0abc353eeb32', 'aaabcc4d-c6be-423c-9d71-53aeda903e81', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Dia pun berusaha memikirkan masa depan tim dengan caranya sendiri."', '{"romaji":"Kare mo kare nari ni chiimu no shourai wo kangaete iru.","tokens":["彼","考えている","チームの","将来を","彼も","なりに","をもって","極まりない"],"target_translation":"Dia pun berusaha memikirkan masa depan tim dengan caranya sendiri."}'::jsonb, '["彼も","彼","なりに","チームの","将来を","考えている"]'::jsonb, NULL, NULL, 'Pengulangan 彼も彼なりに sangat idiomatis untuk menunjukkan empati bahwa dia pun berusaha sesuai kapasitasnya.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bae04600-b8d0-4666-95a3-bab3d6470ddc', 'aaabcc4d-c6be-423c-9d71-53aeda903e81', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Perusahaan kecil memiliki keunggulan tersendiri yang sesuai skalanya."', '{"romaji":"Chuushou kigyou ni wa chuushou kigyou nari no tsuyomi ga aru mono da.","tokens":["なりの","ある","ながら","中小企業には","中小企業","に至って","ものだ","強みが"],"target_translation":"Perusahaan kecil memiliki keunggulan tersendiri yang sesuai skalanya."}'::jsonb, '["中小企業には","中小企業","なりの","強みが","ある","ものだ"]'::jsonb, NULL, NULL, 'XにはXなりのYがある berarti ''X memiliki Y tersendiri yang sesuai dengan sifat/skalanya''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d86c15a8-1956-4149-a5f3-8085681ffcf4', 'aaabcc4d-c6be-423c-9d71-53aeda903e81', 'd1000019-0000-0000-0000-000000000033', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya telah menyusun usulan ini sesuai kemampuan saya sendiri."', '{"romaji":"Fujuubun na ten mo arimasu ga, jibun nari ni teian wo matomete mimashita.","display_text":"不十分な点もありますが、自分なりに提案をまとめてみました。","phonetic_breakdown":["fu-juu-bun","na","ten","mo","a-ri-ma-su","ga","ji-bun","na-ri","ni","tei-an","wo","ma-to-me-te","mi-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"不十分な点もありますが、自分なりに提案をまとめてみました。"}'::jsonb, NULL, NULL, '自分なりに (dengan cara/kapasitas saya sendiri) bernuansa rendah hati namun sungguh-sungguh dalam rapat bisnis.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0303a5d5-5064-48a3-8bf4-ec43ade2c944', 'aaabcc4d-c6be-423c-9d71-53aeda903e81', 'd1000019-0000-0000-0000-000000000033', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa makna utama dari ～なりに di sini?', '{"options":[{"id":"opt_1","text":"Pihak lawan pasti memiliki situasi/alasannya sendiri sehingga tidak baik menyalahkan secara sepihak"},{"id":"opt_2","text":"Pihak lawan tidak punya alasan apa pun"},{"id":"opt_3","text":"Kita harus menyalahkan pihak lawan sekeras mungkin"},{"id":"opt_4","text":"Situasi kedua pihak persis sama"}],"audio_text":"相手にも相手なりの事情があるはずだから、一方的に責めるのは良くない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '相手なりの事情 menekankan empati terhadap keadaan khusus yang dimiliki pihak lain.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f70de5cb-49db-4366-a8dc-53798a7629c6', 'aaabcc4d-c6be-423c-9d71-53aeda903e81', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 初心者には初心者___上達する楽しみがある。', '{"options":["なりの","なりに","をもって","とはいえ"],"translation":"Bagi pemula, ada kesenangan tersendiri dalam berkembang sesuai tahap pemula.","sentence_template":"初心者には初心者[blank]上達する楽しみがある。"}'::jsonb, '{"selected":"なりの"}'::jsonb, NULL, NULL, 'Sebelum frasa nominal 上達する楽しみ, gunakan bentuk ～なりの.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('98554845-aab8-466d-823d-49a25fd99f97', 'ab62f83f-ee2b-4d66-aaa8-ab199cc44723', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Pilih pola yang tepat: 主要取引先の倒産により、当社も資金計画の大幅な修正___。', '{"options":["を前提とした","をものともしなかった","を余儀なくされた","を契機とした"],"translation":"Akibat kebangkrutan mitra bisnis utama, perusahaan kami pun terpaksa merevisi besar-besaran rencana keuangan.","sentence_template":"主要取引先の倒産により、当社も資金計画の大幅な修正[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, NULL, NULL, 'Kebangkrutan mitra utama adalah faktor eksternal yang memaksa revisi besar rencana keuangan (修正を余儀なくされた).', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b66c01f0-babb-404e-9b44-c64eeff9ef28', 'ab62f83f-ee2b-4d66-aaa8-ab199cc44723', 'd1000019-0000-0000-0000-000000000029', 'reading', 'fill_blank', 'Lengkapi kalimat formal berikut: 予算の大幅削減が、研究チームに実験規模の縮小___。', '{"options":["に至った","を余儀なくされた","に足った","を余儀なくさせた"],"translation":"Pemangkasan anggaran besar-besaran memaksa tim peneliti memperkecil skala eksperimen.","sentence_template":"予算の大幅削減が、研究チームに実験規模の縮小[blank]。"}'::jsonb, '{"selected":"を余儀なくさせた"}'::jsonb, NULL, NULL, 'Subjek penyebab (予算の大幅削減が) menuntut bentuk kausatif ～を余儀なくさせた.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f3108af9-4191-428f-a8a2-d3456cd58b0e', 'ab62f83f-ee2b-4d66-aaa8-ab199cc44723', 'd1000019-0000-0000-0000-000000000029', 'listening', 'listening_choice', 'Dengarkan berita berikut. Mengapa festival tradisional itu dibatalkan?', '{"options":[{"id":"opt_1","text":"Jumlah peserta tahun ini jauh lebih sedikit dari target"},{"id":"opt_2","text":"Dinilai sulit menjamin keselamatan sehingga terpaksa dibatalkan"},{"id":"opt_3","text":"Panitia ingin menggantinya dengan konser musik modern"},{"id":"opt_4","text":"Lokasi festival sedang digunakan untuk acara olahraga"}],"audio_text":"安全確保が困難と判断されたため、今年の伝統祭りはやむを得ず中止を余儀なくされた。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '安全確保が困難と判断されたため (karena dinilai sulit menjamin keamanan) menyebabkan 中止を余儀なくされた.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b38b4341-1b31-4f2c-ac3f-535d127dd09a', 'ab62f83f-ee2b-4d66-aaa8-ab199cc44723', 'd1000019-0000-0000-0000-000000000029', 'listening', 'listening_choice', 'Dengarkan ulasan industri berikut. Apa situasi yang dihadapi perusahaan percetakan lokal?', '{"options":[{"id":"opt_1","text":"Mereka menerima pesanan buku cetak terbanyak sepanjang sejarah"},{"id":"opt_2","text":"Mereka mendapat subsidi penuh dari pemerintah untuk membeli mesin cetak baru"},{"id":"opt_3","text":"Digitalisasi pesat memaksa mereka mengubah lini bisnis"},{"id":"opt_4","text":"Mereka menolak menggunakan komputer di seluruh kantor"}],"audio_text":"デジタル化の急速な進展により、地域の老舗印刷会社は事業転換を余儀なくされている。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '事業転換を余儀なくされている berarti ''terpaksa mengalihkan/mengubah bidang usaha''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e517ae4b-5d52-4e7c-a37a-d5cdd4126d33', 'ab62f83f-ee2b-4d66-aaa8-ab199cc44723', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Akibat kekeringan berkepanjangan, para petani terpaksa membatasi penggunaan air."', '{"romaji":"Nagabiku kanbatsu de nouka wa shusui seigen wo yoginaku sareta.","tokens":["干ばつで","取水制限","ながら","長引く","を余儀なく","農家は","に至っては","された"],"target_translation":"Akibat kekeringan berkepanjangan, para petani terpaksa membatasi penggunaan air."}'::jsonb, '["長引く","干ばつで","農家は","取水制限","を余儀なく","された"]'::jsonb, NULL, NULL, '長引く干ばつ (kekeringan berkepanjangan) memaksa 取水制限 (pembatasan pengambilan air).', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('15f753c9-e12c-4611-b636-ed2f26ace8fe', 'ab62f83f-ee2b-4d66-aaa8-ab199cc44723', 'd1000019-0000-0000-0000-000000000029', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami mohon maaf karena terpaksa menunda jadwal pengiriman."', '{"romaji":"Haisou yotei no enki wo yoginaku saremashita koto wo, fukaku owabi moushiagemasu.","display_text":"配送予定の延期を余儀なくされましたことを、深くお詫び申し上げます。","phonetic_breakdown":["hai-sou","yo-tei","no","en-ki","wo","yo-gi-na-ku","sa-re-ma-shi-ta","ko-to","wo","fu-ka-ku","o-wa-bi","mou-shi-a-ge-ma-su"]}'::jsonb, '{"expected_transcript":"配送予定の延期を余儀なくされましたことを、深くお詫び申し上げます。"}'::jsonb, NULL, NULL, 'Penggunaan ～を余儀なくされました dalam surat atau pernyataan permintaan maaf resmi perusahaan.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bab1bfbe-6695-49aa-ad21-093c108fc791', 'ab62f83f-ee2b-4d66-aaa8-ab199cc44723', 'd1000019-0000-0000-0000-000000000029', 'listening', 'listening_choice', 'Dengarkan kutipan berita internasional. Apa konsekuensi sanksi dagang tersebut?', '{"options":[{"id":"opt_1","text":"UKM eksportir mendapatkan keuntungan berlipat ganda"},{"id":"opt_2","text":"Tarif bea masuk dihapuskan sepenuhnya"},{"id":"opt_3","text":"UKM yang bergantung pada ekspor terpaksa memindahkan basis produksinya akibat kenaikan tarif besar"},{"id":"opt_4","text":"Semua pabrik di dalam negeri menambah jam kerja"}],"audio_text":"関税の大幅引き上げを受け、輸出依存度の高い中小企業は苦境に立たされ、生産拠点の移転を余儀なくされている。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '生産拠点の移転を余儀なくされている berarti terpaksa merelokasi basis produksi.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8f3fd656-3d69-4de3-a3e4-812370f3a8b9', 'ab62f83f-ee2b-4d66-aaa8-ab199cc44723', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Cedera serius di tengah musim memaksa sang kapten absen jangka panjang."', '{"romaji":"Shinkoku na kega ni yori, kyaputen wa chouki ridatsu o yoginaku sareta.","tokens":["キャプテンは","を","された。","をもって、","深刻な怪我により、","長期離脱","余儀なく","させた。"],"target_translation":"Cedera serius di tengah musim memaksa sang kapten absen jangka panjang."}'::jsonb, '["深刻な怪我により、","キャプテンは","長期離脱","を","余儀なく","された。"]'::jsonb, NULL, NULL, '長期離脱を余儀なくされた (terpaksa absen jangka panjang) lazim dalam liputan olahraga N1.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d03c222b-678c-4bf6-a329-cb286f90cb7a', 'ab84c9dd-65bb-4b46-b59a-0235b5e1a934', NULL, 'reading', 'fill_blank', 'Pilih istilah hukum yang tepat: 利用___に違反した場合、アカウントが停止されることがある。', '{"options":["規約","要約","予約","節約"],"translation":"Apabila melanggar ketentuan penggunaan, akun dapat ditangguhkan.","sentence_template":"利用[blank]に違反した場合、アカウントが停止されることがある。"}'::jsonb, '{"selected":"規約"}'::jsonb, NULL, NULL, '利用規約 (riyou kiyaku) adalah padanan resmi untuk ''Terms of Service / Ketentuan Penggunaan''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('93c81aae-40c1-4297-965d-8db1c5c43c7f', 'ab84c9dd-65bb-4b46-b59a-0235b5e1a934', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat kepatuhan korporasi berikut: 重大な規定違反に対しては、厳正な___が科される。', '{"options":["処分","成分","配分","気分"],"translation":"Terhadap pelanggaran aturan berat, sanksi yang tegas akan dijatuhkan.","sentence_template":"重大な規定違反に対しては、厳正な[blank]が科される。"}'::jsonb, '{"selected":"処分"}'::jsonb, NULL, NULL, '厳正な処分が科される berarti ''dijatuhi sanksi/tindakan disipliner yang tegas dan adil''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d3e50b52-0217-40cb-af54-93cb0c02ec91', 'ab84c9dd-65bb-4b46-b59a-0235b5e1a934', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk prinsip seleksi: 採用試験は、すべての応募者に対して___に行われなければならない。', '{"options":["不均","恣意","偏狭","公平"],"translation":"Ujian rekrutmen harus dilaksanakan secara adil terhadap seluruh pelamar.","sentence_template":"採用試験は、すべての応募者に対して[blank]に行われなければならない。"}'::jsonb, '{"selected":"公平"}'::jsonb, NULL, NULL, '公平に (kouhei ni) berarti ''secara adil dan tidak memihak''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fdb6435d-bfaa-490c-8895-04d35d232130', 'ab84c9dd-65bb-4b46-b59a-0235b5e1a934', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman kepatuhan perusahaan berikut. Kewajiban apa yang berlaku bagi seluruh pegawai?', '{"options":[{"id":"opt_1","text":"Mempublikasikan seluruh data internal di media sosial"},{"id":"opt_2","text":"Menjaga kerahasiaan informasi sensitif pekerjaan agar tidak bocor ke pihak ketiga"},{"id":"opt_3","text":"Hanya manajer senior yang terikat kewajiban kerahasiaan"},{"id":"opt_4","text":"Menyimpan dokumen rahasia di komputer pribadi di rumah"}],"audio_text":"全社員は、業務上知り得た機密情報を第三者に漏洩しない守秘義務を負う。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '守秘義務を負う (shuhi gimu wo ou) berarti ''memikul kewajiban menjaga kerahasiaan (NDA)''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('86c55e6b-d7bd-4a31-886f-d5a70a9d12bc', 'ab84c9dd-65bb-4b46-b59a-0235b5e1a934', NULL, 'listening', 'listening_choice', 'Dengarkan ketentuan seleksi beasiswa berikut. Bagaimana proses penilaian dilakukan?', '{"options":[{"id":"opt_1","text":"Dipilih secara acak melalui undian terbuka"},{"id":"opt_2","text":"Dinilai hanya berdasarkan urutan waktu pengiriman"},{"id":"opt_3","text":"Dinilai secara ketat oleh komite penyeleksi yang mencakup pakar eksternal"},{"id":"opt_4","text":"Semua pendaftar otomatis dinyatakan lulus tanpa seleksi"}],"audio_text":"提出された書類は、外部の有識者を含む審査委員会によって厳格に評価されます。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '審査委員会によって厳格に評価されます berarti ''dievaluasi secara ketat oleh komite seleksi''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8479a73a-3349-4579-b24a-ee33a642982d', 'ab84c9dd-65bb-4b46-b59a-0235b5e1a934', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Semua orang setara di hadapan hukum."', '{"romaji":"Hou no moto ni oite, subete no hito wa byoudou ni atsukaware nakereba naranai.","display_text":"法の下において、すべての人は平等に扱われなければならない。","phonetic_breakdown":["hou","no","mo-to","ni","o-i-te","su-be-te","no","hi-to","wa","byou-dou","ni","a-tsu-ka-wa-re","na-ke-re-ba","na-ra-nai"]}'::jsonb, '{"expected_transcript":"法の下において、すべての人は平等に扱われなければならない。"}'::jsonb, NULL, NULL, '法の下の平等 adalah prinsip fundamental hukum modern dalam bahasa Jepang formal.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8e561468-172c-4ef8-a33a-f3290b40be13', 'ab84c9dd-65bb-4b46-b59a-0235b5e1a934', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Pilih kosakata hukum/bisnis N1 yang tepat: 理由のいかんによらず、契約違反には___が科される。', '{"options":["違約金","奨学金","祝儀","補助金"],"translation":"Tanpa memandang alasan apa pun, pelanggaran kontrak akan dikenai denda/penalti.","sentence_template":"理由のいかんによらず、契約違反には[blank]が科される。"}'::jsonb, '{"selected":"違約金"}'::jsonb, NULL, NULL, '違約金 (iyakukin = denda pelanggaran kontrak) berpasangan sangat erat dengan klausul いかんによらず.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('060684a6-f3cc-4ad6-849a-28e3032e58a6', 'ab84c9dd-65bb-4b46-b59a-0235b5e1a934', 'd1000019-0000-0000-0000-000000000036', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang hasil pemilihan, kami akan menghormati keputusan suara terbanyak."', '{"romaji":"Touhyou kekka no ikan ni yorazu, minshuteki na kettei o sonchou itashimasu.","display_text":"投票結果のいかんによらず、民主的な決定を尊重いたします。","phonetic_breakdown":["とうひょうけっかの","いかんによらず","みんしゅてきなけっていを","そんちょういたします"]}'::jsonb, '{"expected_transcript":"投票結果のいかんによらず、民主的な決定を尊重いたします。"}'::jsonb, NULL, NULL, '投票結果のいかんによらず mencerminkan sikap kenegarawanan yang formal.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('488d2802-1422-4524-80f8-790951375b27', 'ab9d0995-cc4d-4f5f-ac47-a74e01f016a9', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Pilih pola yang tepat: グローバルに展開する企業___、各国の法規制や環境基準への対応が不可欠だ。', '{"options":["とはいえ","なりに","をもって","ともなると"],"translation":"Jika sudah menjadi perusahaan yang berekspansi secara global, kepatuhan terhadap regulasi hukum dan standar lingkungan tiap negara mutlak diperlukan.","sentence_template":"グローバルに展開する企業[blank]、各国の法規制や環境基準への対応が不可欠だ。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, NULL, NULL, 'グローバルに展開する企業ともなると menekankan kompleksitas standar global.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('04b9e2fe-e2b9-4e55-bea5-4dad4a6890e2', 'ab9d0995-cc4d-4f5f-ac47-a74e01f016a9', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 一流の通訳者___、言葉の置き換えだけでなく話者の意図や文化的背景まで的確に伝える。', '{"options":["に至っては","ずにはおかない","極まりなく","ともなれば"],"translation":"Kalau sudah juru bahasa kelas satu, bukan hanya menerjemahkan kata tetapi juga menyampaikan maksud pembicara dan latar budaya secara tepat.","sentence_template":"一流の通訳者[blank]、言葉の置き換えだけでなく話者の意図や文化的背景まで的確に伝える。"}'::jsonb, '{"selected":"ともなれば"}'::jsonb, NULL, NULL, '一流の通訳者ともなれば menggambarkan standar keunggulan profesional puncak.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('581f69fe-721b-41b6-925a-6a67f034bd33', 'ab9d0995-cc4d-4f5f-ac47-a74e01f016a9', 'd1000019-0000-0000-0000-000000000035', 'listening', 'listening_choice', 'Dengarkan ulasan bisnis berikut. Apa tantangan yang dihadapi saat skala perusahaan membesar?', '{"options":[{"id":"opt_1","text":"Semua cabang luar negeri harus menggunakan satu zona waktu yang sama"},{"id":"opt_2","text":"Diperlukan tata kelola fleksibel yang memperhitungkan perbedaan zona waktu dan kebiasaan bisnis"},{"id":"opt_3","text":"Perusahaan sebaiknya menutup seluruh cabang di luar negeri"},{"id":"opt_4","text":"Tidak ada perbedaan kebiasaan bisnis antarnegara"}],"audio_text":"海外拠点が十カ国以上ともなると、時差や商習慣の違いを踏まえた柔軟なガバナンスが問われる。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '柔軟なガバナンスが問われる berarti ''tata kelola yang fleksibel menjadi ujian/tuntutan utama''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('561992f4-bf17-4431-931f-a357af4aec8c', 'ab9d0995-cc4d-4f5f-ac47-a74e01f016a9', 'd1000019-0000-0000-0000-000000000035', 'listening', 'listening_choice', 'Dengarkan komentar kritikus arsitektur berikut. Apa keistimewaan gedung pencakar langit modern?', '{"options":[{"id":"opt_1","text":"Gedung tersebut dibangun tanpa memperhatikan ketahanan gempa"},{"id":"opt_2","text":"Biaya pembangunannya sama dengan rumah tinggal biasa"},{"id":"opt_3","text":"Teknologi rekayasa termutakhir dikerahkan untuk desain tahan gempa dan penahan tekanan angin"},{"id":"opt_4","text":"Gedung tersebut hanya membutuhkan waktu satu bulan untuk selesai"}],"audio_text":"高さ三百メートルを超える超高層ビルともなれば、耐震設計と風圧対策に最先端の工学技術が結集される。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '最先端の工学技術が結集される berarti ''teknologi rekayasa paling mutakhir dihimpun/dikerahkan''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4a50dc7c-5cb7-4f5b-8c49-c4951990c913', 'ab9d0995-cc4d-4f5f-ac47-a74e01f016a9', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah menjadi perwakilan negara, setiap sikap menjadi sorotan."', '{"romaji":"Kuni no daihyou to mo naru to hitotsu hitotsu no furumai ga chuumoku sareru.","tokens":["振る舞いが","代表","を余儀なく","なりに","一つ一つの","ともなると","注目される","国の"],"target_translation":"Jika sudah menjadi perwakilan negara, setiap sikap menjadi sorotan."}'::jsonb, '["国の","代表","ともなると","一つ一つの","振る舞いが","注目される"]'::jsonb, NULL, NULL, '振る舞いが注目される berarti ''setiap tindak-tanduk menjadi pusat perhatian''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0008a06d-cc68-4e42-9d10-ac13cb90c3ca', 'ab9d0995-cc4d-4f5f-ac47-a74e01f016a9', 'd1000019-0000-0000-0000-000000000035', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah pada tahap perjanjian internasional, satu kata pun ditelaah dengan saksama."', '{"romaji":"Kokusai jouyaku no teiketsu to mo nareba, ichiji ikku made shinchou ni seisa sareru.","display_text":"国際条約の締結ともなれば、一字一句まで慎重に精査される。","phonetic_breakdown":["ko-ku-sai","jou-ya-ku","no","tei-ke-tsu","to","mo","na-re-ba","i-chi-ji","i-kku","ma-de","shin-chou","ni","sei-sa","sa-re-ru"]}'::jsonb, '{"expected_transcript":"国際条約の締結ともなれば、一字一句まで慎重に精査される。"}'::jsonb, NULL, NULL, '一字一句まで精査される berarti ''diteliti secara saksama hingga setiap huruf dan kata''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5236e3d5-5389-4d00-9e91-b7653f900cd6', 'ab9d0995-cc4d-4f5f-ac47-a74e01f016a9', 'd1000019-0000-0000-0000-000000000035', 'listening', 'listening_choice', 'Dengarkan wawancara direktur bank. Apa yang ia katakan tentang transaksi bernilai triliunan?', '{"options":[{"id":"opt_1","text":"Transaksi bernilai triliunan yen selalu ditangani satu staf saja"},{"id":"opt_2","text":"Bank tidak pernah bekerja sama dalam pinjaman internasional"},{"id":"opt_3","text":"Jika sudah pembiayaan internasional berskala triliunan yen, beberapa bank berkolaborasi membagi risiko alih-alih satu lembaga saja"},{"id":"opt_4","text":"Pinjaman internasional tidak memiliki risiko sama sekali"}],"audio_text":"兆円単位の国際融資ともなると、単一の金融機関ではなく複数の銀行が協調してリスクを分担する。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '協調してリスクを分担する menjelaskan mekanisme sindikasi bank pada skala triliunan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d33fc543-5f38-4c39-8eb1-a97a49f0aac2', 'ab9d0995-cc4d-4f5f-ac47-a74e01f016a9', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah menjadi peneliti senior, membimbing generasi penerus juga merupakan tugas utama."', '{"romaji":"Chuuken kenkyuusha to mo naru to, kouhai no ikusei mo juuyou na ninmu da.","tokens":["とも","後輩の育成も","任務だ。","任務だった。","中堅研究者","なると、","重要な","なりに、"],"target_translation":"Jika sudah menjadi peneliti senior, membimbing generasi penerus juga merupakan tugas utama."}'::jsonb, '["中堅研究者","とも","なると、","後輩の育成も","重要な","任務だ。"]'::jsonb, NULL, NULL, '中堅研究者ともなると menyoroti perluasan tanggung jawab pada tahap karier menengah-senior.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2edc389c-020c-4f9c-964c-4858fa4de8ae', 'ae32abdb-14ba-4ddd-b927-2ecfd4cb7181', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Lengkapi komentar editorial berikut: 十分な安全確認を怠ったまま運行を続けたのは、無責任___行為だ。', '{"options":["極まりない","とはいえ","に足る","なりに"],"translation":"Terus beroperasi sambil melalaikan pemeriksaan keselamatan yang memadai adalah tindakan yang amat sangat tidak bertanggung jawab.","sentence_template":"十分な安全確認を怠ったまま運行を続けたのは、無責任[blank]行為だ。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, NULL, NULL, 'Kata sifat-na stem (無責任) + 極まりない menyatakan tingkat ekstrem ''luar biasa / tanpa tandingan''.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('309a99d1-3142-4be8-ab23-98a8f06aa322', 'ae32abdb-14ba-4ddd-b927-2ecfd4cb7181', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk ungkapan formal rasa syukur: 国際的な賞を受賞でき、光栄___。', '{"options":["極まりない","を余儀なくされた","に至った","ともなると"],"translation":"Dapat meraih penghargaan internasional ini sungguh merupakan kehormatan yang tiada tara.","sentence_template":"国際的な賞を受賞でき、光栄[blank]。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, NULL, NULL, '光栄極まりない / 感激の極み adalah penggunaan positif super-formal dari ～極まりない.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0c3ca57f-fa84-4180-b1ce-43c2ddd898c1', 'ae32abdb-14ba-4ddd-b927-2ecfd4cb7181', 'd1000019-0000-0000-0000-000000000032', 'listening', 'listening_choice', 'Dengarkan tanggapan pengamat hukum. Bagaimana penilaian beliau terhadap pernyataan pejabat tersebut?', '{"options":[{"id":"opt_1","text":"Pernyataan itu dianggap sangat bijaksana dan menenangkan"},{"id":"opt_2","text":"Pernyataan yang sama sekali tidak memedulikan perasaan korban itu amat tidak pantas bagi seorang pejabat publik"},{"id":"opt_3","text":"Pejabat tersebut belum pernah memberikan pernyataan apa pun"},{"id":"opt_4","text":"Pengamat hukum mendukung penuh pernyataan tersebut"}],"audio_text":"被害者の心情を全く顧みないあの発言は、公人として不適切極まりないと言わざるを得ない。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '不適切極まりない berarti amat sangat tidak pantas (kritik tajam formal).', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0b5298e2-cfb8-4259-a28c-abf4d235567a', 'ae32abdb-14ba-4ddd-b927-2ecfd4cb7181', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Mengemudi dengan kecepatan tinggi di gang sempit adalah tindakan yang sangat berbahaya."', '{"romaji":"Semai roji o kousoku de hashiru no wa kiken kiwamarinai.","tokens":["高速で走るのは、","極まり","行為だ。","とはいえ、","狭い路地を","危険","ない","極まりなく"],"target_translation":"Mengemudi dengan kecepatan tinggi di gang sempit adalah tindakan yang sangat berbahaya."}'::jsonb, '["狭い路地を","高速で走るのは、","危険","極まり","ない","行為だ。"]'::jsonb, NULL, NULL, '危険極まりない行為 berarti tindakan yang luar biasa berbahaya.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bdbe8f20-c4d3-4d88-ba27-2010697feec4', 'ae32abdb-14ba-4ddd-b927-2ecfd4cb7181', 'd1000019-0000-0000-0000-000000000032', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sungguh amat disayangkan bahwa proyek yang telah lama disiapkan itu terpaksa batal."', '{"romaji":"Naganen junbi shite kita keikaku ga chuushi to nari, zannen kiwamari arimasen.","display_text":"長年準備してきた計画が中止となり、残念極まりありません。","phonetic_breakdown":["ながねんじゅんびしてきた","けいかくがちゅうしとなり","ざんねん","きわまりありません"]}'::jsonb, '{"expected_transcript":"長年準備してきた計画が中止となり、残念極まりありません。"}'::jsonb, NULL, NULL, '残念極まりありません adalah bentuk sopan dari 残念極まりない untuk menyatakan penyesalan mendalam.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('688bddd2-30b9-47c7-8af9-77bbef32d78d', 'ae32abdb-14ba-4ddd-b927-2ecfd4cb7181', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 会議中に何度も相手の話を遮るのは、失礼___態度だ。', '{"options":["極まりない","をもって","ずにはおかない","いかんによらず"],"translation":"Berkali-kali memotong pembicaraan orang lain saat rapat adalah sikap yang luar biasa tidak sopan.","sentence_template":"会議中に何度も相手の話を遮るのは、失礼[blank]態度だ。"}'::jsonb, '{"selected":"極まりない"}'::jsonb, NULL, NULL, '失礼 (kata sifat-na) + 極まりない menekankan ketidaksopanan pada level ekstrem.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2a074fa7-6c12-4c2c-9bb1-d067d996e0ec', 'ae32abdb-14ba-4ddd-b927-2ecfd4cb7181', 'd1000019-0000-0000-0000-000000000032', 'listening', 'listening_choice', 'Dengarkan ulasan berita lingkungan. Apa keluhan warga tentang pembangunan jalan baru?', '{"options":[{"id":"opt_1","text":"Warga memuji transparansi proyek pembangunan jalan"},{"id":"opt_2","text":"Pembangunan jalan sudah disetujui seratus persen warga"},{"id":"opt_3","text":"Cara memaksakan konstruksi tanpa penjelasan ke warga dikecam sebagai amat sangat memaksa"},{"id":"opt_4","text":"Warga meminta proyek konstruksi dipercepat dua kali lipat"}],"audio_text":"住民への説明もなしに工事を強行するやり方は、強引極まりないと強い反発を招いている。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '強引極まりない berarti luar biasa memaksa/otoriter.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b94fe007-e994-4752-b995-7aa929596878', 'ae32abdb-14ba-4ddd-b927-2ecfd4cb7181', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Kesalahan manajemen data pribadi tersebut sungguh keterlaluan dan tidak bisa dimaafkan."', '{"romaji":"Kojin jouhou no zusan na kanri wa ikan kiwamarinai.","tokens":["ずさんな管理は、","極まり","事態だ。","なりに","個人情報の","遺憾","ない","に足る"],"target_translation":"Kesalahan manajemen data pribadi tersebut sungguh keterlaluan dan tidak bisa dimaafkan."}'::jsonb, '["個人情報の","ずさんな管理は、","遺憾","極まり","ない","事態だ。"]'::jsonb, NULL, NULL, '遺憾極まりない (amat sangat disesalkan) adalah frasa pernyataan resmi perusahaan/pemerintah.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1924a05e-786f-46da-bfd1-df123449f132', 'b2a1852c-649b-4279-9602-f3f242d554cb', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk kalimat refleksi berikut: 正解のない課題に対して、チーム全員で解決策を___し続けている。', '{"options":["拒絶","断定","放棄","模索"],"translation":"Terhadap tantangan tanpa jawaban pasti, seluruh tim terus mencari-cari jalan keluar.","sentence_template":"正解のない課題に対して、チーム全員で解決策を[blank]し続けている。"}'::jsonb, '{"selected":"模索"}'::jsonb, NULL, NULL, '模索 (mosaku) berarti ''meraba-raba / terus mencari jalan keluar di tengah ketidakpastian''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('39539e65-f102-48d4-8dfe-d7c4e651d815', 'b2a1852c-649b-4279-9602-f3f242d554cb', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat manajemen berikut: 限られた資源の中でも、現場の___によって業務が大きく改善された。', '{"options":["現状維持","形式主義","創意工夫","責任転嫁"],"translation":"Meski sumber daya terbatas, berkat kreativitas dan inisiatif tim lapangan, operasional meningkat pesat.","sentence_template":"限られた資源の中でも、現場の[blank]によって業務が大きく改善された。"}'::jsonb, '{"selected":"創意工夫"}'::jsonb, NULL, NULL, '創意工夫 (soui kufuu) berarti ''daya cipta dan siasat kreatif'' untuk mengatasi keterbatasan.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0394ed6b-66aa-4843-8afb-733c06ea7729', 'b2a1852c-649b-4279-9602-f3f242d554cb', NULL, 'reading', 'fill_blank', 'Pilih kosakata yang tepat untuk menggambarkan dilema batin: 理想と現実の間で深い___を抱えながら、彼は決断を下した。', '{"options":["満足","安心","油断","葛藤"],"translation":"Sambil memendam konflik batin yang dalam antara idealisme dan realitas, ia mengambil keputusan.","sentence_template":"理想と現実の間で深い[blank]を抱えながら、彼は決断を下した。"}'::jsonb, '{"selected":"葛藤"}'::jsonb, NULL, NULL, '葛藤 (kattou) berarti ''konflik batin / pergulatan pikiran''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('31d08818-649d-4c9c-bfac-13d5b5be90b4', 'b2a1852c-649b-4279-9602-f3f242d554cb', NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan manajer berikut. Sikap apa yang dihargai oleh pembicara?', '{"options":[{"id":"opt_1","text":"Hanya bekerja cepat tanpa memedulikan rekan kerja"},{"id":"opt_2","text":"Menghadapi pekerjaan dengan tulus dan tidak lupa bertenggang rasa terhadap sekitar"},{"id":"opt_3","text":"Menghindari tugas sulit sampai memiliki pengalaman sepuluh tahun"},{"id":"opt_4","text":"Selalu bekerja lembur hingga larut malam setiap hari"}],"audio_text":"経験の浅い若手であっても、日々の業務に誠実に向き合い、周囲への配慮を忘れない姿勢は高く評価される。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '誠実に向き合い (menghadapi dengan tulus) dan 周囲への配慮 (perhatian/tenggang rasa pada sekitar).', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9c3a3846-b34d-49b5-80db-b11998a57df0', 'b2a1852c-649b-4279-9602-f3f242d554cb', NULL, 'listening', 'listening_choice', 'Dengarkan refleksi pemimpin tim berikut. Bagaimana ia memandang peran setiap anggota?', '{"options":[{"id":"opt_1","text":"Semua anggota harus memiliki keahlian yang persis sama"},{"id":"opt_2","text":"Hanya pemimpin yang bertanggung jawab atas kontribusi tim"},{"id":"opt_3","text":"Penting bagi tiap anggota berkontribusi dengan memanfaatkan keunggulan khas masing-masing"},{"id":"opt_4","text":"Anggota baru tidak perlu menyampaikan pendapat dalam rapat"}],"audio_text":"全員が同じ能力を持つ必要はなく、それぞれの持ち味を生かして組織に貢献することが大切だ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '持ち味を生かして組織に貢献する berarti ''memanfaatkan ciri khas/keunggulan diri untuk berkontribusi pada organisasi''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2bd5eb2b-2662-475b-8d93-12aa052f1fcb', 'b2a1852c-649b-4279-9602-f3f242d554cb', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saling menghormati posisi masing-masing adalah fondasi kerja sama."', '{"romaji":"Tagai no tachiba wo sonchou shiau koto ga, shinrai kankei no kiban to naru.","display_text":"互いの立場を尊重し合うことが、信頼関係の基盤となる。","phonetic_breakdown":["ta-gai","no","ta-chi-ba","wo","son-chou","shi-a-u","ko-to","ga","shin-rai","kan-kei","no","ki-ban","to","na-ru"]}'::jsonb, '{"expected_transcript":"互いの立場を尊重し合うことが、信頼関係の基盤となる。"}'::jsonb, NULL, NULL, '立場を尊重し合う (saling menghormati posisi/sudut pandang) adalah ungkapan kepemimpinan yang matang.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('affd3c52-cdb1-4f4a-9c25-8c3b6b728ecc', 'b2a1852c-649b-4279-9602-f3f242d554cb', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Pilih kosakata yang tepat: 限られた資源の中でも、現場なりの___を凝らして成果を出した。', '{"options":["工夫","撤退","放棄","欠席"],"translation":"Di tengah sumber daya yang terbatas pun, tim lapangan memeras kreativitas dengan caranya sendiri hingga membuahkan hasil.","sentence_template":"限られた資源の中でも、現場なりの[blank]を凝らして成果を出した。"}'::jsonb, '{"selected":"工夫"}'::jsonb, NULL, NULL, '工夫を凝らす (mengupayakan kreativitas/akal budi secara optimal) sangat cocok dengan ～なりの.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ce84c11b-ac5e-4b78-b910-8c3b1664aa63', 'b2a1852c-649b-4279-9602-f3f242d554cb', 'd1000019-0000-0000-0000-000000000033', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun belum sempurna, saya telah merangkum pandangan saya sendiri dalam laporan ini."', '{"romaji":"Mijuku nagara mo, watashi nari no kenkai o hon houkokusho ni matomemashita.","display_text":"未熟ながらも、私なりの見解を本報告書にまとめました。","phonetic_breakdown":["みじくながらも","わたしなりのけんかいを","ほんほうこくしょに","まとめました"]}'::jsonb, '{"expected_transcript":"未熟ながらも、私なりの見解を本報告書にまとめました。"}'::jsonb, NULL, NULL, '私なりの見解 (pandangan versi saya sendiri) adalah ungkapan akademis dan bisnis yang sopan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('00e11b19-0b30-4a7f-be90-5a839c2ccb7e', 'b304153f-0c49-4178-a203-65cdfcb1374c', 'd1000019-0000-0000-0000-000000000034', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pidato yang tulus itu pasti menggerakkan hati para pendengar."', '{"romaji":"Ano kokoro no komotta enzetsu wa, choushuu no mune wo utazu ni wa okanai.","display_text":"あの心のこもった演説は、聴衆の胸を打たずにはおかない。","phonetic_breakdown":["a-no","ko-ko-ro","no","ko-mo-tta","en-ze-tsu","wa","chou-shuu","no","mu-ne","wo","u-ta-zu","ni","wa","o-ka-nai"]}'::jsonb, '{"expected_transcript":"あの心のこもった演説は、聴衆の胸を打たずにはおかない。"}'::jsonb, NULL, NULL, '胸を打つ (mune wo utsu: menyentuh/menggetarkan hati) -> 打たずにはおかない.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4ab08913-f5b5-4960-a6e5-99dc62ca5420', 'b304153f-0c49-4178-a203-65cdfcb1374c', 'd1000019-0000-0000-0000-000000000034', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Inovasi teknologi ini pasti akan mengubah cara kerja kita."', '{"romaji":"Kono gijutsu kakushin wa, watashitachi no hatarakikata wo konpon kara kaezu ni wa okanai.","display_text":"この技術革新は、私たちの働き方を根本から変えずにはおかない。","phonetic_breakdown":["ko-no","gi-ju-tsu","ka-ku-shin","wa","wa-ta-shi-ta-chi","no","ha-ta-ra-ki-ka-ta","wo","kon-pon","ka-ra","ka-e-zu","ni","wa","o-ka-nai"]}'::jsonb, '{"expected_transcript":"この技術革新は、私たちの働き方を根本から変えずにはおかない。"}'::jsonb, NULL, NULL, '根本から変える (mengubah dari akarnya) dipadukan dengan ～ずにはおかない.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7e8b96b5-2e03-4e86-8321-8f795eadba8d', 'b304153f-0c49-4178-a203-65cdfcb1374c', 'd1000019-0000-0000-0000-000000000034', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Sikap yang arogan itu pasti akan memicu ketidakpercayaan mitra."', '{"romaji":"Aa shita kouatsuteki na taido wa, torihikisaki no fushinkan wo manekazu ni wa okanai.","display_text":"ああした高圧的な態度は、取引先の不信感を招かずにはおかない。","phonetic_breakdown":["aa","shi-ta","kou-a-tsu-te-ki","na","tai-do","wa","to-ri-hi-ki-sa-ki","no","fu-shin-kan","wo","ma-ne-ka-zu","ni","wa","o-ka-nai"]}'::jsonb, '{"expected_transcript":"ああした高圧的な態度は、取引先の不信感を招かずにはおかない。"}'::jsonb, NULL, NULL, '高圧的な態度 (sikap menekan/arogan) pasti mengundang 不信感 (rasa tidak percaya).', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('31cdc7c5-d072-475e-8e8a-16aaed31e9ee', 'b304153f-0c49-4178-a203-65cdfcb1374c', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Berita mengejutkan itu pasti menimbulkan gejolak di pasar keuangan."', '{"romaji":"Sono sokuhou wa kin''yuu shijou ni douyou wo ataezu ni wa okanai.","tokens":["極まりない","動揺を","なりに","その","与え","ずにはおかない","金融市場に","速報は"],"target_translation":"Berita mengejutkan itu pasti menimbulkan gejolak di pasar keuangan."}'::jsonb, '["その","速報は","金融市場に","動揺を","与え","ずにはおかない"]'::jsonb, NULL, NULL, '動揺を与える (menimbulkan keguncangan/gejolak) -> 与えずにはおかない.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('edeac38b-4234-4d12-bc3f-42f93022461e', 'b304153f-0c49-4178-a203-65cdfcb1374c', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Dedikasi mereka pasti akan membangkitkan rasa hormat siapa pun."', '{"romaji":"Karera no kenshinteki na katsudou wa keii wo idakasezu ni wa okanai.","tokens":["彼らの","敬意を","活動は","献身的な","とはいえ","抱かせ","をもって","ずにはおかない"],"target_translation":"Dedikasi mereka pasti akan membangkitkan rasa hormat siapa pun."}'::jsonb, '["彼らの","献身的な","活動は","敬意を","抱かせ","ずにはおかない"]'::jsonb, NULL, NULL, '敬意を抱かせる (membuat orang menaruh rasa hormat) -> 抱かせずにはおかない.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6cdb31a9-70e9-4a56-a472-6462d0a9c747', 'b304153f-0c49-4178-a203-65cdfcb1374c', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Saya bertekad pasti akan menyelesaikan proyek ini hingga tuntas."', '{"romaji":"Kono keikaku wa kanarazu seikou sasenai de wa okanai.","tokens":["成功","計画は","必ず","ないではおかない","この","ながら","させ","に至って"],"target_translation":"Saya bertekad pasti akan menyelesaikan proyek ini hingga tuntas."}'::jsonb, '["この","計画は","必ず","成功","させ","ないではおかない"]'::jsonb, NULL, NULL, '成功させないではおかない menyatakan tekad kuat untuk menyukseskan proyek.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c5b53ac2-d716-48ab-b6e9-3de4a20cab6c', 'b304153f-0c49-4178-a203-65cdfcb1374c', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Pilih pola yang tepat: 彼の情熱的な演奏は、会場の空気を一変させ___。', '{"options":["ずにはおかなかった","を余儀なくされた","極まりなかった","に足らなかった"],"translation":"Permainan musiknya yang penuh gairah pasti mengubah suasana aula dalam sekejap.","sentence_template":"彼の情熱的な演奏は、会場の空気を一変させ[blank]。"}'::jsonb, '{"selected":"ずにはおかなかった"}'::jsonb, NULL, NULL, '一変させずにはおかなかった (bentuk lampau) menyatakan dampak nyata yang benar-benar terjadi.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('032d346a-010b-4cc2-bee3-27862c084fb2', 'b304153f-0c49-4178-a203-65cdfcb1374c', 'd1000019-0000-0000-0000-000000000034', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Temuan arkeologi ini pasti akan menarik minat para peneliti dari seluruh penjuru dunia."', '{"romaji":"Kono koukogakuteki hakken wa, sekaijuu no kenkyuusha no kanshin o hikazu ni wa okimasen.","display_text":"この考古学的発見は、世界中の研究者の関心を惹かずにはおきません。","phonetic_breakdown":["このこうこがくてき","はっけんは","せかいじゅうのけんきゅうしゃの","かんしんをひかずには","おきません"]}'::jsonb, '{"expected_transcript":"この考古学的発見は、世界中の研究者の関心を惹かずにはおきません。"}'::jsonb, NULL, NULL, '関心を惹く (menarik perhatian/minat) -> 関心を惹かずにはおきません.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('20aa7947-ceb7-49a5-acc0-8122050f3173', 'b648eb48-7507-4fb9-8c7d-fa3a4384219d', 'd1000019-0000-0000-0000-000000000032', 'listening', 'listening_choice', 'Dengarkan pidato penerimaan penghargaan. Apa perasaan yang diungkapkan pembicara?', '{"options":[{"id":"opt_1","text":"Pembicara merasa sangat terhormat sebagai peneliti atas penghargaan bergengsi tersebut"},{"id":"opt_2","text":"Pembicara menolak menerima penghargaan tersebut"},{"id":"opt_3","text":"Pembicara merasa penelitiannya belum layak dinilai"},{"id":"opt_4","text":"Pembicara mengkritik panitia penyelenggara"}],"audio_text":"このような栄誉ある賞を賜り、研究者として光栄極まりない思いでございます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '光栄極まりない思いでございます mengekspresikan rasa terhormat yang luar biasa tinggi.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2dfeff91-2a79-40c0-ba6b-6cea7e205216', 'b648eb48-7507-4fb9-8c7d-fa3a4384219d', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Berjalan sendirian di gunung bersalju tanpa perlengkapan adalah tindakan amat sembrono."', '{"romaji":"Soubi nashi de yukiyama ni hairu no wa mubou kiwamarinai.","tokens":["雪山に入るのは、","極まり","ことだ。","をもって、","装備なしで","無謀","ない","無謀な"],"target_translation":"Berjalan sendirian di gunung bersalju tanpa perlengkapan adalah tindakan amat sembrono."}'::jsonb, '["装備なしで","雪山に入るのは、","無謀","極まり","ない","ことだ。"]'::jsonb, NULL, NULL, '無謀極まりない (amat sangat nekat/sembrono) memakai akar kata sifat-na 無謀.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c610facf-580a-4113-b381-1a3499832312', 'b648eb48-7507-4fb9-8c7d-fa3a4384219d', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Pilih bentuk adverbial yang tepat: 彼の言動は周囲に誤解を与えるもので、不愉快___感じられた。', '{"options":["極まりなく","極まりない","極まりな","極まりに"],"translation":"Ucapan dan tindakannya menimbulkan kesalahpahaman di sekitar sehingga terasa amat sangat tidak menyenangkan.","sentence_template":"彼の言動は周囲に誤解を与えるもので、不愉快[blank]感じられた。"}'::jsonb, '{"selected":"極まりなく"}'::jsonb, NULL, NULL, 'Sebelum verba (感じられた), 極まりない berubah menjadi bentuk adverbial 極まりなく.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('116fd9c3-21e2-4098-9b4d-09ba699b8ebc', 'b648eb48-7507-4fb9-8c7d-fa3a4384219d', 'd1000019-0000-0000-0000-000000000032', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tindakan memalsukan data uji klinis sungguh sangat tercela secara etika."', '{"romaji":"Rinshou shiken no deeta o kaizan suru to wa, gongodoudan, akushitsu kiwamarinai koui desu.","display_text":"臨床試験のデータを改ざんするとは、言語道断、悪質極まりない行為です。","phonetic_breakdown":["りんしょうしけんの","でーたをかいざんするとは","ごんごどうだん","あくしつきわまりない","こういです"]}'::jsonb, '{"expected_transcript":"臨床試験のデータを改ざんするとは、言語道断、悪質極まりない行為です。"}'::jsonb, NULL, NULL, '悪質極まりない (amat sangat jahat/berniat buruk) sering muncul dalam berita hukum N1.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ddcc82de-6cab-4c56-aa5d-a4d45accdfc4', 'b648eb48-7507-4fb9-8c7d-fa3a4384219d', 'd1000019-0000-0000-0000-000000000032', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 難関資格に一発で合格した知らせを聞き、痛快___。', '{"options":["極まりなかった","とはいえなかった","に足らなかった","を余儀なくされた"],"translation":"Mendengar kabar lulus ujian sertifikasi sulit dalam sekali coba, rasanya sungguh luar biasa memuaskan.","sentence_template":"難関資格に一発で合格した知らせを聞き、痛快[blank]。"}'::jsonb, '{"selected":"極まりなかった"}'::jsonb, NULL, NULL, '痛快極まりなかった adalah bentuk lampau dari 痛快極まりない (luar biasa memuaskan/melegakan).', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ddb917f2-ec8a-4f4d-82d3-787a0974fc64', 'b648eb48-7507-4fb9-8c7d-fa3a4384219d', 'd1000019-0000-0000-0000-000000000032', 'listening', 'listening_choice', 'Dengarkan ulasan konsultan bisnis. Mengapa beliau mengkritik prosedur persetujuan di perusahaan itu?', '{"options":[{"id":"opt_1","text":"Sistem persetujuan sudah sangat cepat dan ringkas"},{"id":"opt_2","text":"Semua pembelian perlengkapan kantor digratiskan"},{"id":"opt_3","text":"Karyawan tidak perlu meminta izin siapa pun"},{"id":"opt_4","text":"Mewajibkan cap persetujuan sepuluh orang bahkan untuk membeli alat tulis kecil adalah sistem yang amat tidak efisien"}],"audio_text":"些細な備品購入にまで十人もの承認印を必要とする仕組みは、非効率極まりないと言えます。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '非効率極まりない berarti luar biasa tidak efisien.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7c5faa96-1445-4431-b87e-a728c2acd0f5', 'b648eb48-7507-4fb9-8c7d-fa3a4384219d', 'd1000019-0000-0000-0000-000000000032', 'writing', 'sentence_builder', 'Susun kalimat: "Kebijakan yang tidak konsisten itu membuat para pelaku usaha merasa sangat bingung."', '{"romaji":"Ikkansei no nai seisaku wa jigyousha ni totte meiwaku kiwamarinai.","tokens":["政策は、","迷惑","ない。","に至って、","一貫性のない","事業者にとって","極まり","迷惑な"],"target_translation":"Kebijakan yang tidak konsisten itu membuat para pelaku usaha merasa sangat bingung."}'::jsonb, '["一貫性のない","政策は、","事業者にとって","迷惑","極まり","ない。"]'::jsonb, NULL, NULL, '迷惑極まりない (amat sangat merepotkan/mengganggu) lazim dipakai dalam kritik kebijakan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dfed162e-d0a9-4cc0-b9ed-10bfa6c38d5b', 'b648eb48-7507-4fb9-8c7d-fa3a4384219d', 'd1000019-0000-0000-0000-000000000032', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Membiarkan fasilitas umum rusak selama bertahun-tahun adalah kelalaian yang amat berbahaya."', '{"romaji":"Roukyuuka shita koukyou shisetsu o houchi suru no wa, kiken kiwamarinai taiman desu.","display_text":"老朽化した公共施設を放置するのは、危険極まりない怠慢です。","phonetic_breakdown":["ろうきゅうかした","こうきょうしせつを","ほうちするのは","きけんきわまりない","たいまんです"]}'::jsonb, '{"expected_transcript":"老朽化した公共施設を放置するのは、危険極まりない怠慢です。"}'::jsonb, NULL, NULL, '危険極まりない怠慢 (kelalaian yang luar biasa berbahaya) adalah gaya bahasa editorial N1.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('423f8508-ece4-48d6-91c0-16d4422b4cd9', 'ba2a642c-81a5-42fa-82de-12d98fa36535', 'd1000019-0000-0000-0000-000000000030', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun anggarannya terbatas, kualitas tidak boleh diturunkan."', '{"romaji":"Yosan ga kagirarete iru to wa ie, hinshitsu wo otosu wake ni wa ikanai.","display_text":"予算が限られているとはいえ、品質を落とすわけにはいかない。","phonetic_breakdown":["yo-san","ga","ka-gi-ra-re-te","i-ru","to","wa","i-e","hin-shi-tsu","wo","o-to-su","wa-ke","ni","wa","i-ka-nai"]}'::jsonb, '{"expected_transcript":"予算が限られているとはいえ、品質を落とすわけにはいかない。"}'::jsonb, NULL, NULL, 'Memadukan ～とはいえ dengan ～わけにはいかない (tidak bisa/tidak boleh melakukan...).', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5c956384-d960-4653-a3b7-ab18f288fad6', 'ba2a642c-81a5-42fa-82de-12d98fa36535', 'd1000019-0000-0000-0000-000000000030', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Walaupun disebut proyek kecil, dampaknya sangat luas."', '{"romaji":"Shoukibo na jigyou to wa ie, chiiki shakai e no hakyuu kouka wa ookii.","display_text":"小規模な事業とはいえ、地域社会への波及効果は大きい。","phonetic_breakdown":["shou-ki-bo","na","ji-gyou","to","wa","i-e","chi-i-ki","sha-kai","e","no","ha-kyuu","kou-ka","wa","oo-kii"]}'::jsonb, '{"expected_transcript":"小規模な事業とはいえ、地域社会への波及効果は大きい。"}'::jsonb, NULL, NULL, '波及効果 (hakyuu kouka) berarti ''efek berantai / ripple effect''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dc7a16fe-7d6d-4152-84e4-6e6b86030c13', 'ba2a642c-81a5-42fa-82de-12d98fa36535', 'd1000019-0000-0000-0000-000000000030', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meski memang hari libur, saya tetap harus memeriksa email darurat."', '{"romaji":"Kyuujitsu to wa ie, kinkyu no renraku ni wa taiou dekiru you ni shite iru.","display_text":"休日とはいえ、緊急の連絡には対応できるようにしている。","phonetic_breakdown":["kyuu-ji-tsu","to","wa","i-e","kin-kyuu","no","ren-ra-ku","ni","wa","tai-ou","de-ki-ru","you","ni","shi-te","i-ru"]}'::jsonb, '{"expected_transcript":"休日とはいえ、緊急の連絡には対応できるようにしている。"}'::jsonb, NULL, NULL, '休日とはいえ (meski memang hari libur) diikuti sikap profesional tetap siap merespons kontak darurat.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2e5af8fd-6786-4d0b-8d60-e4c3d6f178e0', 'ba2a642c-81a5-42fa-82de-12d98fa36535', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun memang sudah berpengalaman, persiapan yang matang tetap penting."', '{"romaji":"Keiken ga houfu da to wa ie, jizen no junbi wa kakasenai.","tokens":["ばかりに","準備は","豊富だ","欠かせない","とはいえ","経験が","に至って","事前の"],"target_translation":"Meskipun memang sudah berpengalaman, persiapan yang matang tetap penting."}'::jsonb, '["経験が","豊富だ","とはいえ","事前の","準備は","欠かせない"]'::jsonb, NULL, NULL, '経験が豊富だとはいえ (meski berpengalaman luas) diikuti 事前の準備は欠かせない (persiapan sebelumnya tak tergantikan).', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('055adb68-396f-4019-925d-aa694893730d', 'ba2a642c-81a5-42fa-82de-12d98fa36535', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Walaupun tingkat kriminalitas rendah, kewaspadaan tidak boleh kendur."', '{"romaji":"Chian ga yoi to wa ie, bouhan ishiki wo yurumete wa naranai.","tokens":["をめぐって","緩めては","なりに","ならない","とはいえ","良い","防犯意識を","治安が"],"target_translation":"Walaupun tingkat kriminalitas rendah, kewaspadaan tidak boleh kendur."}'::jsonb, '["治安が","良い","とはいえ","防犯意識を","緩めては","ならない"]'::jsonb, NULL, NULL, '防犯意識を緩めてはならない berarti ''kesadaran pencegahan kejahatan tidak boleh dikendurkan''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e3a1512b-0c5f-4968-96df-80f2eded017a', 'ba2a642c-81a5-42fa-82de-12d98fa36535', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun hasilnya belum sempurna, kemajuan besar telah tercapai."', '{"romaji":"Kanpeki de wa nai to wa ie, ookina zenshin wo togeta.","tokens":["どころか","を余儀なく","遂げた","とはいえ","完璧では","ない","大きな","前進を"],"target_translation":"Meskipun hasilnya belum sempurna, kemajuan besar telah tercapai."}'::jsonb, '["完璧では","ない","とはいえ","大きな","前進を","遂げた"]'::jsonb, NULL, NULL, '大きな前進を遂げた berarti ''telah mencapai kemajuan besar''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b96bf021-bd19-4795-8d1b-db7ee73c327d', 'ba2a642c-81a5-42fa-82de-12d98fa36535', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Pilih pola yang tepat: 専門外___、基本的な財務諸表くらいは読めるようにしておきたい。', '{"options":["とはいえ","ともなると","に足らず","いかんによらず"],"translation":"Meskipun di luar bidang keahlian saya, setidaknya saya ingin bisa membaca laporan keuangan dasar.","sentence_template":"専門外[blank]、基本的な財務諸表くらいは読めるようにしておきたい。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '専門外とはいえ adalah ungkapan rendah hati sekaligus proaktif dalam pengembangan diri.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('93392102-5ffc-42ca-8ef2-b98834ad8cfd', 'ba2a642c-81a5-42fa-82de-12d98fa36535', 'd1000019-0000-0000-0000-000000000030', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun hanya sumbangsih kecil, saya berharap dapat berguna bagi masyarakat lokal."', '{"romaji":"Biryoku to wa ie, chiiki shakai no hatten ni kouken dekireba saiwai desu.","display_text":"微力とはいえ、地域社会の発展に貢献できれば幸いです。","phonetic_breakdown":["びりょく","とはいえ","ちいきしゃかいのはってんに","こうけんできれば","さいわいです"]}'::jsonb, '{"expected_transcript":"微力とはいえ、地域社会の発展に貢献できれば幸いです。"}'::jsonb, NULL, NULL, '微力とはいえ (meskipun tenaga/kontribusi saya kecil) adalah ungkapan rendah hati yang sangat elegan.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('74923e62-ad09-4eb0-a37b-0e12c012aeb0', 'bb14d142-a748-4589-beb0-6f9ff752aa76', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Lengkapi klausul kepatuhan perusahaan berikut: 役職や勤続年数の___、ハラスメント行為には厳正に対処する。', '{"options":["いかんによらず","に至って","極まりなく","なりに"],"translation":"Tanpa memandang jabatan maupun masa kerja, tindakan pelecehan akan ditindak secara tegas dan adil.","sentence_template":"役職や勤続年数の[blank]、ハラスメント行為には厳正に対処する。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, NULL, NULL, 'Kata benda + の + いかんによらず menyatakan prinsip tegas yang berlaku tanpa pengecualian apa pun.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ebc5bb2f-b021-46a0-bba2-0c91bc3c592e', 'bb14d142-a748-4589-beb0-6f9ff752aa76', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Pilih varian formal yang setara dalam dokumen hukum: 理由の___、期限を過ぎた申請書は一切受理しない。', '{"options":["いかんを問わず","とはいえ","ともなると","に足る"],"translation":"Apa pun alasannya, formulir permohonan yang melewati batas waktu tidak akan diterima sama sekali.","sentence_template":"理由の[blank]、期限を過ぎた申請書は一切受理しない。"}'::jsonb, '{"selected":"いかんを問わず"}'::jsonb, NULL, NULL, '～のいかんを問わず adalah pasangan super-formal yang sepadan dengan ～のいかんによらず.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bda692e6-6634-4d5e-92b6-3b9ad35fa25b', 'bb14d142-a748-4589-beb0-6f9ff752aa76', 'd1000019-0000-0000-0000-000000000036', 'listening', 'listening_choice', 'Dengarkan pengumuman aturan ujian sertifikasi. Bagaimana kebijakan bagi peserta yang melanggar aturan?', '{"options":[{"id":"opt_1","text":"Pelanggaran tidak disengaja tetap diberikan nilai lulus"},{"id":"opt_2","text":"Tanpa memandang disengaja atau kelalaian, jika kecurangan terbukti di ruang ujian maka peserta langsung didiskualifikasi"},{"id":"opt_3","text":"Peserta boleh mengulang ujian pada hari yang sama"},{"id":"opt_4","text":"Aturan ujian hanya berlaku bagi peserta baru"}],"audio_text":"故意か過失かのいかんによらず、試験会場で不正行為が確認された場合は直ちに失格となります。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '故意か過失かのいかんによらず berarti tanpa memandang apakah dilakukan sengaja atau karena kelalaian.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('61b4adf6-5550-4a8b-bd0d-e6ba9f1066b6', 'bb14d142-a748-4589-beb0-6f9ff752aa76', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang hasil akhirnya, proses yang jujur tetap harus dijunjung tinggi."', '{"romaji":"Kekka no ikan ni yorazu, kousei na purosesu ga mamorareru beki da.","tokens":["いかん","公正なプロセスが","べきだ。","守った","結果の","によらず、","守られる","とはいえ、"],"target_translation":"Tanpa memandang hasil akhirnya, proses yang jujur tetap harus dijunjung tinggi."}'::jsonb, '["結果の","いかん","によらず、","公正なプロセスが","守られる","べきだ。"]'::jsonb, NULL, NULL, '結果のいかんによらず menegaskan prinsip integritas prosedur tanpa bergantung hasil.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('497f06f8-b375-468b-ab54-cc515c4312c2', 'bb14d142-a748-4589-beb0-6f9ff752aa76', 'd1000019-0000-0000-0000-000000000036', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang kewarganegaraan atau usia, hak asasi setiap individu harus dihormati."', '{"romaji":"Kokuseki ya nenrei no ikan ni yorazu, subete no hito no kenri ga byoudou ni sonchou saremasu.","display_text":"国籍や年齢のいかんによらず、すべての人の権利が平等に尊重されます。","phonetic_breakdown":["こくせきや","ねんれいの","いかんによらず","すべてのひとのけんりが","びょうどうにそんちょうされます"]}'::jsonb, '{"expected_transcript":"国籍や年齢のいかんによらず、すべての人の権利が平等に尊重されます。"}'::jsonb, NULL, NULL, '権利が平等に尊重される (hak dihormati secara setara) adalah bahasa konstitusi/HAM N1.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('66994a8d-daaa-4d6f-a9b8-9f24f1ed8409', 'bb14d142-a748-4589-beb0-6f9ff752aa76', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Lengkapi pasal perjanjian berikut: 損害額の___、情報漏洩が判明した際は速やかに報告する義務がある。', '{"options":["いかんによらず","をもって","を余儀なくされ","ずにはおかず"],"translation":"Tanpa memandang besar kecilnya nilai kerugian, saat kebocoran informasi terungkap wajib segera melapor.","sentence_template":"損害額の[blank]、情報漏洩が判明した際は速やかに報告する義務がある。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, NULL, NULL, '損害額のいかんによらず (berapa pun nilai kerugiannya) adalah klausul standar keamanan data.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b3243d9c-a69f-46d1-b096-d6dab9d08d06', 'bb14d142-a748-4589-beb0-6f9ff752aa76', 'd1000019-0000-0000-0000-000000000036', 'listening', 'listening_choice', 'Dengarkan penjelasan bagian kepegawaian. Bagaimana sistem evaluasi promosi di perusahaan tersebut?', '{"options":[{"id":"opt_1","text":"Promosi hanya diberikan kepada lulusan universitas tertentu"},{"id":"opt_2","text":"Promosi ditentukan berdasarkan kedekatan pribadi"},{"id":"opt_3","text":"Perusahaan menilai promosi semata berdasarkan kemampuan dan prestasi tanpa memandang gender maupun almamater"},{"id":"opt_4","text":"Perusahaan tidak memiliki sistem promosi jabatan"}],"audio_text":"弊社では性別や出身大学のいかんによらず、実力と実績のみで昇進を判断しています。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '性別や出身大学のいかんによらず menegaskan prinsip meritokrasi.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('28a93b35-60de-4a6b-b74b-9646e7b8a913', 'bb14d142-a748-4589-beb0-6f9ff752aa76', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang cuaca, acara peringatan di dalam aula tetap dilaksanakan sesuai jadwal."', '{"romaji":"Tenkou no ikan ni yorazu, hoori nai no shikiten wa yotei doori jisshi sareru.","tokens":["いかん","ホール内の式典は","実施される。","実施した。","天候の","によらず、","予定通り","に至って、"],"target_translation":"Tanpa memandang cuaca, acara peringatan di dalam aula tetap dilaksanakan sesuai jadwal."}'::jsonb, '["天候の","いかん","によらず、","ホール内の式典は","予定通り","実施される。"]'::jsonb, NULL, NULL, '天候のいかんによらず (bagaimanapun cuacanya) lazim pada surat undangan resmi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fdc18641-90ce-4b10-bb4d-b33f59ea29c0', 'c2bfed73-bf19-4235-8353-f02220a5e851', NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat: 新しい税制案については、国民の間で___が分かれている。', '{"options":["勝負","有無","高低","賛否"],"translation":"Mengenai rancangan sistem pajak baru, pro dan kontra terbelah di kalangan masyarakat.","sentence_template":"新しい税制案については、国民の間で[blank]が分かれている。"}'::jsonb, '{"selected":"賛否"}'::jsonb, NULL, NULL, '賛否が分かれる (sanpi ga wakareru) berarti ''pendapat setuju dan tidak setuju terbelah''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('187ed240-a7cb-4ca0-a448-44b255d8cc47', 'c2bfed73-bf19-4235-8353-f02220a5e851', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi kebijakan berikut: 理念は立派だが、現場での___に疑問が残る。', '{"options":["装飾性","娯楽性","偶然性","実効性"],"translation":"Prinsipnya memang mulia, tetapi efektivitas penerapannya di lapangan masih menyisakan keraguan.","sentence_template":"理念は立派だが、現場での[blank]に疑問が残る。"}'::jsonb, '{"selected":"実効性"}'::jsonb, NULL, NULL, '実効性 (jikkousei) berarti ''efektivitas nyata / daya laksana'' suatu aturan atau kebijakan.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('796d0396-1a7b-4afc-ab1d-b9cae18a8ef4', 'c2bfed73-bf19-4235-8353-f02220a5e851', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk wacana lingkungan dan ekonomi: 長期的な視点から、事業の___を高める必要がある。', '{"options":["即時性","排他性","持続可能性","曖昧性"],"translation":"Dari sudut pandang jangka panjang, perlu meningkatkan keberlanjutan bisnis.","sentence_template":"長期的な視点から、事業の[blank]を高める必要がある。"}'::jsonb, '{"selected":"持続可能性"}'::jsonb, NULL, NULL, '持続可能性 (jizoku kanousei) adalah padanan resmi untuk ''sustainability / keberlanjutan''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('25b39197-3b6e-40a1-a790-bf19cff10382', 'c2bfed73-bf19-4235-8353-f02220a5e851', NULL, 'listening', 'listening_choice', 'Dengarkan komentar berita berikut. Bagaimana sifat dari kebijakan yang baru diumumkan?', '{"options":[{"id":"opt_1","text":"Kebijakan permanen yang tidak akan diubah selama sepuluh tahun"},{"id":"opt_2","text":"Langkah sementara yang akan ditinjau ulang secara mendasar tahun fiskal depan"},{"id":"opt_3","text":"Program sukarela yang hanya berlaku bagi perusahaan asing"},{"id":"opt_4","text":"Aturan lama yang sudah dicabut sejak tahun lalu"}],"audio_text":"今回導入された支援策はあくまで暫定措置であり、来年度には抜本的な見直しが予定されている。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, 'あくまで暫定措置であり berarti ''hanya merupakan langkah sementara (provisional measure)''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cfed1512-f807-40c6-a3bd-c5aef7e81aa9', 'c2bfed73-bf19-4235-8353-f02220a5e851', NULL, 'listening', 'listening_choice', 'Dengarkan cuplikan diskusi berikut. Apa tantangan yang ditekankan pembicara?', '{"options":[{"id":"opt_1","text":"Efisiensi kerja menurun drastis sejak teknologi baru diterapkan"},{"id":"opt_2","text":"Semua persoalan etika telah sepenuhnya terselesaikan"},{"id":"opt_3","text":"Dari sisi etika, masih banyak sekali permasalahan yang menumpuk"},{"id":"opt_4","text":"Biaya perangkat keras menjadi semakin murah setiap tahun"}],"audio_text":"技術革新によって業務効率は飛躍的に向上したが、倫理面では依然として課題が山積している。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '課題が山積している (kadai ga sanseki shite iru) berarti ''masalah/tantangan menumpuk bagai gunung''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('72f67100-e887-413e-ba77-2863739595ff', 'c2bfed73-bf19-4235-8353-f02220a5e851', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kita perlu mempertimbangkan persoalan ini dari berbagai sudut pandang."', '{"romaji":"Kono mondai wa takakuteki na shiten kara kentou suru hitsuyou ga aru.","display_text":"この問題は多角的な視点から検討する必要がある。","phonetic_breakdown":["ko-no","mon-dai","wa","ta-ka-ku-te-ki","na","shi-ten","ka-ra","ken-tou","su-ru","hi-tsu-you","ga","a-ru"]}'::jsonb, '{"expected_transcript":"この問題は多角的な視点から検討する必要がある。"}'::jsonb, NULL, NULL, '多角的な視点 (takakuteki na shiten) berarti ''sudut pandang multidimensi/beragam''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7cf2391b-90ad-45d6-b49e-865fb6391003', 'c2bfed73-bf19-4235-8353-f02220a5e851', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: 暫定的な___とはいえ、両国の対話が再開された意義は大きい。', '{"options":["合意","決裂","拒否","撤退"],"translation":"Meskipun baru kesepakatan sementara, makna dimulainya kembali dialog kedua negara sangatlah besar.","sentence_template":"暫定的な[blank]とはいえ、両国の対話が再開された意義は大きい。"}'::jsonb, '{"selected":"合意"}'::jsonb, NULL, NULL, '暫定的な合意 (kesepakatan sementara) adalah kolokasi diplomasi dan hukum bisnis N1.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('03bf2f30-3b8a-4997-a926-b0216cf90465', 'c2bfed73-bf19-4235-8353-f02220a5e851', 'd1000019-0000-0000-0000-000000000030', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun masih dalam tahap uji coba, hasilnya menunjukkan potensi yang menjanjikan."', '{"romaji":"Mada shiken dankai to wa ie, juubun ni jitsuyouka ga kitai dekiru kekka desu.","display_text":"まだ試験段階とはいえ、十分に実用化が期待できる結果です。","phonetic_breakdown":["まだ","しけんだんかいとはいえ","じゅうぶんに","じつようかがきたいできる","けっかです"]}'::jsonb, '{"expected_transcript":"まだ試験段階とはいえ、十分に実用化が期待できる結果です。"}'::jsonb, NULL, NULL, '試験段階とはいえ (meskipun masih tahap uji coba) umum dalam laporan R&D.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9439267d-cf09-4ef8-8c82-4ce79a96dcd5', 'c2f608f1-b8eb-4a78-8464-ae48422b7f86', 'd1000019-0000-0000-0000-000000000037', 'listening', 'listening_choice', 'Dengarkan pernyataan kepala penelitian. Apa syarat data agar bisa dijadikan bukti ilmiah?', '{"options":[{"id":"opt_1","text":"Hasil eksperimen yang belum terverifikasi keterulangannya tidak layak dipakai sebagai bukti ilmiah"},{"id":"opt_2","text":"Semua hasil eksperimen otomatis diterima sebagai bukti ilmiah"},{"id":"opt_3","text":"Eksperimen ilmiah tidak memerlukan keterulangan hasil"},{"id":"opt_4","text":"Peneliti tidak perlu mempublikasikan metode eksperimennya"}],"audio_text":"再現性が確認されていない実験結果は、科学的な証拠として採用するに足らない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '採用するに足らない menegaskan standar ketelitian ilmiah tingkat N1.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('21c840bd-f35e-4623-bf7b-b20f43798d48', 'c2f608f1-b8eb-4a78-8464-ae48422b7f86', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Usaha keras dan ketulusannya adalah hal yang sungguh patut dipuji."', '{"romaji":"Kare no doryoku to seijitsusa wa shousan ni taru mono da.","tokens":["誠実さは、","に","ものだ。","ともなると、","彼の努力と","称賛","足る","に足りない"],"target_translation":"Usaha keras dan ketulusannya adalah hal yang sungguh patut dipuji."}'::jsonb, '["彼の努力と","誠実さは、","称賛","に","足る","ものだ。"]'::jsonb, NULL, NULL, '称賛に足る (patut/layak mendapat pujian) adalah ungkapan apresiasi formal.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fc066e21-62cf-4326-b17c-f42872d80030', 'c2f608f1-b8eb-4a78-8464-ae48422b7f86', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 国際会議で発表するからには、専門家からの評価___完成度を目指すべきだ。', '{"options":["に足る","なりに","をもって","極まりない"],"translation":"Karena akan mempresentasikan di konferensi internasional, kita harus menargetkan tingkat kematangan yang layak dinilai para pakar.","sentence_template":"国際会議で発表するからには、専門家からの評価[blank]完成度を目指すべきだ。"}'::jsonb, '{"selected":"に足る"}'::jsonb, NULL, NULL, '評価に足る (layak untuk dinilai/diapresiasi) memakai kata benda 評価 + に足る.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7c6c120c-46fd-4463-aa93-81e496bf3ce9', 'c2f608f1-b8eb-4a78-8464-ae48422b7f86', 'd1000019-0000-0000-0000-000000000037', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pengalaman kegagalan sekalipun bukan hal yang patut disesali jika menjadi pelajaran berharga."', '{"romaji":"Shippai no keiken de attemo, tsugi ni tsunagaru nara nageku ni tarimasen.","display_text":"失敗の経験であっても、次につながるなら嘆くに足りません。","phonetic_breakdown":["しっぱいのけいけんであっても","つぎにつながるなら","なげくに","たりません"]}'::jsonb, '{"expected_transcript":"失敗の経験であっても、次につながるなら嘆くに足りません。"}'::jsonb, NULL, NULL, '嘆くに足りません (tidak layak untuk diratapi/disesali) adalah ungkapan reflektif formal N1.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3fcb8a8e-0fed-4fe5-9d56-1f5b53ae13d4', 'c2f608f1-b8eb-4a78-8464-ae48422b7f86', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 彼の長年にわたる社会貢献は、まさに賞賛___立派なものだ。', '{"options":["に足る","に至って","を余儀なくされ","とはいえ"],"translation":"Kontribusi sosialnya selama bertahun-tahun sungguh luar biasa dan patut mendapat pujian.","sentence_template":"彼の長年にわたる社会貢献は、まさに賞賛[blank]立派なものだ。"}'::jsonb, '{"selected":"に足る"}'::jsonb, NULL, NULL, '賞賛に足る (layak dipuji) memodifikasi フレーズ 立派なものだ.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ac684833-0444-474a-9090-8aeea2de97f0', 'c2f608f1-b8eb-4a78-8464-ae48422b7f86', 'd1000019-0000-0000-0000-000000000037', 'listening', 'listening_choice', 'Dengarkan tanggapan direktur riset. Mengapa ia menolak usulan proyek tersebut?', '{"options":[{"id":"opt_1","text":"Proposal itu sudah sangat matang dan siap disahkan"},{"id":"opt_2","text":"Dewan direksi telah menyetujui seluruh anggaran proposal"},{"id":"opt_3","text":"Ukuran pasarnya melampaui seluruh perkiraan"},{"id":"opt_4","text":"Karena sama sekali tidak ada data pendukung ukuran pasar, proposal itu belum layak diajukan ke rapat direksi"}],"audio_text":"市場規模の裏付けが全くなく、このままでは役員会に提出するに足りない企画だ。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '提出するに足りない berarti tidak cukup memenuhi standar untuk diajukan.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0f2a614-6a1e-4718-92b9-c86a36888ff2', 'c2f608f1-b8eb-4a78-8464-ae48422b7f86', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Mereka adalah mitra kerja yang sungguh layak untuk dipercaya sepenuhnya."', '{"romaji":"Karera wa kokoro kara shinrai suru ni taru paatonaa da.","tokens":["心から","に","パートナーだ。","いかんによらず、","彼らは","信頼する","足る","足らない"],"target_translation":"Mereka adalah mitra kerja yang sungguh layak untuk dipercaya sepenuhnya."}'::jsonb, '["彼らは","心から","信頼する","に","足る","パートナーだ。"]'::jsonb, NULL, NULL, '信頼するに足る (layak dipercaya) adalah kolokasi yang sangat sering diujikan pada JLPT N1.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('06621d7c-96e2-4d97-a0bb-daa32bc263fc', 'c2f608f1-b8eb-4a78-8464-ae48422b7f86', 'd1000019-0000-0000-0000-000000000037', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dengan kesiapan ini, Anda telah memiliki kemampuan yang layak untuk menantang JLPT N1."', '{"romaji":"Kore made no kensan no seika wa, juubun ni jishin o motsu ni taru mono desu.","display_text":"これまでの研鑽の成果は、十分に自信を持つに足るものです。","phonetic_breakdown":["これまでの","けんさんのせいかは","じゅうぶんに","じしんをもつに","たるものです"]}'::jsonb, '{"expected_transcript":"これまでの研鑽の成果は、十分に自信を持つに足るものです。"}'::jsonb, NULL, NULL, '自信を持つに足る (layak untuk merasa percaya diri) menjadi penutup motivasi kurikulum N1.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('26154a75-11f0-45a0-bf93-7c15be3fc25f', 'c492a2c2-1e1e-4a02-b204-65ff22d66229', 'd1000019-0000-0000-0000-000000000036', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang latar belakang, semua anggota memiliki hak yang sama."', '{"romaji":"Shusshin ya keireki no ikan ni yorazu, zenkaiin wa byoudou no kenri wo yuusuru.","display_text":"出身や経歴のいかんによらず、全会員は平等の権利を有する。","phonetic_breakdown":["shu-sshin","ya","kei-re-ki","no","i-kan","ni","yo-ra-zu","zen-kai-in","wa","byou-dou","no","ken-ri","wo","yuu-su-ru"]}'::jsonb, '{"expected_transcript":"出身や経歴のいかんによらず、全会員は平等の権利を有する。"}'::jsonb, NULL, NULL, '権利を有する (memiliki hak) adalah istilah baku dalam anggaran dasar dan peraturan organisasi.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8bc0e288-4131-4ac4-87a6-796114c947ca', 'c492a2c2-1e1e-4a02-b204-65ff22d66229', 'd1000019-0000-0000-0000-000000000036', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang alasan, kekerasan tidak pernah dapat dibenarkan."', '{"romaji":"Ikanaru riyuu no ikan ni yorazu, bouryoku wa kesshite younin sarenai.","display_text":"いかなる理由のいかんによらず、暴力は決して容認されない。","phonetic_breakdown":["i-ka-na-ru","ri-yuu","no","i-kan","ni","yo-ra-zu","bou-ryo-ku","wa","ke-sshi-te","you-nin","sa-re-nai"]}'::jsonb, '{"expected_transcript":"いかなる理由のいかんによらず、暴力は決して容認されない。"}'::jsonb, NULL, NULL, '容認されない (younin sarenai) berarti ''tidak dapat dibenarkan/ditoleransi''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a0e78499-51b5-48e6-b972-16cb1cbcc7b1', 'c492a2c2-1e1e-4a02-b204-65ff22d66229', 'd1000019-0000-0000-0000-000000000036', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang skala perusahaan, perlindungan data adalah kewajiban bersama."', '{"romaji":"Kigyou kibo no ikan ni kakawarazu, kojin jouhou hogo no tettei ga motomerareru.","display_text":"企業規模のいかんにかかわらず、個人情報保護の徹底が求められる。","phonetic_breakdown":["ki-gyou","ki-bo","no","i-kan","ni","ka-ka-wa-ra-zu","ko-jin","jou-hou","ho-go","no","te-ttei","ga","mo-to-me-ra-re-ru"]}'::jsonb, '{"expected_transcript":"企業規模のいかんにかかわらず、個人情報保護の徹底が求められる。"}'::jsonb, NULL, NULL, '個人情報保護の徹底 (penerapan ketat perlindungan data pribadi).', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('77d393bd-2561-44c2-b032-4139f52946a2', 'c492a2c2-1e1e-4a02-b204-65ff22d66229', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang hasil ujian, usahamu selama ini tidak sia-sia."', '{"romaji":"Gouhi no ikan ni yorazu kore made no doryoku wa muda ni naranai.","tokens":["努力は","よらず","をもって","これまでの","無駄にならない","合否の","いかんに","極まりない"],"target_translation":"Tanpa memandang hasil ujian, usahamu selama ini tidak sia-sia."}'::jsonb, '["合否の","いかんに","よらず","これまでの","努力は","無駄にならない"]'::jsonb, NULL, NULL, '合否のいかんによらず berarti ''tanpa memandang lulus atau tidak lulus''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5b353c77-d88b-4036-ae0b-431808c2e760', 'c492a2c2-1e1e-4a02-b204-65ff22d66229', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang posisi, semua karyawan wajib mematuhi kode etik."', '{"romaji":"Tachiba no ikan ni yorazu koudou kihan wo junshu suru gimu ga aru.","tokens":["義務がある","とはいえ","なりに","よらず","いかんに","立場の","遵守する","行動規範を"],"target_translation":"Tanpa memandang posisi, semua karyawan wajib mematuhi kode etik."}'::jsonb, '["立場の","いかんに","よらず","行動規範を","遵守する","義務がある"]'::jsonb, NULL, NULL, '行動規範を遵守する (mematuhi kode etik perilaku).', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('34215abe-fc50-402e-a52d-92a1a80b27de', 'c492a2c2-1e1e-4a02-b204-65ff22d66229', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Bergantung pada isi jawaban pihak lawan, kami akan meninjau langkah berikutnya."', '{"romaji":"Senpou no kaitou ikan de wa tsugi no taiou wo kentou suru.","tokens":["次の","いかんでは","対応を","に至って","回答","ながら","先方の","検討する"],"target_translation":"Bergantung pada isi jawaban pihak lawan, kami akan meninjau langkah berikutnya."}'::jsonb, '["先方の","回答","いかんでは","次の","対応を","検討する"]'::jsonb, NULL, NULL, '回答いかんでは (bergantung pada bagaimana jawaban pihak lawan).', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4ba0929-4c87-4c0c-a7e7-38cb96d68ed7', 'c492a2c2-1e1e-4a02-b204-65ff22d66229', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Pilih pola yang tepat: 相手との関係性の___、監査業務は客観的かつ中立に遂行される。', '{"options":["いかんによらず","極まりなく","ずにはおかず","に足らず"],"translation":"Tanpa memandang hubungan dengan pihak terkait, tugas audit dijalankan secara objektif dan netral.","sentence_template":"相手との関係性の[blank]、監査業務は客観的かつ中立に遂行される。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, NULL, NULL, '関係性のいかんによらず menegaskan independensi auditor.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('890c6cb9-ed43-4af1-85a6-45c78a40f441', 'c492a2c2-1e1e-4a02-b204-65ff22d66229', 'd1000019-0000-0000-0000-000000000036', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang skala proyek, standar kualitas kami tidak pernah berubah."', '{"romaji":"Anken kibo no ikan ni yorazu, heisha no hinshitsu kijun wa issai kawarimasen.","display_text":"案件規模のいかんによらず、弊社の品質基準は一切変わりません。","phonetic_breakdown":["あんけんきぼの","いかんによらず","へいしゃのひんしつきじゅんは","いっさいかわりません"]}'::jsonb, '{"expected_transcript":"案件規模のいかんによらず、弊社の品質基準は一切変わりません。"}'::jsonb, NULL, NULL, '品質基準は一切変わりません menguatkan komitmen mutu yang konsisten.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e196849b-6e72-42f5-9a00-b6d049c100db', 'c7333e80-1e36-40e9-9cbf-4b1daef01a6b', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Lengkapi kalimat ulasan seni berikut: 彼女の力強い歌声は、聴く者すべてを感動させ___。', '{"options":["ずにはおかない","ざるを得ない","かねない","に足らない"],"translation":"Suara nyanyiannya yang penuh daya pasti akan menggetarkan hati setiap pendengarnya.","sentence_template":"彼女の力強い歌声は、聴く者すべてを感動させ[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, NULL, NULL, 'Kata kerja (bentuk nai, ganti ない -> ず) + にはおかない menyatakan bahwa sesuatu pasti/niscaya menimbulkan efek tertentu.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('303f1894-169f-486e-9293-8d86e6e2c1b3', 'c7333e80-1e36-40e9-9cbf-4b1daef01a6b', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk kata kerja する: このスキャンダルは、政権の支持率に深刻な打撃を与えず___。', '{"options":["にはかなわない","にはいられない","にはすまない","にはおかない"],"translation":"Skandal ini pasti akan memberikan pukulan serius pada tingkat dukungan pemerintah.","sentence_template":"このスキャンダルは、政権の支持率に深刻な打撃を与えず[blank]。"}'::jsonb, '{"selected":"にはおかない"}'::jsonb, NULL, NULL, '与えずにはおかない berarti ''niscaya akan memberikan (pukulan serius)'' secara objektif/tak terelakkan.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d2e0ff0-6eee-477b-9823-a0a5b0966aff', 'c7333e80-1e36-40e9-9cbf-4b1daef01a6b', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Lengkapi kalimat yang menyatakan tekad kuat berikut: 今回の不当な扱いに対しては、必ず真相を究明し___。', '{"options":["どころではない","ようがない","かねない","ないではおかない"],"translation":"Terhadap perlakuan tidak adil kali ini, saya bertekad pasti akan mengungkap kebenarannya.","sentence_template":"今回の不当な扱いに対しては、必ず真相を究明し[blank]。"}'::jsonb, '{"selected":"ないではおかない"}'::jsonb, NULL, NULL, '～ないではおかない (atau せずにはおかない) juga digunakan untuk menyatakan tekad kuat pembicara bahwa ia pasti akan melakukannya.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e1f04863-a21f-44be-a93f-bc7c749f00e0', 'c7333e80-1e36-40e9-9cbf-4b1daef01a6b', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Kebijakan itu pasti akan memicu perdebatan sengit di masyarakat."', '{"romaji":"Sono seisaku wa shakai ni hageshii giron wo makiokosazu ni wa okanai.","tokens":["をもって","なりに","巻き起こさ","激しい","社会に","議論を","その政策は","ずにはおかない"],"target_translation":"Kebijakan itu pasti akan memicu perdebatan sengit di masyarakat."}'::jsonb, '["その政策は","社会に","激しい","議論を","巻き起こさ","ずにはおかない"]'::jsonb, NULL, NULL, '議論を巻き起こす (membangkitkan perdebatan) -> 巻き起こさずにはおかない (pasti akan membangkitkan perdebatan).', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('baefcafa-3be6-4645-adde-5d9938b470f7', 'c7333e80-1e36-40e9-9cbf-4b1daef01a6b', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Keindahan pemandangan itu pasti memukau siapa pun yang melihatnya."', '{"romaji":"Sono zekkei wa miru hito no kokoro wo ubawazu ni wa okanai.","tokens":["心を","見る人の","とはいえ","ずには","おかない","に至って","その絶景は","奪わ"],"target_translation":"Keindahan pemandangan itu pasti memukau siapa pun yang melihatnya."}'::jsonb, '["その絶景は","見る人の","心を","奪わ","ずには","おかない"]'::jsonb, NULL, NULL, '心を奪う (memikat/merenggut hati) -> 奪わずにはおかない.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e8a39510-5eb1-4e5f-a186-69d6e9aa321f', 'c7333e80-1e36-40e9-9cbf-4b1daef01a6b', 'd1000019-0000-0000-0000-000000000034', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Laporan tersebut pasti akan mengubah cara pandang publik."', '{"romaji":"Sono chousa houkoku wa, seron no ninshiki wo kaezu ni wa okanai darou.","display_text":"その調査報告は、世論の認識を変えずにはおかないだろう。","phonetic_breakdown":["so-no","chou-sa","hou-ko-ku","wa","se-ron","no","nin-shi-ki","wo","ka-e-zu","ni","wa","o-ka-nai","da-rou"]}'::jsonb, '{"expected_transcript":"その調査報告は、世論の認識を変えずにはおかないだろう。"}'::jsonb, NULL, NULL, '変えずにはおかないだろう berarti ''pasti akan mengubah (persepsi opini publik)''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('31762cf2-f336-4de5-aa5d-d332cc527666', 'c7333e80-1e36-40e9-9cbf-4b1daef01a6b', 'd1000019-0000-0000-0000-000000000034', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa perbedaan nuansa ～ずにはおかない di sini?', '{"options":[{"id":"opt_1","text":"Akhir film itu pasti secara alami mengundang air mata penonton setenang apa pun"},{"id":"opt_2","text":"Penonton dilarang menangis di dalam bioskop"},{"id":"opt_3","text":"Akhir film itu sangat lucu dan mengundang tawa"},{"id":"opt_4","text":"Film itu tidak memiliki akhir cerita"}],"audio_text":"あの映画の結末は、どんな冷静な観客であっても涙を誘わずにはおかない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '涙を誘わずにはおかない menunjukkan efek emosional yang tak terhindarkan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a6e32538-ddb1-4adc-a5da-30c46758eeec', 'c7333e80-1e36-40e9-9cbf-4b1daef01a6b', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Lengkapi kalimat dengan konjugasi yang benar: 真実を知った彼女は、真犯人を徹底的に追及___。', '{"options":["せずにはおかないだろう","しずにはおかないだろう","すずにはおかないだろう","さずにはおかないだろう"],"translation":"Setelah mengetahui kebenaran, ia pasti akan mengusut pelaku sebenarnya sampai tuntas (tekad tak terbendung).","sentence_template":"真実を知った彼女は、真犯人を徹底的に追及[blank]。"}'::jsonb, '{"selected":"せずにはおかないだろう"}'::jsonb, NULL, NULL, '追及する -> 追及せずにはおかない juga dipakai untuk tekad kuat ''pasti akan melakukan''.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e94623c1-15b0-4c80-9974-63398eda598d', 'c8386cfe-7132-44ca-b55a-79aa4744148e', NULL, 'reading', 'fill_blank', 'Pilih istilah korporasi yang tepat: 東証プライム市場の___には、極めて高い情報開示の透明性が求められる。', '{"options":["個人商店","任意団体","同好会","上場企業"],"translation":"Perusahaan terbuka di pasar Prime Bursa Tokyo dituntut memiliki transparansi keterbukaan informasi yang sangat tinggi.","sentence_template":"東証プライム市場の[blank]には、極めて高い情報開示の透明性が求められる。"}'::jsonb, '{"selected":"上場企業"}'::jsonb, NULL, NULL, '上場企業 (joujou kigyou) berarti ''perusahaan tercatat/terbuka (Tbk)'' di bursa efek.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('806e520b-37a7-41ce-a705-627c14021fd4', 'c8386cfe-7132-44ca-b55a-79aa4744148e', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat tata kelola perusahaan berikut: 重要な買収案件は、___の承認を経て正式に決定される。', '{"options":["懇親会","町内会","同窓会","取締役会"],"translation":"Rencana akuisisi penting diputuskan secara resmi setelah melalui persetujuan dewan direksi.","sentence_template":"重要な買収案件は、[blank]の承認を経て正式に決定される。"}'::jsonb, '{"selected":"取締役会"}'::jsonb, NULL, NULL, '取締役会 (torishimariyakukai) berarti ''rapat/dewan direksi (Board of Directors)''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ebaade42-dbdf-4a97-bede-e2b96e711d32', 'c8386cfe-7132-44ca-b55a-79aa4744148e', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk konteks kebijakan makro: ___の編成にあたっては、将来の世代への負担も考慮しなければならない。', '{"options":["領収書","国家予算","家計簿","小遣い"],"translation":"Dalam penyusunan anggaran negara, beban bagi generasi mendatang juga harus diperhitungkan.","sentence_template":"[blank]の編成にあたっては、将来の世代への負担も考慮しなければならない。"}'::jsonb, '{"selected":"国家予算"}'::jsonb, NULL, NULL, '国家予算の編成 berarti ''penyusunan anggaran pendapatan dan belanja negara (APBN)''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('59ead0d0-905e-42ff-8bef-78c2d486eba5', 'c8386cfe-7132-44ca-b55a-79aa4744148e', NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan kepala keamanan berikut. Apa yang dipersiapkan untuk acara tersebut?', '{"options":[{"id":"opt_1","text":"Sistem pengamanan yang sangat ketat dan luar biasa diterapkan menyambut konferensi para pemimpin negara"},{"id":"opt_2","text":"Konferensi dibuka bebas untuk umum tanpa pemeriksaan identitas"},{"id":"opt_3","text":"Jumlah petugas keamanan dikurangi demi menghemat anggaran"},{"id":"opt_4","text":"Acara dipindahkan ke luar ruangan di taman kota"}],"audio_text":"各国首脳が集う国際会議の開催にあたり、例年にない厳重な警備体制が敷かれている。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '厳重な警備体制が敷かれている berarti ''sistem pengamanan ketat diberlakukan''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d086b2a0-e816-44a7-993c-aae520fa0042', 'c8386cfe-7132-44ca-b55a-79aa4744148e', NULL, 'listening', 'listening_choice', 'Dengarkan komentar pelatih olahraga berikut. Apa perbedaan turnamen tingkat dunia?', '{"options":[{"id":"opt_1","text":"Hanya keberuntungan semata yang menentukan pemenang"},{"id":"opt_2","text":"Bukan hanya teknik, melainkan ketangguhan mental ekstrem yang menentukan menang-kalah"},{"id":"opt_3","text":"Atlet tidak perlu berlatih teknik sebelum bertanding"},{"id":"opt_4","text":"Pertandingan final selalu berakhir seri"}],"audio_text":"世界選手権の決勝の舞台では、技術だけでなく極限の精神力が勝敗を分ける。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '極限の精神力が勝敗を分ける berarti ''kekuatan mental di titik ekstrem menentukan kemenangan atau kekalahan''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('59523458-77e0-4d23-9450-d48ff37accb4', 'c8386cfe-7132-44ca-b55a-79aa4744148e', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Semakin tinggi jabatan, semakin besar pula tanggung jawab sosialnya."', '{"romaji":"Yakushoku ga agaru hodo, shakaiteki na sekinin mo omoku naru.","display_text":"役職が上がるほど、社会的な責任も重くなる。","phonetic_breakdown":["ya-ku-sho-ku","ga","a-ga-ru","ho-do","sha-kai-te-ki","na","se-ki-nin","mo","o-mo-ku","na-ru"]}'::jsonb, '{"expected_transcript":"役職が上がるほど、社会的な責任も重くなる。"}'::jsonb, NULL, NULL, '社会的な責任 (tanggung jawab sosial) meningkat seiring tingginya 役職 (jabatan).', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('52b69c7e-1d24-44af-b076-a65b0e92bb87', 'c8386cfe-7132-44ca-b55a-79aa4744148e', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: 役員クラスともなると、長期的な経営___を描く力が求められる。', '{"options":["戦略","趣味","雑談","休暇"],"translation":"Jika sudah mencapai kelas direksi, dituntut kemampuan merancang strategi/visi manajemen jangka panjang.","sentence_template":"役員クラスともなると、長期的な経営[blank]を描く力が求められる。"}'::jsonb, '{"selected":"戦略"}'::jsonb, NULL, NULL, '経営戦略を描く (merancang strategi manajemen) adalah kolokasi bisnis tingkat eksekutif.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('68f8189d-fe5e-4a4e-a82a-afddd1375d71', 'c8386cfe-7132-44ca-b55a-79aa4744148e', 'd1000019-0000-0000-0000-000000000035', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjadi restoran bintang tiga, detail pelayanan terkecil pun diperhatikan dengan saksama."', '{"romaji":"Mitsuboshi resutoran to mo naru to, sekkyaku no saibu made kanpeki ni hairyo sarete imasu.","display_text":"三つ星レストランともなると、接客の細部まで完璧に配慮されています。","phonetic_breakdown":["みつぼしれすとらんと","もなると","せっきゃくのさいぶまで","かんぺきにはいりょ","されています"]}'::jsonb, '{"expected_transcript":"三つ星レストランともなると、接客の細部まで完璧に配慮されています。"}'::jsonb, NULL, NULL, '細部まで完璧に配慮する menggambarkan standar layanan kelas dunia.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('75c5bae1-2d40-4894-abd9-959ab9f47674', 'd3809777-686d-4bd1-bcb2-c9cb38d00b17', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Lengkapi kalimat bisnis berikut: 国際的な大企業の社長___、一つの発言が株価を大きく左右する。', '{"options":["ともなると","なりに","とはいえ","をもって"],"translation":"Jika sudah sampai pada posisi direktur utama perusahaan multinasional besar, satu pernyataan saja sangat memengaruhi harga saham.","sentence_template":"国際的な大企業の社長[blank]、一つの発言が株価を大きく左右する。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, NULL, NULL, '～ともなると / ～ともなれば menyoroti standar, dampak, atau tuntutan khusus ketika mencapai level/skala tinggi.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6b266b69-e80a-4216-a50b-ca06a96b6e4f', 'd3809777-686d-4bd1-bcb2-c9cb38d00b17', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Pilih bentuk yang tepat untuk tingkat keahlian: プロのオーケストラの演奏者___、わずかな音程のずれも許されない。', '{"options":["ともなれば","に至っては","を余儀なくされ","極まりなく"],"translation":"Jika sudah mencapai level musisi orkestra profesional, penyimpangan nada sekecil apa pun tidak ditoleransi.","sentence_template":"プロのオーケストラの演奏者[blank]、わずかな音程のずれも許されない。"}'::jsonb, '{"selected":"ともなれば"}'::jsonb, NULL, NULL, '～ともなれば adalah varian kondisional yang sangat alami dengan ～ともなると.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f6f61109-a268-426a-a49d-5d56ede042ee', 'd3809777-686d-4bd1-bcb2-c9cb38d00b17', 'd1000019-0000-0000-0000-000000000035', 'listening', 'listening_choice', 'Dengarkan wawancara direktur konstruksi. Apa yang membedakan proyek berskala nasional?', '{"options":[{"id":"opt_1","text":"Proyek skala nasional bisa diselesaikan dalam dua hari tanpa koordinasi"},{"id":"opt_2","text":"Jika sudah sampai proyek nasional bernilai puluhan miliar yen, koordinasi dengan kementerian terkait saja memakan waktu sangat besar"},{"id":"opt_3","text":"Proyek nasional tidak memerlukan persetujuan pemerintah"},{"id":"opt_4","text":"Anggaran proyek nasional selalu lebih kecil dari proyek lokal"}],"audio_text":"総事業費が数百億円規模の国家プロジェクトともなると、関係省庁との調整だけでも膨大な時間を要します。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '国家プロジェクトともなると menekankan kompleksitas khusus pada skala proyek raksasa.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f79fec95-2c32-425c-8a5b-3af03f12234b', 'd3809777-686d-4bd1-bcb2-c9cb38d00b17', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah memasuki bulan Desember, pusat kota dipenuhi suasana akhir tahun."', '{"romaji":"Juunigatsu to mo naru to, toshin wa shiwasu no funiki ni tsutsumareru.","tokens":["とも","都心は","包まれる。","包まれた。","十二月","なると、","師走の雰囲気に","なりに、"],"target_translation":"Jika sudah memasuki bulan Desember, pusat kota dipenuhi suasana akhir tahun."}'::jsonb, '["十二月","とも","なると、","都心は","師走の雰囲気に","包まれる。"]'::jsonb, NULL, NULL, '十二月ともなると (jika sudah sampai bulan Desember) menandai perubahan suasana khas musim.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2465a7b0-0da6-40ce-8c07-d6213012b26b', 'd3809777-686d-4bd1-bcb2-c9cb38d00b17', 'd1000019-0000-0000-0000-000000000035', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika sudah menjabat kepala departemen, kita harus memikirkan strategi seluruh perusahaan."', '{"romaji":"Buchou kurasu to mo naru to, jibusho dake de naku zenshateki na shiten ga motomeraremasu.","display_text":"部長クラスともなると、自部署だけでなく全社的な視点が求められます。","phonetic_breakdown":["ぶちょうくらす","ともなると","じぶしょだけでなく","ぜんしゃてきなしてんが","もとめられます"]}'::jsonb, '{"expected_transcript":"部長クラスともなると、自部署だけでなく全社的な視点が求められます。"}'::jsonb, NULL, NULL, '部長クラスともなると menegaskan ekspektasi kepemimpinan tingkat eksekutif.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8e3c36d6-a5fb-4c7d-b1e5-9dec90275211', 'd3809777-686d-4bd1-bcb2-c9cb38d00b17', 'd1000019-0000-0000-0000-000000000035', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 大学院の博士課程___、自ら独自の研究テーマを切り開く力が不可欠だ。', '{"options":["ともなると","ずにはおかず","に足らず","いかんによらず"],"translation":"Jika sudah masuk jenjang doktoral pascasarjana, kemampuan merintis topik penelitian orisinal sendiri mutlak diperlukan.","sentence_template":"大学院の博士課程[blank]、自ら独自の研究テーマを切り開く力が不可欠だ。"}'::jsonb, '{"selected":"ともなると"}'::jsonb, NULL, NULL, '博士課程ともなると membedakan tuntutan jenjang doktoral dari jenjang sebelumnya.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ce1776aa-e3ff-4537-8c90-2cc8c4146b45', 'd3809777-686d-4bd1-bcb2-c9cb38d00b17', 'd1000019-0000-0000-0000-000000000035', 'listening', 'listening_choice', 'Dengarkan percakapan dua peneliti. Apa tantangan jika hasil riset dipublikasikan di jurnal top dunia?', '{"options":[{"id":"opt_1","text":"Jurnal ilmiah top dunia tidak memiliki proses penelaahan sejawat"},{"id":"opt_2","text":"Siapa saja bisa langsung menerbitkan tulisan dalam satu jam"},{"id":"opt_3","text":"Jika sudah sampai level memuat makalah di jurnal ilmiah puncak dunia, ketatnya proses peer-review melampaui bayangan"},{"id":"opt_4","text":"Peneliti tidak perlu menyertakan data eksperimen"}],"audio_text":"世界最高峰の学術誌に論文を載せるレベルともなれば、査読の厳しさは想像を超えるよ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, 'レベルともなれば menyoroti standar ketat yang menyertai pencapaian level tertinggi.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fee98328-0204-48a7-9075-7a03230b077d', 'd3809777-686d-4bd1-bcb2-c9cb38d00b17', 'd1000019-0000-0000-0000-000000000035', 'writing', 'sentence_builder', 'Susun kalimat: "Jika sudah mencapai tingkat JLPT N1, Anda diharapkan mampu memahami tajuk rencana koran."', '{"romaji":"N1 reberu to mo naru to, shinbun no shasetsu o rikai suru chikara ga kitai sareru.","tokens":["とも","新聞の社説を","期待される。","期待した。","N1レベル","なると、","理解する力が","とはいえ、"],"target_translation":"Jika sudah mencapai tingkat JLPT N1, Anda diharapkan mampu memahami tajuk rencana koran."}'::jsonb, '["N1レベル","とも","なると、","新聞の社説を","理解する力が","期待される。"]'::jsonb, NULL, NULL, 'N1レベルともなると menegaskan standar kompetensi bahasa tingkat lanjut.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('45588c6b-acee-4a89-aae3-cee0c5ba908b', 'd406e447-80a3-4c75-9302-82ddea97767f', NULL, 'reading', 'fill_blank', 'Pilih istilah akademis yang tepat: 主張を裏付ける客観的な___が不足しているため、再調査が必要だ。', '{"options":["噂話","根拠","偏見","空想"],"translation":"Karena dasar/bukti objektif yang mendukung argumen masih kurang, penyelidikan ulang diperlukan.","sentence_template":"主張を裏付ける客観的な[blank]が不足しているため、再調査が必要だ。"}'::jsonb, '{"selected":"根拠"}'::jsonb, NULL, NULL, '客観的な根拠 (kyakkanteki na konkyo) berarti ''dasar/bukti yang objektif''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dcf2d6d1-baba-44b0-981e-502b98349223', 'd406e447-80a3-4c75-9302-82ddea97767f', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat evaluasi profesional berikut: 長年の確かな___により、その企業は業界内外から厚い信頼を得ている。', '{"options":["失敗","遅延","実績","誇張"],"translation":"Berkat rekam jejak nyata selama bertahun-tahun, perusahaan itu memperoleh kepercayaan mendalam dari dalam dan luar industri.","sentence_template":"長年の確かな[blank]により、その企業は業界内外から厚い信頼を得ている。"}'::jsonb, '{"selected":"実績"}'::jsonb, NULL, NULL, '確かな実績 (tashika na jisseki) berarti ''rekam jejak/pencapaian nyata yang terbukti''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('736591ae-c20f-48bf-8563-c85805ec7193', 'd406e447-80a3-4c75-9302-82ddea97767f', NULL, 'reading', 'fill_blank', 'Pilih kata kerja formal untuk menguji kebenaran data: 提出された仮説の妥当性を、複数の実験によって徹底的に___した。', '{"options":["憶測","無視","検証","放置"],"translation":"Keabsahan hipotesis yang diajukan telah diverifikasi secara menyeluruh melalui beberapa eksperimen.","sentence_template":"提出された仮説の妥当性を、複数の実験によって徹底的に[blank]した。"}'::jsonb, '{"selected":"検証"}'::jsonb, NULL, NULL, '妥当性を検証する (datousei wo kenshou suru) berarti ''memverifikasi keabsahan/validitas''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('87d7f391-d5dd-48a7-9582-6ef39b63a888', 'd406e447-80a3-4c75-9302-82ddea97767f', NULL, 'listening', 'listening_choice', 'Dengarkan komentar juri penghargaan berikut. Mengapa penelitian itu dipuji tinggi?', '{"options":[{"id":"opt_1","text":"Penelitian itu tidak memiliki kebaruan sama sekali"},{"id":"opt_2","text":"Penelitian itu bernilai sangat tinggi dari sisi kebaruan dan makna sosialnya"},{"id":"opt_3","text":"Penelitian itu ditolak karena kurang relevan bagi masyarakat"},{"id":"opt_4","text":"Penelitian itu belum selesai diuji di laboratorium"}],"audio_text":"この研究は新規性と社会的意義の両面において極めて価値が高く、国際的な評価に値する。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '新規性と社会的意義 (kebaruan dan signifikansi sosial) menjadikannya bernilai sangat tinggi.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('95505aca-edd2-49cd-b75e-fe0ed6ddeb2e', 'd406e447-80a3-4c75-9302-82ddea97767f', NULL, 'listening', 'listening_choice', 'Dengarkan pendapat rekan kerja berikut. Bagaimana penilaiannya terhadap pemimpin baru tersebut?', '{"options":[{"id":"opt_1","text":"Ia sosok yang dihormati semua orang berkat kepribadian tulus dan penilaian yang tepat"},{"id":"opt_2","text":"Ia sering ragu-ragu dalam mengambil keputusan penting"},{"id":"opt_3","text":"Ia jarang berkomunikasi dengan anggota timnya"},{"id":"opt_4","text":"Ia baru saja mengundurkan diri dari jabatannya"}],"audio_text":"誠実な人柄と的確な判断力を兼ね備えた彼女は、誰からも敬意を集める人物だ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '誠実な人柄と的確な判断力を兼ね備えた berarti ''memadukan karakter tulus dan daya nilai yang jitu''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('82632148-cda7-4645-9587-267ff0211e9b', 'd406e447-80a3-4c75-9302-82ddea97767f', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Usulan itu memiliki dasar yang kuat dan layak dipertimbangkan."', '{"romaji":"Sono teian ni wa meikaku na konkyo ga ari, kentou suru kachi ga juubun ni aru.","display_text":"その提案には明確な根拠があり、検討する価値が十分にある。","phonetic_breakdown":["so-no","tei-an","ni","wa","mei-ka-ku","na","kon-kyo","ga","a-ri","ken-tou","su-ru","ka-chi","ga","juu-bun","ni","a-ru"]}'::jsonb, '{"expected_transcript":"その提案には明確な根拠があり、検討する価値が十分にある。"}'::jsonb, NULL, NULL, '明確な根拠 (dasar yang jelas) dan 検討する価値 (nilai kelayakan untuk dikaji).', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('44968743-e276-4dbb-864e-351fda1cb376', 'd406e447-80a3-4c75-9302-82ddea97767f', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: この報告書は経営判断の材料として十分に___に足る。', '{"options":["信頼","撤回","放棄","無視"],"translation":"Laporan ini sangat layak dipercaya sebagai bahan pengambilan keputusan manajemen.","sentence_template":"この報告書は経営判断の材料として十分に[blank]に足る。"}'::jsonb, '{"selected":"信頼"}'::jsonb, NULL, NULL, '信頼に足る (layak dipercaya) adalah pasangan kosakata paling klasik dengan ～に足る.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1aa9cead-690e-4576-9045-91e1adfd9028', 'd406e447-80a3-4c75-9302-82ddea97767f', 'd1000019-0000-0000-0000-000000000037', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karya inovasi tersebut benar-benar patut dibanggakan kepada dunia."', '{"romaji":"Kono kakushinteki na gijutsu wa, sekai ni hokoru ni taru igyou desu.","display_text":"この革新的な技術は、世界に誇るに足る偉業です。","phonetic_breakdown":["このかくしんてきな","ぎじゅつは","せかいにほこるにたる","いぎょうです"]}'::jsonb, '{"expected_transcript":"この革新的な技術は、世界に誇るに足る偉業です。"}'::jsonb, NULL, NULL, '世界に誇るに足る (layak dibanggakan kepada dunia) adalah ungkapan formal tingkat tinggi.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5bd3e6ba-e6ba-4194-9962-a8a5a365c470', 'd682e234-08e7-4ab2-af42-f0f3f5a6f602', 'd1000019-0000-0000-0000-000000000033', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Jika waktunya sempit, mari kita susun prioritas sesuai kondisi itu."', '{"romaji":"Jikan ga kagirarete iru nara kagirarete iru nari ni, yuusen jun''i wo meikaku ni shiyou.","display_text":"時間が限られているなら限られているなりに、優先順位を明確にしよう。","phonetic_breakdown":["ji-kan","ga","ka-gi-ra-re-te","i-ru","na-ra","ka-gi-ra-re-te","i-ru","na-ri","ni","yuu-sen","jun-i","wo","mei-ka-ku","ni","shi-you"]}'::jsonb, '{"expected_transcript":"時間が限られているなら限られているなりに、優先順位を明確にしよう。"}'::jsonb, NULL, NULL, 'Pola ～なら～なりに menegaskan sikap adaptif dan solutif di tengah keterbatasan.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8b60953c-c81f-4477-bd0b-17306aab9737', 'd682e234-08e7-4ab2-af42-f0f3f5a6f602', 'd1000019-0000-0000-0000-000000000033', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Setiap generasi memiliki nilai dan cara pandangnya sendiri."', '{"romaji":"Sorezore no sedai ni wa, sorezore no sedai nari no kachikan ga aru.","display_text":"それぞれの世代には、それぞれの世代なりの価値観がある。","phonetic_breakdown":["so-re-zo-re","no","se-dai","ni","wa","so-re-zo-re","no","se-dai","na-ri","no","ka-chi-kan","ga","a-ru"]}'::jsonb, '{"expected_transcript":"それぞれの世代には、それぞれの世代なりの価値観がある。"}'::jsonb, NULL, NULL, '価値観 (kachikan: nilai-nilai / pandangan hidup) dipadukan dengan ～なりの.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('888b0dbf-2a16-464b-9fb2-45e6cb200e16', 'd682e234-08e7-4ab2-af42-f0f3f5a6f602', 'd1000019-0000-0000-0000-000000000033', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya pun telah memikirkan masalah ini matang-matang dengan cara saya sendiri."', '{"romaji":"Watashi to shite mo, watashi nari ni kono ken wo shinken ni kentou shite kimashita.","display_text":"私としても、私なりにこの件を真剣に検討してきました。","phonetic_breakdown":["wa-ta-shi","to","shi-te","mo","wa-ta-shi","na-ri","ni","ko-no","ken","wo","shin-ken","ni","ken-tou","shi-te","ki-ma-shi-ta"]}'::jsonb, '{"expected_transcript":"私としても、私なりにこの件を真剣に検討してきました。"}'::jsonb, NULL, NULL, 'Ungkapan sopan dan tegas saat menyampaikan hasil pemikiran pribadi dalam forum kerja.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b693227c-2263-402a-b87d-8644ab872f75', 'd682e234-08e7-4ab2-af42-f0f3f5a6f602', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Sesuai usianya, dia menunjukkan kedewasaan yang mengagumkan."', '{"romaji":"Nenrei nari ni ochitsuita handanryoku wo mi ni tsukete iru.","tokens":["身につけて","落ち着いた","極まりない","なりに","判断力を","いる","をもって","年齢"],"target_translation":"Sesuai usianya, dia menunjukkan kedewasaan yang mengagumkan."}'::jsonb, '["年齢","なりに","落ち着いた","判断力を","身につけて","いる"]'::jsonb, NULL, NULL, '年齢なりに berarti ''sesuai dengan usianya''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3ab0a8f0-950b-411b-934e-8beee26819e1', 'd682e234-08e7-4ab2-af42-f0f3f5a6f602', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun bukan ahli, saya ingin berkontribusi sesuai kemampuan saya."', '{"romaji":"Senmonka de nakute mo jibun nari ni shakai ni kouken shitai.","tokens":["専門家で","自分","に至って","なりに","とはいえ","なくても","社会に","貢献したい"],"target_translation":"Meskipun bukan ahli, saya ingin berkontribusi sesuai kemampuan saya."}'::jsonb, '["専門家で","なくても","自分","なりに","社会に","貢献したい"]'::jsonb, NULL, NULL, '自分なりに社会に貢献したい berarti ''ingin berkontribusi pada masyarakat sesuai kapasitas diri sendiri''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('17c278c9-95b3-4b39-8e2b-a2c846b2673c', 'd682e234-08e7-4ab2-af42-f0f3f5a6f602', 'd1000019-0000-0000-0000-000000000033', 'writing', 'sentence_builder', 'Susun kalimat: "Para pemula pun memiliki cara belajar tersendiri yang efektif."', '{"romaji":"Shoshinsha ni wa shoshinsha nari no manabikata ga aru hazu da.","tokens":["ある","初心者","を余儀なく","はずだ","ながら","初心者には","学び方が","なりの"],"target_translation":"Para pemula pun memiliki cara belajar tersendiri yang efektif."}'::jsonb, '["初心者には","初心者","なりの","学び方が","ある","はずだ"]'::jsonb, NULL, NULL, '初心者なりの学び方 berarti ''cara belajar tersendiri yang cocok bagi pemula''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ecb220ba-2dde-4ee5-9927-dbd397112f07', 'd682e234-08e7-4ab2-af42-f0f3f5a6f602', 'd1000019-0000-0000-0000-000000000033', 'reading', 'fill_blank', 'Pilih bentuk yang tepat: 高い道具がなくても、手元にある材料___おいしい料理は作れる。', '{"options":["なりに","極まりなく","ずにはおかず","いかんによらず"],"translation":"Meski tanpa peralatan mahal, masakan lezat bisa dibuat sesuai bahan yang ada di tangan.","sentence_template":"高い道具がなくても、手元にある材料[blank]おいしい料理は作れる。"}'::jsonb, '{"selected":"なりに"}'::jsonb, NULL, NULL, '材料なりに (sesuai kondisi bahan yang ada) memodifikasi verba 作れる.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9fb6586f-9d4e-41d8-970a-16833c6d92cb', 'd682e234-08e7-4ab2-af42-f0f3f5a6f602', 'd1000019-0000-0000-0000-000000000033', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Saya ingin terus belajar dan bertumbuh dengan kecepatan saya sendiri tanpa terburu-buru."', '{"romaji":"Aserazu, jibun nari ni ippo zutsu seichou shite ikitai to omotte imasu.","display_text":"焦らず、自分なりに一歩ずつ成長していきたいと思っています。","phonetic_breakdown":["あせらず","じぶんなりに","いっぽずつ","せいちょうしていきたいと","おもっています"]}'::jsonb, '{"expected_transcript":"焦らず、自分なりに一歩ずつ成長していきたいと思っています。"}'::jsonb, NULL, NULL, '自分なりに一歩ずつ mengekspresikan sikap bertumbuh yang tenang dan konsisten.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2abcb1a3-15e5-4fe1-b537-ddf88ba56f0d', 'd794c7ad-f291-4dce-8356-b8b47cbf1a83', NULL, 'listening', 'listening_choice', 'Dengarkan berita ekonomi berikut. Apa yang terpaksa dilakukan oleh perusahaan manufaktur tersebut?', '{"options":[{"id":"opt_1","text":"Meningkatkan ekspor mobil listrik ke Amerika Serikat"},{"id":"opt_2","text":"Membangun pabrik semikonduktor baru dalam satu bulan"},{"id":"opt_3","text":"Terpaksa memangkas produksi secara signifikan akibat kelangkaan semikonduktor"},{"id":"opt_4","text":"Menurunkan harga jual seluruh lini kendaraan"}],"audio_text":"半導体不足の長期化により、自動車メーカー各社は大幅な減産を余儀なくされている。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '大幅な減産を余儀なくされている berarti ''terpaksa melakukan pengurangan produksi besar-besaran''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1aa1f7cd-7ac6-4f30-a775-315ea8115d5c', 'd794c7ad-f291-4dce-8356-b8b47cbf1a83', NULL, 'listening', 'listening_choice', 'Dengarkan laporan transportasi berikut. Mengapa jadwal penerbangan terganggu?', '{"options":[{"id":"opt_1","text":"Terjadi pemogokan staf bandara selama dua hari"},{"id":"opt_2","text":"Landasan pacu sedang menjalani renovasi terjadwal"},{"id":"opt_3","text":"Sistem reservasi tiket mengalami gangguan jaringan"},{"id":"opt_4","text":"Salju lebat yang mencetak rekor memaksa banyak penerbangan dibatalkan atau tertunda lama"}],"audio_text":"記録的な大雪の影響で、多数の便が欠航や大幅な遅延を余儀なくされました。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '記録的な大雪の影響で (akibat salju lebat pemecah rekor) menyebabkan 欠航や大幅な遅延を余儀なくされました.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('af8406aa-7698-4793-960f-10fcfcd8a85e', 'd794c7ad-f291-4dce-8356-b8b47cbf1a83', NULL, 'listening', 'listening_choice', 'Dengarkan pernyataan analis pasar berikut. Apa tekanan utama yang dihadapi sektor ritel?', '{"options":[{"id":"opt_1","text":"Pelemahan yen yang tajam dan kenaikan biaya tenaga kerja memaksa perubahan model bisnis"},{"id":"opt_2","text":"Penurunan jumlah wisatawan asing secara mendadak"},{"id":"opt_3","text":"Kelebihan pasokan tenaga kerja di sektor ritel"},{"id":"opt_4","text":"Penghapusan pajak konsumsi oleh pemerintah pusat"}],"audio_text":"急激な円安と人件費の上昇が、小売業界にビジネスモデルの転換を余儀なくさせている。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '急激な円安と人件費の上昇 memaksa sektor ritel melakukan ビジネスモデルの転換.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('0b93debf-8e4a-4e99-8765-2aaf819251b8', 'd794c7ad-f291-4dce-8356-b8b47cbf1a83', NULL, 'reading', 'fill_blank', 'Lengkapi berita berikut: 感染症の拡大を受け、多くの飲食店が営業時間の短縮___。', '{"options":["を顧みなかった","を皮切りにした","を余儀なくされた","をものともしなかった"],"translation":"Menyusul meluasnya penyakit menular, banyak restoran terpaksa mempersingkat jam operasionalnya.","sentence_template":"感染症の拡大を受け、多くの飲食店が営業時間の短縮[blank]。"}'::jsonb, '{"selected":"を余儀なくされた"}'::jsonb, NULL, NULL, '営業時間の短縮を余儀なくされた adalah ungkapan berita yang sangat natural untuk ''terpaksa memendekkan jam buka''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('facf049f-df30-46eb-8ac5-779940d91526', 'd794c7ad-f291-4dce-8356-b8b47cbf1a83', NULL, 'reading', 'fill_blank', 'Pilih kata benda yang paling alami sebelum を余儀なくされる: 建物の老朽化により、図書館は一時___を余儀なくされた。', '{"options":["閉館","入館","開館","来館"],"translation":"Akibat penuaan bangunan, perpustakaan terpaksa ditutup sementara.","sentence_template":"建物の老朽化により、図書館は一時[blank]を余儀なくされた。"}'::jsonb, '{"selected":"閉館"}'::jsonb, NULL, NULL, '一時閉館を余儀なくされた berarti ''terpaksa ditutup sementara'' karena bangunan tua (老朽化).', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f2ef5083-c41a-4925-8659-4aa5ffa86fde', 'd794c7ad-f291-4dce-8356-b8b47cbf1a83', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 予期せぬ法改正が、企業に大規模なシステム改修___。', '{"options":["を余儀なくさせた","に至らせた","を余儀なくされた","に足らしめた"],"translation":"Revisi undang-undang yang tak terduga memaksa perusahaan melakukan perombakan sistem berskala besar.","sentence_template":"予期せぬ法改正が、企業に大規模なシステム改修[blank]。"}'::jsonb, '{"selected":"を余儀なくさせた"}'::jsonb, NULL, NULL, 'Subjeknya 予期せぬ法改正 (penyebab) dan objek penerimanya 企業に, sehingga menggunakan bentuk kausatif を余儀なくさせた.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('812f94ef-3e8c-4984-b982-6e1d1f3604b3', 'd794c7ad-f291-4dce-8356-b8b47cbf1a83', 'd1000019-0000-0000-0000-000000000029', 'writing', 'sentence_builder', 'Susun kalimat: "Kenaikan suku bunga memaksa banyak pengembang properti menunda proyek baru."', '{"romaji":"Kinri joushou wa ooku no fudousan gaisha ni shinki keikaku no enki o yoginaku saseta.","tokens":["多くの不動産会社に","を","させた。","とはいえ、","金利上昇は","新規計画の延期","余儀なく","された。"],"target_translation":"Kenaikan suku bunga memaksa banyak pengembang properti menunda proyek baru."}'::jsonb, '["金利上昇は","多くの不動産会社に","新規計画の延期","を","余儀なく","させた。"]'::jsonb, NULL, NULL, 'Kausatif を余儀なくさせた menghubungkan penyebab ekonomi dengan dampaknya pada pelaku industri.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('65fca0b0-7a6a-47bd-a390-5d607411afbd', 'd794c7ad-f291-4dce-8356-b8b47cbf1a83', 'd1000019-0000-0000-0000-000000000029', 'listening', 'listening_choice', 'Dengarkan laporan cuaca. Mengapa festival kembang api harus dipindahkan tanggalnya?', '{"options":[{"id":"opt_1","text":"Karena tidak ada penonton yang membeli tiket"},{"id":"opt_2","text":"Karena panitia terpaksa menunda tanggal pelaksanaan akibat potensi angin kencang dan ombak tinggi"},{"id":"opt_3","text":"Karena kembang api belum dikirim dari pabrik"},{"id":"opt_4","text":"Karena lokasi pantai sedang direnovasi"}],"audio_text":"強風と高波の恐れがあるため、主催者は開催日の順延を余儀なくされたと発表した。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '開催日の順延 (penundaan tanggal pelaksanaan ke hari cadangan) + を余儀なくされた.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('ec79188a-92d8-4bf8-a6f4-b685d3a3a76c', 'd8c798e4-faa1-437b-9b18-52c0bae6905e', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Lengkapi kalimat opini berikut: 景気が回復傾向にある___、地方の中小企業にはまだ恩恵が届いていない。', '{"options":["とはいえ","ともなると","とあって","とばかりに"],"translation":"Meskipun ekonomi memang cenderung pulih, manfaatnya belum sampai ke UKM di daerah.","sentence_template":"景気が回復傾向にある[blank]、地方の中小企業にはまだ恩恵が届いていない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '～とはいえ mengakui fakta di klausa pertama (''memang benar bahwa...''), lalu menyampaikan kenyataan yang bertolak belakang atau catatan penting.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('daf6841e-2a6a-49fe-9aa0-e7b659ff2ae4', 'd8c798e4-faa1-437b-9b18-52c0bae6905e', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Pilih pola yang tepat untuk mengakui status/kondisi: 初心者___、基本的な安全ルールは必ず守らなければならない。', '{"options":["なりに","とはいえ","に足る","を皮切りに"],"translation":"Meskipun memang pemula, aturan keselamatan dasar tetap wajib dipatuhi.","sentence_template":"初心者[blank]、基本的な安全ルールは必ず守らなければならない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, 'Kata benda + とはいえ (''meski memang berstatus...'') menekankan bahwa pengecualian tidak berlaku.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('9b2879fc-f1cd-49af-88e3-cd6e5af966c9', 'd8c798e4-faa1-437b-9b18-52c0bae6905e', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Lengkapi kalimat berikut dengan konjungsi formal yang setara: リモートワークが普及した___、対面での議論の重要性は変わらない。', '{"options":["といえども","とは限らず","と相まって","とはいうものの"],"translation":"Walaupun kerja jarak jauh telah meluas, pentingnya diskusi tatap muka tetap tidak berubah.","sentence_template":"リモートワークが普及した[blank]、対面での議論の重要性は変わらない。"}'::jsonb, '{"selected":"とはいうものの"}'::jsonb, NULL, NULL, 'とはいうものの memiliki nuansa konsesif yang sangat dekat dengan とはいえ, lazim digunakan dalam esai dan editorial.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4f6c0f13-76f4-4727-b6d5-2380307f396b', 'd8c798e4-faa1-437b-9b18-52c0bae6905e', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Meskipun musim semi telah tiba, pagi dan malam masih dingin."', '{"romaji":"Haru ni natta to wa ie, asaban wa mada hiekomu.","tokens":["とはいえ","に至って","冷え込む","春に","朝晩は","ながら","なった","まだ"],"target_translation":"Meskipun musim semi telah tiba, pagi dan malam masih dingin."}'::jsonb, '["春に","なった","とはいえ","朝晩は","まだ","冷え込む"]'::jsonb, NULL, NULL, '春になったとはいえ (meski memang sudah musim semi) diikuti fakta kontras 朝晩はまだ冷え込む.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f12d1e67-a193-4693-96bd-cc3dd01c1b1f', 'd8c798e4-faa1-437b-9b18-52c0bae6905e', 'd1000019-0000-0000-0000-000000000030', 'writing', 'sentence_builder', 'Susun kalimat: "Walaupun hanya sementara, beban biaya tetaplah besar."', '{"romaji":"Ichijiteki to wa ie, hiyou no futan wa kesshite karukunai.","tokens":["を余儀なく","負担は","一時的","とはいえ","費用の","軽くない","決して","ばかりに"],"target_translation":"Walaupun hanya sementara, beban biaya tetaplah besar."}'::jsonb, '["一時的","とはいえ","費用の","負担は","決して","軽くない"]'::jsonb, NULL, NULL, 'Kata sifat-na (tanpa だ atau dengan だ) + とはいえ: 一時的とはいえ (''meski hanya sementara'').', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('5e66d38c-1fee-4fea-adb4-71d1c901cc59', 'd8c798e4-faa1-437b-9b18-52c0bae6905e', 'd1000019-0000-0000-0000-000000000030', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Meskipun memang sudah terbiasa, tidak boleh lengah sedikit pun."', '{"romaji":"Nareta sagyou to wa ie, isshun no yudan mo yurusarenai.","display_text":"慣れた作業とはいえ、一瞬の油断も許されない。","phonetic_breakdown":["na-re-ta","sa-gyou","to","wa","i-e","i-sshun","no","yu-dan","mo","yu-ru-sa-re-nai"]}'::jsonb, '{"expected_transcript":"慣れた作業とはいえ、一瞬の油断も許されない。"}'::jsonb, NULL, NULL, '一瞬の油断も許されない berarti ''kelengahan sesaat pun tidak dapat ditoleransi''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6c22a228-f972-4a98-b0fd-aacf9eac6134', 'd8c798e4-faa1-437b-9b18-52c0bae6905e', 'd1000019-0000-0000-0000-000000000030', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Manakah ringkasan yang paling akurat?', '{"options":[{"id":"opt_1","text":"Mengorbankan waktu bersama keluarga karena sibuk kerja adalah hal yang keliru tujuan meskipun pekerjaan memang padat"},{"id":"opt_2","text":"Pekerjaan harus selalu mengalahkan waktu bersama keluarga"},{"id":"opt_3","text":"Pembicara sedang tidak memiliki pekerjaan sama sekali"},{"id":"opt_4","text":"Keluarga tidak perlu menghabiskan waktu bersama"}],"audio_text":"仕事が忙しいとはいえ、家族と過ごす時間まで削ってしまっては本末転倒だ。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '本末転倒 (terbalik antara tujuan dan sarana) menegaskan evaluasi kritis setelah 忙しいとはいえ.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('df04bf18-d408-41a7-a09e-df7ef05fd158', 'd8c798e4-faa1-437b-9b18-52c0bae6905e', 'd1000019-0000-0000-0000-000000000030', 'reading', 'fill_blank', 'Lengkapi kalimat dengan struktur yang tepat: 予算が限られている___、品質を妥協するつもりはない。', '{"options":["とはいえ","を余儀なくされ","をもって","なりに"],"translation":"Meskipun anggaran memang terbatas, kami tidak berniat mengorbankan kualitas.","sentence_template":"予算が限られている[blank]、品質を妥協するつもりはない。"}'::jsonb, '{"selected":"とはいえ"}'::jsonb, NULL, NULL, '限られているとはいえ mengakui keterbatasan anggaran sebelum menegaskan komitmen kualitas.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('76706912-18fd-4616-98e2-91944a9c61b5', 'd9194b67-9393-432b-be1f-c2cf609e3d20', 'd1000019-0000-0000-0000-000000000028', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Baru setelah situasi memburuk, mereka mulai bertindak."', '{"romaji":"Jitai ga shinkokuka suru ni itatte, hajimete taiou ni noridashita.","display_text":"事態が深刻化するに至って、初めて対応に乗り出した。","phonetic_breakdown":["ji-tai","ga","shin-ko-ku-ka","su-ru","ni","i-ta-tte","ha-ji-me-te","tai-ou","ni","no-ri-da-shi-ta"]}'::jsonb, '{"expected_transcript":"事態が深刻化するに至って、初めて対応に乗り出した。"}'::jsonb, NULL, NULL, '対応に乗り出す berarti ''mulai turun tangan menangani'', sering dipadukan dengan ～に至って.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('2d68af04-631a-41fd-b226-b823a6f576b4', 'd9194b67-9393-432b-be1f-c2cf609e3d20', 'd1000019-0000-0000-0000-000000000028', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mulai dari perencanaan hingga pelaksanaan, dia mengawasi semuanya."', '{"romaji":"Kikaku no ritsuan kara genba no un''you ni itaru made, kare ga toukatsu shita.","display_text":"企画の立案から現場の運用に至るまで、彼が統括した。","phonetic_breakdown":["ki-ka-ku","no","ri-tsu-an","ka-ra","gen-ba","no","un-you","ni","i-ta-ru","ma-de","ka-re","ga","tou-ka-tsu","shi-ta"]}'::jsonb, '{"expected_transcript":"企画の立案から現場の運用に至るまで、彼が統括した。"}'::jsonb, NULL, NULL, '立案 (ritsuan: penyusunan rencana) hingga 運用 (un''you: operasional lapangan) dirangkai dengan ～に至るまで.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8fbb4131-c422-408c-96fa-e3f30778d0ad', 'd9194b67-9393-432b-be1f-c2cf609e3d20', 'd1000019-0000-0000-0000-000000000028', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Bagaimana masalah ini sampai berkembang sejauh ini?"', '{"romaji":"Naze mondai ga koko made kakudai suru ni itatta no ka, kenshou ga hitsuyou da.","display_text":"なぜ問題がここまで拡大するに至ったのか、検証が必要だ。","phonetic_breakdown":["na-ze","mon-dai","ga","ko-ko","ma-de","ka-ku-dai","su-ru","ni","i-ta-tta","no","ka","ken-shou","ga","hi-tsu-you","da"]}'::jsonb, '{"expected_transcript":"なぜ問題がここまで拡大するに至ったのか、検証が必要だ。"}'::jsonb, NULL, NULL, '拡大するに至ったのか menanyakan proses/sebab hingga masalah meluas sampai titik tersebut.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f3e75ad3-e7ae-49a8-8f54-550df1c25943', 'd9194b67-9393-432b-be1f-c2cf609e3d20', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Baru setelah kehilangan kepercayaan publik, dia mengundurkan diri."', '{"romaji":"Seron no shinrai wo ushinau ni itatte youyaku jinin shita.","tokens":["ばかりに","ようやく","世論の","信頼を","に至って","失う","辞任した","に沿って"],"target_translation":"Baru setelah kehilangan kepercayaan publik, dia mengundurkan diri."}'::jsonb, '["世論の","信頼を","失う","に至って","ようやく","辞任した"]'::jsonb, NULL, NULL, '世論の信頼を失うに至って (hingga kehilangan kepercayaan publik) diikuti ようやく辞任した (akhirnya mengundurkan diri).', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7aba5596-114e-4412-bb5b-ac41b6c0e365', 'd9194b67-9393-432b-be1f-c2cf609e3d20', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Sekarang sudah terlambat untuk menyalahkan siapa pun."', '{"romaji":"Ima ni itatte wa dare wo semete mo shikata ga nai.","tokens":["仕方が","責めても","に至るまで","どころか","ない","に至っては","今","誰を"],"target_translation":"Sekarang sudah terlambat untuk menyalahkan siapa pun."}'::jsonb, '["今","に至っては","誰を","責めても","仕方が","ない"]'::jsonb, NULL, NULL, '今に至っては menegaskan situasi sudah terlanjur terjadi sehingga menyalahkan pihak mana pun tidak ada gunanya.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('d4bd506d-f57c-4e9c-b59b-49e316b54b5d', 'd9194b67-9393-432b-be1f-c2cf609e3d20', 'd1000019-0000-0000-0000-000000000028', 'writing', 'sentence_builder', 'Susun kalimat: "Dia memeriksa detail terkecil dari kontrak tersebut."', '{"romaji":"Keiyakusho no saibu ni itaru made nen''iri ni kakunin shita.","tokens":["に至っては","をめぐって","に至るまで","契約書の","細部","した","念入りに","確認"],"target_translation":"Dia memeriksa detail terkecil dari kontrak tersebut."}'::jsonb, '["契約書の","細部","に至るまで","念入りに","確認","した"]'::jsonb, NULL, NULL, '細部に至るまで berarti ''hingga ke detail-detail terkecil''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('51fc720b-21a4-48c4-8be5-d6eac0f8d620', 'd9194b67-9393-432b-be1f-c2cf609e3d20', 'd1000019-0000-0000-0000-000000000028', 'reading', 'fill_blank', 'Pilih pola yang tepat: 資金繰りが完全に行き詰まる___、銀行団への支援要請が決まった。', '{"options":["に至って","なりに","に足る","ずにはおかず"],"translation":"Ketika arus kas benar-benar buntu, diputuskan untuk meminta dukungan konsorsium bank.","sentence_template":"資金繰りが完全に行き詰まる[blank]、銀行団への支援要請が決まった。"}'::jsonb, '{"selected":"に至って"}'::jsonb, NULL, NULL, '行き詰まるに至って menandai kondisi finansial yang mencapai batas akhir.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('943c44a5-db96-4a7d-94e5-a4fbf5c13d16', 'd9194b67-9393-432b-be1f-c2cf609e3d20', 'd1000019-0000-0000-0000-000000000028', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Mulai dari detail terkecil hingga kebijakan besar, semuanya ditinjau secara cermat."', '{"romaji":"Saibu ni itaru made tetteiteki ni kenshou shita ue de, saishuu houkokusho o matomemashita.","display_text":"細部に至るまで徹底的に検証した上で、最終報告書をまとめました。","phonetic_breakdown":["さいぶに","いたるまで","てっていてきに","けんしょうしたうえで","さいしゅうほうこくしょを","まとめました"]}'::jsonb, '{"expected_transcript":"細部に至るまで徹底的に検証した上で、最終報告書をまとめました。"}'::jsonb, NULL, NULL, '細部に至るまで (hingga ke detail terkecil) adalah frasa standar N1.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1b31a303-e9a1-435e-a8e8-ad4e63c6b826', 'da58a88f-55aa-460e-8cc5-78cf4cce264f', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Lengkapi ulasan seni berikut: 彼女の圧倒的な歌唱力は、聴く者すべてを感動させ___。', '{"options":["ずにはおかない","を余儀なくされない","に足らない","極まりない"],"translation":"Kemampuan bernyanyinya yang luar biasa pasti akan membuat setiap pendengarnya terharu tanpa terkecuali.","sentence_template":"彼女の圧倒的な歌唱力は、聴く者すべてを感動させ[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, NULL, NULL, 'V-nai (tanpa い) + ずにはおかない menyatakan dampak psikologis/sosial yang pasti dan tak terhindarkan.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4ad6eb42-cea6-43d0-8702-c67b26d854ea', 'da58a88f-55aa-460e-8cc5-78cf4cce264f', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Pilih konjugasi yang tepat untuk kata kerja する: この画期的な発見は、今後の医学界に大きな変革をもたら___。', '{"options":["さずにはおかない","しずにはおかない","せずにはおかない","すずにはおかない"],"translation":"Penemuan terobosan ini pasti akan membawa perubahan besar bagi dunia kedokteran ke depan.","sentence_template":"この画期的な発見は、今後の医学界に大きな変革をもたら[blank]。"}'::jsonb, '{"selected":"さずにはおかない"}'::jsonb, NULL, NULL, 'もたらす (golongan 1) -> もたらさ + ずにはおかない.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('40271efa-0575-434b-b495-61a22456ee45', 'da58a88f-55aa-460e-8cc5-78cf4cce264f', 'd1000019-0000-0000-0000-000000000034', 'listening', 'listening_choice', 'Dengarkan ulasan kritikus film. Apa dampak film dokumenter tersebut pada penonton?', '{"options":[{"id":"opt_1","text":"Film dokumenter itu membuat penonton tertidur di bioskop"},{"id":"opt_2","text":"Film dokumenter yang menampilkan realitas perang secara lugas itu pasti menggugah pertanyaan mendalam di benak penonton"},{"id":"opt_3","text":"Film dokumenter itu hanya berisi komedi ringan"},{"id":"opt_4","text":"Penonton tidak memahami bahasa yang digunakan dalam film itu"}],"audio_text":"戦火の現実を淡々と映し出したそのドキュメンタリーは、見る者に深い問いを投げかけずにはおかない。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '深い問いを投げかけずにはおかない berarti pasti menimbulkan perenungan/pertanyaan mendalam.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('95eda033-4076-4f8c-bba5-e1d8d3df3994', 'da58a88f-55aa-460e-8cc5-78cf4cce264f', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Skandal korupsi besar tersebut pasti akan mengguncang kepercayaan publik."', '{"romaji":"Sono oshoku jiken wa kokumin no shinrai o yurugasazu ni wa okanai.","tokens":["国民の信頼を","ずには","ない。","とはいえ、","その汚職事件は、","揺るがさ","おか","揺るがす"],"target_translation":"Skandal korupsi besar tersebut pasti akan mengguncang kepercayaan publik."}'::jsonb, '["その汚職事件は、","国民の信頼を","揺るがさ","ずには","おか","ない。"]'::jsonb, NULL, NULL, '揺るがす (mengguncang) -> 揺るがさずにはおかない.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('33809c5f-fcae-4f68-9410-66fbde2dceba', 'da58a88f-55aa-460e-8cc5-78cf4cce264f', 'd1000019-0000-0000-0000-000000000034', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Keindahan arsitektur kuno itu pasti membuat siapa pun yang melihatnya terpukau."', '{"romaji":"Sono kokenchiku no sourei na utsukushisa wa, otozureru hitobito o miryou sezu ni wa okimasen.","display_text":"その古建築の壮麗な美しさは、訪れる人々を魅了せずにはおきません。","phonetic_breakdown":["そのこけんちくの","そうれいなうつくしさは","おとずれるひとびとを","みりょうせずには","おきません"]}'::jsonb, '{"expected_transcript":"その古建築の壮麗な美しさは、訪れる人々を魅了せずにはおきません。"}'::jsonb, NULL, NULL, '魅了する (memukau) -> 魅了せずにはおきません (bentuk する selalu menjadi せずにはおかない).', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('08935df0-4c2d-4c5c-8f0a-f50a720415b1', 'da58a88f-55aa-460e-8cc5-78cf4cce264f', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Lengkapi kalimat editorial: 新税の導入は、家計の負担増を通じて消費動向に影響を与え___。', '{"options":["ずにはおかない","なりに","をもって","ともなると"],"translation":"Penerapan pajak baru pasti akan memberi pengaruh pada tren konsumsi melalui meningkatnya beban rumah tangga.","sentence_template":"新税の導入は、家計の負担増を通じて消費動向に影響を与え[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, NULL, NULL, '影響を与えずにはおかない menyatakan dampak ekonomi yang niscaya terjadi.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('03530b43-2b87-4463-be98-ebb22a6ab144', 'da58a88f-55aa-460e-8cc5-78cf4cce264f', 'd1000019-0000-0000-0000-000000000034', 'listening', 'listening_choice', 'Dengarkan komentar pakar sejarah. Apa efek dari penemuan naskah kuno tersebut?', '{"options":[{"id":"opt_1","text":"Naskah kuno itu tidak memiliki nilai sejarah apa pun"},{"id":"opt_2","text":"Naskah kuno itu memperkuat teori lama tanpa perubahan"},{"id":"opt_3","text":"Naskah kuno yang baru ditemukan ini adalah materi amat penting yang pasti akan membalikkan teori mapan sebelumnya dari akarnya"},{"id":"opt_4","text":"Naskah kuno itu hilang sebelum sempat diteliti"}],"audio_text":"今回発見された古文書は、従来の定説を根底から覆さずにはおかない極めて重要な資料だ。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '定説を根底から覆さずにはおかない berarti pasti membalikkan teori baku dari dasarnya.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('78a433a5-2945-4553-835b-deec3ae78abd', 'da58a88f-55aa-460e-8cc5-78cf4cce264f', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Pidato yang penuh semangat itu pasti membangkitkan keberanian para pendengarnya."', '{"romaji":"Sono netsuben wa kiku hito ni yuuki o ataezu ni wa okanai.","tokens":["聞く人に","与え","おかない。","極まりない。","その熱弁は、","勇気を","ずには","与えた"],"target_translation":"Pidato yang penuh semangat itu pasti membangkitkan keberanian para pendengarnya."}'::jsonb, '["その熱弁は、","聞く人に","勇気を","与え","ずには","おかない。"]'::jsonb, NULL, NULL, '勇気を与えずにはおかない (pasti menumbuhkan keberanian) memakai golongan 2 与える -> 与え + ずにはおかない.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('bb759f40-b0f4-40d0-9127-d1c2aa57f2ca', 'dbe9280e-f2fa-4034-b734-36c1d636b026', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk surat resmi: 審査の結果は、後日___にてご連絡いたします。', '{"options":["表面","場面","書面","正面"],"translation":"Hasil seleksi akan kami sampaikan di kemudian hari secara tertulis.","sentence_template":"審査の結果は、後日[blank]にてご連絡いたします。"}'::jsonb, '{"selected":"書面"}'::jsonb, NULL, NULL, '書面 (shomen) berarti ''dokumen tertulis'', sangat lazim dalam komunikasi resmi dan hukum.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c0b45c16-677f-4e06-8a14-bd2d58e24a48', 'dbe9280e-f2fa-4034-b734-36c1d636b026', NULL, 'reading', 'fill_blank', 'Lengkapi pengumuman resmi berikut: 理事長は今年度末の___に伴い、退任されることとなった。', '{"options":["中途採用","無期限延長","新規就任","任期満了"],"translation":"Ketua dewan pengurus akan mengundurkan diri seiring berakhirnya masa jabatan pada akhir tahun fiskal ini.","sentence_template":"理事長は今年度末の[blank]に伴い、退任されることとなった。"}'::jsonb, '{"selected":"任期満了"}'::jsonb, NULL, NULL, '任期満了 (ninki manryou) berarti ''berakhirnya masa jabatan secara penuh''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3c9b5842-2d22-461c-84a0-9847947f2555', 'dbe9280e-f2fa-4034-b734-36c1d636b026', NULL, 'reading', 'fill_blank', 'Pilih istilah hukum yang tepat: 改正された個人情報保護法は、来年四月一日に___される。', '{"options":["施行","旅行","流行","同行"],"translation":"Undang-undang perlindungan data pribadi yang telah direvisi akan mulai diberlakukan pada 1 April tahun depan.","sentence_template":"改正された個人情報保護法は、来年四月一日に[blank]される。"}'::jsonb, '{"selected":"施行"}'::jsonb, NULL, NULL, '施行 (shikou) berarti ''pemberlakuan resmi suatu undang-undang atau peraturan''.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('8e5f3434-2efe-42c4-958a-c677e6fdace9', 'dbe9280e-f2fa-4034-b734-36c1d636b026', NULL, 'listening', 'listening_choice', 'Dengarkan pengumuman penutupan acara berikut. Apa yang diumumkan oleh pembawa acara?', '{"options":[{"id":"opt_1","text":"Acara peringatan hari ini resmi ditutup dengan lancar"},{"id":"opt_2","text":"Acara peringatan ditunda selama dua jam karena kendala teknis"},{"id":"opt_3","text":"Sesi tanya jawab baru akan dimulai setelah istirahat"},{"id":"opt_4","text":"Para tamu diminta pindah ke aula lantai dua"}],"audio_text":"以上をもちまして、本日の記念式典を滞りなく閉会とさせていただきます。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '以上をもちまして...閉会とさせていただきます adalah kalimat penutup upacara formal yang baku.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('dbd01965-d04d-458a-91b4-5147a911d2fb', 'dbe9280e-f2fa-4034-b734-36c1d636b026', NULL, 'listening', 'listening_choice', 'Dengarkan pesan otomatis berikut. Kapan batas akhir penerimaan lamaran?', '{"options":[{"id":"opt_1","text":"Tanggal 13 bulan depan pukul lima sore"},{"id":"opt_2","text":"Tanggal 30 bulan ini pukul lima sore"},{"id":"opt_3","text":"Pendaftaran dibuka sepanjang tahun tanpa batas waktu"},{"id":"opt_4","text":"Tanggal 30 bulan ini pukul sembilan pagi"}],"audio_text":"本年度の奨学金申請は、今月三十日午後五時をもって受付を終了いたします。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '今月三十日午後五時をもって受付を終了いたします berarti ''pendaftaran ditutup pada tanggal 30 bulan ini pukul 17.00''.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('eaf67302-9b2b-4903-9775-3bcc81085d8a', 'dbe9280e-f2fa-4034-b734-36c1d636b026', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami akan menanggapi setiap keluhan pelanggan dengan penuh ketulusan."', '{"romaji":"Okyakusama no go-iken ni wa, seii wo motte taiou itashimasu.","display_text":"お客様のご意見には、誠意をもって対応いたします。","phonetic_breakdown":["o-kya-ku-sa-ma","no","go-i-ken","ni","wa","sei-i","wo","mo-tte","tai-ou","i-ta-shi-ma-su"]}'::jsonb, '{"expected_transcript":"お客様のご意見には、誠意をもって対応いたします。"}'::jsonb, NULL, NULL, '誠意をもって (seii wo motte: dengan ketulusan/iktikad baik) adalah frasa standar layanan korporasi Jepang.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('c129c24d-b48d-45e8-b812-4c32cc4c937b', 'dbe9280e-f2fa-4034-b734-36c1d636b026', 'd1000019-0000-0000-0000-000000000031', 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: 本日の会議はこれをもって___といたします。', '{"options":["閉会","開会","欠席","延期"],"translation":"Dengan ini, rapat hari ini resmi dinyatakan selesai/ditutup.","sentence_template":"本日の会議はこれをもって[blank]といたします。"}'::jsonb, '{"selected":"閉会"}'::jsonb, NULL, NULL, 'これをもって閉会といたします adalah kalimat penutup rapat resmi.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b5e515e9-cd81-490b-9434-a8cd2a60ba34', 'dbe9280e-f2fa-4034-b734-36c1d636b026', 'd1000019-0000-0000-0000-000000000031', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kami mengucapkan terima kasih yang tulus melalui pesan tertulis ini."', '{"romaji":"Ryakugi nagara shochuu o motte atsuku orei moushiagemasu.","display_text":"略儀ながら書中をもって厚く御礼申し上げます。","phonetic_breakdown":["りゃくぎながら","しょちゅうをもって","あつくおれい","もうしあげます"]}'::jsonb, '{"expected_transcript":"略儀ながら書中をもって厚く御礼申し上げます。"}'::jsonb, NULL, NULL, '略儀ながら書中をもって (meski secara singkat melalui surat ini) adalah salam surat formal klasik.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6a9787b0-e9e1-45f7-9c70-948102bfd348', 'e031fdb2-3384-4bfc-bb01-fa256561d6c2', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Lengkapi ulasan akademis berikut: 長年の実証データに基づく彼の理論は、十分に信頼___ものだ。', '{"options":["するに足る","したに足る","してに足る","せに足る"],"translation":"Teorinya yang didasarkan pada data empiris bertahun-tahun adalah hal yang sangat layak untuk dipercaya.","sentence_template":"長年の実証データに基づく彼の理論は、十分に信頼[blank]ものだ。"}'::jsonb, '{"selected":"するに足る"}'::jsonb, NULL, NULL, 'V-dict (信頼する) + に足る menyatakan bahwa sesuatu memiliki nilai/kualitas yang cukup layak untuk dinilai demikian.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('b6e7b054-f6d1-44b5-a7f4-8d9b19ce9a76', 'e031fdb2-3384-4bfc-bb01-fa256561d6c2', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Pilih bentuk negatif yang tepat (tidak layak dianggap serius): 根拠を欠いた噂話など、議論する___。', '{"options":["に足りない","に足る","を余儀なくされる","ずにはおかない"],"translation":"Gosip yang tidak memiliki dasar bukti seperti itu sama sekali tidak layak untuk diperdebatkan.","sentence_template":"根拠を欠いた噂話など、議論する[blank]。"}'::jsonb, '{"selected":"に足りない"}'::jsonb, NULL, NULL, '～に足りない / ～に足らない berarti ''tidak sepadan / tidak layak untuk...''.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6d4c8d54-2bbc-4933-a91b-76fecdafefd6', 'e031fdb2-3384-4bfc-bb01-fa256561d6c2', 'd1000019-0000-0000-0000-000000000037', 'listening', 'listening_choice', 'Dengarkan evaluasi komite investasi. Mengapa mereka menyetujui pendanaan startup tersebut?', '{"options":[{"id":"opt_1","text":"Karena perusahaan itu meminta dana sangat kecil"},{"id":"opt_2","text":"Berdasarkan keunggulan teknologi dan potensi pasar, komite menilai perusahaan itu sangat menjanjikan dan layak menerima investasi jangka panjang"},{"id":"opt_3","text":"Karena komite tidak sempat memeriksa laporan keuangan"},{"id":"opt_4","text":"Karena seluruh pesaing perusahaan itu sudah bangkrut"}],"audio_text":"技術的な優位性と市場の成長性を踏まえ、同社は長期的な投資に足る極めて有望な企業と判断した。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '投資に足る (kata benda 投資 + に足る) berarti layak untuk diinvestasikan.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fca09ee6-577c-4a62-bea6-3bac7cd1915c', 'e031fdb2-3384-4bfc-bb01-fa256561d6c2', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Ia adalah seorang pemimpin yang memiliki rekam jejak layak dihormati."', '{"romaji":"Kare wa sonkei ni taru rippa na jisseki o motsu riidaa da.","tokens":["尊敬","立派な実績を","リーダーだ。","とはいえ、","彼は","に足る","持つ","に足らない"],"target_translation":"Ia adalah seorang pemimpin yang memiliki rekam jejak layak dihormati."}'::jsonb, '["彼は","尊敬","に足る","立派な実績を","持つ","リーダーだ。"]'::jsonb, NULL, NULL, '尊敬に足る (layak dihormati) menggunakan kata benda aksi 尊敬 + に足る.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('49f3cf36-16df-4229-ace4-cc5c683c283f', 'e031fdb2-3384-4bfc-bb01-fa256561d6c2', 'd1000019-0000-0000-0000-000000000037', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Proposal ini dilengkapi analisis tajam yang sangat layak untuk dipertimbangkan secara serius."', '{"romaji":"Kono teiansho wa, shinken ni kentou suru ni taru surudoi bunseki o sonaete imasu.","display_text":"この提案書は、真剣に検討するに足る鋭い分析を備えています。","phonetic_breakdown":["このていあんしょは","しんけんに","けんとうするにたる","するどいぶんせきを","そなえています"]}'::jsonb, '{"expected_transcript":"この提案書は、真剣に検討するに足る鋭い分析を備えています。"}'::jsonb, NULL, NULL, '検討するに足る (layak untuk ditelaah/dipertimbangkan) adalah ungkapan evaluasi eksekutif N1.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a6ffcbea-ba1a-4b98-97b6-77f87ecd3380', 'e031fdb2-3384-4bfc-bb01-fa256561d6c2', 'd1000019-0000-0000-0000-000000000037', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 今回見つかった新事実は、歴史の教科書を書き換える___重大な発見だ。', '{"options":["に足る","なりに","をもって","いかんによらず"],"translation":"Fakta baru yang ditemukan kali ini adalah penemuan besar yang cukup layak untuk menulis ulang buku teks sejarah.","sentence_template":"今回見つかった新事実は、歴史の教科書を書き換える[blank]重大な発見だ。"}'::jsonb, '{"selected":"に足る"}'::jsonb, NULL, NULL, '書き換えるに足る menegaskan bobot penemuan yang sepadan dengan tindakan sebesar itu.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('cba0320a-f25f-472e-a067-1074da3eb417', 'e031fdb2-3384-4bfc-bb01-fa256561d6c2', 'd1000019-0000-0000-0000-000000000037', 'listening', 'listening_choice', 'Dengarkan komentar juri lomba sastra. Bagaimana penilaian beliau terhadap karya pemenang?', '{"options":[{"id":"opt_1","text":"Karya itu dinilai terlalu dangkal dan terburu-buru"},{"id":"opt_2","text":"Juri tidak jadi memilih pemenang tahun ini"},{"id":"opt_3","text":"Ketelitian struktur dan kedalaman penggambaran manusianya menjadikannya mahakarya yang sungguh layak meraih hadiah utama"},{"id":"opt_4","text":"Karya itu didiskualifikasi karena melebihi batas halaman"}],"audio_text":"構成の緻密さと人間描写の深さは、まさに大賞を受賞するに足る傑作であった。"}'::jsonb, '{"selected_id":"opt_3"}'::jsonb, NULL, NULL, '受賞するに足る傑作 berarti mahakarya yang pantas meraih penghargaan.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fa5745bc-322e-4b67-8836-96a64ea1363f', 'e031fdb2-3384-4bfc-bb01-fa256561d6c2', 'd1000019-0000-0000-0000-000000000037', 'writing', 'sentence_builder', 'Susun kalimat: "Masalah sekecil itu tidak layak untuk terlalu dikhawatirkan."', '{"romaji":"Sonna chiisana mondai wa shinpai suru ni taranai.","tokens":["小さな問題は、","に","ない。","極まりない。","そんな","心配する","足ら","足る"],"target_translation":"Masalah sekecil itu tidak layak untuk terlalu dikhawatirkan."}'::jsonb, '["そんな","小さな問題は、","心配する","に","足ら","ない。"]'::jsonb, NULL, NULL, '心配するに足らない (tidak layak dikhawatirkan) adalah bentuk negatif alami dari ～に足る.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e4fc60fb-b804-4452-abec-632e48259182', 'ef50a2a5-7fe7-4bb2-8c3a-03e90ce29acf', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Lengkapi klausul peraturan berikut: 理由の___、期限を過ぎた申請書は一切受理いたしません。', '{"options":["いかんによらず","いかんによって","いかんで","極まりなく"],"translation":"Tanpa memandang apa pun alasannya, formulir permohonan yang melewati tenggat sama sekali tidak akan diterima.","sentence_template":"理由の[blank]、期限を過ぎた申請書は一切受理いたしません。"}'::jsonb, '{"selected":"いかんによらず"}'::jsonb, NULL, NULL, 'Kata benda (+ の) + いかんによらず / いかんにかかわらず berarti ''tanpa memandang bagaimana pun kondisi X''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6eb18c6b-a040-4549-a5b9-67f66e940142', 'ef50a2a5-7fe7-4bb2-8c3a-03e90ce29acf', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Pilih pola yang menyatakan ketergantungan pada kondisi (bukan mengabaikan): 調査結果の___、計画を中止せざるを得なくなる可能性がある。', '{"options":["いかんにかかわらず","いかんによっては","いかんによらず","いかんを問わず"],"translation":"Bergantung pada bagaimana hasil penyelidikannya, ada kemungkinan proyek terpaksa dibatalkan.","sentence_template":"調査結果の[blank]、計画を中止せざるを得なくなる可能性がある。"}'::jsonb, '{"selected":"いかんによっては"}'::jsonb, NULL, NULL, 'Perhatikan bedanya: ～いかんによらず (tanpa memandang) vs ～いかんによっては / ～いかんで (bergantung pada).', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('78e9063b-7e96-4f37-8a51-dfc6a2364ae6', 'ef50a2a5-7fe7-4bb2-8c3a-03e90ce29acf', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Lengkapi kalimat formal berikut: 当社は、国籍や性別の___、公正な評価制度を採用している。', '{"options":["いかんで","ともなると","に至って","いかんにかかわらず"],"translation":"Perusahaan kami menerapkan sistem evaluasi yang adil tanpa memandang kewarganegaraan maupun jenis kelamin.","sentence_template":"当社は、国籍や性別の[blank]、公正な評価制度を採用している。"}'::jsonb, '{"selected":"いかんにかかわらず"}'::jsonb, NULL, NULL, '～いかんにかかわらず bersinonim erat dengan ～いかんによらず dalam dokumen kebijakan SDM.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('fabfc3fe-5ec9-4316-8246-2e056455af56', 'ef50a2a5-7fe7-4bb2-8c3a-03e90ce29acf', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang hasilnya, kita harus menerima keputusan juri."', '{"romaji":"Kekka no ikan ni yorazu shinsain no hantei ni shitagau.","tokens":["いかんに","判定に","なりに","結果の","審査員の","よらず","とはいえ","従う"],"target_translation":"Tanpa memandang hasilnya, kita harus menerima keputusan juri."}'::jsonb, '["結果の","いかんに","よらず","審査員の","判定に","従う"]'::jsonb, NULL, NULL, '結果のいかんによらず berarti ''apa pun hasilnya / tanpa memandang hasilnya''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('a7d0f9e9-72a2-4b9b-afc1-4e0bc7e6c5f8', 'ef50a2a5-7fe7-4bb2-8c3a-03e90ce29acf', 'd1000019-0000-0000-0000-000000000036', 'writing', 'sentence_builder', 'Susun kalimat: "Tanpa memandang status jabatan, pelanggaran hukum akan ditindak tegas."', '{"romaji":"Yakushoku no ikan ni yorazu fusei koui wa kibishiku shobatsu sareru.","tokens":["不正行為は","処罰される","をもって","よらず","厳しく","いかんに","役職の","極まりない"],"target_translation":"Tanpa memandang status jabatan, pelanggaran hukum akan ditindak tegas."}'::jsonb, '["役職の","いかんに","よらず","不正行為は","厳しく","処罰される"]'::jsonb, NULL, NULL, '役職のいかんによらず menegaskan prinsip kesetaraan aturan tanpa pengecualian pangkat.', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('175de98d-2f6d-4503-853b-33dbd26c111f', 'ef50a2a5-7fe7-4bb2-8c3a-03e90ce29acf', 'd1000019-0000-0000-0000-000000000036', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Tanpa memandang usia atau pengalaman, siapa pun dapat melamar."', '{"romaji":"Nenrei ya keireki no ikan ni yorazu, donata demo go-oubo itadakemasu.","display_text":"年齢や経歴のいかんによらず、どなたでもご応募いただけます。","phonetic_breakdown":["nen-rei","ya","kei-re-ki","no","i-kan","ni","yo-ra-zu","do-na-ta","de-mo","go-ou-bo","i-ta-da-ke-ma-su"]}'::jsonb, '{"expected_transcript":"年齢や経歴のいかんによらず、どなたでもご応募いただけます。"}'::jsonb, NULL, NULL, 'Ungkapan pengumuman lowongan atau kompetisi yang sangat resmi dan inklusif.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3796c8f8-361d-4cd1-b2d1-b8623f713b58', 'ef50a2a5-7fe7-4bb2-8c3a-03e90ce29acf', 'd1000019-0000-0000-0000-000000000036', 'listening', 'listening_choice', 'Dengarkan kalimat berikut. Apa makna utama dari ～いかんによらず?', '{"options":[{"id":"opt_1","text":"Prosedur yang ditetapkan hukum wajib dipatuhi tanpa memandang kehendak pribadi seseorang"},{"id":"opt_2","text":"Seseorang bebas mengabaikan hukum jika tidak setuju"},{"id":"opt_3","text":"Hukum hanya berlaku jika seseorang menginginkannya"},{"id":"opt_4","text":"Prosedur hukum bisa diubah oleh siapa saja"}],"audio_text":"本人の意思のいかんによらず、法律で定められた手続きは遵守しなければならない。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '本人の意思のいかんによらず menegaskan keberlakuan hukum yang objektif.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('37ab5250-71f9-485c-a916-9a557b2bcd93', 'ef50a2a5-7fe7-4bb2-8c3a-03e90ce29acf', 'd1000019-0000-0000-0000-000000000036', 'reading', 'fill_blank', 'Lengkapi kalimat dengan partikel penghubung yang tepat: 資格の有無___いかんによらず、意欲のある方を歓迎します。', '{"options":["の","を","に","で"],"translation":"Tanpa memandang ada tidaknya sertifikat, kami menyambut siapa saja yang memiliki motivasi tinggi.","sentence_template":"資格の有無[blank]いかんによらず、意欲のある方を歓迎します。"}'::jsonb, '{"selected":"の"}'::jsonb, NULL, NULL, 'Struktur baku adalah [Kata Benda] + の + いかんによらず (atau langsung kata benda + いかんによらず pada beberapa frasa, namun の adalah bentuk paling standar dan formal).', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4068f539-c21a-4eed-9f8e-fce4b71c07d5', 'fd5f8b3d-5401-459c-a1ef-64dce96e9b88', NULL, 'reading', 'fill_blank', 'Pilih kata yang tepat untuk berita politik: 突然の増税発表は、国民の激しい___を招いた。', '{"options":["称賛","反発","歓迎","妥協"],"translation":"Pengumuman kenaikan pajak mendadak memicu penolakan keras dari masyarakat.","sentence_template":"突然の増税発表は、国民の激しい[blank]を招いた。"}'::jsonb, '{"selected":"反発"}'::jsonb, NULL, NULL, '反発を招く (hanpatsu wo maneku) berarti ''mengundang reaksi penolakan/perlawanan''.', 1, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4512944d-9395-4a96-9bf7-d3d5d80a6d7f', 'fd5f8b3d-5401-459c-a1ef-64dce96e9b88', NULL, 'reading', 'fill_blank', 'Lengkapi kalimat ulasan budaya berikut: その独創的な演出は、世界中の観客を___した。', '{"options":["困惑","失望","退屈","魅了"],"translation":"Penyutradaraan yang orisinal itu memikat penonton di seluruh dunia.","sentence_template":"その独創的な演出は、世界中の観客を[blank]した。"}'::jsonb, '{"selected":"魅了"}'::jsonb, NULL, NULL, '魅了する (miryou suru) berarti ''mempesona / memikat hati secara mendalam''.', 2, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('465d639b-8d52-4906-bcba-b169a2196363', 'fd5f8b3d-5401-459c-a1ef-64dce96e9b88', NULL, 'reading', 'fill_blank', 'Pilih istilah yang tepat untuk wacana publik: 新しい法案をめぐり、専門家の間でも強い___が広がっている。', '{"options":["歓喜","確信","懸念","無関心"],"translation":"Terkait rancangan undang-undang baru, kekhawatiran kuat pun meluas di kalangan para pakar.","sentence_template":"新しい法案をめぐり、専門家の間でも強い[blank]が広がっている。"}'::jsonb, '{"selected":"懸念"}'::jsonb, NULL, NULL, '懸念 (kenen) berarti ''kekhawatiran / rasa cemas yang beralasan'' dalam bahasa berita formal.', 3, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7efcce37-46e2-4e70-b114-d113f6a97c46', 'fd5f8b3d-5401-459c-a1ef-64dce96e9b88', NULL, 'listening', 'listening_choice', 'Dengarkan ulasan film berikut. Bagaimana reaksi penonton terhadap film dokumenter tersebut?', '{"options":[{"id":"opt_1","text":"Film itu membangkitkan empati mendalam dan diskusi lintas generasi"},{"id":"opt_2","text":"Film itu hanya ditonton oleh kalangan sejarawan saja"},{"id":"opt_3","text":"Penonton menilai alur ceritanya terlalu ringan dan komedis"},{"id":"opt_4","text":"Penayangannya dihentikan karena kurang peminat"}],"audio_text":"戦時下の日常を描いたこの記録映画は、世代を超えて深い共感と議論を呼び起こしている。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '深い共感と議論を呼び起こしている berarti ''membangkitkan empati mendalam dan perdebatan/diskusi''.', 4, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('1233f7f7-07f2-415e-87c3-39195929cd84', 'fd5f8b3d-5401-459c-a1ef-64dce96e9b88', NULL, 'listening', 'listening_choice', 'Dengarkan berita ilmu pengetahuan berikut. Mengapa penemuan itu menjadi sorotan global?', '{"options":[{"id":"opt_1","text":"Karena hanya mengulang hasil penelitian lima puluh tahun lalu"},{"id":"opt_2","text":"Karena mematahkan teori mapan sebelumnya dan mengguncang dunia fisika"},{"id":"opt_3","text":"Karena penelitian tersebut dibatalkan sebelum dipublikasikan"},{"id":"opt_4","text":"Karena biayanya sangat kecil dibandingkan proyek lain"}],"audio_text":"従来の定説を覆す今回の発見は、物理学界全体に大きな衝撃を与えた。"}'::jsonb, '{"selected_id":"opt_2"}'::jsonb, NULL, NULL, '従来の定説を覆す (membalikkan teori baku sebelumnya) dan 大きな衝撃を与えた (memberi guncangan besar).', 5, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('4ee1ff70-5d6a-4590-9e32-f12e3cfded23', 'fd5f8b3d-5401-459c-a1ef-64dce96e9b88', NULL, 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Pernyataan tersebut mendapat pujian luas dari komunitas internasional."', '{"romaji":"Sono eidan wa kokusai shakai kara hiroku shousan wo abita.","display_text":"その英断は国際社会から広く称賛を浴びた。","phonetic_breakdown":["so-no","ei-dan","wa","ko-ku-sai","sha-kai","ka-ra","hi-ro-ku","shou-san","wo","a-bi-ta"]}'::jsonb, '{"expected_transcript":"その英断は国際社会から広く称賛を浴びた。"}'::jsonb, NULL, NULL, '称賛を浴びる (shousan wo abiru) berarti ''dibanjiri pujian'', sedangkan 英断 (eidan) berarti ''keputusan berani dan bijak''.', 6, '2026-11-25T18:49:03.530846+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('11b9a218-0c3b-4f62-ab19-3d5efeb25dd9', 'fd5f8b3d-5401-459c-a1ef-64dce96e9b88', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Pilih kosakata N1 yang tepat: この法案の可決は、社会全体に大きな___を呼ばずにはおかない。', '{"options":["波紋","休暇","祝賀","平穏"],"translation":"Pengesahan rancangan undang-undang ini pasti akan mengundang perdebatan/gelombang reaksi besar di seluruh masyarakat.","sentence_template":"この法案の可決は、社会全体に大きな[blank]を呼ばずにはおかない。"}'::jsonb, '{"selected":"波紋"}'::jsonb, NULL, NULL, '波紋を呼ぶ (menimbulkan riak/dampak polemik luas) adalah kolokasi media N1 yang erat dengan ずにはおかない.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('961efac2-c3ab-4742-ab88-3f364a9c2e5d', 'fd5f8b3d-5401-459c-a1ef-64dce96e9b88', 'd1000019-0000-0000-0000-000000000034', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Kinerja luar biasa tim muda itu pasti akan menarik perhatian seluruh dunia olahraga."', '{"romaji":"Wakate chiimu no mezamashii katsuyaku wa, supootsukai zentai no chuumoku o atsumezu ni wa okimasen.","display_text":"若手チームの目覚ましい活躍は、スポーツ界全体の注目を集めずにはおきません。","phonetic_breakdown":["わかてちーむの","めざましいかつやくは","すぽーつかいぜんたいの","ちゅうもくをあつめずには","おきません"]}'::jsonb, '{"expected_transcript":"若手チームの目覚ましい活躍は、スポーツ界全体の注目を集めずにはおきません。"}'::jsonb, NULL, NULL, '注目を集めずにはおきません berarti pasti menyita perhatian publik.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('908d1312-ee38-42d9-8097-df6a5554ee20', 'fe503263-beaa-4b1a-82bb-405282f577db', 'd1000019-0000-0000-0000-000000000034', 'listening', 'listening_choice', 'Dengarkan analisis media. Bagaimana reaksi pasar terhadap penggabungan dua raksasa teknologi itu?', '{"options":[{"id":"opt_1","text":"Merger mengejutkan dua pemimpin industri itu pasti akan memicu rasa waspada/krisis tajam di kalangan pesaing domestik maupun asing"},{"id":"opt_2","text":"Pesaing menyambut gembira merger tersebut tanpa kekhawatiran"},{"id":"opt_3","text":"Merger tersebut dibatalkan sebelum diumumkan"},{"id":"opt_4","text":"Industri teknologi tidak terpengaruh sama sekali"}],"audio_text":"業界一位と二位の電撃的な経営統合は、国内外の競合他社に激しい危機感を抱かせずにはおかないだろう。"}'::jsonb, '{"selected_id":"opt_1"}'::jsonb, NULL, NULL, '危機感を抱かせずにはおかない (bentuk kausatif 抱かせる + ずにはおかない) berarti pasti membuat mereka merasakan krisis.', 1, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6cc7ec5b-b3eb-4d89-8d27-a186138dc4dd', 'fe503263-beaa-4b1a-82bb-405282f577db', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Ketidakadilan yang terang-terangan itu pasti akan memicu kemarahan masyarakat luas."', '{"romaji":"Sono fukousei na shochi wa shimin no ikari o manekazu ni wa okanai.","tokens":["市民の怒りを","ずには","ない。","なりに、","その不公正な処置は、","招か","おか","招いた"],"target_translation":"Ketidakadilan yang terang-terangan itu pasti akan memicu kemarahan masyarakat luas."}'::jsonb, '["その不公正な処置は、","市民の怒りを","招か","ずには","おか","ない。"]'::jsonb, NULL, NULL, '招く -> 招かずにはおかない menyatakan reaksi sosial yang tak terbendung.', 2, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('e84e7dcf-51e1-49c2-bb8d-a77fe0f78a56', 'fe503263-beaa-4b1a-82bb-405282f577db', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Pilih bentuk yang sesuai: 彼の誠実な人柄は、接するすべての人に好感を抱か___。', '{"options":["せずにはおかない","さずにはおかない","すずにはおかない","しずにはおかない"],"translation":"Kepribadiannya yang tulus pasti membuat setiap orang yang berinteraksi dengannya menaruh simpati.","sentence_template":"彼の誠実な人柄は、接するすべての人に好感を抱か[blank]。"}'::jsonb, '{"selected":"せずにはおかない"}'::jsonb, NULL, NULL, '抱かせる (kausatif, membuat orang lain merasakan) -> 抱かせ + ずにはおかない.', 3, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('3a9e885e-ebdf-450b-9a20-86a0bba628a7', 'fe503263-beaa-4b1a-82bb-405282f577db', 'd1000019-0000-0000-0000-000000000034', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Karya sastra klasik ini pasti meninggalkan kesan mendalam bagi pembaca lintas zaman."', '{"romaji":"Kono meisaku bungaku wa, jidai o koete dokusha no kokoro ni fukai yoin o nokosazu ni wa okimasen.","display_text":"この名作文学は、時代を超えて読者の心に深い余韻を残さずにはおきません。","phonetic_breakdown":["このめいさくぶんがくは","じだいをこえて","どくしゃのこころに","ふかいよいんを","のこさずにはおきません"]}'::jsonb, '{"expected_transcript":"この名作文学は、時代を超えて読者の心に深い余韻を残さずにはおきません。"}'::jsonb, NULL, NULL, '余韻を残す (meninggalkan kesan mendalam yang membekas) + ずにはおきません.', 4, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7e2e0f2a-58f7-4643-9a49-c6f1017aad17', 'fe503263-beaa-4b1a-82bb-405282f577db', 'd1000019-0000-0000-0000-000000000034', 'reading', 'fill_blank', 'Lengkapi kalimat berikut: 気候変動の加速は、世界の食料供給体制に深刻な打撃を与え___。', '{"options":["ずにはおかない","を余儀なくされる","に足る","いかんによらず"],"translation":"Percepatan perubahan iklim pasti akan memberikan pukulan serius bagi sistem pasokan pangan dunia.","sentence_template":"気候変動の加速は、世界の食料供給体制に深刻な打撃を与え[blank]。"}'::jsonb, '{"selected":"ずにはおかない"}'::jsonb, NULL, NULL, '打撃を与えずにはおかない menyatakan konsekuensi besar yang niscaya terjadi.', 5, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('7c031e5b-cb3f-4a35-8d17-4ae874a17e74', 'fe503263-beaa-4b1a-82bb-405282f577db', 'd1000019-0000-0000-0000-000000000034', 'listening', 'listening_choice', 'Dengarkan ulasan pameran foto. Apa yang dirasakan pengunjung melihat foto-foto alam liar itu?', '{"options":[{"id":"opt_1","text":"Pengunjung merasa foto-foto itu biasa saja"},{"id":"opt_2","text":"Foto-foto itu diambil di dalam studio tertutup"},{"id":"opt_3","text":"Pameran foto itu ditutup karena sepi pengunjung"},{"id":"opt_4","text":"Deretan foto alam ekstrem tersebut memiliki kekuatan yang pasti menumbuhkan rasa takjub mendalam pada siapa pun yang melihatnya"}],"audio_text":"極限の自然を捉えた写真の数々は、見る者に畏敬の念を覚えさせずにはおかない迫力がある。"}'::jsonb, '{"selected_id":"opt_4"}'::jsonb, NULL, NULL, '畏敬の念を覚えさせずにはおかない berarti pasti menimbulkan rasa hormat dan takjub.', 6, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('f17991a1-ae6e-4fef-b11e-7c097a525e7b', 'fe503263-beaa-4b1a-82bb-405282f577db', 'd1000019-0000-0000-0000-000000000034', 'writing', 'sentence_builder', 'Susun kalimat: "Perubahan demografi yang cepat pasti akan memaksa peninjauan ulang sistem pensiun."', '{"romaji":"Jinkou kouzou no henka wa nenkin seido no minaoshi o semarazu ni wa okanai.","tokens":["年金制度の","迫ら","おかない。","をもって、","人口構造の変化は、","見直しを","ずには","迫った"],"target_translation":"Perubahan demografi yang cepat pasti akan memaksa peninjauan ulang sistem pensiun."}'::jsonb, '["人口構造の変化は、","年金制度の","見直しを","迫ら","ずには","おかない。"]'::jsonb, NULL, NULL, '迫る (mendesak) -> 迫らずにはおかない.', 7, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
INSERT INTO exercises ("id", "lesson_id", "grammar_point_id", "skill_pillar", "exercise_type", "prompt", "content", "correct_answer", "acceptable_answers", "diagnostic_rubric", "explanation", "order_index", "created_at") VALUES ('6274129f-e489-4985-83df-42ce41ada2b9', 'fe503263-beaa-4b1a-82bb-405282f577db', 'd1000019-0000-0000-0000-000000000034', 'speaking', 'speaking_repeat', 'Dengarkan dan tirukan kalimat: "Dedikasi para relawan di lokasi bencana pasti menyentuh hati siapa pun yang menyaksikannya."', '{"romaji":"Hisaichi de no borantia no katagata no kenshin wa, miru hito no mune o utazu ni wa okimasen.","display_text":"被災地でのボランティアの方々の献身は、見る人の胸を打たずにはおきません。","phonetic_breakdown":["ひさいちでの","ぼらんてぃあのかたがたの","けんしんは","みるひとのむねを","うたずにはおきません"]}'::jsonb, '{"expected_transcript":"被災地でのボランティアの方々の献身は、見る人の胸を打たずにはおきません。"}'::jsonb, NULL, NULL, '胸を打つ (menyentuh hati secara mendalam) -> 胸を打たずにはおきません.', 8, '2026-11-26T03:34:06.420184+00:00') ON CONFLICT DO NOTHING;
